#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_SEQUENCE_NUMBER 0xFFFFFFFFU

typedef struct {
    uint64_t timestamp;
    uint32_t sequenceNumber;
    size_t dataLength;
} FrameHeader;

FrameHeader* allocate_frame_headers(size_t count, uint64_t min_timestamp, uint64_t max_timestamp) {
    if (count == 0 || min_timestamp > max_timestamp) {
        return NULL; // Invalid input
    }

    FrameHeader *headers = malloc(count * sizeof(FrameHeader));
    if (!headers) {
        return NULL; // Memory allocation failed
    }

    uint32_t sequenceNumber = 1;
    for (size_t i = 0; i < count; ++i) {
        headers[i].timestamp = min_timestamp + i;
        headers[i].sequenceNumber = sequenceNumber++;
        if (sequenceNumber > MAX_SEQUENCE_NUMBER) {
            free(headers);
            return NULL; // Sequence number overflow
        }
        headers[i].dataLength = rand() % 1024; // Example data length, adjust as needed
    }

    return headers;
}

int main() {
    size_t count = 100;
    uint64_t min_timestamp = 1633075200; // Example timestamp (January 1, 2022)
    uint64_t max_timestamp = 1633161600; // Example timestamp (January 2, 2022)

    FrameHeader *frames = allocate_frame_headers(count, min_timestamp, max_timestamp);
    if (!frames) {
        fprintf(stderr, "Failed to allocate frame headers\n");
        return 1;
    }

    // Process the frames...

    free(frames);

    return 0;
}
