#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* allocate_records(int count) {
    if (count <= 0) return NULL;

    record* records = (record*)malloc(count * sizeof(record));
    if (!records) return NULL;

    for (int i = 0; i < count; ++i) {
        records[i].value = rand();
    }

    return records;
}

long* allocate_offsets(int count, int key_count) {
    if (count <= 0 || key_count <= 0) return NULL;

    long* offsets = (long*)malloc(count * sizeof(long));
    int* keys = (int*)malloc(key_count * sizeof(int));

    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        offsets[i] = rand();
    }

    for (int i = 0; i < key_count; ++i) {
        keys[i] = rand() % key_count;
    }

    free(keys);
    return offsets;
}

int main() {
    srand(time(NULL));

    int record_count = 1000;
    int key_count = 500;

    record* records = allocate_records(record_count);
    long* offsets = allocate_offsets(record_count, key_count);

    if (records && offsets) {
        // Use the allocated arrays
        free(records);
        free(offsets);
    }

    return 0;
}
