    if (argc != 4) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <rules>\n", argv[0]);
        return EXIT_FAILURE;
    }

    parseAndTransformFile(argv[1], argv[2], argv[3]);

    return EXIT_SUCCESS;
