#include <stdio.h>
#include <stdlib.h>

int processNetworkStream(int *networkData, int size) {
    if (size <= 0 || networkData == NULL) {
        return -1; // Invalid input handling
    }

    int *validIntegers = (int *)malloc(100 * sizeof(int));
    if (validIntegers == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    int validCount = 0;
    for (int i = 0; i < size && validCount < 100; ++i) {
        if (networkData[i] >= -1000 && networkData[i] <= 1000) {
            validIntegers[validCount++] = networkData[i];
        }
    }

    if (validCount == 0) {
        free(validIntegers);
        return -1; // No valid integers received
    }

    int maxInteger = validIntegers[0];
    for (int i = 1; i < validCount; ++i) {
        if (validIntegers[i] > maxInteger) {
            maxInteger = validIntegers[i];
        }
    }

    free(validIntegers);
    return maxInteger;
}
```

