#include <string.h>
#include <ctype.h>

#define MAX_MAC_LENGTH 18

typedef struct {
    unsigned char mac[6];
} MacAddress;

int validate_mac_address(const char *mac_str, MacAddress *out_mac) {
    if (strlen(mac_str) != MAX_MAC_LENGTH) {
        return -1; // Invalid length
    }

    for (int i = 0; i < MAX_MAC_LENGTH; i++) {
        if ((i % 3 == 2 && mac_str[i] != ':') || 
            (!isxdigit(mac_str[i]) && !isspace(mac_str[i]))) {
            return -1; // Invalid character or format
        }
    }

    char *token = strtok((char *)mac_str, ":");
    int index = 0;
    while (token) {
        if (index >= 6) {
            return -1; // Too many tokens
        }
        unsigned char value = 0;
        for (int j = 0; j < 2; j++) {
            if (!isxdigit(token[j])) {
                return -1; // Invalid hex digit
            }
            value = (value << 4) | (isdigit(token[j]) ? token[j] - '0' : toupper(token[j]) - 'A' + 10);
        }
        out_mac->mac[index++] = value;
        token = strtok(NULL, ":");
    }

    if (index != 6) {
        return -1; // Not enough tokens
    }

    return 0; // Success
}

void log_conversion(const char *mac_str, int result) {
    if (result == 0) {
        printf("Conversion successful: %s\n", mac_str);
    } else {
        printf("Conversion failed for: %s\n", mac_str);
    }
}
