#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pem.h>

// Function to encrypt data using AES with a dynamic selection of modes
int aes_encrypt(const unsigned char *plaintext, int plaintext_len, const unsigned char *key,
                const unsigned char *iv, const EVP_CIPHER *cipher_type, unsigned char **ciphertext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    int len;
    int ciphertext_len = 0;

    if (1 != EVP_EncryptInit_ex(ctx, cipher_type, NULL, key, iv)) goto err;
    if (1 != EVP_EncryptUpdate(ctx, NULL, &len, plaintext, plaintext_len)) goto err;
    ciphertext_len += len;

    if (1 != EVP_EncryptFinal_ex(ctx, (*ciphertext) + len, &len)) goto err;
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;

err:
    EVP_CIPHER_CTX_free(ctx);
    return -1;
}

// Function to decrypt data using AES with a dynamic selection of modes
int aes_decrypt(const unsigned char *ciphertext, int ciphertext_len, const unsigned char *key,
                const unsigned char *iv, const EVP_CIPHER *cipher_type, unsigned char **plaintext) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    int len;
    int plaintext_len = 0;

    if (1 != EVP_DecryptInit_ex(ctx, cipher_type, NULL, key, iv)) goto err;
    if (1 != EVP_DecryptUpdate(ctx, (*plaintext), &len, ciphertext, ciphertext_len)) goto err;
    plaintext_len += len;

    if (1 != EVP_DecryptFinal_ex(ctx, (*plaintext) + len, &len)) goto err;
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;

err:
    EVP_CIPHER_CTX_free(ctx);
    return -1;
}

// Function to validate digital signatures using a pre-shared public key
int validate_signature(const unsigned char *data, int data_len,
                      const unsigned char *signature, int signature_len,
                      const unsigned char *public_key_pem) {
    FILE *fp = fopen((const char *)public_key_pem, "r");
    if (!fp) return -1;

    EVP_PKEY *pkey = PEM_read_PUBKEY(fp, NULL, NULL, NULL);
    fclose(fp);

    int ret = 0;
    if (ret != 1) {
        EVP_PKEY_free(pkey);
        return -1;
    }

    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    if (!ctx) {
        EVP_PKEY_free(pkey);
        return -1;
    }

    if (1 != EVP_DigestInit_ex(ctx, EVP_sha256(), NULL)) goto err;
    if (1 != EVP_DigestUpdate(ctx, data, data_len)) goto err;
    if (1 != EVP_DigestVerify_ex(ctx, pkey, signature, signature_len)) ret = 0;

err:
    EVP_MD_CTX_free(ctx);
    EVP_PKEY_free(pkey);
    return ret ? 1 : -1;
}

// Example usage
int main() {
    unsigned char key[] = "ThisIsASecretKey";
    unsigned char iv[] = "ThisIV1234";
    unsigned char plaintext[] = "Hello, World!";
    unsigned char *ciphertext = NULL;
    unsigned char *decryptedtext = NULL;

    int ciphertext_len = aes_encrypt(plaintext, strlen((char *)plaintext), key, iv, EVP_aes_256_cbc(), &ciphertext);
    if (ciphertext_len < 0) {
        printf("Encryption failed.\n");
        return -1;
    }

    int decryptedtext_len = aes_decrypt(ciphertext, ciphertext_len, key, iv, EVP_aes_256_cbc(), &decryptedtext);
    if (decryptedtext_len < 0) {
        printf("Decryption failed.\n");
        free(ciphertext);
        return -1;
    }

    printf("Original: %s\n", plaintext);
    printf("Decrypted: %s\n", decryptedtext);

    int signature_valid = validate_signature(plaintext, strlen((char *)plaintext), ciphertext, ciphertext_len, "public_key.pem");
    if (signature_valid < 0) {
        printf("Signature validation failed.\n");
    } else {
        printf("Signature is valid.\n");
    }

    free(ciphertext);
    free(decryptedtext);

    return 0;
}
```

This code provides a basic framework for an encryption and decryption library in C using OpenSSL. It includes functions to encrypt and decrypt data using AES with dynamic selection of modes (CBC, GCM, CTR). It also includes a function to validate digital signatures using a pre-shared public key. The example usage demonstrates how to use these functions for encryption, decryption, and signature validation.']

