import java.net.HttpURLConnection;
import java.net.URL;
import org.json.JSONArray;
import org.json.JSONObject;

public class PokemonWeaknessService {

    private static final String API_URL = "https://pokeapi.co/api/v2/pokemon/";
    private static final String CONFIG_FILE_PATH = "path/to/config/file.properties";

    public String getDetailedWeaknesses(String pokemonName) {
        try {
            URL url = new URL(API_URL + pokemonName);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
                String inputLine;
                StringBuilder content = new StringBuilder();
                while ((inputLine = in.readLine()) != null) {
                    content.append(inputLine);
                }
                in.close();

                JSONObject jsonResponse = new JSONObject(content.toString());
                JSONArray typesArray = jsonResponse.getJSONArray("types");
                StringBuilder weaknesses = new StringBuilder();

                for (int i = 0; i < typesArray.length(); i++) {
                    JSONObject typeObject = typesArray.getJSONObject(i);
                    String typeName = typeObject.getJSONObject("type").getString("name");
                    weaknesses.append(getWeaknessesForType(typeName));
                }

                return weaknesses.toString();
            } else {
                throw new IOException("API request failed with response code: " + responseCode);
            }
        } catch (IOException e) {
            e.printStackTrace();
            return "Error retrieving Pokemon data";
        }
    }

    private String getWeaknessesForType(String typeName) {
        try {
            // Simulate fetching weaknesses from a configuration file
            Properties config = new Properties();
            config.load(new FileInputStream(CONFIG_FILE_PATH));
            String weaknesses = config.getProperty(typeName + ".weaknesses");
            return weaknesses != null ? weaknesses : "";
        } catch (IOException e) {
            e.printStackTrace();
            return "Error retrieving type weaknesses";
        }
    }

    // Additional methods for handling dual types, thread safety, and other enhancements can be added here
}
