    CryptoOperation *ops = get_crypto_operations();
    NonceManager nm = generate_nonce();

    for (int i = 0; ops[i].operation != NULL; i++) {
        printf("Performing operation: %s\n", ops[i].name);
        ops[i].operation(); // Execute the cryptographic operation
        // Use unique nonce for each operation
