#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>

typedef enum {
    ENCRYPT,
    DECRYPT,
    SIGNATURE_VERIFY,
    MAC_GENERATE,
    MAC_VERIFY
} OperationType;

typedef struct {
    EVP_CIPHER *cipher;
    unsigned char key[32];
    unsigned char iv[16];
} CipherContext;

typedef struct {
    EVP_PKEY *pkey;
    const EVP_MD *md;
} SignatureContext;

typedef struct {
    EVP_PKEY *pkey;
    const EVP_MD *md;
} MACContext;

void initialize_library() {
    OpenSSL_add_all_algorithms();
}

OperationType parse_operation(char *operation_str) {
    if (strcmp(operation_str, "encrypt") == 0) return ENCRYPT;
    if (strcmp(operation_str, "decrypt") == 0) return DECRYPT;
    if (strcmp(operation_str, "verify_signature") == 0) return SIGNATURE_VERIFY;
    if (strcmp(operation_str, "generate_mac") == 0) return MAC_GENERATE;
    if (strcmp(operation_str, "verify_mac") == 0) return MAC_VERIFY;
    return -1; // Invalid operation
}

CipherContext* create_cipher_context(char *cipher_name, unsigned char *key, unsigned char *iv) {
    CipherContext *ctx = malloc(sizeof(CipherContext));
    ctx->cipher = EVP_get_cipherbyname(cipher_name);
    memcpy(ctx->key, key, sizeof(ctx->key));
    memcpy(ctx->iv, iv, sizeof(ctx->iv));
    return ctx;
}

int encrypt_data(CipherContext *ctx, unsigned char *input, size_t input_len, unsigned char **output, size_t *output_len) {
    EVP_CIPHER_CTX *evp_ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit_ex(evp_ctx, ctx->cipher, NULL, ctx->key, ctx->iv)) {
        EVP_CIPHER_CTX_free(evp_ctx);
        return -1;
    }
    *output_len = input_len + EVP_CIPHER_block_size(ctx->cipher);
    *output = malloc(*output_len);
    int len;
    if (!EVP_EncryptUpdate(evp_ctx, *output, &len, input, input_len)) {
        free(*output);
        EVP_CIPHER_CTX_free(evp_ctx);
        return -1;
    }
    int final_len;
    if (!EVP_EncryptFinal_ex(evp_ctx, (*output) + len, &final_len)) {
        free(*output);
        EVP_CIPHER_CTX_free(evp_ctx);
        return -1;
    }
    *output_len = len + final_len;
    EVP_CIPHER_CTX_free(evp_ctx);
    return 0;
}

// Similar functions for decryption, signature verification, MAC generation, and MAC verification

void destroy_cipher_context(CipherContext *ctx) {
    free(ctx);
}

int main(int argc, char **argv) {
    // Command line parsing and execution logic here
    return 0;
}
