#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <semaphore.h>
#include <signal.h>

#define SEM_NAME "/my_semaphore"
#define LOG_FILE "operation_log.txt"
#define TEMP_DIR "/tmp"

sem_t *init_semaphore(const char *name, unsigned int value) {
    return sem_open(name, O_CREAT | O_EXCL, 0644, value);
}

void cleanup_semaphore(sem_t *sem, const char *name) {
    if (sem != SEM_FAILED) {
        sem_close(sem);
        sem_unlink(name);
    }
}

int create_secure_temp_file(const char *dir) {
    int fd;
    do {
        char temp_name[256];
        snprintf(temp_name, sizeof(temp_name), "%s/tempfile.XXXXXX", dir);
        fd = mkstemp(temp_name);
    } while (fd == -1 && errno == EEXIST);

    if (fd != -1) {
        unlink(temp_name); // Remove the temporary name
    }

    return fd;
}

void log_operation(const char *operation, const char *data) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log != NULL) {
        fprintf(log, "[%s] %s\n", operation, data);
        fclose(log);
    }
}

void handle_sigint(int signum) {
    // Custom signal handler for cleanup
    cleanup_semaphore(sem, SEM_NAME);
    exit(signum);
}

int main() {
    sem_t *sem = init_semaphore(SEM_NAME, 1);
    if (sem == SEM_FAILED) {
        perror("Failed to initialize semaphore");
        return EXIT_FAILURE;
    }

    // Set up signal handler for graceful termination
    signal(SIGINT, handle_sigint);

    int temp_fd = create_secure_temp_file(TEMP_DIR);
    if (temp_fd == -1) {
        perror("Failed to create secure temporary file");
        cleanup_semaphore(sem, SEM_NAME);
        return EXIT_FAILURE;
    }

    // Perform operations with the semaphore and temporary file
    sem_wait(sem);
    log_operation("Operation", "Starting operation");

    // Simulate work with temporary file
    write(temp_fd, "Data written", 12);

    log_operation("Operation", "Completed operation");
    sem_post(sem);

    close(temp_fd);

    cleanup_semaphore(sem, SEM_NAME);

    return EXIT_SUCCESS;
}
