#include <iostream>
#include <cstdlib>

void processArray(int*& arr, int& size, int target, int increment) {
    bool found = false;
    for (int i = 0; i < size; ++i) {
        if (arr[i] == target) {
            arr[i] += increment;
            found = true;
            break;
        }
    }

    if (!found) {
        // Create a new array with increased size
        int newSize = size + 1;
        int* newArr = new int[newSize];

        // Copy existing elements to the new array
        for (int i = 0; i < size; ++i) {
            newArr[i] = arr[i];
        }

        // Add the target value
        newArr[size] = target + increment;

        // Free the old array and update pointers
        delete[] arr;
        arr = newArr;
        size = newSize;
    }
}

int main() {
    int initialSize = 5;
    int* myArray = new int[initialSize]{1, 2, 3, 4, 5};
    int targetValue = 3;
    int incrementValue = 10;

    processArray(myArray, initialSize, targetValue, incrementValue);

    for (int i = 0; i < initialSize; ++i) {
        std::cout << myArray[i] << " ";
    }
    delete[] myArray;
    return 0;
}
