namespace beast = boost::beast;         // from <boost/beast.hpp>
namespace http = beast::http;           // from <boost/beast/http.hpp>
namespace net = boost::asio;            // from <boost/asio.hpp>
using tcp = net::ip::tcp;               // from <boost/asio/ip/tcp.hpp>

// HTTP client function for GET request
void get_request(tcp::resolver& resolver, beast::tcp_stream& stream, std::string const& host, std::string const& target) {
    // Set up the HTTP request
    http::request<http::string_body> req{http::verb::get, target, 11};
    req.set(http::field::host, host);
    req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);

    // Send the request
    beast::error_code ec;
    http::write(stream, req, ec);
    if (ec) {
        std::cerr << "Error sending request: " << ec.message() << std::endl;
        return;
    }

    // Receive the response
    http::response<http::dynamic_body> res;
    http::read(stream, res, ec);
    if (ec) {
        std::cerr << "Error receiving response: " << ec.message() << std::endl;
        return;
    }

    // Handle the response
    std::cout << "Response status code: " << res.result_int() << std::endl;
}

// HTTP client function for POST request
void post_request(tcp::resolver& resolver, beast::tcp_stream& stream, std::string const& host, std::string const& target, std::string const& body) {
    // Set up the HTTP request
    http::request<http::string_body> req{http::verb::post, target, 11};
    req.set(http::field::host, host);
    req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);
    req.set(http::field::content_type, "application/json");
    req.body() = body;
    req.prepare_payload();

    // Send the request
    beast::error_code ec;
    http::write(stream, req, ec);
    if (ec) {
        std::cerr << "Error sending request: " << ec.message() << std::endl;
        return;
    }

    // Receive the response
    http::response<http::dynamic_body> res;
    http::read(stream, res, ec);
    if (ec) {
        std::cerr << "Error receiving response: " << ec.message() << std::endl;
        return;
    }

    // Handle the response
    std::cout << "Response status code: " << res.result_int() << std::endl;
}

int main() {
    try {
        // Set up ASIO context and resolver
        net::io_context ioc{1};
        tcp::resolver resolver{ioc};

        // Resolve the host
        auto const results = resolver.resolve("example.com", "80");

        // Connect to the server
        tcp::socket socket{ioc};
        beast::get_lowest_layer(socket).connect(*results.begin(), ec);
        if (ec) {
            std::cerr << "Error connecting: " << ec.message() << std::endl;
            return EXIT_FAILURE;
        }

        // Perform HTTP GET request
        get_request(resolver, socket, "example.com", "/");

        // Perform HTTP POST request
        post_request(resolver, socket, "example.com", "/", "{\"key\":\"value\"}");

    } catch (std::exception const& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
