class SessionIdentifierGenerator {
public:
    SessionIdentifierGenerator(int regionId) : rng_(std::random_device()()), gen_(rng_()) {
        seedFromExternalService(regionId);
    }

    std::string generateSessionId(int range = 1000000) {
        std::lock_guard<std::mutex> lock(mutex_);
        return std::to_string(gen_.operator()(range));
    }

private:
    void seedFromExternalService(int regionId) {
        // Simulate fetching a unique seed from an external service
        auto futureSeed = std::async(std::launch::async, [regionId]() -> uint64_t {
            std::this_thread::sleep_for(std::chrono::milliseconds(10)); // Simulating network latency
            return regionId * 1000 + std::random_device()();
        });

        seed_ = futureSeed.get();
        gen_.seed(seed_);
    }

    std::mt19937 rng_;
    std::mt19937 gen_;
    uint64_t seed_;
    std::mutex mutex_;
};

int main() {
    SessionIdentifierGenerator generator(1); // Create an instance for region 1
    std::thread t1([&generator]() {
        for (int i = 0; i < 5; ++i) {
            std::cout << "Thread 1: " << generator.generateSessionId() << std::endl;
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
    });

    std::thread t2([&generator]() {
        for (int i = 0; i < 5; ++i) {
            std::cout << "Thread 2: " << generator.generateSessionId() << std::endl;
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
    });

    t1.join();
    t2.join();

    return 0;
}
