using System;
using System.Collections.Generic;
using System.Data;

public class UserQueryExecutor
{
    public IDataReader ExecuteUserQuery(IDbConnection connection, List<Tuple<string, object>> filterCriteria, int pageNumber = 1, int pageSize = 10)
    {
        // Construct the SQL query dynamically based on filter criteria
        var sqlBuilder = new System.Text.StringBuilder("SELECT * FROM Users WHERE 1=1");
        var parameters = new List<IDataParameter>();

        foreach (var criterion in filterCriteria)
        {
            if (criterion.Item2 != null && !string.IsNullOrEmpty(criterion.Item2.ToString()))
            {
                sqlBuilder.Append($" AND {criterion.Item1} = @{criterion.Item1}");
                parameters.Add(new System.Data.SqlClient.SqlParameter($"@{criterion.Item1}", criterion.Item2));
            }
        }

        // Add pagination parameters
        var pageNumberParam = new System.Data.SqlClient.SqlParameter("@PageNumber", pageNumber);
        var pageSizeParam = new System.Data.SqlClient.SqlParameter("@PageSize", pageSize);

        sqlBuilder.Append(" ORDER BY UserID OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY");

        // Calculate offset based on page number and page size
        parameters.Add(new System.Data.SqlClient.SqlParameter("@Offset", (pageNumber - 1) * pageSize));

        using (var command = connection.CreateCommand())
        {
            command.CommandText = sqlBuilder.ToString();
            command.CommandType = CommandType.Text;

            foreach (var parameter in parameters)
            {
                command.Parameters.Add(parameter);
            }

            return command.ExecuteReader(CommandBehavior.CloseConnection);
        }
    }
}
```

This code snippet demonstrates a method to dynamically build and execute an SQL query based on multiple filter criteria. It handles null and empty values for each filter, supports pagination, and efficiently manages memory and garbage collection during query execution. The method uses `IDataParameter` to prevent SQL injection attacks and ensures the connection is closed after executing the command.']

