from flask import Flask, request, jsonify
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
import requests
from retrying import retry
import json

app = Flask(__name__)
limiter = Limiter(
    app,
    key_func=get_remote_address,
    default_limits=["200 per day", "50 per hour"]
)

class Resource:
    def __init__(self, id, data):
        self.id = id
        self.data = data

# In-memory cache for resources
resource_cache = {}

@app.route('/api/v1/resources/<int:resource_id>', methods=['PUT'])
@limiter.limit("20 per minute")
def update_resource(resource_id):
    try:
        resource_data = request.get_json()
        if not resource_data:
            return jsonify({"error": "No data provided"}), 400

        # Update the in-memory cache
        if resource_id in resource_cache:
            resource_cache[resource_id].data = resource_data
            return jsonify({"message": f"Resource {resource_id} updated successfully", "data": resource_cache[resource_id].data}), 200
        else:
            return jsonify({"error": f"Resource {resource_id} not found"}), 404

    except Exception as e:
        app.logger.error(f"Error updating resource: {e}")
        return jsonify({"error": "Internal server error"}), 500

@app.route('/api/v1/resources/<int:resource_id>', methods=['DELETE'])
@limiter.limit("20 per minute")
def delete_resource(resource_id):
    try:
        if resource_id in resource_cache:
            del resource_cache[resource_id]
            return jsonify({"message": f"Resource {resource_id} deleted successfully"}), 200
        else:
            return jsonify({"error": f"Resource {resource_id} not found"}), 404

    except Exception as e:
        app.logger.error(f"Error deleting resource: {e}")
        return jsonify({"error": "Internal server error"}), 500

@retry(stop_max_attempt_number=5, wait_exponential_multiplier=1000)
def fetch_external_data(url):
    response = requests.get(url)
    response.raise_for_status()
    return response.json()

if __name__ == '__main__':
    app.run(debug=True)
```

