public List<XmlElement> FindElementsByXPath(XmlDocument xmlDoc, string elementName)
{
    List<XmlElement> result = new List<XmlElement>();
    try
    {
        XmlNodeList nodes = xmlDoc.DocumentElement.SelectNodes($"//{elementName}");
        if (nodes != null)
        {
            foreach (XmlNode node in nodes)
            {
                if (node is XmlElement element)
                {
                    result.Add(element);
                }
            }
        }
        else
        {
            // If no elements are found, return all non-matching elements
            XmlNodeList allNodes = xmlDoc.DocumentElement.SelectNodes($"//*");
            foreach (XmlNode node in allNodes)
            {
                if (!(node is XmlElement element))
                {
                    result.Add((XmlElement)node);
                }
            }
        }
    }
    catch (XmlException ex)
    {
        Console.WriteLine($"XML parsing error: {ex.Message}");
    }
    catch (XPathException ex)
    {
        Console.WriteLine($"XPath evaluation error: {ex.Message}");
    }

    return result;
}
