use std::env;
use std::fs::{self, DirBuilder};
use log::{info, warn};

pub fn create_directory_and_set_env_var(dir_name: &str) -> Result<String, String> {
    if env::var_exists(dir_name) {
        let current_dir = env::current_dir().map_err(|e| format!("Failed to get current directory: {}", e))?;
        info!("Environment variable {} is already set. Current directory: {:?}", dir_name, current_dir);
        return Ok(current_dir.to_str().unwrap().to_string());
    }

    let dir_path = env::var_os(dir_name).and_then(|p| p.into_string_lossy().into_owned()).unwrap_or_else(|| dir_name.to_string());

    DirBuilder::new()
        .recursive(true)
        .create(&dir_path)
        .map_err(|e| format!("Failed to create directory {}: {}", dir_path, e))?;

    env::set_var(dir_name, &dir_path);
    info!("Created directory: {} and set environment variable {}", dir_path, dir_name);

    Ok(dir_path)
}
```

