['```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;

public class StringHasher {
    private static final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private static boolean isCaseSensitive = true;

    public static void setCaseSensitivity(boolean caseSensitive) {
        isCaseSensitive = caseSensitive;
    }

    public static String hash(String input, boolean toUpperCase) throws NoSuchAlgorithmException {
        if (input == null || input.isEmpty()) {
            return "";
        }

        String key = generateKey(input);
        if (cache.containsKey(key)) {
            return cache.get(key);
        }

        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }

        String result = toUpperCase ? hexString.toString().toUpperCase() : hexString.toString();
        cache.put(key, result);
        return result;
    }

    private static String generateKey(String input) {
        return isCaseSensitive ? input : input.toLowerCase();
    }

    public static boolean compareHashes(String hash1, String hash2) {
        if (hash1 == null || hash2 == null) {
            return false;
        }
        return hash1.equals(hash2);
    }
}
