import os
import logging
from concurrent.futures import ThreadPoolExecutor
from typing import Dict

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def process_directory(directory_path: str, extensions: list) -> Dict[str, int]:
    def process_file(file_path):
        try:
            with open(file_path, 'r', encoding='utf-8') as file:
                content = file.read()
                return os.path.basename(file_path), len(content)
        except FileNotFoundError:
            logger.error(f"File not found: {file_path}")
            return None
        except Exception as e:
            logger.error(f"Error processing file {file_path}: {e}")
            return None

    def is_valid_file(file_name):
        _, ext = os.path.splitext(file_name)
        return ext in extensions

    try:
        if not os.path.isdir(directory_path):
            raise ValueError("The provided path is not a valid directory.")

        files_to_process = [
            os.path.join(directory_path, f) for f in os.listdir(directory_path)
            if os.path.isfile(os.path.join(directory_path, f)) and is_valid_file(f)
        ]

        with ThreadPoolExecutor(max_workers=10) as executor:
            results = list(executor.map(process_file, files_to_process))

    except Exception as e:
        logger.error(f"Error processing directory: {e}")
        return {}

    return {name: length for name, length in results if name and length}

# Example usage
if __name__ == "__main__":
    report = process_directory('/path/to/directory', ['.txt'])
    print(report)
