    const label = testLabels[i];
    const testFunction = f[i];

    tests.push(async () => {
      try {
        blueslip.reset(); // Reset mocking library
        console.log(`Starting test: ${moduleName} - ${label}`, new Date());

        const startTime = performance.now();
        await testFunction(configService); // Execute test with async support
        const endTime = performance.now();

        console.log(`Test completed: ${moduleName} - ${label}`, `Time taken: ${endTime - startTime} ms`);
      } catch (error) {
        console.error(`Error in test: ${moduleName} - ${label}`, error);
      }
    });
  }

  // Implement dynamic concurrency control and resource utilization
  const maxConcurrentTests = Math.min(testLabels.length, 10); // Example limit
  const executor = async () => {
    while (tests.length > 0) {
      const concurrentTests = tests.splice(0, maxConcurrentTests);
      await Promise.all(concurrentTests.map(test => test()));
    }
  };

  await executor();
