function refreshDialogFields(resourceId, url, fieldNames, callback) {
  var processedFields = {};

  function sendFieldMessage(fieldName) {
    window.parent.postMessage({ resourceId: resourceId, fieldName: fieldName }, '*');
    processedFields[fieldName] = true;
  }

  angular.forEach($scope.dialogFields, function(field) {
    if (fieldNames.indexOf(field.name) !== -1 && !processedFields[field.name]) {
      sendFieldMessage(field.name);
    }
  });

  window.addEventListener('message', function(event) {
    if (event.origin !== 'http://example.com') return; // Replace with actual origin
    var response = JSON.parse(event.data);
    if (response.status === 'success' && processedFields[response.fieldName]) {
      var field = $scope.dialogFields.find(f => f.name === response.fieldName);
      if (field) {
        field.value = response.result;
      }
    } else if (!processedFields[response.fieldName]) {
      $scope.dialogFields.push({ name: response.fieldName, value: response.result });
      processedFields[response.fieldName] = true;
    }
    callback(response);
  });
}
