import java.util.concurrent.*;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;

public class DataCollectionService {

    private final BlockingQueue<String> buffer;
    private final int bufferSize;
    private final KafkaProducer<String, String> producer;
    private final ExecutorService executor;
    private volatile boolean isPaused = false;

    public DataCollectionService(int bufferSize, Properties kafkaProps) {
        this.bufferSize = bufferSize;
        this.buffer = new ArrayBlockingQueue<>(bufferSize);
        this.producer = new KafkaProducer<>(kafkaProps);
        this.executor = Executors.newSingleThreadExecutor();
    }

    public void start() {
        executor.submit(() -> {
            while (true) {
                try {
                    if (!isPaused) {
                        String data = fetchDataFromAPI(); // Simulated API call
                        buffer.put(data);
                        sendNotification("Data received: " + data);
                    }
                    Thread.sleep(getRandomDelay());
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });
    }

    public void pause() {
        isPaused = true;
    }

    public void resume() {
        isPaused = false;
    }

    private String fetchDataFromAPI() throws InterruptedException {
        // Simulated data fetching
        return "Data at " + System.currentTimeMillis();
    }

    private int getRandomDelay() throws InterruptedException {
        // Random delay between 100ms and 500ms
        Thread.sleep(100 + (int) (Math.random() * 400));
        return (int) (100 + Math.random() * 400);
    }

    private void sendNotification(String message) {
        producer.send(new ProducerRecord<>("notifications", null, message));
    }

    public void stop() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
        producer.close();
    }

    public static void main(String[] args) {
        Properties kafkaProps = new Properties();
        kafkaProps.put("bootstrap.servers", "localhost:9092");
        kafkaProps.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        kafkaProps.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");

        DataCollectionService service = new DataCollectionService(100, kafkaProps);
        service.start();

        // Simulate pausing and resuming
        try {
            Thread.sleep(5000);
            service.pause();
            Thread.sleep(2000);
            service.resume();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        service.stop();
    }
}
