    private static final ConcurrentHashMap<String, Integer> FAILED_ATTEMPTS = new ConcurrentHashMap<>();

    static {
        // Initialize allowed domains
        ALLOWED_DOMAINS.add("example.com");
        ALLOWED_DOMAINS.add("api.example.com");
    }

    public boolean validateURL(String url) {
        if (url == null || url.isEmpty()) {
            return false;
        }

        String userId = getUserIdFromRequest(); // Implement this method to retrieve user ID
        int maxAttempts = 5;

        if (FAILED_ATTEMPTS.getOrDefault(userId, 0) >= maxAttempts) {
            return false;
        }

        try {
            URI uri = new URI(url);
            String protocol = uri.getScheme();
            String domain = uri.getHost();

            if (!isValidProtocol(protocol) || !ALLOWED_DOMAINS.contains(domain)) {
                incrementFailedAttempts(userId);
                return false;
            }
        } catch (URISyntaxException e) {
            incrementFailedAttempts(userId);
            return false;
        }

        // Integrate with external rate-limiting service here

        return true;
    }

    private boolean isValidProtocol(String protocol) {
        // Implement validation for allowed protocols
        return "http".equals(protocol) || "https".equals(protocol);
    }

    private void incrementFailedAttempts(String userId) {
        FAILED_ATTEMPTS.put(userId, FAILED_ATTEMPTS.getOrDefault(userId, 0) + 1);
    }

    private String getUserIdFromRequest() {
        // Implement logic to retrieve user ID from the request
        return "user123";
    }
}
