import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class ThemeBitmapCache {

    private static final String CACHE_ROOT = getDynamicCachePath();
    private static final int MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB
    private Map<String, File> cacheMap = new HashMap<>();
    private Object lock = new Object();

    public ThemeBitmapCache() {
        ensureDefaultThemeDirectory();
        validateAndAdjustPermissions();
    }

    public void addOrUpdateTheme(String themeId, byte[] bitmapData) throws IOException, NoSuchAlgorithmException {
        synchronized (lock) {
            File cachedFile = getOrCreateCachedFile(themeId);
            if (bitmapData.length > MAX_FILE_SIZE) {
                throw new IOException("Theme file exceeds maximum size limit.");
            }
            try (FileOutputStream fos = new FileOutputStream(cachedFile)) {
                fos.write(bitmapData);
            }
            cacheMap.put(themeId, cachedFile);
        }
    }

    public byte[] getTheme(String themeId) throws IOException {
        File file = cacheMap.get(themeId);
        if (file == null || !file.exists()) {
            throw new IOException("Theme not found.");
        }
        try (FileInputStream fis = new FileInputStream(file)) {
            return fis.readAllBytes();
        }
    }

    public void removeTheme(String themeId) {
        synchronized (lock) {
            File file = cacheMap.remove(themeId);
            if (file != null && file.exists()) {
                file.delete();
            }
        }
    }

    private File getOrCreateCachedFile(String themeId) throws IOException, NoSuchAlgorithmException {
        String hash = calculateHash(themeId);
        File cachedFile = new File(CACHE_ROOT, hash + ".png");
        if (!cachedFile.exists()) {
            cachedFile.createNewFile();
        }
        return cachedFile;
    }

    private String calculateHash(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = md.digest(input.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private static String getDynamicCachePath() {
        // Implement a secure, dynamic approach to determine the installation path
        // Avoid common pitfalls like hardcoded sensitive information
        return "/path/to/cache/directory";
    }

    private void ensureDefaultThemeDirectory() {
        File cacheDir = new File(CACHE_ROOT);
        if (!cacheDir.exists()) {
            cacheDir.mkdirs();
        }
    }

    private void validateAndAdjustPermissions() {
        // Implement file permission validation and adjustment logic here
        // Ensure that only authorized processes can modify theme files
        // Balance security with user convenience
    }

    public void logError(String message) {
        System.err.println("Error: " + message);
    }
}
