<?php

// Define a class to handle configuration loading
class ConfigLoader {
    private $cache = [];
    private $apiUrl;
    private $apiClient;

    public function __construct($apiUrl, $apiKey) {
        $this->apiUrl = $apiUrl . '?key=' . urlencode($apiKey);
        $this->apiClient = new \GuzzleHttp\Client();
    }

    public function getConfig($key) {
        if (!isset($this->cache[$key])) {
            try {
                $response = $this->apiClient->request('GET', $this->apiUrl);
                $configData = json_decode($response->getBody(), true);

                // Store the configuration in cache
                $this->cache[$key] = $configData[$key];
            } catch (\Exception $e) {
                // Log error without exposing sensitive information
                error_log('Failed to load config from API: ' . $e->getMessage());
                throw new \RuntimeException('Unable to retrieve configuration');
            }
        }

        return $this->cache[$key];
    }

    public function refreshConfig($key = null) {
        if ($key === null) {
            // Invalidate all cache
            $this->cache = [];
        } else {
            // Invalidate specific config key
            unset($this->cache[$key]);
        }
    }
}

// Example usage in a web application
$apiUrl = 'https://api.example.com/config';
$apiKey = 'your_api_key_here';

$configLoader = new ConfigLoader($apiUrl, $apiKey);

try {
    // Retrieve specific configuration setting
    $databaseHost = $configLoader->getConfig('database_host');
    echo "Database Host: $databaseHost";
} catch (\RuntimeException $e) {
    echo $e->getMessage();
}

// Periodically refresh cache for frequently accessed settings
$configLoader->refreshConfig('database_host');

?>
```

This code snippet demonstrates a basic implementation of a configuration loader in PHP that uses an external API to fetch configuration settings. It includes caching mechanisms, error handling, and methods to refresh specific or all cached configurations. The use of Guzzle HTTP client ensures that the script can handle transient failures gracefully by logging errors without exposing sensitive information.']

