function processFileAndGenerateReport($reportLength, $characterSet, $filePath) {
    // Generate random string for report identifier
    $reportId = substr(str_shuffle(str_repeat($characterSet, ceil($reportLength / strlen($characterSet)))), 1, $reportLength);

    // Initialize an array to hold the processed reports
    $processedReports = [];

    try {
        // Read the file contents synchronously
        $fileContents = file_get_contents($filePath);

        if ($fileContents === false) {
            throw new Exception("Failed to read file.");
        }

        // Parse JSON data from the file
        $reportsData = json_decode($fileContents, true);

        if (json_last_error() !== JSON_ERROR_NONE) {
            throw new Exception("Malformed JSON in the file.");
        }

        // Filter and process reports
        foreach ($reportsData as $report) {
            if (// Add your filtering criteria here, e.g., date range, status
                isset($report['title']) && isset($report['summary']) && isset($report['metadata'])) {

                $reportBody = $report['title'] . "\n" .
                              $report['summary'] . "\n" .
                              json_encode($report['metadata'], JSON_PRETTY_PRINT) . "\n";

                $processedReports[] = $reportBody;
            }
        }
    } catch (Exception $e) {
        error_log("Error processing file: " . $e->getMessage());
        return [
            'reportId' => $reportId,
            'reports' => [],
            'count' => 0
        ];
    }

    // Return the report ID, processed reports, and count
    return [
        'reportId' => $reportId,
        'reports' => $processedReports,
        'count' => count($processedReports)
    ];
}

