        snprintf(request, sizeof(request), "GET /api/user HTTP/1.1\r\nHost: %s\r\nAuthorization: Bearer %s\r\n", ip_address, client.access_token);

        if(send_request(request, &client) == 0) {
            return 0; // Success
        }

        attempts++;
    }

    return -1; // Failed after max retries
}

