<?php

class PasswordUpdater {
    private $database;
    private $authService;

    public function __construct($dbConfig, $authService) {
        $this->database = new DatabaseConnection($dbConfig);
        $this->authService = $authService;
    }

    public function updatePassword($userId, $currentPassword, $newPassword) {
        // Authenticate user
        if (!$this->authService->authenticate($userId, $currentPassword)) {
            $this->logAttempt(false, $userId, $_SERVER['REMOTE_ADDR'], 'Authentication failed');
            return ['status' => 'error', 'message' => 'Invalid credentials'];
        }

        // Check password strength
        if (!$this->isStrongPassword($newPassword)) {
            $this->logAttempt(false, $userId, $_SERVER['REMOTE_ADDR'], 'Password does not meet strength requirements');
            return ['status' => 'error', 'message' => 'Password is too weak'];
        }

        // Update password in database
        try {
            $this->database->beginTransaction();
            $this->updateUserPassword($userId, $newPassword);
            $this->logAttempt(true, $userId, $_SERVER['REMOTE_ADDR'], 'Success');
            $this->database->commit();
            return ['status' => 'success', 'message' => 'Password updated successfully'];
        } catch (Exception $e) {
            $this->database->rollBack();
            $this->logAttempt(false, $userId, $_SERVER['REMOTE_ADDR'], 'Database error: ' . $e->getMessage());
            return ['status' => 'error', 'message' => 'An error occurred while updating the password'];
        }
    }

    private function isStrongPassword($password) {
        // Implement dynamic password strength policy based on historical usage
        return strlen($password) >= 8 && preg_match('/[a-z]/', $password) && preg_match('/[A-Z]/', $password) && preg_match('/\d/', $password);
    }

    private function updateUserPassword($userId, $newPassword) {
        // Update user password in database
        $this->database->query("UPDATE users SET password = :password WHERE id = :id", ['id' => $userId, 'password' => password_hash($newPassword, PASSWORD_DEFAULT)]);
    }

    private function logAttempt($success, $userId, $ipAddress, $message) {
        // Log each password update attempt
        $this->database->query("INSERT INTO password_update_logs (user_id, ip_address, success, message, timestamp) VALUES (:user_id, :ip_address, :success, :message, NOW())", [
            'user_id' => $userId,
            'ip_address' => $ipAddress,
            'success' => $success ? 1 : 0,
            'message' => $message
        ]);
    }
}

interface DatabaseConnection {
    public function beginTransaction();
    public function commit();
    public function rollBack();
    public function query($sql, $params = []);
}

interface AuthService {
    public function authenticate($userId, $password);
}

