#define TOKEN_LENGTH 16

unsigned long generate_session_token(unsigned char *token, unsigned long *token_count) {
    static unsigned long last_token = 0;
    static time_t last_time = 0;

    // Initialize token and count on first call
    if (*token == NULL && *token_count == 0) {
        *token = (unsigned char *)malloc(TOKEN_LENGTH);
        if (!*token) {
            return -1; // Memory allocation failed
        }
        srand(time(NULL));
        *token_count = 0;
        last_token = rand();
        last_time = time(NULL);
    }

    // Generate a new token if it's been more than 24 hours since the last one
    if (time(NULL) - last_time > 86400) {
        srand(time(NULL));
        last_token = rand();
        last_time = time(NULL);
        (*token_count)++;
    } else {
        (*token_count)++;
    }

    // Ensure uniqueness within a 24-hour period
    while (last_token == *token_count) {
        (*token_count)++;
    }

    // Convert token count to bytes and store in the token array
    for (int i = 0; i < TOKEN_LENGTH; i++) {
        token[i] = (unsigned char)(*token_count >> (i * 8));
    }

    return *token_count;
}

void free_session_token(unsigned char *token) {
    if (token != NULL) {
        free(token);
    }
}
