using System;
using System.Security.Cryptography;

public class RandomValueGenerator
{
    private readonly Random _random = new Random();
    private readonly RNGCryptoServiceProvider _rngCrypto = new RNGCryptoServiceProvider();

    public int LowerBound { get; set; }
    public int UpperBound { get; set; }

    public RandomValueGenerator(int lowerBound, int upperBound)
    {
        if (lowerBound > upperBound)
            throw new ArgumentException("Lower bound cannot be greater than upper bound.");

        LowerBound = lowerBound;
        UpperBound = upperBound;
    }

    public float NextFloat()
    {
        return _random.NextSingle() * (UpperBound - LowerBound) + LowerBound;
    }

    public int NextInt()
    {
        if (LowerBound == UpperBound)
            return LowerBound;

        return _random.Next(LowerBound, UpperBound + 1);
    }

    public int NextSecureInt()
    {
        if (LowerBound == UpperBound)
            return LowerBound;

        byte[] buffer = new byte[4];
        _rngCrypto.GetBytes(buffer);
        int randomValue = BitConverter.ToInt32(buffer, 0);

        // Scale the random value to fit within the specified range
        int range = UpperBound - LowerBound + 1;
        return (randomValue % range) + LowerBound;
    }
}
