// Define a structure to hold unique error messages
typedef struct {
    char** messages;
    size_t count;
} ErrorMessages;

// Function to hash an error message (simplified example)
unsigned long hash(const char* str) {
    unsigned long h = 0;
    while (*str) {
        h = h * 31 + *str++;
    }
    return h % 1024; // Assuming a table size of 1024 for simplicity
}

// Function to check if an error message already exists in the set
int contains(const char* msg, ErrorMessages* err) {
    unsigned long idx = hash(msg);
    for (size_t i = 0; i < err->count; ++i) {
        if (strcmp(err->messages[i], msg) == 0) {
            return 1;
        }
    }
    return 0;
}

// Function to add an error message to the set
void add(const char* msg, ErrorMessages* err) {
    unsigned long idx = hash(msg);
    for (size_t i = 0; i < err->count; ++i) {
        if (strcmp(err->messages[i], msg) == 0) {
            return; // Avoid adding duplicates
        }
    }
    char* new_msg = strdup(msg); // Duplicate the message string
    err->messages[err->count++] = new_msg;
}

// Function to process log files in a directory
ErrorMessages* process_logs(const char* dir_path, size_t* total_count) {
    DIR *dir;
    struct dirent *entry;
    ErrorMessages *error_set = (ErrorMessages*)calloc(1, sizeof(ErrorMessages));
    error_set->messages = (char**)malloc(1024 * sizeof(char*)); // Initial capacity of 1024
    error_set->count = 0;

    if ((dir = opendir(dir_path)) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_type == DT_REG && strstr(entry->d_name, ".log") != NULL) {
                char file_path[1024];
                snprintf(file_path, sizeof(file_path), "%s/%s", dir_path, entry->d_name);
                FILE *file = fopen(file_path, "r");
                if (file != NULL) {
                    char buffer[1024];
                    while (fgets(buffer, sizeof(buffer), file)) {
                        if (strstr(buffer, "ERROR") != NULL) {
                            add(buffer, error_set); // Add only error messages
                        }
                    }
                    fclose(file);
                }
            }
        }
        closedir(dir);
    } else {
        perror("opendir");
        free(error_set->messages);
        free(error_set);
        return NULL;
    }

    *total_count = error_set->count;
    return error_set;
}

// Example usage
int main() {
    size_t total_errors = 0;
    ErrorMessages* errors = process_logs("/path/to/logs", &total_errors);

    if (errors != NULL) {
        printf("Total unique error messages: %zu\n", total_errors);
        for (size_t i = 0; i < errors->count; ++i) {
            printf("%s", errors->messages[i]);
            free(errors->messages[i]); // Clean up dynamically allocated strings
        }
        free(errors->messages); // Free the array of pointers
        free(errors); // Free the structure itself
    }

    return 0;
}
