#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tiffio.h>
#include <openssl/md5.h>
#include "logging.h"

typedef struct {
    uint16 bitsPerSample;
    uint16 samplesPerPixel;
    uint32 extraSamples;
    unsigned char *md5Hash;
} ImageMetadata;

int processTiffImage(const char *filePath, ImageMetadata *metadata) {
    TIFF *tiff = TIFFOpen(filePath, "r");
    if (!tiff) {
        logError("Failed to open TIFF file: %s", filePath);
        return -1; // Error opening file
    }

    metadata->bitsPerSample = TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE);
    metadata->samplesPerPixel = TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL);
    metadata->extraSamples = TIFFGetFieldDefaulted(tiff, TIFFTAG_EXTRASAMPLES);

    if (metadata->bitsPerSample != 1 && metadata->bitsPerSample != 2 &&
        metadata->bitsPerSample != 4 && metadata->bitsPerSample != 8 &&
        metadata->bitsPerSample != 16) {
        logError("Unsupported bits per sample: %d", metadata->bitsPerSample);
        TIFFClose(tiff);
        return -2; // Unsupported bit depth
    }

    uint32 width, height;
    TIFFGetField(tiff, TIFFTAG_IMAGEWIDTH, &width);
    TIFFGetField(tiff, TIFFTAG_IMAGELENGTH, &height);

    metadata->md5Hash = (unsigned char *)malloc(16);
    MD5_CTX md5Context;
    MD5_Init(&md5Context);

    uint32 scanlineSize = TIFFScanlineSize(tiff);
    for (uint32 row = 0; row < height; row++) {
        void *buffer = _TIFFmalloc(scanlineSize);
        if (!buffer) {
            logError("Failed to allocate memory for scanline");
            TIFFClose(tiff);
            free(metadata->md5Hash);
            return -3; // Memory allocation failed
        }
        TIFFReadScanline(tiff, buffer, row, 0);
        MD5_Update(&md5Context, buffer, scanlineSize);
        _TIFFfree(buffer);
    }

    MD5_Final(metadata->md5Hash, &md5Context);
    TIFFClose(tiff);

    logInfo("Parsed image metadata: bitsPerSample=%d, samplesPerPixel=%d, extraSamples=%u", 
             metadata->bitsPerSample, metadata->samplesPerPixel, metadata->extraSamples);

    return 0; // Success
}
