#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FILENAME_LENGTH 30
#define NEW_FILE_TYPE_LENGTH 3
#define MAX_TRANSFORMED_FILENAME_LENGTH 50

typedef struct {
    char filename[MAX_FILENAME_LENGTH];
} Filename;

int is_valid_filename(const char *filename) {
    if (strlen(filename) > MAX_FILENAME_LENGTH || strlen(filename) == 0) return 0;
    for (int i = 0; i < strlen(filename); i++) {
        if (!isalnum((unsigned char)filename[i]) && filename[i] != '.') return 0;
    }
    return 1;
}

void transform_filename(Filename *filename, const char *new_file_type, Filename **transformed_filenames, int *num_transformed_files) {
    if (strlen(new_file_type) != NEW_FILE_TYPE_LENGTH) return;

    char base_name[MAX_FILENAME_LENGTH];
    strncpy(base_name, filename->filename, MAX_FILENAME_LENGTH);
    base_name[MAX_FILENAME_LENGTH - 1] = '\0';

    char new_filename[MAX_TRANSFORMED_FILENAME_LENGTH];
    int digits_count = strlen(base_name);

    snprintf(new_filename, MAX_TRANSFORMED_FILENAME_LENGTH, "%s_%d%s", base_name, digits_count, new_file_type);

    if (strlen(new_filename) > MAX_TRANSFORMED_FILENAME_LENGTH) {
        new_filename[MAX_TRANSFORMED_FILENAME_LENGTH - 1] = '\0';
    }

    // Check for uniqueness and add to list
    int is_unique = 1;
    for (int i = 0; i < *num_transformed_files; i++) {
        if (strcmp(new_filename, transformed_filenames[i]->filename) == 0) {
            is_unique = 0;
            break;
        }
    }

    if (is_unique && strlen(new_filename) > 0) {
        transformed_filenames[*num_transformed_files] = (Filename *)malloc(sizeof(Filename));
        strcpy(transformed_filenames[*num_transformed_files]->filename, new_filename);
        (*num_transformed_files)++;
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <new_file_type> [filenames...]\n", argv[0]);
        return 1;
    }

    const char *new_file_type = argv[1];
    Filename **transformed_filenames = (Filename **)malloc(100 * sizeof(Filename *));
    int num_transformed_files = 0;

    for (int i = 2; i < argc && num_transformed_files < 100; i++) {
        if (is_valid_filename(argv[i])) {
            transform_filename((Filename *)argv[i], new_file_type, transformed_filenames, &num_transformed_files);
        }
    }

    printf("Transformed Filenames:\n");
    for (int i = 0; i < num_transformed_files; i++) {
        printf("%s\n", transformed_filenames[i]->filename);
        free(transformed_filenames[i]);
    }

    free(transformed_filenames);

    return 0;
}
