#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

#define MAX_COMMAND_LENGTH 256

int execute_shell_command(const char *command, const char *directory) {
    pid_t pid;
    int status;

    // Validate and sanitize the command string
    if (strchr(command, ';') != NULL || strchr(command, '|') != NULL || strchr(command, '&') != NULL) {
        fprintf(stderr, "Error: Invalid characters in command.\n");
        return 0;
    }

    // Change to the specified directory if valid
    if (directory != NULL && chdir(directory) != 0) {
        perror("Error: Changing directory failed");
        return 0;
    }

    // Fork a new process to execute the command
    pid = fork();
    if (pid == -1) {
        perror("Error: Fork failed");
        return 0;
    } else if (pid == 0) {
        // Child process
        char *args[MAX_COMMAND_LENGTH / 2 + 1];
        char *token = strtok((char *)command, " ");
        int i = 0;

        while (token != NULL && i < MAX_COMMAND_LENGTH / 2) {
            args[i++] = token;
            token = strtok(NULL, " ");
        }
        args[i] = NULL;

        // Execute the command
        if (execvp(args[0], args) == -1) {
            perror("Error: Command execution failed");
            exit(EXIT_FAILURE);
        }
    } else {
        // Parent process
        // Wait for the child process to finish or log the attempt
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            return 1;
        } else {
            fprintf(stderr, "Error: Command execution failed with status %d\n", WEXITSTATUS(status));
            return 0;
        }
    }

    return 0;
}
