import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class DirectoryLister {

    private static final List<String> ALLOWED_DIRECTORIES = Arrays.asList("safe_dir1", "safe_dir2");
    private ExecutorService executorService = Executors.newFixedThreadPool(10);

    public void listDirectory(String userInput) {
        Path path = Paths.get(userInput);
        if (isValidDirectory(path)) {
            Future<?> future = executorService.submit(() -> {
                try {
                    Process process = Runtime.getRuntime().exec("dir " + userInput); // Adjust command for different OS
                    BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                    String line;
                    while ((line = reader.readLine()) != null) {
                        System.out.println(line);
                    }
                    int exitCode = process.waitFor();
                    System.out.println("Command exited with code: " + exitCode);
                } catch (IOException | InterruptedException e) {
                    e.printStackTrace();
                }
            });
            // Optionally handle future to manage task completion
        } else {
            System.out.println("Invalid directory or access denied.");
        }
    }

    private boolean isValidDirectory(Path path) {
        if (!Files.exists(path) || !Files.isDirectory(path)) {
            return false;
        }
        Path normalizedPath = path.normalize();
        for (String allowedDir : ALLOWED_DIRECTORIES) {
            if (normalizedPath.startsWith(allowedDir)) {
                return true;
            }
        }
        return false;
    }

    public void shutdown() {
        executorService.shutdown();
    }

    public static void main(String[] args) {
        DirectoryLister directoryLister = new DirectoryLister();
        // Example usage
        directoryLister.listDirectory("C:\\safe_dir1\\subdir");
        // Shutdown the application when done
        directoryLister.shutdown();
    }
}
