using System.Threading.Tasks;
using System.Security.Cryptography;

public class EncryptionService
{
    private const string ApiUrl = "https://api.example.com/encryption";
    private readonly HttpClient _httpClient;
    private readonly List<Tuple<string, string>> _whitelist;

    public EncryptionService(List<Tuple<string, string>> whitelist)
    {
        _whitelist = whitelist;
        _httpClient = new HttpClient();
    }

    public async Task DecryptMessageAsync(string base64Password, string base64EncryptedMessage, Connection connection, Action<string, bool> callback)
    {
        try
        {
            if (string.IsNullOrEmpty(connection.Title) || connection.Dependency == null)
            {
                callback("Connection is invalid.", false);
                return;
            }

            var credentials = await FetchCredentialsAsync();
            if (!IsValidCredential(credentials))
            {
                callback("Invalid credentials provided.", false);
                return;
            }

            var passwordBytes = Convert.FromBase64String(base64Password);
            var encryptedMessageBytes = Convert.FromBase64String(base64EncryptedMessage);
            var decryptedMessage = Decrypt(encryptedMessageBytes, credentials.Key, credentials.IV);

            callback(decryptedMessage, true);
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error processing message: {ex.Message}");
            callback("An error occurred during the decryption process.", false);
        }
    }

    private async Task<CryptoCredentials> FetchCredentialsAsync()
    {
        try
        {
            using var response = await _httpClient.GetAsync(ApiUrl, HttpCompletionOption.ResponseHeadersRead);
            response.EnsureSuccessStatusCode();

            var content = await response.Content.ReadAsStringAsync();
            // Assuming the API returns JSON with "key" and "iv"
            var credentials = JsonConvert.DeserializeObject<CryptoCredentials>(content);
            return credentials;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error fetching credentials: {ex.Message}");
            throw new InvalidOperationException("Failed to fetch encryption key and IV.", ex);
        }
    }

    private bool IsValidCredential(CryptoCredentials credentials)
    {
        return _whitelist.Any(w => w.Item1 == credentials.Key && w.Item2 == credentials.IV);
    }

    private string Decrypt(byte[] encryptedData, byte[] key, byte[] iv)
    {
        using var tripleDES = TripleDES.Create();
        tripleDES.Key = key;
        tripleDES.IV = iv;

        using var msDecrypt = new MemoryStream(encryptedData);
        using var csDecrypt = new CryptoStream(msDecrypt, tripleDES.CreateDecryptor(), CryptoStreamMode.Read);
        using var srDecrypt = new StreamReader(csDecrypt);

        return srDecrypt.ReadToEnd();
    }
}

public class Connection
{
    public string Title { get; set; }
    public object Dependency { get; set; } // Placeholder for actual dependency object
}

public class CryptoCredentials
{
    public string Key { get; set; }
    public string IV { get; set; }
}
