public class ConfigValidator {

    private final CredentialService credentialService;
    private final DatabaseConnector databaseConnector;

    public ConfigValidator(CredentialService credentialService, DatabaseConnector databaseConnector) {
        this.credentialService = credentialService;
        this.databaseConnector = databaseConnector;
    }

    public List<ValidationResult> validateConfigs(List<ConfigObject> configObjects) {
        return configObjects.stream()
                .map(this::validateConfig)
                .collect(Collectors.toList());
    }

    private ValidationResult validateConfig(ConfigObject configObject) {
        try {
            // Validate URL
            if (!isValidUrl(configObject.getUrl())) {
                return new ValidationResult(false, "Invalid database connection URL");
            }

            // Retrieve credentials from secure service
            String username = credentialService.getUsername(configObject.getIdentifier());
            String password = credentialService.getPassword(configObject.getIdentifier());

            if (username == null || password == null) {
                return new ValidationResult(false, "Failed to retrieve credentials");
            }

            // Attempt connection
            boolean isConnected = databaseConnector.connect(configObject.getUrl(), username, password);
            if (!isConnected) {
                return new ValidationResult(false, "Database connection failed");
            }

            return new ValidationResult(true, "Validation successful");

        } catch (Exception e) {
            logError(e);
            return new ValidationResult(false, "An error occurred during validation: " + e.getMessage());
        }
    }

    private boolean isValidUrl(String url) {
        // Basic URL check (not exhaustive)
        try {
            new java.net.URL(url).toURI();
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    private void logError(Exception e) {
        // Log error for monitoring and debugging
