using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class Base64Decoder
{
    private readonly ICryptoService cryptoService;

    public Base64Decoder(ICryptoService cryptoService)
    {
        this.cryptoService = cryptoService ?? throw new ArgumentNullException(nameof(cryptoService));
    }

    public async Task<List<string>> DecryptMessagesAsync(string base64EncodedString, string delimiter)
    {
        var decryptedMessages = new List<string>();
        try
        {
            // Split the Base64-encoded string into individual messages based on the delimiter
            var messageArray = base64EncodedString.Split(delimiter);

            await Parallel.ForEachAsync(messageArray, async (message, cancellationToken) =>
            {
                try
                {
                    // Decode the Base64 string to a byte array
                    var encryptedBytes = Convert.FromBase64String(message.Trim());
                    // Retrieve keys and IVs from external data source with fallback mechanism
                    var (key, iv) = await cryptoService.GetKeyAndIVAsync(cancellationToken);
                    // Decrypt the message using Triple DES
                    var decryptedBytes = await cryptoService.DecryptAsync(encryptedBytes, key, iv, cancellationToken);
                    // Convert the decrypted bytes back to a string and add to the list
                    decryptedMessages.Add(Encoding.UTF8.GetString(decryptedBytes));
                }
                catch (Exception ex)
                {
                    // Log error and continue processing remaining messages
                    Console.WriteLine($"Error decrypting message: {ex.Message}");
                }
            });
        }
        catch (Exception ex)
        {
            // Handle potential exceptions gracefully
            Console.WriteLine($"General error: {ex.Message}");
        }

        return decryptedMessages;
    }
}

public interface ICryptoService
{
    Task<(byte[], byte[])> GetKeyAndIVAsync(CancellationToken cancellationToken);
    Task<byte[]> DecryptAsync(byte[] encryptedData, byte[] key, byte[] iv, CancellationToken cancellationToken);
}

