using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AesCbcDecryptor
{
    public static byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv, PaddingMode paddingMode = PaddingMode.PKCS7)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Padding = paddingMode;

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            using (MemoryStream msDecrypt = new MemoryStream(ciphertext))
            using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
            {
                byte[] decryptedBytes = new byte[ciphertext.Length];
                int bytesDecrypted = csDecrypt.Read(decryptedBytes, 0, decryptedBytes.Length);
                Array.Resize(ref decryptedBytes, bytesDecrypted);
                return decryptedBytes;
            }
        }
    }

    public static byte[] DecryptFromBase64(string base64Ciphertext, byte[] key, byte[] iv, PaddingMode paddingMode = PaddingMode.PKCS7)
    {
        byte[] ciphertext = Convert.FromBase64String(base64Ciphertext);
        return Decrypt(ciphertext, key, iv, paddingMode);
    }

    public static string DecryptToString(string base64Ciphertext, byte[] key, byte[] iv, Encoding encoding, PaddingMode paddingMode = PaddingMode.PKCS7)
    {
        byte[] decryptedBytes = DecryptFromBase64(base64Ciphertext, key, iv, paddingMode);
        return encoding.GetString(decryptedBytes);
    }
}
```

