import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.util.logging.Level;
import java.util.logging.Logger;

public class CustomDeserializationUtil {

    private static final Logger logger = Logger.getLogger(CustomDeserializationUtil.class.getName());

    public static <T> T deserialize(byte[] byteArray, Class<T> expectedClass) {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(byteArray);
             ObjectInputStream ois = new ObjectInputStream(bais)) {

            // Deserialize the object
            Object obj = ois.readObject();

            // Check if the deserialized object is an instance of the expected class
            if (!expectedClass.isInstance(obj)) {
                logger.log(Level.SEVERE, "Deserialized object is not an instance of the expected class: {0}", expectedClass.getName());
                return null;
            }

            // Cast and return the deserialized object
            return expectedClass.cast(obj);
        } catch (ClassNotFoundException e) {
            logger.log(Level.SEVERE, "Missing class during deserialization: {0}", expectedClass.getName(), e);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Deserialization failed due to an error", e);
        }

        return null;
    }

    public static void main(String[] args) {
        // Example usage
        try {
            // Assuming we have a byte array and the expected class type
            byte[] byteArray = ...; // Populate with actual data
            Class<MyClass> expectedClass = MyClass.class;

            MyClass instance = deserialize(byteArray, expectedClass);
            if (instance != null) {
                System.out.println("Deserialized successfully: " + instance);
            } else {
                System.out.println("Failed to deserialize.");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

