class NetworkClient {
public:
    NetworkClient(io_context& io_context, const string& server)
        : resolver_(io_context), socket_(io_context) {
        resolve(server);
    }

    void sendRequest() {
        async_read_until(socket_, buffer_, "\n", bind(&NetworkClient::handleRead, this, placeholders::_1, placeholders::_2));
    }

private:
    void resolve(const string& server) {
        resolver_.async_resolve(server, "http",
            bind(&NetworkClient::handleResolve, this, placeholders::_1, placeholders::_2));
    }

    void handleResolve(const system::error_code& error, const ip::tcp::resolver::results_type& results) {
        if (!error) {
            async_connect(socket_, results,
                bind(&NetworkClient::handleConnect, this, placeholders::_1));
        }
    }

    void handleConnect(const system::error_code& error) {
        if (!error) {
            sendRequest();
        }
    }

    void handleRead(const system::error_code& error, size_t bytes_transferred) {
        if (!error) {
            // Process the response
            async_read_until(socket_, buffer_, "\n", bind(&NetworkClient::handleRead, this, placeholders::_1, placeholders::_2));
        } else {
            cerr << "Error: " << error.message() << endl;
