#[derive(Clone)]
struct DirectoryManager {
    client: Client,
    env_var_name: String,
    state: Arc<Mutex<State>>,
}

struct State {
    directories: Vec<String>,
}

impl DirectoryManager {
    pub fn new(api_url: &str, env_var_name: &str) -> Self {
        DirectoryManager {
            client: Client::new(),
            env_var_name: env_var_name.to_string(),
            state: Arc::new(Mutex::new(State { directories: vec![] })),
        }
    }

    pub async fn create_directory(&self, dir_name: String) -> Result<(), Box<dyn std::error::Error>> {
        let mut state = self.state.lock().unwrap();

        if state.directories.contains(&dir_name) {
            return Ok(());
        }

        // Validate directory name with external API
        if !self.validate_directory_name(&dir_name).await? {
            error!("Directory name validation failed");
            return Err("Directory name validation failed".into());
        }

        // Create directory (simplified for example)
        std::fs::create_dir(&dir_name)?;
        info!("Created directory: {}", dir_name);

        state.directories.push(dir_name.clone());

        // Update environment variable
        env::set_var(&self.env_var_name, &state.directories.join(","));

        Ok(())
    }

    async fn validate_directory_name(&self, dir_name: &str) -> Result<bool, Box<dyn std::error::Error>> {
        let response = self.client.get(&format!("{}/validate", "http://api.example.com"))
            .query(&[("name", dir_name)])
            .send()
            .await?;

        if response.status() == StatusCode::OK {
            Ok(true)
        } else {
            Err("Directory name validation failed".into())
        }
    }
}

