# DynamicObjectFramework.py

import json
from threading import Lock
from collections import defaultdict
from datetime import datetime, timedelta
from abc import ABC, abstractmethod
from typing import Any, Dict, Callable, Optional

class DynamicObject:
    def __init__(self, data: Dict[str, Any]):
        self.data = data

    def to_json(self) -> str:
        return json.dumps(self.data)

    @staticmethod
    def from_json(json_str: str) -> 'DynamicObject':
        return DynamicObject(json.loads(json_str))

class DynamicFactory(ABC):
    @abstractmethod
    def create_object(self, data: Dict[str, Any]) -> DynamicObject:
        pass

class FactoryRegistry:
    _instance = None
    _lock = Lock()
    _registry = defaultdict(Dict)
    _inactive_timeout = timedelta(hours=1)

    @staticmethod
    def get_instance():
        with FactoryRegistry._lock:
            if FactoryRegistry._instance is None:
                FactoryRegistry._instance = FactoryRegistry()
            return FactoryRegistry._instance

    def register_factory(self, type_name: str, factory_func: Callable[[Dict[str, Any]], DynamicObject]):
        self._registry[type_name][factory_func] = datetime.now()

    def get_factory(self, type_name: str) -> Optional[Callable[[Dict[str, Any]], DynamicObject]]:
        now = datetime.now()
        active_factories = {factory for factory, last_used in self._registry[type_name].items() if now - last_used < self._inactive_timeout}
        return next(iter(active_factories), None)

    def remove_inactive(self):
        now = datetime.now()
        to_remove = [type_name for type_name, factories in self._registry.items() for factory, last_used in list(factories.items()) if now - last_used > self._inactive_timeout]
        for type_name in to_remove:
            del self._registry[type_name]

class DynamicObjectFramework:
    def __init__(self):
        self.factory_registry = FactoryRegistry.get_instance()

    def register_object_type(self, type_name: str, factory_func: Callable[[Dict[str, Any]], DynamicObject]):
        self.factory_registry.register_factory(type_name, factory_func)

    def create_dynamic_object(self, type_name: str, data: Dict[str, Any]) -> Optional[DynamicObject]:
        factory = self.factory_registry.get_factory(type_name)
        if factory:
            return factory(data)
        return None

# Usage example
class UserFactory(DynamicFactory):
    def create_object(self, data: Dict[str, Any]) -> DynamicObject:
        return DynamicObject({'name': data['name'], 'age': data['age']})

framework = DynamicObjectFramework()
framework.register_object_type('User', UserFactory())

user_data = {'name': 'John Doe', 'age': 30}
dynamic_user = framework.create_dynamic_object('User', user_data)
print(dynamic_user.to_json())
```

This code snippet provides a basic implementation of the `DynamicObjectFramework` class, which includes the `DynamicObject` class for handling JSON data and the `FactoryRegistry` class for managing dynamic factory functions. The `DynamicObjectFramework` class allows users to register object types with their corresponding factory functions and create dynamic objects based on the type name."]

