int read_and_validate_input(int *count) {
    char buffer[MAX_INT_SIZE];
    printf("Enter the number of integers: ");
    if (fgets(buffer, MAX_INT_SIZE, stdin) == NULL || sscanf(buffer, "%d", count) != 1) {
        fprintf(stderr, "Invalid input for the number of integers.\n");
        return -1;
    }
    if (*count <= 0) {
        fprintf(stderr, "Number of integers must be greater than zero.\n");
        return -1;
    }
    return 0;
}

void read_integers(int *array, int count) {
    printf("Enter %d integers:\n", count);
    for (int i = 0; i < count; i++) {
        if (scanf("%d", &array[i]) != 1) {
            fprintf(stderr, "Invalid input for integer at position %d.\n", i + 1);
            exit(EXIT_FAILURE);
        }
    }
}

int find_largest_integer(int *array, int count) {
    int largest = array[0];
    for (int i = 1; i < count; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void populate_NFAPI_structures(NFAPI_CRC_INDICATION_PDU_T *structs, int largest, int count) {
    for (int i = 0; i < count; i++) {
        structs[i].RX_UE_INFORMATION_TAG = i + 1;
        structs[i].RNTI = i + 100;
        structs[i].CRC_INDICATION_REL8_TAG = (i % 2 == 0) ? largest : 0;
    }
}

void free_memory(NFAPI_CRC_INDICATION_PDU_T *structs, int count) {
    free(structs);
}

int main() {
    int count;
    if (read_and_validate_input(&count) != 0) {
        return EXIT_FAILURE;
    }

    int *array = (int *)malloc(count * sizeof(int));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed for integer array.\n");
        return EXIT_FAILURE;
    }

    read_integers(array, count);

    int largest = find_largest_integer(array, count);
    printf("Largest integer: %d\n", largest);

    NFAPI_CRC_INDICATION_PDU_T *structs = (NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (structs == NULL) {
        fprintf(stderr, "Memory allocation failed for NFAPI structures.\n");
        free(array);
        return EXIT_FAILURE;
    }

    populate_NFAPI_structures(structs, largest, count);

    free_memory(structs, count);
    free(array);

    return EXIT_SUCCESS;
}
