    EVP_add_cipher(EVP_camellia_128_ecb());
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha256());

    RSA *rsa = RSA_new();
    if (rsa) {
        // Initialize RSA with SHA1
        RSA_set0_key(rsa, BN_new(), BN_new(), NULL);
        EVP_PKEY *pkey = EVP_PKEY_new_fromRSA(rsa);
        RSA_free(rsa);

        if (pkey) {
            EVP_add_cipher(EVP_aes_256_cbc());
            // Use pkey with AES-256-CBC
            EVP_PKEY_free(pkey);
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}
