        perror("Failed to allocate memory for records");
        return NULL;
    }

    int* seeds = malloc(count * sizeof(int));
    if (seeds == NULL) {
        perror("Failed to allocate memory for random seed array");
        free(records);
        return NULL;
    }

    time_t current_time = time(NULL);
    srand(current_time);

    for (int i = 0; i < count; ++i) {
        seeds[i] = rand();
    }

    for (int i = 0; i < count; ++i) {
        records[i].offset = i * sizeof(record);
        records[i].key = lower_bound + rand_r(&seeds[i]) % (upper_bound - lower_bound + 1);
    }

    free(seeds);

    return records;
}

void free_records(record* records, int count) {
    for (int i = 0; i < count; ++i) {
        records[i].offset = 0;
        records[i].key = 0;
    }
    free(records);
