#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SESSIONS 5000
#define MAX_LINE_LENGTH 256

typedef struct {
    char session_id[10];
    time_t start_time;
    time_t end_time;
    char event_type;
} Session;

Session* read_log_files(char** file_names, int num_files, int* total_sessions);
double calculate_average_duration(Session* sessions, int total_sessions);

int main() {
    // Example usage
    char* files[] = {"log1.txt", "log2.txt"};
    int total_sessions;
    Session* sessions = read_log_files(files, 2, &total_sessions);

    if (sessions) {
        double average_duration = calculate_average_duration(sessions, total_sessions);
        printf("Average session duration: %.2f seconds\n", average_duration);
        free(sessions);
    } else {
        printf("Failed to process log files.\n");
    }

    return 0;
}

Session* read_log_files(char** file_names, int num_files, int* total_sessions) {
    Session* sessions = (Session*)malloc(MAX_SESSIONS * sizeof(Session));
    if (!sessions) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    *total_sessions = 0;

    for (int i = 0; i < num_files; ++i) {
        FILE* file = fopen(file_names[i], "r");
        if (!file) {
            perror("Failed to open log file");
            free(sessions);
            return NULL;
        }

        char line[MAX_LINE_LENGTH];
        while (fgets(line, sizeof(line), file)) {
            Session new_session;
            int num_read = fscanf(line, "%9s %ld %c", new_session.session_id, &new_session.start_time, &new_session.event_type);
            if (num_read != 3) {
                fprintf(stderr, "Invalid format in log file.\n");
                fclose(file);
                free(sessions);
                return NULL;
            }

            // Check for duplicate session IDs
            for (int j = 0; j < *total_sessions; ++j) {
                if (strcmp(sessions[j].session_id, new_session.session_id) == 0) {
                    fprintf(stderr, "Duplicate session ID found.\n");
                    fclose(file);
                    free(sessions);
                    return NULL;
                }
            }

            sessions[*total_sessions] = new_session;
            ++(*total_sessions);

            // Reallocation if necessary
            if (*total_sessions >= MAX_SESSIONS) {
                Session* temp = (Session*)realloc(sessions, (*total_sessions + 1000) * sizeof(Session));
                if (!temp) {
                    fprintf(stderr, "Memory reallocation failed.\n");
                    fclose(file);
                    free(sessions);
                    return NULL;
                }
                sessions = temp;
            }

            // Check for invalid timestamps
            time_t current_time = time(NULL);
            if (new_session.start_time > current_time || new_session.event_type != 'S' && new_session.event_type != 'E') {
                fprintf(stderr, "Invalid timestamp or event type.\n");
                fclose(file);
                free(sessions);
                return NULL;
            }

            // End of session
            if (new_session.event_type == 'E') {
                for (int j = *total_sessions - 2; j >= 0; --j) {
                    if (strcmp(sessions[j].session_id, new_session.session_id) == 0 && sessions[j].event_type == 'S') {
                        sessions[j].end_time = new_session.start_time;
                        break;
                    }
                }
            }
        }

        fclose(file);
    }

    return sessions;
}

double calculate_average_duration(Session* sessions, int total_sessions) {
    int valid_sessions = 0;
    time_t total_duration = 0;

    for (int i = 0; i < total_sessions; ++i) {
        if (sessions[i].event_type == 'E') {
            ++valid_sessions;
            total_duration += sessions[i].end_time - sessions[i].start_time;
        }
    }

    return valid_sessions > 0 ? (double)total_duration / valid_sessions : -1;
}
