typedef struct {
    time_t timestamp;
    int event_id;
    char *message;
} LogEntry;

LogEntry* allocate_log_entries(int num_entries, size_t message_size, int *num_allocated) {
    if (num_entries <= 0 || message_size <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    LogEntry *log_entries = (LogEntry*)malloc(num_entries * sizeof(LogEntry));
    if (!log_entries) {
        perror("Failed to allocate memory for log entries.");
        *num_allocated = 0;
        return NULL;
    }

    char **messages = (char**)calloc(num_entries, sizeof(char*));
    if (!messages) {
        fprintf(stderr, "Failed to allocate memory for message buffers.\n");
        free(log_entries);
        *num_allocated = 0;
        return NULL;
    }

    for (int i = 0; i < num_entries; ++i) {
        messages[i] = (char*)malloc(message_size);
        if (!messages[i]) {
            fprintf(stderr, "Failed to allocate memory for message buffer %d.\n", i);
            for (int j = 0; j < i; ++j) {
                free(messages[j]);
            }
            free(messages);
            free(log_entries);
            *num_allocated = 0;
            return NULL;
        }
    }

    time_t now = time(NULL);
    srand((unsigned int)now);

    for (int i = 0; i < num_entries; ++i) {
        log_entries[i].timestamp = rand();
        log_entries[i].event_id = rand() % 1000; // Assuming event IDs are within a small range
        log_entries[i].message = messages[i];
    }

    *num_allocated = num_entries;
    return log_entries;
}

void free_log_entries(LogEntry *log_entries, int num_entries) {
    for (int i = 0; i < num_entries; ++i) {
        free(log_entries[i].message);
    }
    free((char**)log_entries->message);
    free(log_entries);
}
