// Function prototypes
void allocate_memory(long** long_arr, char*** string_arr, config** config_arr, int size);
void free_memory(long* long_arr, char** string_arr, config* config_arr, int size);
void initialize_configs(config* config_arr, int size);
int is_unique_id(int id, config* config_arr, int size);
int get_next_id();
void log_memory_usage(double start_time, double end_time, size_t total_mem);

// Global variables
int next_id = 1;
int max_ids = 1000; // Adjust based on expected range of IDs

void allocate_memory(long** long_arr, char*** string_arr, config** config_arr, int size) {
    *long_arr = (long*)malloc(size * sizeof(long));
    if (*long_arr == NULL) {
        fprintf(stderr, "Memory allocation failed for long array\n");
        exit(1);
    }

    *string_arr = (char**)malloc(size * sizeof(char*));
    if (*string_arr == NULL) {
        free(*long_arr);
        fprintf(stderr, "Memory allocation failed for string array\n");
        exit(1);
    }

    *config_arr = (config*)malloc(size * sizeof(config));
    if (*config_arr == NULL) {
        free(*long_arr);
        free(*string_arr);
        fprintf(stderr, "Memory allocation failed for config array\n");
        exit(1);
    }
}

void free_memory(long* long_arr, char** string_arr, config* config_arr, int size) {
    free(long_arr);
    free(string_arr);
    free(config_arr);
}

void initialize_configs(config* config_arr, int size) {
    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < size; i++) {
        while (!is_unique_id(next_id, config_arr, size)) {
            next_id = get_next_id();
        }
        config_arr[i].probability = ((double)rand() / RAND_MAX);
        asprintf(&config_arr[i].name, "Config%d", i);
        config_arr[i].id = next_id;
    }
}

int is_unique_id(int id, config* config_arr, int size) {
    for (int i = 0; i < size; i++) {
        if (config_arr[i].id == id) {
            return 0;
        }
    }
    return 1;
}

int get_next_id() {
    if (next_id >= max_ids) {
        max_ids *= 2;
        printf("Increasing ID range to %d\n", max_ids);
    }
    return next_id++;
}

void log_memory_usage(double start_time, double end_time, size_t total_mem) {
    printf("Memory allocation took %.6f seconds and used %zu bytes\n", (end_time - start_time), total_mem);
}
