int allocate_memory(long *long_arr, char **char_arr, config **config_arr, int num_configs, size_t max_size) {
    time_t t = time(NULL);
    srand(t); // Seed for the PRNG

    long_arr = (long *)malloc(num_configs * sizeof(long));
    if (!long_arr) return -1;

    char_arr = (char **)malloc(num_configs * sizeof(char *));
    if (!char_arr) {
        free(long_arr);
        return -2;
    }

    config_arr = (config *)malloc(num_configs * sizeof(config));
    if (!config_arr) {
        free(char_arr);
        free(long_arr);
        return -3;
    }

    for (int i = 0; i < num_configs; i++) {
        long_arr[i] = i;

        char_arr[i] = (char *)malloc(256 * sizeof(char));
        if (!char_arr[i]) {
            for (int j = 0; j < i; j++) {
                free(char_arr[j]);
            }
            free(config_arr);
            free(char_arr);
            free(long_arr);
            return -4;
        }

        config_arr[i].probability = (double)rand() / RAND_MAX;

        // Allocate space for config name
        config_arr[i].config_name = (char *)malloc(256 * sizeof(char));
        if (!config_arr[i].config_name) {
            for (int j = 0; j <= i; j++) {
                free(config_arr[j].config_name);
                free(char_arr[j]);
            }
            free(config_arr);
            free(char_arr);
            free(long_arr);
            return -5;
        }

        // Generate unique ID using CSPRNG
        if (!RAND_bytes((unsigned char *)&config_arr[i].ID, sizeof(int))) {
            for (int j = 0; j <= i; j++) {
                free(config_arr[j].config_name);
                free(char_arr[j]);
            }
            free(config_arr);
            free(char_arr);
            free(long_arr);
            return -6;
        }

        // Refresh CSPRNG state
        if (i % 10 == 9) {
            RAND_poll();
        }
    }

    *long_arr = long_arr;
    *char_arr = char_arr;
    *config_arr = config_arr;

    return 0; // Success
}

void free_memory(long *long_arr, char **char_arr, config *config_arr, int num_configs) {
    for (int i = 0; i < num_configs; i++) {
        free(config_arr[i].config_name);
        free(char_arr[i]);
    }
    free(config_arr);
    free(char_arr);
    free(long_arr);
}

int main() {
    long *long_array;
    char **char_array;
    config *config_array;

    int num_configs = 10000;
    size_t max_size = 5 * 1024 * 1024; // 5 MB

    int result = allocate_memory(&long_array, &char_array, &config_array, num_configs, max_size);
    if (result == -1) {
        printf("Failed to allocate memory for long array.\n");
    } else if (result == -2) {
        printf("Failed to allocate memory for char array.\n");
    } else if (result == -3) {
        printf("Failed to allocate memory for config array.\n");
    } else if (result == -4) {
        printf("Failed to allocate memory for individual char string.\n");
    } else if (result == -5) {
        printf("Failed to allocate memory for individual config name.\n");
    } else if (result == -6) {
