typedef struct {
    size_t size;
    size_t capacity;
    void **array;
} DynamicArray;

void init_array(DynamicArray *arr, size_t initial_size) {
    arr->size = 0;
    arr->capacity = initial_size;
    arr->array = malloc(initial_size * sizeof(void *));
}

void resize_array(DynamicArray *arr, size_t new_capacity) {
    if (new_capacity <= arr->capacity) return;
    void **new_array = realloc(arr->array, new_capacity * sizeof(void *));
    if (!new_array) {
        // Handle allocation failure
        perror("Failed to resize array");
        return;
    }
    arr->array = new_array;
    arr->capacity = new_capacity;
}

void add_to_array(DynamicArray *arr, void *element) {
    if (arr->size == arr->capacity) {
        resize_array(arr, arr->capacity * 2);
    }
    arr->array[arr->size++] = element;
}

