void init_memory_pool(MemoryPool *pool, size_t block_size, size_t initial_size) {
    init_array(&pool->free_blocks, initial_size);
    pool->block_size = block_size;
}

void *allocate_from_pool(MemoryPool *pool) {
    if (pool->free_blocks.size == 0) {
        resize_array(&pool->free_blocks, pool->free_blocks.capacity * 2);
    }
    void *block = malloc(pool->block_size);
    add_to_array(&pool->free_blocks, block);
