#include <semaphore.h>

typedef struct {
    int value;
} record;

int create_records(int num_records, long **offsets, int **keys, record **records, sem_t *sem, int range_start, int range_end) {
    // Allocate memory for offsets and keys arrays
    *offsets = (long *)malloc(num_records * sizeof(long));
    if (*offsets == NULL) return -1;

    *keys = (int *)malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -1;
    }

    // Allocate memory for records array
    *records = (record *)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -1;
    }

    // Initialize semaphore with initial value
    if (sem_init(sem, 0, num_records) != 0) {
        free(*offsets);
        free(*keys);
        free(*records);
        return -1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Initialize records with pseudo-random values within the specified range
    for (int i = 0; i < num_records; ++i) {
        (*keys)[i] = rand() % (range_end - range_start + 1) + range_start;
        (*records)[i].value = (*keys)[i];
    }

    return 0;
}

void destroy_records(int num_records, long *offsets, int *keys, record *records, sem_t *sem) {
    // Clean up allocated memory
    free(offsets);
    free(keys);
    free(records);

    // Destroy semaphore
    sem_destroy(sem);
}
