#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} record;

long* allocate_long_array(size_t size);
int* allocate_int_array(size_t size);
record* allocate_record_array(size_t size);

void init_long_array(long* array, size_t size, long min, long max);
void init_int_array(int* array, size_t size, int min, int max);
void populate_records(record* records, size_t size, void (*prng)(int*, int, int));

void free_memory(long* long_array, int* int_array, record* record_array);

void sort_records(record* records, size_t size, int (*compare)(const void*, const void*));

long* allocate_long_array(size_t size) {
    if (size == 0 || size < 0) {
        fprintf(stderr, "Error: Invalid array size.\n");
        return NULL;
    }
    long* array = malloc(size * sizeof(long));
    if (!array) {
        perror("Failed to allocate memory for 'long' array.");
        return NULL;
    }
    return array;
}

int* allocate_int_array(size_t size) {
    if (size == 0 || size < 0) {
        fprintf(stderr, "Error: Invalid array size.\n");
        return NULL;
    }
    int* array = malloc(size * sizeof(int));
    if (!array) {
        perror("Failed to allocate memory for 'int' array.");
        return NULL;
    }
    return array;
}

record* allocate_record_array(size_t size) {
    if (size == 0 || size < 0) {
        fprintf(stderr, "Error: Invalid array size.\n");
        return NULL;
    }
    record* array = malloc(size * sizeof(record));
    if (!array) {
        perror("Failed to allocate memory for 'record' array.");
        return NULL;
    }
    return array;
}

void init_long_array(long* array, size_t size, long min, long max) {
    if (size == 0 || size < 0 || min > max) {
        fprintf(stderr, "Error: Invalid initialization parameters.\n");
        return;
    }
    for (size_t i = 0; i < size; ++i) {
        array[i] = min + rand() % (max - min + 1);
    }
}

void init_int_array(int* array, size_t size, int min, int max) {
    if (size == 0 || size < 0 || min > max) {
        fprintf(stderr, "Error: Invalid initialization parameters.\n");
        return;
    }
    for (size_t i = 0; i < size; ++i) {
        array[i] = min + rand() % (max - min + 1);
    }
}

void populate_records(record* records, size_t size, void (*prng)(int*, int, int)) {
    if (!records || !prng || size == 0 || size < 0) {
        fprintf(stderr, "Error: Invalid parameters for record population.\n");
        return;
    }
    prng((int*)records, size * sizeof(record), 0);
}

void free_memory(long* long_array, int* int_array, record* record_array) {
    if (long_array) {
        free(long_array);
    }
    if (int_array) {
        free(int_array);
    }
    if (record_array) {
        free(record_array);
    }
}

void sort_records(record* records, size_t size, int (*compare)(const void*, const void*)) {
    if (!records || !compare || size == 0 || size < 0) {
        fprintf(stderr, "Error: Invalid parameters for record sorting.\n");
        return;
    }
    qsort(records, size, sizeof(record), compare);
}

int record_compare(const void* a, const void* b) {
    const record* ra = (const record*)a;
    const record* rb = (const record*)b;
    if (ra->value < rb->value) return -1;
    if (ra->value > rb->value) return 1;
    return 0;
}
