#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int session_id;
    int timeout;
} Session;

typedef struct {
    Session* sessions;
    size_t capacity;
    size_t size;
} SessionPool;

Session* allocate_session(SessionPool* pool, int timeout) {
    if (pool->size >= pool->capacity) {
        // Resize the array or handle error
        return NULL;
    }

    // Generate a unique session ID using a PRNG
    unsigned int seed = time(NULL);
    int new_id = rand_r(&seed);

    // Validate uniqueness within a specified range
    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->sessions[i].session_id == new_id) {
            // Retry or handle collision
            return NULL;
        }
    }

    Session* session = &pool->sessions[pool->size++];
    session->session_id = new_id;
    session->timeout = timeout;

    return session;
}

void initialize_session_pool(SessionPool* pool, size_t initial_capacity) {
    pool->sessions = (Session*)malloc(initial_capacity * sizeof(Session));
    if (!pool->sessions) {
        // Handle allocation failure
        exit(EXIT_FAILURE);
    }
    pool->capacity = initial_capacity;
    pool->size = 0;
}

void destroy_session_pool(SessionPool* pool) {
    free(pool->sessions);
    pool->sessions = NULL;
    pool->capacity = 0;
    pool->size = 0;
}
