void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

void initialize_prng(int seed) {
    srand(seed);
}

int random_between(int min, int max) {
    return rand() % (max - min + 1) + min;
}

long multiple_of_prime(long num, long prime) {
    if (num % prime == 0) return num;
    return ((num / prime) * prime + prime);
}

double precise_double(double value) {
    return (value >= 0.0 && value <= 1.0) ? value : 0.5; // Clamp to [0, 1]
}

record* create_record_array(int count, int min_int, int max_int, long prime, double precise_val) {
    record* records = allocate_memory(count * sizeof(record));
    for (int i = 0; i < count; i++) {
        records[i].a = random_between(min_int, max_int);
        records[i].b = multiple_of_prime(records[i].a, prime);
        records[i].c = precise_double(precise_val);
    }
    return records;
}

void free_memory(void* ptr) {
    if (ptr != NULL) {
        free(ptr);
    }
}

int main() {
    int count = 10;
    int min_int = -100;
    int max_int = 100;
    long prime = 7;
    double precise_val = 0.5;

    initialize_prng(time(NULL));
    record* records = create_record_array(count, min_int, max_int, prime, precise_val);

    // Use the records array...

    free_memory(records);
    return 0;
}
