} Transaction;

typedef struct MemoryPool {
    void* memory;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->memory = malloc(initial_size);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }
    pool->allocated_size = initial_size;
    pool->used_size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* memory_pool_alloc(MemoryPool* pool, size_t size) {
    if (pthread_mutex_lock(&pool->lock)) return NULL;
    if (pool->used_size + size > pool->allocated_size) {
        void* new_memory = realloc(pool->memory, pool->allocated_size * 2);
        if (!new_memory) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->memory = new_memory;
        pool->allocated_size *= 2;
    }
    void* ptr = (char*)pool->memory + pool->used_size;
    pool->used_size += size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->memory);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

Record* create_records(size_t count, int min_value, int max_value) {
    Record* records = (Record*)memory_pool_alloc(memory_pool, count * sizeof(Record));
    if (!records) return NULL;
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
    return records;
}

int* create_keys(size_t count, int min_value, int max_value) {
    int* keys = (int*)memory_pool_alloc(memory_pool, count * sizeof(int));
    if (!keys) return NULL;
    for (size_t i = 0; i < count; ++i) {
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
    }
    return keys;
}

User* create_users(size_t count, MemoryPool* memory_pool) {
    User* users = (User*)memory_pool_alloc(memory_pool, count * sizeof(User));
    if (!users) return NULL;
    for (size_t i = 0; i < count; ++i) {
        users[i].email = (char*)memory_pool_alloc(memory_pool, 256);
        if (!users[i].email) return NULL;
        sprintf(users[i].name, "User%d", i);
        users[i].email[0] = '\0';
        users[i].session_id = rand();
    }
    return users;
}

Transaction* create_transactions(size_t count, User* users, MemoryPool* memory_pool) {
    Transaction* transactions = (Transaction*)memory_pool_alloc(memory_pool, count * sizeof(Transaction));
    if (!transactions) return NULL;
    for (size_t i = 0; i < count; ++i) {
        transactions[i].timestamp = time(NULL);
        transactions[i].amount = rand() / (float)RAND_MAX * 1000.0f;
        sprintf(transactions[i].description, "Transaction%d", i);
        transactions[i].user_profile = &users[rand() % count];
    }
    return transactions;
}

void log_memory_allocation(MemoryPool* pool, size_t size) {
    printf("Allocated: %zu bytes\n", size);
    printf("Used: %zu bytes\n", pool->used_size);
    printf("Available: %zu bytes\n", pool->allocated_size - pool->used_size);
}

int main() {
    srand(time(NULL));
    MemoryPool* memory_pool = create_memory_pool(RECORD_SIZE * 1024);

    size_t count = 100;
    Record* records = create_records(count, 1, 1000);
    int* keys = create_keys(count, 1, 1000);
    User* users = create_users(count, memory_pool);
    Transaction* transactions = create_transactions(count, users, memory_pool);

    log_memory_allocation(memory_pool, count * sizeof(Record) + count * sizeof(int) + count * sizeof(User) + count * sizeof(Transaction));

    destroy_memory_pool(memory_pool);
    return 0;
}
