record* allocate_records(int num_records, int min_value, int max_value) {
    if (min_value >= max_value) {
        return NULL; // Handle error: invalid range
    }
    record* records = (record*)malloc(num_records * sizeof(record));
    if (records == NULL) {
        return NULL; // Handle memory allocation failure
    }
    srand(time(0)); // Seed PRNG for consistent pseudo-randomness across runs
    for (int i = 0; i < num_records; i++) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }
    return records;
}

sem_t* initialize_semaphore(int initial_value) {
    sem_t* semaphore = (sem_t*)malloc(sizeof(sem_t));
    if (semaphore == NULL || sem_init(semaphore, 0, initial_value) != 0) {
        free(semaphore); // Clean up on failure
        return NULL; // Handle error: failed to initialize semaphore
    }
    return semaphore;
}

void cleanup_resources(long* offsets, int* keys, record* records, sem_t* semaphore) {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
