['```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ACCOUNTS 10000

typedef struct {
    long id;
    char name[50];
    double balance;
} account;

account *accounts[MAX_ACCOUNTS];
int next_id = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

long generate_unique_id() {
    static pthread_mutex_t csprng_lock = PTHREAD_MUTEX_INITIALIZER;
    static unsigned long seed = time(NULL);
    pthread_mutex_lock(&csprng_lock);
    seed = seed * 1664525 + 1013904223;
    pthread_mutex_unlock(&csprng_lock);
    return (long)(seed % MAX_ACCOUNTS);
}

int allocate_account(const char *name, double initial_balance) {
    if (next_id >= MAX_ACCOUNTS) {
        return -1; // Out of memory
    }

    int id = generate_unique_id();
    while (accounts[id] != NULL) {
        id = generate_unique_id(); // Ensure uniqueness
    }

    pthread_mutex_lock(&lock);
    accounts[id] = (account *)malloc(sizeof(account));
    if (!accounts[id]) {
        pthread_mutex_unlock(&lock);
        return -1; // Allocation failed
    }
    pthread_mutex_unlock(&lock);

    accounts[id]->id = id;
    strncpy(accounts[id]->name, name, sizeof(accounts[id]->name) - 1);
    accounts[id]->balance = initial_balance;

    pthread_mutex_lock(&lock);
    next_id++;
    pthread_mutex_unlock(&lock);

    return id;
}

void free_account(int id) {
    if (id < 0 || id >= MAX_ACCOUNTS || !accounts[id]) {
        return; // Invalid ID or already freed
    }

    pthread_mutex_lock(&lock);
    free(accounts[id]);
    accounts[id] = NULL;
    next_id--;
    pthread_mutex_unlock(&lock);
}

// Example usage:
int main() {
    int id = allocate_account("John Doe", 1000.50);
    if (id >= 0) {
        printf("Account created with ID: %ld\n", id);
        // Use the account...
        free_account(id);
    } else {
        printf("Failed to create account.\n");
    }
    return 0;
}
```

