#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

#define MAX_USERS 1000
#define INITIAL_SIZE 100

typedef struct {
    int id;
    char* name;
    char* email;
} User;

typedef struct {
    time_t timestamp;
    double amount;
    char* description;
    User* user;
} Transaction;

typedef struct {
    int seed;
    pthread_mutex_t lock;
} PRNGState;

void init_prng(PRNGState* prng) {
    srand(time(NULL));
    prng->seed = rand();
    pthread_mutex_init(&prng->lock, NULL);
}

int generate_session_id(PRNGState* prng) {
    pthread_mutex_lock(&prng->lock);
    int id = prng->seed;
    prng->seed = rand();
    pthread_mutex_unlock(&prng->lock);
    return id;
}

void init_user(User* user, char* name, char* email, PRNGState* prng) {
    user->name = strdup(name);
    user->email = strdup(email);
    user->session_id = generate_session_id(prng);
}

User* create_users(int count, PRNGState* prng) {
    User* users = malloc(count * sizeof(User));
    if (users == NULL) {
        perror("Failed to allocate memory for users");
        return NULL;
    }
    for (int i = 0; i < count; ++i) {
        init_user(&users[i], "User", "user@example.com", prng);
    }
    return users;
}

void free_users(User* users, int count) {
    for (int i = 0; i < count; ++i) {
        free(users[i].name);
        free(users[i].email);
