void manage_memory(long** long_array, char*** string_array, Config** config_array, size_t array_size) {
    if (array_size > MAX_CONFIGS) {
        fprintf(stderr, "Error: Array size exceeds maximum allowed.\n");
        return;
    }

    *long_array = (long*)malloc(array_size * sizeof(long));
    if (*long_array == NULL) {
        fprintf(stderr, "Memory allocation failed for long array.\n");
        return;
    }

    *string_array = (char**)calloc(array_size, sizeof(char*));
    if (*string_array == NULL) {
        free(*long_array);
        fprintf(stderr, "Memory allocation failed for string array.\n");
        return;
    }

    *config_array = (Config*)malloc(array_size * sizeof(Config));
    if (*config_array == NULL) {
        free(*long_array);
        free(*string_array);
        fprintf(stderr, "Memory allocation failed for config array.\n");
        return;
    }

    // Initialize arrays and structures
    for (size_t i = 0; i < array_size; i++) {
        (*long_array)[i] = rand();
        (*string_array)[i] = strdup("example");
        (*config_array)[i].probability = 0.5 + rand() / (double)RAND_MAX;
        (*config_array)[i].name = strdup("config");
    }
}

int main() {
    long* long_array;
    char** string_array;
    Config* config_array;

    manage_memory(&long_array, &string_array, &config_array, 10);

    // Use the allocated arrays and structures
    for (size_t i = 0; i < 10; i++) {
        printf("Long: %ld\n", long_array[i]);
        printf("String: %s\n", string_array[i]);
        printf("Config: Probability = %f, Name = %s\n", config_array[i].probability, config_array[i].name);
    }

    // Free allocated memory
    free(long_array);
    for (size_t i = 0; i < 10; i++) {
        free(string_array[i]);
        free(config_array[i].name);
    }
    free(string_array);
    free(config_array);

    return 0;
}
