#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    unsigned long session_id;
} Session;

typedef struct {
    char name[256];
    char email[256];
    Session *session;
} User;

typedef struct {
    time_t timestamp;
    double amount;
    char description[256];
    User *user;
} Transaction;

typedef struct MemoryPool {
    void *memory;
    size_t size;
    size_t used;
} MemoryPool;

void initializeMemoryPool(MemoryPool *pool, size_t initialSize) {
    pool->memory = malloc(initialSize);
    pool->size = initialSize;
    pool->used = 0;
}

void* allocateFromPool(MemoryPool *pool, size_t size) {
    if (pool->used + size > pool->size) {
        // Resize the pool
        pool->size *= 2;
        pool->memory = realloc(pool->memory, pool->size);
    }
    void *ptr = ((char*)pool->memory) + pool->used;
    pool->used += size;
    return ptr;
}

Session* allocateSessions(MemoryPool *pool, int numSessions) {
    Session *sessions = (Session*)allocateFromPool(pool, numSessions * sizeof(Session));
    for (int i = 0; i < numSessions; ++i) {
        sessions[i].session_id = rand(); // Replace with CSPRNG for production
    }
    return sessions;
}

User* allocateUsers(MemoryPool *pool, int numUsers, Session *sessions) {
    User *users = (User*)allocateFromPool(pool, numUsers * sizeof(User));
    for (int i = 0; i < numUsers; ++i) {
        users[i].session = &sessions[i];
        snprintf(users[i].name, sizeof(users[i].name), "User%d", i);
        snprintf(users[i].email, sizeof(users[i].email), "user%d@example.com", i);
    }
    return users;
}

Transaction* allocateTransactions(MemoryPool *pool, int numTransactions, User *users) {
    Transaction *transactions = (Transaction*)allocateFromPool(pool, numTransactions * sizeof(Transaction));
    for (int i = 0; i < numTransactions; ++i) {
        transactions[i].user = &users[rand() % numUsers]; // Random user
        transactions[i].timestamp = time(NULL);
        transactions[i].amount = rand() / (double)RAND_MAX;
        snprintf(transactions[i].description, sizeof(transactions[i].description), "Transaction%d", i);
    }
    return transactions;
}

void logAllocationDetails(MemoryPool *pool, int numSessions, int numUsers, int numTransactions) {
    time_t start = time(NULL);
    Session *sessions = allocateSessions(pool, numSessions);
    User *users = allocateUsers(pool, numUsers, sessions);
    Transaction *transactions = allocateTransactions(pool, numTransactions, users);

    time_t end = time(NULL);
    printf("Memory Allocation Details:\n");
    printf("Start Time: %s", ctime(&start));
    printf("End Time: %s", ctime(&end));
    printf("Total Memory Used: %zu bytes\n", pool->used);
    printf("Sessions Allocated: %d\n", numSessions);
    printf("Users Allocated: %d\n", numUsers);
    printf("Transactions Allocated: %d\n", numTransactions);

    // Free allocated memory
    free(sessions);
    free(users);
    free(transactions);
}
```

