#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define data structures
typedef struct {
    double priority;
    char* name;
    int session_limit;
} config;

typedef struct {
    time_t timestamp;
    char* identifier;
    config* cfg;
} session_record;

// Global variables for memory pool and PRNG state
void* memory_pool;
pthread_mutex_t pool_mutex;
unsigned long prng_state = 0x5DEECE66D;

// PRNG function to generate unique identifiers
unsigned long prng() {
    prng_state = (prng_state * 0x5DEECE66D + 0xB) & 0xFFFFFFFFFFFFF;
    return prng_state;
}

// Memory allocation wrapper with error handling and logging
void* safe_malloc(size_t size, const char* location) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed at %s\n", location);
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to manage dynamic memory allocation and initialization
void initialize_core_data(int num_configs, int num_sessions) {
    pthread_mutex_lock(&pool_mutex);

    // Allocate memory for config structures
    config* configs = safe_malloc(num_configs * sizeof(config), "initialize_core_data");

    // Initialize config structures with unique IDs using PRNG
    for (int i = 0; i < num_configs; i++) {
        configs[i].priority = (double)prng() / UINT64_MAX;
        configs[i].name = safe_malloc(256 * sizeof(char), "initialize_core_data");
        snprintf(configs[i].name, 256, "config_%lu", prng());
        configs[i].session_limit = rand();
    }

    // Allocate memory for session records
    session_record* sessions = safe_malloc(num_sessions * sizeof(session_record), "initialize_core_data");

    // Initialize session records with timestamps and unique IDs
    for (int i = 0; i < num_sessions; i++) {
        sessions[i].timestamp = time(NULL);
        sessions[i].identifier = safe_malloc(256 * sizeof(char), "initialize_core_data");
        snprintf(sessions[i].identifier, 256, "session_%lu", prng());
        sessions[i].cfg = &configs[rand() % num_configs]; // Randomly assign config
    }

    // Log initialization details
    printf("Initialized %d configs and %d sessions\n", num_configs, num_sessions);

    pthread_mutex_unlock(&pool_mutex);
}

// Cleanup function to handle memory leaks and resource deallocation
void cleanup_core_data(config* configs, session_record* sessions, int num_configs, int num_sessions) {
    pthread_mutex_lock(&pool_mutex);

    // Free config structures
    for (int i = 0; i < num_configs; i++) {
        free(configs[i].name);
    }
    free(configs);

    // Free session records
    for (int i = 0; i < num_sessions; i++) {
        free(sessions[i].identifier);
    }
    free(sessions);

    pthread_mutex_unlock(&pool_mutex);
}

// Main function to demonstrate usage
int main() {
    int num_configs = 10;
    int num_sessions = 20;

    // Initialize PRNG seed
    srand(time(NULL));

    initialize_core_data(num_configs, num_sessions);

    cleanup_core_data(NULL, NULL, num_configs, num_sessions);

    return 0;
}
