#define MAX_SESSIONS 1024
#define MAX_USERS 1024
#define MAX_TRANSACTIONS 1024

typedef struct {
    char session_id[32];
} Session;

typedef struct {
    char name[64];
    char email[128];
    Session *session;
} User;

typedef struct {
    time_t timestamp;
    double amount;
    char description[256];
    User *user;
} Transaction;

Session sessions[MAX_SESSIONS];
User users[MAX_USERS];
Transaction transactions[MAX_TRANSACTIONS];

void initialize_memory() {
    srand(time(NULL));
}

int allocate_session(Session **session) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (sessions[i].session_id[0] == '\0') {
            sprintf(sessions[i].session_id, "%d", rand());
            *session = &sessions[i];
            return 1;
        }
    }
    return 0;
}

int allocate_user(User **user) {
    for (int i = 0; i < MAX_USERS; i++) {
        if (users[i].name[0] == '\0') {
            users[i].session = NULL;
            *user = &users[i];
            return 1;
        }
    }
    return 0;
}

int allocate_transaction(Transaction **transaction) {
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        if (transactions[i].timestamp == 0) {
            transactions[i].user = NULL;
            *transaction = &transactions[i];
            return 1;
        }
    }
    return 0;
}

void log_message(const char *message, int level) {
    static FILE *log_file = fopen("app.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    if (level > 1) {
        fprintf(log_file, "%s\n", message);
    }
    if (level > 0) {
        printf("%s\n", message);
    }
}

int main() {
    Session *session;
    User *user;
    Transaction *transaction;

    initialize_memory();

    if (allocate_session(&session)) {
        log_message("Session allocated successfully", 1);
    } else {
        log_message("Failed to allocate session", 0);
    }

    if (allocate_user(&user)) {
        log_message("User allocated successfully", 1);
    } else {
        log_message("Failed to allocate user", 0);
    }

    if (allocate_transaction(&transaction)) {
        log_message("Transaction allocated successfully", 1);
    } else {
        log_message("Failed to allocate transaction", 0);
    }

    return 0;
}
