    pthread_mutex_lock(&memory_lock);
    monitor.frequency++;
    double new_success_rate = (monitor.success_rate * (monitor.frequency - 1) + 1) / monitor.frequency;
    if (new_success_rate < monitor.success_rate) {
        printf("Memory allocation failure detected\n");
    }
    monitor.success_rate = new_success_rate;
    pthread_mutex_unlock(&memory_lock);
