typedef struct {
    time_t timestamp;
    char event_description[EVENT_RECORD_SIZE];
    Config* config_ptr;
} EventRecord;

void initialize_data_structures(long long num_configs, long long num_events) {
    if (!RAND_status()) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    Config** configs = (Config**)malloc(num_configs * sizeof(Config*));
    EventRecord** events = (EventRecord**)malloc(num_events * sizeof(EventRecord*));

    if (!configs || !events) {
        fprintf(stderr, "Memory allocation failed\n");
        free(configs);
        free(events);
        exit(EXIT_FAILURE);
    }

    for (long long i = 0; i < num_configs; ++i) {
        configs[i] = (Config*)malloc(sizeof(Config));
        if (!configs[i]) {
            fprintf(stderr, "Memory allocation failed for config %lld\n", i);
            free(configs);
            free(events);
            exit(EXIT_FAILURE);
        }
        RAND_bytes((unsigned char*)&configs[i]->probability, sizeof(double));
        snprintf(configs[i]->config_name, CONFIG_STRUCT_SIZE, "Config_%lld", i);
        configs[i]->timeout_duration = rand() % 600 + 1; // Random timeout between 1 and 10 minutes
    }

    for (long long i = 0; i < num_events; ++i) {
        events[i] = (EventRecord*)malloc(sizeof(EventRecord));
        if (!events[i]) {
            fprintf(stderr, "Memory allocation failed for event %lld\n", i);
            free_configs(configs, num_configs);
            free_events(events, i);
            exit(EXIT_FAILURE);
        }
