typedef struct Account {
    int id;
    char name[128];
    char email[128];
    char dob[12];
    Transaction *transactions;
    size_t transaction_count;
    size_t transaction_capacity;
} Account;

Account* create_account(char *name, char *email, char *dob) {
    Account *acc = malloc(sizeof(Account));
    acc->id = random();
    strcpy(acc->name, name);
    strcpy(acc->email, email);
    strcpy(acc->dob, dob);
    acc->transactions = NULL;
    acc->transaction_count = 0;
    acc->transaction_capacity = 16;
    acc->transactions = realloc(acc->transactions, acc->transaction_capacity * sizeof(Transaction));
    return acc;
}

void add_transaction(Account *acc, time_t timestamp, double amount, char *description) {
    if (acc->transaction_count == acc->transaction_capacity) {
        acc->transaction_capacity *= 2;
        acc->transactions = realloc(acc->transactions, acc->transaction_capacity * sizeof(Transaction));
    }
    Transaction *new_transaction = &acc->transactions[acc->transaction_count++];
    new_transaction->timestamp = timestamp;
    new_transaction->amount = amount;
    strcpy(new_transaction->description, description);
}

void free_account(Account *acc) {
    free(acc->transactions);
    free(acc);
}
