MemoryManager* create_memory_manager(size_t initial_size, size_t max_memory_limit) {
    MemoryManager *mm = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!mm) return NULL;

    mm->users = (UserProfile*)calloc(initial_size, sizeof(UserProfile));
    mm->offsets = (long*)calloc(initial_size, sizeof(long));
    mm->keys = (int*)calloc(initial_size, sizeof(int));
    mm->records = (Record**)calloc(initial_size, sizeof(Record*));
    mm->metadata = (Metadata*)calloc(initial_size, sizeof(Metadata));
    if (!mm->users || !mm->offsets || !mm->keys || !mm->records || !mm->metadata) {
        free_memory_manager(mm);
        return NULL;
    }

    mm->user_count = initial_size;
    mm->max_memory_limit = max_memory_limit;

    srand(time(NULL));
    for (size_t i = 0; i < initial_size; i++) {
        sprintf(mm->users[i].session_id, "%d", rand());
    }

    return mm;
}

void free_memory_manager(MemoryManager *mm) {
    if (!mm) return;

    for (size_t i = 0; i < mm->user_count; i++) {
        for (int j = 0; j < mm->keys[i]; j++) {
            free(mm->records[i][j].value);
        }
        free(mm->records[i]);
    }

    free(mm->users);
    free(mm->offsets);
    free(mm->keys);
    free(mm->records);
    free(mm->metadata);

    free(mm);
}

// Additional functions for memory management, logging, and concurrency handling would be implemented here.

