    MemoryManager *mm = create_memory_manager(1000, 1024 * 1024); // 1MB limit
    if (!mm) {
        printf("Failed to allocate memory manager.\n");
        return 1;
    }

    // Use the memory manager...

    free_memory_manager(mm);
    return 0;
}
