session_id* create_session_ids(int count) {
    session_id *ids = malloc(count * sizeof(session_id));
    if (!ids) {
        perror("Memory allocation failed for session IDs");
        return NULL;
    }
    // Initialize with CSPRNG values
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        ids[i].id = rand();
    }
    return ids;
}

user_profile* create_user_profiles(session_id *session_ids, int count) {
    user_profile *profiles = malloc(count * sizeof(user_profile));
    if (!profiles) {
        perror("Memory allocation failed for user profiles");
        free(session_ids);
        return NULL;
    }
    // Initialize with random names and emails
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        snprintf(profiles[i].name, sizeof(profiles[i].name), "User%d", i);
        snprintf(profiles[i].email, sizeof(profiles[i].email), "user%d@example.com", i);
        profiles[i].session = &session_ids[i];
    }
    return profiles;
}

transaction_record* create_transaction_records(user_profile *profiles, int count) {
    transaction_record *records = malloc(count * sizeof(transaction_record));
    if (!records) {
        perror("Memory allocation failed for transaction records");
        free(profiles);
        free(session_ids); // Assuming session_ids and profiles are allocated together
        return NULL;
    }
    // Initialize with random timestamps, amounts, and descriptions
    srand(time(NULL));
    time_t now = time(NULL);
    for (int i = 0; i < count; i++) {
        records[i].timestamp = now - rand() % 365 * 24 * 60 * 60;
        records[i].amount = ((double)rand()) / RAND_MAX * 1000.0;
        snprintf(records[i].description, sizeof(records[i].description), "Transaction%d", i);
        records[i].user = &profiles[i];
    }
    return records;
}

void free_resources(session_id *session_ids, user_profile *profiles, transaction_record *records) {
    free(session_ids);
    free(profiles);
    free(records);
}

int main() {
    int count = 1000; // Example data volume
    session_id *session_ids = create_session_ids(count);
    if (session_ids == NULL) return -1;

    user_profile *profiles = create_user_profiles(session_ids, count);
    if (profiles == NULL) return -1;

    transaction_record *records = create_transaction_records(profiles, count);
    if (records == NULL) return -1;

    // Use the allocated resources

    free_resources(session_ids, profiles, records);

    return 0;
}
