int validate_identifier(char* identifier, record** records, int size) {
    for (int i = 0; i < size; i++) {
        if (strcmp(records[i]->identifier, identifier) == 0) {
            return 1;
        }
    }
    return 0;
}

char* generate_unique_identifier(int seed) {
    // Implement unique identifier generation logic here
    // Ensure the PRNG meets performance requirements and handles concurrency
    char* identifier = malloc(20 * sizeof(char));
    sprintf(identifier, "%d", seed);
    return identifier;
}

void initialize_arrays(long** offsets, int** keys, record*** records, int size) {
    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = (record**)malloc(size * sizeof(record*));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        (*keys)[i] = rand() % size;
        while (1) {
            char* identifier = generate_unique_identifier(rand());
            if (!validate_identifier(identifier, *records, i)) {
                (*records)[i] = (record*)malloc(sizeof(record));
                (*records)[i]->value = rand();
                (*records)[i]->identifier = identifier;
                break;
            }
            free(identifier);
        }
    }

    log_allocation_details(*offsets, *keys, *records, size);
