class ConfigManager {
private:
    std::map<std::string, std::string> configMap;
    std::mutex mtx;
    std::mt19937 prng;

public:
    ConfigManager() : prng(std::random_device{}()) {}

    void loadConfigFromAPI(const std::string& url) {
        // Simulate loading config from a REST API
        std::this_thread::sleep_for(std::chrono::seconds(1));
        configMap = {{"network_timeout", "5000"}, {"retry_interval", "300"}};
    }

    void updateConfig(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mtx);
        configMap[key] = value;
    }

    void deleteConfig(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        if (configMap.find(key) != configMap.end()) {
            configMap.erase(key);
        }
    }

    std::string getConfig(const std::string& key) const {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = configMap.find(key);
        if (it != configMap.end()) {
            return it->second;
        }
        return "";
    }

    int getRandomThreshold(int min, int max) {
        std::uniform_int_distribution<int> dis(min, max);
        return dis(prng);
    }

    void monitorHealth() {
        // Simulate health monitoring
        while (true) {
            std::cout << "Checking system health..." << std::endl;
            std::this_thread::sleep_for(std::chrono::seconds(5));
        }
    }

    void applyUpdatesIfNecessary() {
        // Simulate applying updates
        std::lock_guard<std::mutex> lock(mtx);
        if (configMap.empty()) {
            loadConfigFromAPI("http://example.com/api/config");
        }
    }
};

int main() {
    ConfigManager configManager;
    configManager.loadConfigFromAPI("http://example.com/api/config");

    std::thread healthThread(&ConfigManager::monitorHealth, &configManager);
    healthThread.detach();

    while (true) {
        std::string key = "network_timeout";
        std::cout << "Current " << key << ": " << configManager.getConfig(key) << std::endl;
        int newThreshold = configManager.getRandomThreshold(2500, 7500);
        configManager.updateConfig("retry_interval", std::to_string(newThreshold));
        std::this_thread::sleep_for(std::chrono::seconds(10));
    }

    return 0;
}
