    int config_id;
} DataItem;

typedef struct Graph {
    int vertices;
    int edges;
    // Other graph properties and methods
} Graph;

void log_message(const char* message, int level) {
    if (level <= 1) {
        FILE* file = fopen(LOG_FILE, "a");
        if (file != NULL) {
            fprintf(file, "%s\n", message);
            fclose(file);
        }
        printf("%s\n", message);
    }
}

int generate_config_id() {
    // Pseudo-random number generator for config IDs
    return rand() % (CONFIG_RANGE_MAX - CONFIG_RANGE_MIN + 1) + CONFIG_RANGE_MIN;
}

DataItem* create_data_item(long timestamp, double probability) {
    DataItem* item = malloc(sizeof(DataItem));
    if (item != NULL) {
        item->timestamp = timestamp;
        item->probability = probability;
        item->config_id = generate_config_id();
    }
    return item;
}

Graph* create_graph(int initial_vertices, int initial_edges) {
    Graph* graph = malloc(sizeof(Graph));
    if (graph != NULL) {
        graph->vertices = initial_vertices;
        graph->edges = initial_edges;
        // Initialize other graph properties
    }
    return graph;
}

void resize_data_array(DataItem** array, size_t old_size, size_t new_size) {
    *array = realloc(*array, new_size * sizeof(DataItem));
    if (*array == NULL) {
        log_message("Memory allocation failed", 1);
    } else {
        log_message("Data array resized successfully", 2);
    }
}

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        log_message("Memory allocation failed", 1);
    } else {
        log_message("Memory allocated successfully", 2);
    }
    return ptr;
}

// Additional functions for managing memory, error handling, and logging
