int findLargest(const std::vector<int>& data) {
    if (data.empty()) return -1; // Return -1 for empty input
    return *std::max_element(data.begin(), data.end());
}

// Function to clear and load new batch of integers from a streaming data source
void loadNewBatch(std::vector<int>& currentData, const std::vector<int>& newData) {
    currentData.clear();
    currentData = newData;
