typedef struct {
    long id;
    char name[MAX_NAME_LENGTH];
    double balance;
} Account;

Account* create_accounts(int num_accounts, int *error_code) {
    if (num_accounts > MAX_ACCOUNTS || num_accounts <= 0) {
        *error_code = -1; // Invalid number of accounts
        return NULL;
    }

    srand(time(NULL)); // Seed PRNG

    Account *accounts = (Account *)malloc(num_accounts * sizeof(Account));
    if (!accounts) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    for (int i = 0; i < num_accounts; i++) {
        accounts[i].id = rand(); // Generate unique ID using PRNG
        snprintf(accounts[i].name, MAX_NAME_LENGTH, "User%d", i); // Example name generation
        accounts[i].balance = 0.0; // Initialize balance to zero
    }

    *error_code = 0; // Success
    return accounts;
}

void destroy_accounts(Account *accounts) {
    free(accounts);
}

int main() {
    int error_code;
    Account *accounts = create_accounts(5, &error_code);

    if (error_code == 0) {
        printf("Accounts created successfully.\n");
        destroy_accounts(accounts);
    } else {
        switch (error_code) {
            case -1:
                printf("Invalid number of accounts requested.\n");
                break;
            case -2:
                printf("Memory allocation failed.\n");
                break;
            default:
                printf("Unknown error occurred.\n");
                break;
        }
    }

    return 0;
}
