        configs[i] = (Config*)malloc(sizeof(Config));
        if (!configs[i]) {
            for (long j = 0; j < i; ++j) {
                free(configs[j]);
            }
            free(string_array);
            free(int_array);
            free(configs);
            return NULL;
        }

        configs[i]->probability = drand48();
        configs[i]->config_name = (char*)malloc(256 * sizeof(char));
        if (!configs[i]->config_name) {
            for (long j = 0; j <= i; ++j) {
                free(configs[j]);
            }
            free(string_array);
            free(int_array);
            free(configs);
            return NULL;
