                free(configs[j]);
            }
            free(string_array);
            free(int_array);
            free(configs);
            return NULL;
        }

        configs[i]->unique_id = unique_id;
    }

    *string_array = (char*)calloc(num_strings, sizeof(char));
    if (!*string_array) {
        for (long i = 0; i < num_configs; ++i) {
            free(configs[i]->config_name);
            free(configs[i]);
        }
        free(string_array);
        free(int_array);
        free(configs);
        return NULL;
    }

    *int_array = (long*)calloc(num_ints, sizeof(long));
    if (!*int_array) {
        for (long i = 0; i < num_configs; ++i) {
            free(configs[i]->config_name);
            free(configs[i]);
        }
        free(*string_array);
        free(int_array);
        free(configs);
        return NULL;
    }

