#define MAX_EVENTS 1000

typedef struct {
    long timestamp;
    double value;
} Event;

int initialize_data_structures(long** timestamps, double** values, Event** events, size_t num_events) {
    if (num_events > MAX_EVENTS) {
        return -1; // Error: Too many events
    }

    *timestamps = (long*)malloc(num_events * sizeof(long));
    *values = (double*)malloc(num_events * sizeof(double));
    *events = (Event*)malloc(num_events * sizeof(Event));

    if (!(*timestamps) || !(*values) || !(*events)) {
        free(*timestamps);
        free(*values);
        free(*events);
        return -2; // Error: Memory allocation failed
    }

    // Seed PRNG from /dev/urandom for entropy
    FILE* urandom = fopen("/dev/urandom", "rb");
    if (!urandom) {
        perror("Failed to open /dev/urandom");
        free(*timestamps);
        free(*values);
        free(*events);
        return -3; // Error: Failed to seed PRNG
    }

    uint64_t seed;
    fread(&seed, sizeof(uint64_t), 1, urandom);
    fclose(urandom);

    srand(seed);

    for (size_t i = 0; i < num_events; ++i) {
        (*timestamps)[i] = time(NULL);
        (*values)[i] = ((double)rand() / RAND_MAX) * 2.0 - 1.0;
        (*events)[i].timestamp = (*timestamps)[i];
        (*events)[i].value = (*values)[i];
    }

    return 0; // Success
}
