#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ResourceCollection;

void initResourceCollection(ResourceCollection* collection, size_t initialCapacity) {
    collection->records = (Record*)malloc(initialCapacity * sizeof(Record));
    collection->capacity = initialCapacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

void freeResourceCollection(ResourceCollection* collection) {
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
}

void addOrUpdateResource(ResourceCollection* collection, long offset, int key) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i].offset == offset) {
            collection->records[i].key = key;
            pthread_mutex_unlock(&collection->lock);
            return;
        }
    }
    if (collection->size >= collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        Record* newRecords = (Record*)realloc(collection->records, newCapacity * sizeof(Record));
        if (newRecords == NULL) {
            pthread_mutex_unlock(&collection->lock);
            return; // Handle memory allocation failure
        }
        collection->records = newRecords;
        collection->capacity = newCapacity;
    }
    collection->records[collection->size].offset = offset;
    collection->records[collection->size].key = key;
    ++collection->size;
    pthread_mutex_unlock(&collection->lock);
}

void deleteResource(ResourceCollection* collection, long offset) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->records[i].offset == offset) {
            for (size_t j = i; j < collection->size - 1; ++j) {
                collection->records[j] = collection->records[j + 1];
            }
            --collection->size;
            pthread_mutex_unlock(&collection->lock);
            return;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

// Implement HTTP PUT and DELETE methods to interact with the ResourceCollection
