int recordCount = 0;
pthread_mutex_t mutex;

void initializeResource() {
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        resourceCollection[i].offset = rand();
        resourceCollection[i].key = rand() % 1000;
        resourceCollection[i].value = rand() % 100;
        recordCount++;
    }
}

void updateResource(int identifier, int newValue) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (resourceCollection[i].key == identifier) {
            resourceCollection[i].value = newValue;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void deleteResource(int identifier) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (resourceCollection[i].key == identifier) {
            resourceCollection[i] = (record){rand(), rand() % 1000, rand() % 100};
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void logResourceUsage() {
    printf("Current Record Count: %d\n", recordCount);
}
