#define MAX_RECORDS 1000

typedef struct {
    long offset;
    int key;
    int value;
} record;

record* resourceManager(int method, int identifier, int updateKey, int updateValue) {
    static record records[MAX_RECORDS];
    static int count = 0;
    static int initialized = 0;

    if (!initialized) {
        srand(time(NULL));
        for (int i = 0; i < MAX_RECORDS; i++) {
            records[i].offset = rand() % 1000000;
            records[i].key = rand() % 1000;
            records[i].value = rand() % 1000;
        }
        initialized = 1;
    }

    if (method == PUT) {
        for (int i = 0; i < count; i++) {
            if (records[i].key == identifier) {
                records[i].key = updateKey;
                records[i].value = updateValue;
                return &records[i];
            }
        }
        return NULL;
    } else if (method == DELETE) {
        for (int i = 0; i < count; i++) {
            if (records[i].key == identifier) {
                memset(&records[i], 0, sizeof(record));
                count--;
                return &records[count];
            }
        }
        return NULL;
    }

    return NULL;
}
