#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    int value;
} record;

typedef struct {
    record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} resourceManager;

void resourceManager_init(resourceManager* rm, size_t initialCapacity) {
    rm->records = (record*)malloc(initialCapacity * sizeof(record));
    if (!rm->records) exit(1);
    rm->capacity = initialCapacity;
    rm->size = 0;
    pthread_mutex_init(&rm->mutex, NULL);
    pthread_cond_init(&rm->cond, NULL);
}

void resourceManager_destroy(resourceManager* rm) {
    free(rm->records);
    pthread_mutex_destroy(&rm->mutex);
    pthread_cond_destroy(&rm->cond);
}

int resourceManager_add(resourceManager* rm, long offset, int key, int value) {
    pthread_mutex_lock(&rm->mutex);
    if (rm->size == rm->capacity) {
        record* newRecords = realloc(rm->records, rm->capacity * 2 * sizeof(record));
        if (!newRecords) {
            pthread_mutex_unlock(&rm->mutex);
            return -1;
        }
        rm->records = newRecords;
        rm->capacity *= 2;
    }
    rm->records[rm->size].offset = offset;
    rm->records[rm->size].key = key;
    rm->records[rm->size].value = value;
    ++rm->size;
    pthread_mutex_unlock(&rm->mutex);
    return 0;
}

int resourceManager_get(resourceManager* rm, int key) {
    pthread_mutex_lock(&rm->mutex);
    for (size_t i = 0; i < rm->size; ++i) {
        if (rm->records[i].key == key) {
            pthread_mutex_unlock(&rm->mutex);
            return rm->records[i].value;
        }
    }
    pthread_mutex_unlock(&rm->mutex);
    return -1;
}

void resourceManager_remove(resourceManager* rm, int key) {
    pthread_mutex_lock(&rm->mutex);
    for (size_t i = 0; i < rm->size; ++i) {
        if (rm->records[i].key == key) {
            --rm->size;
            if (i < rm->size) {
                memmove(&rm->records[i], &rm->records[i + 1], (rm->size - i) * sizeof(record));
            }
            break;
        }
    }
    pthread_mutex_unlock(&rm->mutex);
}
