#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

int* allocateLongArray(int size) {
    return (int*)malloc(size * sizeof(int));
}

int* allocateIntArray(int size) {
    return (int*)malloc(size * sizeof(int));
}

record* allocateRecordArray(int size) {
    return (record*)malloc(size * sizeof(record));
}

void initializeArrays(int* longArray, int* intArray, record* recordArray, int size) {
    for (int i = 0; i < size; i++) {
        longArray[i] = i * 10;
        intArray[i] = i + 1;
        recordArray[i].value = rand() % 100; // Random value between 0 and 99
    }
}

void serializeRecords(record* recordArray, int size, FILE* file) {
    for (int i = 0; i < size; i++) {
        fwrite(&recordArray[i], sizeof(record), 1, file);
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator
    int size = 1000; // Example size

    int* longArray = allocateLongArray(size);
    if (longArray == NULL) {
        fprintf(stderr, "Memory allocation failed for long array\n");
        return -1;
    }

    int* intArray = allocateIntArray(size);
    if (intArray == NULL) {
        fprintf(stderr, "Memory allocation failed for int array\n");
        free(longArray);
        return -1;
    }

    record* recordArray = allocateRecordArray(size);
    if (recordArray == NULL) {
        fprintf(stderr, "Memory allocation failed for record array\n");
        free(longArray);
        free(intArray);
        return -1;
    }

    initializeArrays(longArray, intArray, recordArray, size);

    FILE* file = fopen("records.bin", "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        free(longArray);
        free(intArray);
        free(recordArray);
        return -1;
    }

    serializeRecords(recordArray, size, file);

    fclose(file);
    free(longArray);
    free(intArray);
    free(recordArray);

    return 0;
}
