#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_FILENAME_LENGTH 256
#define MAX_REVIEW_COUNT 1000

typedef struct {
    long id;
    int userId;
    double rating;
} Review;

char* transformFilename(const char* original, const char* newFileType) {
    static char transformed[MAX_FILENAME_LENGTH];
    snprintf(transformed, sizeof(transformed), "%.*s_%zu.%s", (int)(strrchr(original, '.') - original), original, strlen(original), newFileType);
    return transformed;
}

Review* generateReviews(const char** filenames, int count, const char* newFileType, long seed) {
    srand(seed);
    Review* reviews = (Review*)malloc(count * sizeof(Review));
    if (!reviews) return NULL;

    for (int i = 0; i < count; ++i) {
        reviews[i].id = rand() % (LONG_MAX / 2); // Generate a pseudo-random ID
        reviews[i].userId = rand() % 10000 + 1;   // Generate a pseudo-random user ID
        reviews[i].rating = ((double)rand() / RAND_MAX) * 5.0; // Generate a pseudo-random rating
    }

    return reviews;
}

int main(int argc, char* argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <new_file_type> <filename_count>\n", argv[0]);
        return 1;
    }

    const char* newFileType = argv[1];
    int count = atoi(argv[2]);

    if (strlen(newFileType) != 3) {
        fprintf(stderr, "New file type must be exactly three characters long.\n");
        return 1;
    }

    const char* filenames[MAX_REVIEW_COUNT];
    for (int i = 0; i < count; ++i) {
        char buffer[256];
        snprintf(buffer, sizeof(buffer), "file%d.txt", i);
        filenames[i] = strdup(buffer);
    }

    Review* reviews = generateReviews(filenames, count, newFileType, time(NULL));
    if (!reviews) {
        fprintf(stderr, "Failed to allocate memory for reviews.\n");
        return 1;
    }

    // Process each transformed filename and review
    for (int i = 0; i < count; ++i) {
        char* transformedFilename = transformFilename(filenames[i], newFileType);
        printf("Transformed Filename: %s\n", transformedFilename);

        // Use reviews[i] as needed

        free((void*)filenames[i]); // Clean up dynamically allocated filenames
    }

    free(reviews); // Free dynamically allocated review structure
    return 0;
}
```

