            double* double_array = (double*)ptr;
            for (size_t i = 0; i < size / sizeof(double); i++) {
                double_array[i] = random_double(5.0, 2.0);
            }
            break;
        case 's':
            char** string_array = (char**)ptr;
            for (size_t i = 0; i < size / sizeof(char*); i++) {
                string_array[i] = malloc(128 * sizeof(char));
                if (string_array[i] == NULL) {
                    printf("Memory allocation failed.\n");
                    exit(1);
                }
                for (int j = 0; j < 127; j++) {
                    string_array[i][j] = rand() % 94 + 33; // Alphanumeric and special symbols
                }
                string_array[i][127] = '\0';
            }
            break;
        case 'r':
            record* record_array = (record*)ptr;
            for (size_t i = 0; i < size / sizeof(record); i++) {
                record_array[i].value = random_int(0, 1000000); // Example range
                record_array[i].floating_point = random_double(5.0, 2.0);
                for (int j = 0; j < 127; j++) {
                    record_array[i].string[j] = rand() % 94 + 33; // Alphanumeric and special symbols
                }
                record_array[i].string[127] = '\0';
            }
            break;
        default:
            printf("Invalid type.\n");
            exit(1);
    }
    return ptr;
}

void free_memory(char type, size_t size, void* data) {
    switch (type) {
        case 's':
            char** string_array = (char**)data;
            for (size_t i = 0; i < size / sizeof(char*); i++) {
                free(string_array[i]);
            }
        // No need to free the array of pointers itself
            break;
        case 'r':
            record* record_array = (record*)data;
            for (size_t i = 0; i < size / sizeof(record); i++) {
                free(record_array[i].string);
            }
        // No need to free the record array itself
            break;
        default:
            free(data);
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    size_t size = 1024; // Example size
    void* long_array = allocate_and_initialize('l', size * sizeof(long), NULL);
    void* int_array = allocate_and_initialize('i', size * sizeof(int), NULL);
    void* double_array = allocate_and_initialize('d', size * sizeof(double), NULL);
    void* string_array = allocate_and_initialize('s', size * sizeof(char*), NULL);
    void* record_array = allocate_and_initialize('r', size * sizeof(record), NULL);

    // Use the allocated arrays...

    free_memory('l', size * sizeof(long), long_array);
    free_memory('i', size * sizeof(int), int_array);
    free_memory('d', size * sizeof(double), double_array);
    free_memory('s', size * sizeof(char*), string_array);
    free_memory('r', size * sizeof(record), record_array);

    return 0;
}
