#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define NUM_PACKETS 1000
#define MIN_KEY -1000
#define MAX_KEY 1000

typedef struct {
    unsigned char byte;
    long offset;
    int key;
} packet;

unsigned long hash_function(long offset, int key) {
    return (offset * 31 + key) % NUM_PACKETS;
}

void initialize_arrays(packet **packets, long **offsets, int **keys, unsigned char **data_bytes) {
    *packets = (packet *)malloc(NUM_PACKETS * sizeof(packet));
    if (*packets == NULL) {
        fprintf(stderr, "Memory allocation failed for packets\n");
        exit(1);
    }

    *offsets = (long *)malloc(NUM_PACKETS * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        free(*packets);
        exit(1);
    }

    *keys = (int *)malloc(NUM_PACKETS * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(*packets);
        free(*offsets);
        exit(1);
    }

    *data_bytes = (unsigned char *)malloc(NUM_PACKETS * sizeof(unsigned char));
    if (*data_bytes == NULL) {
        fprintf(stderr, "Memory allocation failed for data bytes\n");
        free(*packets);
        free(*offsets);
        free(*keys);
        exit(1);
    }
}

void generate_packets(packet *packets, long *offsets, int *keys, unsigned char *data_bytes) {
    srand(time(NULL));

    for (int i = 0; i < NUM_PACKETS; i++) {
        offsets[i] = i;
        keys[i] = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
        data_bytes[i] = rand() % 256;
        packets[i].byte = data_bytes[i];
        packets[i].offset = offsets[i];
        packets[i].key = keys[i];

        unsigned long hash = hash_function(offsets[i], keys[i]);
        while (packets[hash].byte != 0) {
            hash = (hash + 1) % NUM_PACKETS;
        }
        packets[hash] = packets[i];
    }
}

void print_packets(packet *packets, int count) {
    for (int i = 0; i < count; i++) {
        printf("Packet %d: byte=%c, offset=%ld, key=%d\n", i, packets[i].byte, packets[i].offset, packets[i].key);
    }
}

int main() {
    packet *packets;
    long *offsets;
    int *keys;
    unsigned char *data_bytes;

    initialize_arrays(&packets, &offsets, &keys, &data_bytes);

    generate_packets(packets, offsets, keys, data_bytes);

    print_packets(packets, NUM_PACKETS);

    free(packets);
    free(offsets);
    free(keys);
    free(data_bytes);

    return 0;
}
