#include <openssl/rand.h> // For CSPRNG
#include <stdio.h>

// Define a struct for financial transaction records
typedef struct {
    uint64_t transaction_id;
    time_t timestamp;
    double amount;
    char description[256];
} TransactionRecord;

// Function to securely generate a unique transaction ID using CSPRNG
uint64_t secure_transaction_id() {
    static bool seeded = false;
    if (!seeded) {
        RAND_seed(time(NULL), sizeof(time_t));
        seeded = true;
    }
    uint64_t id;
    while (RAND_bytes((unsigned char *)&id, sizeof(id)) != 1) {}
    return id;
}

// Function to allocate and initialize a dynamic collection of transaction records
TransactionRecord* init_transaction_collection(size_t initial_size, size_t *collection_size, FILE *log_file, bool log_to_console) {
    TransactionRecord *collection = malloc(initial_size * sizeof(TransactionRecord));
    if (!collection) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    time_t start_time = time(NULL);
    for (size_t i = 0; i < initial_size; ++i) {
        collection[i].transaction_id = secure_transaction_id();
        collection[i].timestamp = time(NULL);
        collection[i].amount = rand() * 1.0 / RAND_MAX;
        snprintf(collection[i].description, sizeof(collection[i].description), "Transaction %zu", i);
    }
    time_t end_time = time(NULL);

    size_t total_memory_used = initial_size * sizeof(TransactionRecord);

    if (log_file) {
        fprintf(log_file, "Memory allocation start time: %ld\n", start_time);
        fprintf(log_file, "Memory allocation end time: %ld\n", end_time);
        fprintf(log_file, "Total memory used: %zu bytes\n", total_memory_used);
        for (size_t i = 0; i < initial_size; ++i) {
            fprintf(log_file, "Transaction %zu ID: %llu, Timestamp: %ld, Amount: %.2f, Description: %s\n",
                    i, collection[i].transaction_id, collection[i].timestamp, collection[i].amount, collection[i].description);
        }
    }

    if (log_to_console) {
        printf("Memory allocation start time: %ld\n", start_time);
        printf("Memory allocation end time: %ld\n", end_time);
        printf("Total memory used: %zu bytes\n", total_memory_used);
        for (size_t i = 0; i < initial_size; ++i) {
            printf("Transaction %zu ID: %llu, Timestamp: %ld, Amount: %.2f, Description: %s\n",
                   i, collection[i].transaction_id, collection[i].timestamp, collection[i].amount, collection[i].description);
        }
    }

    *collection_size = initial_size;
    return collection;
}

// Example usage
int main() {
    FILE *log_file = fopen("memory_allocation_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    size_t initial_size = 1024;
    size_t collection_size;
    TransactionRecord *transactions = init_transaction_collection(initial_size, &collection_size, log_file, true);
    if (transactions) {
        free(transactions);
    }
    fclose(log_file);

    return 0;
}
