    std::mt19937 gen;
    std::mutex mtx;
    std::atomic<bool> isUpdating;

public:
    ConfigManager() : gen(rd()), isUpdating(false) {}

    void loadConfig(const std::string& profile) {
        // Simulate fetching configuration from a REST API
        configSettings = {"retry_interval", 10}, {"connection_timeout", 30}};
        // Simulate applying PRNG-based adjustments
        adjustConfig(profile);
    }

    void updateConfig(const std::string& key, int value) {
        std::lock_guard<std::mutex> lock(mtx);
        if (isUpdating) return; // Prevent recursive updates
        isUpdating = true;
        configSettings[key] = value;
        isUpdating = false;
        propagateUpdates();
    }

    void adjustConfig(const std::string& profile) {
        // Simulate PRNG-based adjustments based on profile and system state
        std::uniform_int_distribution<> dis(1, 5);
        for (auto& pair : configSettings) {
            pair.second += dis(gen);
        }
    }

    void propagateUpdates() {
        // Simulate propagating updates across the distributed system
        std::cout << "Updating configuration across nodes..." << std::endl;
    }

    void monitorHealth() {
        // Simulate monitoring configuration health
        if (configSettings["retry_interval"] > 60) {
            updateConfig("retry_interval", 30);
            std::cout << "Retry interval updated due to health check." << std::endl;
        }
    }
};

int main() {
    ConfigManager manager;
    manager.loadConfig("default");
    manager.updateConfig("retry_interval", 20);
    manager.monitorHealth();
    return 0;
