// Function to manage dynamic memory allocation for arrays and config structures
int allocate_memory(long* int_array, char*** string_array, config** config_array, size_t array_size) {
    // Allocate memory for the integer array
    if ((int_array = (long*)malloc(array_size * sizeof(long))) == NULL) {
        return -1; // Return error code on allocation failure
    }

    // Allocate memory for the string array
    if ((*string_array = (char**)malloc(array_size * sizeof(char*))) == NULL) {
        free(int_array); // Free previously allocated integer array
        return -2; // Return error code on allocation failure
    }

    // Allocate memory for the config structure array
    if ((config_array = (config*)malloc(array_size * sizeof(config))) == NULL) {
        free(string_array); // Free previously allocated string array
        free(int_array); // Free previously allocated integer array
        return -3; // Return error code on allocation failure
    }

    // Initialize the config structure array with unique identifiers and sample data
    uint64_t seed = 123456789;
    for (size_t i = 0; i < array_size; ++i) {
        int_array[i] = fast_prng(seed);
        seed = fast_prng(seed);

        // Allocate memory for each string in the string array
        if ((*string_array[i] = (char*)malloc(256 * sizeof(char))) == NULL) {
            free_config_array(config_array, array_size); // Free previously allocated arrays
            return -4; // Return error code on allocation failure
        }

        snprintf((*string_array[i]), 256, "Config_%zu", i);

        config_array[i].probability = (double)i / array_size;
        snprintf(config_array[i].name, sizeof(config_array[i].name), "Config%zu", i);
