#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_INPUT_SIZE 10000

typedef struct record {
    int value;
} Record;

int find(int parent[], int i) {
    if (parent[i] == -1)
        return i;
    return find(parent, parent[i]);
}

void unionSet(int parent[], int x, int y) {
    int xroot = find(parent, x);
    int yroot = find(parent, y);

    if (xroot != yroot) {
        parent[xroot] = yroot;
    }
}

int initializeAndCountDisjointPairs(int inputArray[], int size, long** offsets, int** keys, Record** records, double* executionTime) {
    if (size > MAX_INPUT_SIZE) {
        fprintf(stderr, "Input size exceeds maximum allowed.\n");
        return -1;
    }

    *offsets = malloc(size * sizeof(long));
    *keys = malloc(size * sizeof(int));
    *records = malloc(size * sizeof(Record));

    if (!*offsets || !*keys || !*records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }

    srand(time(NULL)); // Seed for reproducible random numbers
    clock_t start = clock();

    for (int i = 0; i < size; i++) {
        (*offsets)[i] = rand() % size;
        (*keys)[i] = rand() % size;
        (*records)[i].value = rand() % size;

        int x = find(*records, i);
        int y = find(*records, (i + 1) % size);

        if (x != y) {
            unionSet(*records, x, y);
        }
    }

    clock_t end = clock();
    *executionTime = ((double)(end - start)) / CLOCKS_PER_SEC;

    return size;
}

int main() {
    int inputArray[] = {1, 2, 3, 4, 5};
    int size = sizeof(inputArray) / sizeof(inputArray[0]);

    long* offsets;
    int* keys;
    Record* records;
    double executionTime;

    int result = initializeAndCountDisjointPairs(inputArray, size, &offsets, &keys, &records, &executionTime);

    if (result != -1) {
        printf("Number of disjoint pairs: %d\n", result);
        printf("Execution time: %.2f milliseconds\n", executionTime * 1000);

        free(offsets);
        free(keys);
        for (int i = 0; i < size; i++) {
            free(records[i].value); // Assuming each record's value is dynamically allocated
        }
        free(records);
    }

    return 0;
}
