#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define structures and types
typedef struct {
    char buffer[1024];
    int field;
    unsigned int checksum;
} record;

typedef struct {
    long *timestamps;
    int *identifiers;
    record **records;
    char **metadata;
    size_t count;
    size_t capacity;
} data_store;

// Function to generate pseudo-random value
unsigned long gen_random() {
    static unsigned long seed = 123456789L;
    return seed = seed * 1103515245 + 12345;
}

// Initialize data store with given capacity
data_store* init_data_store(size_t initial_capacity) {
    data_store *ds = (data_store *)malloc(sizeof(data_store));
    ds->timestamps = (long *)calloc(initial_capacity, sizeof(long));
    ds->identifiers = (int *)calloc(initial_capacity, sizeof(int));
    ds->records = (record **)calloc(initial_capacity, sizeof(record *));
    ds->metadata = (char **)calloc(initial_capacity, sizeof(char *));
    ds->count = 0;
    ds->capacity = initial_capacity;
    return ds;
}

// Free allocated memory for data store
void free_data_store(data_store *ds) {
    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->records[i]->buffer);
        free(ds->records[i]);
        free(ds->metadata[i]);
    }
    free(ds->timestamps);
    free(ds->identifiers);
    free(ds->records);
    free(ds->metadata);
    free(ds);
}

// Add a new record to the data store
void add_record(data_store *ds, const char *buffer, int field) {
    if (ds->count == ds->capacity) {
        ds->timestamps = realloc(ds->timestamps, ds->capacity * 2 * sizeof(long));
        ds->identifiers = realloc(ds->identifiers, ds->capacity * 2 * sizeof(int));
        ds->records = realloc(ds->records, ds->capacity * 2 * sizeof(record *));
        ds->metadata = realloc(ds->metadata, ds->capacity * 2 * sizeof(char *));
        ds->capacity *= 2;
    }

    record *rec = (record *)malloc(sizeof(record));
    rec->field = field;
    strncpy(rec->buffer, buffer, sizeof(rec->buffer) - 1);
    rec->buffer[sizeof(rec->buffer) - 1] = '\0';

    // Calculate checksum
    unsigned int sum = 0;
    for (size_t i = 0; rec->buffer[i]; ++i)
        sum += (unsigned char)rec->buffer[i];
    rec->checksum = sum;

    ds->records[ds->count] = rec;
    ds->metadata[ds->count] = strdup("Record created");
    ++ds->count;
}

// Example usage
int main() {
    srand(time(NULL));
    data_store *store = init_data_store(100);

    for (size_t i = 0; i < 150; ++i) {
        char buffer[16];
        snprintf(buffer, sizeof(buffer), "Data %zu", i);
        add_record(store, buffer, gen_random() % 100);
    }

    free_data_store(store);
    return 0;
}
```

