// Define the structure for a linked list node
typedef struct Node {
    int value;
    struct Node* next;
} Node;

// Function to create a new node with the given value
Node* create_node(int value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

// Function to add a node to the end of the linked list
void add_node(Node** head, int value) {
    Node* new_node = create_node(value);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to generate a cryptographically secure pseudo-random number
int csprng() {
    static int seed = 0;
    if (seed == 0) {
        srand(time(NULL)); // Initialize seed with the current time
    }
    return rand();
}

// Function to populate the linked list from an external data source
void populate_list(Node** head, FILE* input_stream) {
    while (!feof(input_stream)) {
        int value;
        if (fscanf(input_stream, "%d", &value) == 1) {
            add_node(head, value);
        } else {
            // If the fscanf fails, generate a random number
            add_node(head, csprng());
        }
    }
}

// Function to iterate over the linked list and perform operations
void process_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        // Perform operations on each record here
        printf("%d ", current->value);
        current = current->next;
    }
    printf("\n");
}

// Function to export the collected data back to the external source
void export_data(Node* head, FILE* output_stream) {
    Node* current = head;
    while (current != NULL) {
        fprintf(output_stream, "%d ", current->value);
        current = current->next;
    }
    fprintf(output_stream, "\n");
}

// Function to free the memory allocated for the linked list
void free_list(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }
    *head = NULL;
}

int main() {
    FILE* input_stream = fopen("input.txt", "r");
    FILE* output_stream = fopen("output.txt", "w");

    if (input_stream == NULL || output_stream == NULL) {
        fprintf(stderr, "Failed to open file\n");
        return 1;
    }

    Node* head = NULL;

    // Populate the linked list from the external data source
    populate_list(&head, input_stream);

    // Process the linked list and perform operations
    process_list(head);

    // Export the collected data back to the external source
    export_data(head, output_stream);

    // Free the memory allocated for the linked list
    free_list(&head);

    fclose(input_stream);
    fclose(output_stream);

    return 0;
}
