#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct Record {
    int value;
} Record;

// Define the doubly-linked list node
typedef struct Node {
    long offset;
    int key;
    Record *record;
    struct Node *prev;
    struct Node *next;
} Node;

// Function to initialize a new record with a random value
Record* init_record() {
    Record *rec = (Record*)malloc(sizeof(Record));
    rec->value = rand(); // Using rand for simplicity, consider using a CSPRNG for production
    return rec;
}

// Function to create and initialize a new node
Node* create_node(long offset, int key) {
    Node *node = (Node*)malloc(sizeof(Node));
    node->offset = offset;
    node->key = key;
    node->record = init_record();
    node->prev = NULL;
    node->next = NULL;
    return node;
}

// Function to add a new node at the end of the list
void add_node(Node **head, long offset, int key) {
    Node *new_node = create_node(offset, key);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
        new_node->prev = current;
    }
}

// Function to remove a node at the specified position
void remove_node(Node **head, int position) {
    if (*head == NULL) return;
    Node *current = *head;
    for (int i = 0; current != NULL && i < position; i++) {
        current = current->next;
    }
    if (current == NULL) return;
    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        *head = current->next;
    }
    if (current->next != NULL) {
        current->next->prev = current->prev;
    }
    free(current);
}

// Function to iterate over the list in forward direction
void print_forward(Node *head, int threshold) {
    Node *current = head;
    while (current != NULL) {
        if (current->record->value > threshold) {
            printf("Value: %d\n", current->record->value);
        }
        current = current->next;
    }
}

// Function to iterate over the list in backward direction
void print_backward(Node *head, int threshold) {
    Node *current = head;
    while (current != NULL && current->next != NULL) {
        current = current->next;
    }
    while (current != NULL) {
        if (current->record->value > threshold) {
            printf("Value: %d\n", current->record->value);
        }
        current = current->prev;
    }
}

// Function to validate the linked list structure
void validate_list(Node *head) {
    Node *current = head;
    while (current != NULL) {
        if (current->next != NULL && current->next->prev != current ||
            current->prev != NULL && current->prev->next != current) {
            printf("List corruption detected!\n");
            return;
        }
        current = current->next;
    }
    printf("List is valid.\n");
}

// Function to free all allocated memory
void free_list(Node *head) {
    Node *current = head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp->record);
        free(temp);
    }
}
```

