#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Node {
    int value;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} LinkedList;

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insertNode(LinkedList* list, int value) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->value = value;
    newNode->prev = list->tail;
    newNode->next = NULL;

    if (list->tail != NULL) {
        list->tail->next = newNode;
    } else {
        list->head = newNode;
    }
    list->tail = newNode;
    pthread_mutex_unlock(&list->lock);
}

void* prngThread(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    while (1) {
        insertNode(list, rand()); // Use a secure PRNG for production
        sleep(1); // Simulate varying rates of incoming data
    }
    return NULL;
}

// Additional functions for filtering, sorting, aggregating, exporting data,
// logging, handling network failures, and concurrent access will be implemented here.

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    while (list->head != NULL) {
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);
    }
    list->tail = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
```

