using System;

public class RandomValueGenerator
{
    private readonly Random _random;
    public int MinIntBound { get; }
    public int MaxIntBound { get; }
    public float MinFloatBound { get; }
    public float MaxFloatBound { get; }

    public RandomValueGenerator(int minIntBound, int maxIntBound, float minFloatBound, float maxFloatBound)
    {
        if (minIntBound > maxIntBound || minFloatBound > maxFloatBound)
            throw new ArgumentException("Invalid bounds");

        MinIntBound = minIntBound;
        MaxIntBound = maxIntBound;
        MinFloatBound = minFloatBound;
        MaxFloatBound = maxFloatBound;

        _random = new Random();
    }

    public int NextInt()
    {
        return _random.Next(MinIntBound, MaxIntBound + 1);
    }

    public float NextFloat()
    {
        return (float)(_random.NextDouble() * (MaxFloatBound - MinFloatBound) + MinFloatBound);
    }
}
