        }
        sessions[i].timestamp = time(NULL);
        strncpy(sessions[i].status, defaultStatus, sizeof(sessions[i].status) - 1);
    }

    return sessions;
}

void freeSessions(Session* sessions, int size) {
    if (sessions != NULL) free(sessions);
}
