#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <openssl/rand.h>

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

Record* allocate_and_initialize_records(size_t initial_size, size_t* actual_size) {
    if (initial_size == 0) return NULL;

    // Allocate initial memory for the linked list
    Node* head = malloc(sizeof(Node));
    if (!head) {
        *actual_size = 0;
        return NULL;
    }
    head->next = NULL;

    // Initialize random seed using CSPRNG
    if (RAND_bytes((unsigned char*)&initial_size, sizeof(initial_size)) != 1) {
        free(head);
        *actual_size = 0;
        return NULL;
    }

    Node* current = head;
    for (size_t i = 1; i < initial_size; ++i) {
        // Allocate memory for each node
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            // Free previously allocated nodes on failure
            while (head) {
                Node* temp = head;
                head = head->next;
                free(temp);
            }
            *actual_size = i;
            return NULL;
        }

        current->next = new_node;
        current = new_node;

        // Generate random values for the record fields
        if (RAND_bytes((unsigned char*)&new_node->data.key, sizeof(new_node->data.key)) != 1 ||
            RAND_bytes((unsigned char*)&new_node->data.offset, sizeof(new_node->data.offset)) != 1) {
            // Free previously allocated nodes on failure
            while (head) {
                Node* temp = head;
                head = head->next;
                free(temp);
            }
            *actual_size = i + 1;
            return NULL;
        }
    }

    *actual_size = initial_size;
    return head->data.key; // Return pointer to the array of keys
}
