int* allocateAndInitializeKeys(int size) {
    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        // Handle allocation failure
        logError("Failed to allocate memory for keys");
        return NULL;
    }
    // Initialize keys
    for (int i = 0; i < size; ++i) {
        keys[i] = i + 1; // Example initialization logic
    }
    return keys;
}

Record* allocateAndInitializeRecords(int targetValue, int minValue, int maxValue) {
    if (targetValue <= 0 || minValue >= maxValue) {
        logError("Invalid input parameters");
        return NULL;
    }

    Record* records = (Record*)malloc(targetValue * sizeof(Record));
    if (!records) {
        // Handle allocation failure
        logError("Failed to allocate memory for records");
        return NULL;
    }

    int currentSum = 0;
    while (currentSum < targetValue) {
        int randomValue;
        if (!RAND_bytes((unsigned char*)&randomValue, sizeof(randomValue))) {
            // Handle CSPRNG failure
            logError("Failed to generate cryptographically secure random number");
            free(records);
            return NULL;
        }

        randomValue = (randomValue % (maxValue - minValue + 1)) + minValue;
        if (currentSum > 0 && records[currentSum - 1].value == randomValue) {
            continue; // Ensure no two consecutive records have the same value
        }
        records[currentSum].value = randomValue;
        currentSum += randomValue;
    }

    return records;
}

void initializeArrays(int targetValue, int minValue, int maxValue, long** offsets, int** keys, Record** records) {
    *offsets = allocateAndInitializeOffsets(targetValue);
    if (!*offsets) {
        // Handle allocation failure
        logError("Failed to allocate memory for offsets");
        return;
    }

    *keys = allocateAndInitializeKeys(targetValue);
    if (!*keys) {
        // Handle allocation failure
        logError("Failed to allocate memory for keys");
        free(*offsets);
        return;
    }

    *records = allocateAndInitializeRecords(targetValue, minValue, maxValue);
    if (!*records) {
        // Handle allocation failure
        logError("Failed to allocate memory for records");
        free(*offsets);
        free(*keys);
        return;
    }
}

