#define MAX_RECORDS 1024

long* offsets = NULL;
int* keys = NULL;
record* records = NULL;
char** metadata = NULL;
int num_records = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_arrays(int initial_size) {
    offsets = (long*)malloc(initial_size * sizeof(long));
    keys = (int*)malloc(initial_size * sizeof(int));
    records = (record*)malloc(initial_size * sizeof(record));
    metadata = (char**)malloc(initial_size * sizeof(char*));

    if (!offsets || !keys || !records || !metadata) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < initial_size; ++i) {
        offsets[i] = -1;
        keys[i] = -1;
        records[i].value = 0;
        metadata[i] = NULL;
    }
}

void* worker_thread(void* arg) {
    int thread_id = *(int*)arg;

    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&lock);
        if (offsets[i] == -1 && keys[i] == -1) {
            offsets[i] = i;
            keys[i] = rand() % 10000 + thread_id * 10000; // Ensure unique keys
            records[i].value = rand() % (num_records / 2);
            metadata[i] = strdup("New record");
        }
        pthread_mutex_unlock(&lock);

        // Simulate some work
        usleep(rand() % 1000);
    }

    free(arg);
    return NULL;
}

int main() {
    srand(time(NULL));
    int initial_size = 512;

    initialize_arrays(initial_size);

    pthread_t threads[4];
    int thread_ids[4];

    for (int i = 0; i < 4; ++i) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, worker_thread, &thread_ids[i]) != 0) {
            perror("Thread creation failed");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Clean up
    free(offsets);
    free(keys);
    for (int i = 0; i < num_records; ++i) {
        free(metadata[i]);
    }
    free(records);

    return 0;
}
