#include <time.h>

typedef struct {
    int value;
} Record;

#define MAX_RECORDS 1001

void prng_init(unsigned seed);
unsigned prng_get_random();

void initialize_data_structures(int *long_offsets, int *int_keys, Record *records, int num_records, FILE *log_fd) {
    if (num_records > MAX_RECORDS) {
        fprintf(log_fd, "Error: Number of records exceeds maximum limit.\n");
        return;
    }

    prng_init(time(NULL)); // Seed the PRNG with current time

    for (int i = 0; i < num_records; i++) {
        long_offsets[i] = prng_get_random();
        int_keys[i] = prng_get_random();

        if (records[i].value != 0) { // Check if record is already initialized
            fprintf(log_fd, "Warning: Record %d is already initialized. Overwriting.\n", i);
        }
        records[i].value = prng_get_random();
    }

    // Log successful initialization
    fprintf(log_fd, "Data structures initialized successfully for %d records.\n", num_records);
}

void prng_init(unsigned seed) {
    srand(seed);
}

unsigned prng_get_random() {
    return rand() % 1001; // Generates a pseudo-random number between 0 and 1000
}
