#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000000
#define INITIAL_CAPACITY 1024

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} array_pool;

array_pool *create_array_pool(size_t initial_capacity) {
    array_pool *pool = malloc(sizeof(array_pool));
    if (!pool) {
        perror("Memory allocation failed for pool");
        return NULL;
    }

    pool->offsets = malloc(initial_capacity * sizeof(long));
    pool->keys = malloc(initial_capacity * sizeof(int));
    pool->records = malloc(initial_capacity * sizeof(record *));
    pool->capacity = initial_capacity;
    pool->count = 0;

    if (!pool->offsets || !pool->keys || !pool->records) {
        perror("Memory allocation failed for arrays");
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    srand(time(NULL));
    for (size_t i = 0; i < initial_capacity; ++i) {
        pool->records[i] = malloc(sizeof(record));
        if (!pool->records[i]) {
            perror("Memory allocation failed for record");
            array_pool_destroy(pool);
            return NULL;
        }
        pool->records[i]->value = rand() % 1001;
    }

    return pool;
}

void destroy_array_pool(array_pool *pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->records[i]);
    }
    pthread_mutex_destroy(&pool->lock);
    free(pool->offsets);
    free(pool->keys);
    free(pool->records);
    free(pool);
}

void *array_pool_add_record(array_pool *pool, long offset, int key) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count == pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        long *new_offsets = realloc(pool->offsets, new_capacity * sizeof(long));
        int *new_keys = realloc(pool->keys, new_capacity * sizeof(int));
        record **new_records = realloc(pool->records, new_capacity * sizeof(record *));

        if (!new_offsets || !new_keys || !new_records) {
            perror("Memory reallocation failed");
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }

        pool->offsets = new_offsets;
        pool->keys = new_keys;
        pool->records = new_records;
        pool->capacity = new_capacity;

        for (size_t i = pool->count; i < new_capacity; ++i) {
            pool->records[i] = malloc(sizeof(record));
            if (!pool->records[i]) {
                perror("Memory allocation failed for record");
                array_pool_destroy(pool);
                pthread_mutex_unlock(&pool->lock);
                return NULL;
            }
            pool->records[i]->value = rand() % 1001;
        }
    }

    pool->offsets[pool->count] = offset;
    pool->keys[pool->count] = key;
    void *result = (void *)pool->records[pool->count];
    ++pool->count;

    pthread_mutex_unlock(&pool->lock);
    return result;
}

// Add other functions as needed, such as array_pool_remove_record, array_pool_get_record, etc.
