#include <time.h>

typedef struct {
    int value;
    char status;
} record;

unsigned long custom_prng(unsigned long seed) {
    seed *= 6364136223809551615UL + 1;
    return seed >> 17;
}

record* allocate_and_initialize(int* keys, int key_count, int min_value, int max_value, unsigned long* seed, bool* success) {
    if (key_count < 0 || min_value > max_value) {
        *success = false;
        return NULL;
    }

    record* records = (record*)malloc(key_count * sizeof(record));
    unsigned long* offsets = (unsigned long*)malloc(key_count * sizeof(unsigned long));

    if (!records || !offsets) {
        free(records);
        free(offsets);
        *success = false;
        return NULL;
    }

    bool* used_offsets = (bool*)calloc(key_count, sizeof(bool));
    srand(time(NULL)); // Seed for the custom PRNG

    for (int i = 0; i < key_count; ++i) {
        unsigned long offset;
        do {
            *seed = custom_prng(*seed);
            offset = (*seed & 0xFFFFFFFF); // Simplified for demonstration
        } while (used_offsets[offset % key_count]);

        used_offsets[offset % key_count] = true;
        offsets[i] = offset;

        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].status = 'I'; // Initialized
    }

    *success = true;
    free(used_offsets);
    return records;
}

void cleanup(record* records, unsigned long* offsets, int key_count) {
    free(records);
    free(offsets);
}
