} record;

int populate_secure_records(record** records, size_t num_records) {
    *records = (record*)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        return -1; // Memory allocation failed
    }

    for (size_t i = 0; i < num_records; i++) {
        memset(&(*records)[i], 0, sizeof(record));
        (*records)[i].timestamp = time(NULL);
        (*records)[i].label[64] = '\0';

        // Seed the random number generator
        unsigned char seed[32];
        if (!RAND_bytes(seed, sizeof(seed))) {
            fprintf(stderr, "Error generating random seed\n");
            free(*records);
            return -1;
        }
        RAND_seed(seed, sizeof(seed));

        // Generate unique secure identifier
        do {
            (*records)[i].id = (unsigned long)rand();
        } while (is_identifier_duplicate(*records, num_records, i));

        // Allocate memory for additional fields
        (*records)[i].key_indices = (size_t*)malloc(10 * sizeof(size_t));
        (*records)[i].random_weights = (double*)malloc(10 * sizeof(double));
        (*records)[i].flags = (bool*)malloc(10 * sizeof(bool));

        if ((*records)[i].key_indices == NULL || 
            (*records)[i].random_weights == NULL || 
            (*records)[i].flags == NULL) {
            fprintf(stderr, "Error allocating memory for additional fields\n");
            free_records(*records, num_records);
            return -1;
        }

        // Initialize additional fields
        for (size_t j = 0; j < 10; j++) {
            (*records)[i].key_indices[j] = rand();
            (*records)[i].random_weights[j] = ((double)rand()) / RAND_MAX;
            (*records)[i].flags[j] = (bool)(rand() % 2);
        }
    }

    return 0;
}

void free_records(record* records, size_t num_records) {
    for (size_t i = 0; i < num_records; i++) {
        if (records[i].key_indices != NULL) {
            free(records[i].key_indices);
        }
        if (records[i].random_weights != NULL) {
            free(records[i].random_weights);
        }
        if (records[i].flags != NULL) {
            free(records[i].flags);
        }
    }
    free(records);
}

bool is_identifier_duplicate(record* records, size_t num_records, size_t index) {
    for (size_t i = 0; i < index; i++) {
        if (records[index].id == records[i].id) {
            return true;
        }
    }
    return false;
}
