    // Allocate memory for offsets
    long* offsets = (long*)malloc(size * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        exit(1);
    }

    // Initialize offsets
    for (int i = 0; i < size; i++) {
        offsets[i] = i;
    }

    // Allocate memory for keys
    int* keys = (int*)malloc(size * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offsets);
        exit(1);
    }

    // Initialize keys with random numbers using a PRNG
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % MAX_RECORD_VALUE;
    }

    // Allocate memory for records
    *records = (record*)malloc(size * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        exit(1);
    }

    // Initialize records with random values within the specified range
    for (int i = 0; i < size; i++) {
        (*records)[i].value = rand() % MAX_RECORD_VALUE;
    }

    // Union-Find data structure to determine disjoint pairs
    *disjointPairsCount = 0;
    for (int i = 1; i < size; i++) {
        clock_t start, end;
        start = clock();
        // Check if the current element is disjoint from any previous elements
        int isDisjoint = 1;
        for (int j = 0; j < i; j++) {
            if ((*records)[i].value == (*records)[j].value) {
                isDisjoint = 0;
                break;
            }
        }
        end = clock();
        double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;
        printf("Time taken for disjointness check %d: %.6f seconds\n", i, time_taken);
        if (isDisjoint) {
            (*disjointPairsCount)++;
        }
    }

    return offsets;
}
