void dynamic_memory_allocation(long num_ints, char** strings, config* configs, int initial_size) {
    if (num_ints > 0) {
        long* int_array = (long*)malloc(num_ints * sizeof(long));
        if (int_array == NULL) {
            perror("Failed to allocate memory for integers");
            exit(EXIT_FAILURE);
        }
        // Initialize array with unique IDs
        for (long i = 0; i < num_ints; ++i) {
            int_array[i] = generate_unique_id();
        }

        // Free allocated memory when done
        free(int_array);
    }

    if (strings != NULL && *strings != NULL) {
        char** string_array = (char**)malloc(initial_size * sizeof(char*));
        if (string_array == NULL) {
            perror("Failed to allocate memory for strings");
            exit(EXIT_FAILURE);
        }
        // Initialize array with unique IDs
        for (int i = 0; i < initial_size; ++i) {
            string_array[i] = (char*)malloc(256 * sizeof(char));
            snprintf(string_array[i], 256, "String_%lu", generate_unique_id());
        }

        // Free allocated memory when done
        for (int i = 0; i < initial_size; ++i) {
            free(string_array[i]);
        }
        free(string_array);
    }

    if (configs != NULL && configs[0].configuration_name != NULL) {
        config* config_array = (config*)malloc(initial_size * sizeof(config));
        if (config_array == NULL) {
            perror("Failed to allocate memory for configurations");
            exit(EXIT_FAILURE);
        }
        // Initialize array with unique IDs and random probabilities
        srand(time(NULL)); // Seed for randomness
        for (int i = 0; i < initial_size; ++i) {
