            config_array[i].configuration_name = (char*)malloc(256 * sizeof(char));
            snprintf(config_array[i].configuration_name, 256, "Config_%lu", generate_unique_id());
        }

        // Free allocated memory when done
        for (int i = 0; i < initial_size; ++i) {
            free(config_array[i].configuration_name);
        }
        free(config_array);
    }
}

