typedef struct {
    unsigned int id;
    char *firmware_version;
    char **event_logs;
    size_t log_count;
} Device;

Device* create_device(Device** device_list, size_t *size, size_t index) {
    if (index >= *size) {
        *size *= 2;
        *device_list = realloc(*device_list, *size * sizeof(Device));
    }
    if (*device_list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    (*device_list)[index].id = rand(); // Replace with CSPRNG for production
    (*device_list)[index].firmware_version = (char *)malloc(10 * sizeof(char));
    if ((*device_list)[index].firmware_version == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    strcpy((*device_list)[index].firmware_version, "v1.0");

    (*device_list)[index].event_logs = (char **)malloc(2 * sizeof(char *));
    if ((*device_list)[index].event_logs == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free((*device_list)[index].firmware_version);
        return NULL;
    }
    for (size_t i = 0; i < 2; i++) {
        (*device_list)[index].event_logs[i] = (char *)malloc(50 * sizeof(char));
        if ((*device_list)[index].event_logs[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            for (size_t j = 0; j < i; j++) {
                free((*device_list)[index].event_logs[j]);
            }
            free((*device_list)[index].firmware_version);
            return NULL;
        }
    }

    (*device_list)[index].log_count = 2;

    return &(*device_list)[index];
}

void destroy_device(Device *device) {
    if (device->firmware_version != NULL) {
        free(device->firmware_version);
    }
    for (size_t i = 0; i < device->log_count; i++) {
        if (device->event_logs[i] != NULL) {
            free(device->event_logs[i]);
        }
    }
    if (device->event_logs != NULL) {
        free(device->event_logs);
    }
}

int main() {
    srand(time(NULL)); // Seed for CSPRNG, replace with actual CSPRNG in production

    size_t size = 1;
    Device *device_list = malloc(size * sizeof(Device));
    if (device_list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    Device *new_device = create_device(&device_list, &size, 0);
    if (new_device != NULL) {
        printf("Device created with ID: %u\n", new_device->id);
    }

    destroy_device(new_device);

    free(device_list);

    return 0;
}
