#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_DEVICES 100
#define MAX_FIRMWARES 50
#define MAX_EVENTS 200

typedef struct {
    int device_id;
} Device;

typedef struct {
    char version[20];
    time_t build_date;
    Device* device_instance;
} Firmware;

typedef struct {
    time_t timestamp;
    char description[100];
    int severity_level;
    Firmware* firmware_version;
} Event;

typedef struct {
    Device** devices;
    Firmware** firmwares;
    Event** events;
    int device_count;
    int firmware_count;
    int event_count;
} MemoryManager;

MemoryManager* init_memory_manager() {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->devices = (Device**)malloc(MAX_DEVICES * sizeof(Device*));
    manager->firmwares = (Firmware**)malloc(MAX_FIRMWARES * sizeof(Firmware*));
    manager->events = (Event**)malloc(MAX_EVENTS * sizeof(Event*));

    manager->device_count = 0;
    manager->firmware_count = 0;
    manager->event_count = 0;

    if (!manager->devices || !manager->firmwares || !manager->events) {
        free(manager);
        return NULL;
    }

    srand(time(NULL)); // Initialize random seed

    return manager;
}

void add_device(MemoryManager* manager) {
    if (manager->device_count >= MAX_DEVICES) return;

    Device* device = (Device*)malloc(sizeof(Device));
    if (!device) return;

    device->device_id = rand(); // Using simple rand() for demonstration purposes

    manager->devices[manager->device_count++] = device;
}

void add_firmware(MemoryManager* manager, const char* version, time_t build_date) {
    if (manager->firmware_count >= MAX_FIRMWARES) return;

    Firmware* firmware = (Firmware*)malloc(sizeof(Firmware));
    if (!firmware) return;

    strcpy(firmware->version, version);
    firmware->build_date = build_date;
    firmware->device_instance = manager->devices[manager->device_count - 1]; // Assuming last device is always the latest

    manager->firmwares[manager->firmware_count++] = firmware;
}

void add_event(MemoryManager* manager, const char* description, int severity_level) {
    if (manager->event_count >= MAX_EVENTS) return;

    Event* event = (Event*)malloc(sizeof(Event));
    if (!event) return;

    time_t now = time(NULL);
    strcpy(event->description, description);
    event->severity_level = severity_level;
    event->timestamp = now;
    event->firmware_version = manager->firmwares[manager->firmware_count - 1]; // Assuming last firmware is always the latest

    manager->events[manager->event_count++] = event;
}

void free_memory_manager(MemoryManager* manager) {
    for (int i = 0; i < manager->device_count; i++) {
        free(manager->devices[i]);
    }
    for (int i = 0; i < manager->firmware_count; i++) {
        free(manager->firmwares[i]);
    }
    for (int i = 0; i < manager->event_count; i++) {
        free(manager->events[i]);
    }

    free(manager->devices);
    free(manager->firmwares);
    free(manager->events);
    free(manager);
}

int main() {
    MemoryManager* manager = init_memory_manager();
    if (!manager) return -1;

    add_device(manager);
    add_firmware(manager, "v1.0", time(NULL));
    add_event(manager, "Device initialized successfully", 1);

    free_memory_manager(manager);

    return 0;
}
