#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    double probability;
    char* config_name;
} Config;

// Define a structure to hold the dynamic arrays and their metadata
typedef struct {
    long* long_array;
    char** string_array;
    Config* config_array;
    size_t array_size;
    size_t max_size;
    pthread_mutex_t mutex; // Mutex for thread-safe operations
} DynamicMemoryManager;

DynamicMemoryManager* create_memory_manager(size_t initial_size) {
    DynamicMemoryManager* manager = (DynamicMemoryManager*)malloc(sizeof(DynamicMemoryManager));
    if (!manager) return NULL;

    manager->long_array = (long*)malloc(initial_size * sizeof(long));
    manager->string_array = (char**)malloc(initial_size * sizeof(char*));
    manager->config_array = (Config*)malloc(initial_size * sizeof(Config));
    manager->array_size = initial_size;
    manager->max_size = initial_size;

    if (!manager->long_array || !manager->string_array || !manager->config_array) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void resize_memory_manager(DynamicMemoryManager* manager, size_t new_size) {
    pthread_mutex_lock(&manager->mutex);
    if (new_size > manager->max_size) {
        manager->long_array = realloc(manager->long_array, new_size * sizeof(long));
        manager->string_array = realloc(manager->string_array, new_size * sizeof(char*));
        manager->config_array = realloc(manager->config_array, new_size * sizeof(Config));
        manager->max_size = new_size;
    }
    pthread_mutex_unlock(&manager->mutex);
}

void initialize_memory_manager(DynamicMemoryManager* manager) {
    for (size_t i = 0; i < manager->array_size; ++i) {
        manager->long_array[i] = rand(); // Initialize with random values
        manager->string_array[i] = malloc(256 * sizeof(char)); // Allocate memory for strings
        sprintf(manager->string_array[i], "Config_%zu", i);
        manager->config_array[i].probability = (double)rand() / RAND_MAX;
        manager->config_array[i].config_name = strdup(manager->string_array[i]);
    }
}

void free_memory_manager(DynamicMemoryManager* manager) {
    for (size_t i = 0; i < manager->array_size; ++i) {
        free(manager->string_array[i]);
        free(manager->config_array[i].config_name);
    }
    free(manager->long_array);
    free(manager->string_array);
    free(manager->config_array);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}
