#define MAX_LOG_ENTRIES 1000

void log_entry(const char* message) {
    static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_mutex);
    printf("%s\n", message);
    // Additional logging to file or network can be added here
    pthread_mutex_unlock(&log_mutex);
}

void *initialize_data(void *args) {
    int thread_id = *(int *)args;
    long range_start = ((thread_id * 100) % MAX_LOG_ENTRIES) + 1;
    long range_end = ((thread_id * 200) % MAX_LOG_ENTRIES) + 1;

    long* long_array = malloc(sizeof(long) * 100);
    char** string_array = malloc(sizeof(char*) * 50);
    Config* config_array = malloc(sizeof(Config) * 30);
    long* offset_array = malloc(sizeof(long) * 20);
    int* key_array = malloc(sizeof(int) * 15);
    Record* record_array = malloc(sizeof(Record) * 10);
    char log_entries[MAX_LOG_ENTRIES][100];

    if (!long_array || !string_array || !config_array || !offset_array || !key_array || !record_array) {
        log_entry("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL) + thread_id);

    for (int i = 0; i < 100; i++) {
        long_array[i] = range_start + rand() % (range_end - range_start);
        log_entries[i][0] = '\0';
        snprintf(log_entries[i], sizeof(log_entries[i]), "Long array entry %d: %ld", i, long_array[i]);
    }

    for (int i = 0; i < 50; i++) {
        string_array[i] = malloc(20);
        snprintf(string_array[i], 20, "String %d", i);
    }

    for (int i = 0; i < 30; i++) {
        config_array[i].id = range_start + rand() % (range_end - range_start);
        config_array[i].value = rand();
