#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define TABLE_SIZE 1024
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct record {
    int value;
} Record;

typedef struct hash_table {
    Record **records;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

HashTable *create_hash_table(size_t initial_size) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Memory allocation failed for hash table\n");
        return NULL;
    }
    table->records = (Record **)calloc(initial_size, sizeof(Record *));
    if (!table->records) {
        free(table);
        fprintf(stderr, "Memory allocation failed for records array\n");
        return NULL;
    }
    table->size = initial_size;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->size; ++i) {
        if (table->records[i]) {
            free(table->records[i]);
        }
    }
    free(table->records);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

unsigned int hash_function(int key, size_t size) {
    return ((unsigned long)key * 2166136261UL + 1) % size;
}

void resize_hash_table(HashTable *table) {
    size_t new_size = table->size * 2;
    Record **new_records = (Record **)calloc(new_size, sizeof(Record *));
    if (!new_records) {
        fprintf(stderr, "Memory allocation failed for resized records array\n");
        return;
    }

    for (size_t i = 0; i < table->size; ++i) {
        Record *record = table->records[i];
        if (record) {
            size_t index = hash_function(record->value, new_size);
            while (new_records[index]) {
                index = (index + 1) % new_size;
            }
            new_records[index] = record;
        }
    }

    free(table->records);
    table->records = new_records;
    table->size = new_size;
}

int insert_record(HashTable *table, int key, int value) {
    pthread_mutex_lock(&table->lock);
    if ((double)table->count / table->size > LOAD_FACTOR_THRESHOLD) {
        resize_hash_table(table);
    }

    size_t index = hash_function(key, table->size);
    while (table->records[index]) {
        index = (index + 1) % table->size;
    }

    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&table->lock);
        fprintf(stderr, "Memory allocation failed for record\n");
        return -1;
    }
    record->value = value;
    table->records[index] = record;
    ++table->count;

    pthread_mutex_unlock(&table->lock);
    return 0;
}

Record *get_record(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->size);
    while (table->records[index] && table->records[index]->value != key) {
        index = (index + 1) % table->size;
    }

    Record *record = table->records[index];
    pthread_mutex_unlock(&table->lock);
    return record;
}

int main() {
    HashTable *table = create_hash_table(TABLE_SIZE);
    if (!table) {
        return -1;
    }

    for (int i = 0; i < 2048; ++i) {
        insert_record(table, i, rand());
    }

    Record *record = get_record(table, 500);
    if (record) {
        printf("Value at key 500: %d\n", record->value);
    } else {
        printf("Key 500 not found in table\n");
    }

    destroy_hash_table(table);
    return 0;
}
