[Route("api/[controller]")]
public class HtmlUpdateController : ControllerBase
{
    private readonly IHtmlValidationService _validationService;
    private readonly ICacheProvider _cacheProvider;
    private readonly ILogger<HtmlUpdateController> _logger;

    public HtmlUpdateController(IHtmlValidationService validationService, ICacheProvider cacheProvider, ILogger<HtmlUpdateController> logger)
    {
        _validationService = validationService;
        _cacheProvider = cacheProvider;
        _logger = logger;
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateElement([FromBody] HtmlUpdateRequest request)
    {
        try
        {
            // Validate inputs
            if (!_validationService.ValidateInputs(request))
            {
                return BadRequest("Invalid input parameters.");
            }

            // Retrieve cached page section
            var pageSection = await _cacheProvider.GetPageSectionAsync(request.PageSectionId);
            if (pageSection == null)
            {
                return NotFound($"Page section with ID '{request.PageSectionId}' not found.");
            }

            // Update element HTML content
            var updatedElement = pageSection.Elements.FirstOrDefault(e => e.Id == request.ElementId);
            if (updatedElement != null)
            {
                updatedElement.HtmlContent = request.HtmlContent;
                await _cacheProvider.UpdatePageSectionAsync(pageSection);

                // Trigger real-time update via WebSockets
                await BroadcastUpdate(request.PageSectionId, updatedElement);

                return Ok("HTML element updated successfully.");
            }

            return NotFound($"Element with ID '{request.ElementId}' not found in page section '{request.PageSectionId}'.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while updating HTML element.");
            return StatusCode(500, "Internal server error.");
        }
