#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/rand.h>

#define MAX_RECORD_SIZE 1024

typedef struct {
    int value;
    char identifier[MAX_RECORD_SIZE];
    time_t timestamp;
} record;

typedef struct node {
    record *data;
    struct node *next;
} node;

node* create_node(record *data) {
    node *new_node = (node *)malloc(sizeof(node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed for new node\n");
        exit(EXIT_FAILURE);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

record* create_record(int range_start, int range_end, const char *identifier_chars, size_t identifier_length) {
    record *rec = (record *)malloc(sizeof(record));
    if (rec == NULL) {
        fprintf(stderr, "Memory allocation failed for new record\n");
        exit(EXIT_FAILURE);
    }

    rec->value = range_start + rand() % (range_end - range_start + 1);

    for (size_t i = 0; i < identifier_length; ++i) {
        rec->identifier[i] = identifier_chars[rand() % strlen(identifier_chars)];
    }
    rec->identifier[identifier_length] = '\0';

    rec->timestamp = time(NULL);
    return rec;
}

node* initialize_arrays(size_t array_size, int range_start, int range_end, const char *identifier_chars, size_t identifier_length) {
    srand(time(NULL));
    node *head = NULL;

    for (size_t i = 0; i < array_size; ++i) {
        record *rec = create_record(range_start, range_end, identifier_chars, identifier_length);
        node *new_node = create_node(rec);

        if (head == NULL) {
            head = new_node;
        } else {
            node *temp = head;
            while (temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
    }

    return head;
}

void cleanup_records(node **head) {
    node *current = *head;
    node *next;

    while (current != NULL) {
        next = current->next;
        free(current->data);
        free(current);
        current = next;
    }

    *head = NULL;
}

int export_to_file(const char *filename, node *head) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return -1;
    }

    while (head != NULL) {
        fprintf(file, "%d,%s,%ld\n", head->data->value, head->data->identifier, (long)head->data->timestamp);
        head = head->next;
    }

    fclose(file);
    return 0;
}

int main() {
    size_t array_size = 1000;
    int range_start = -1000;
    int range_end = 1000;
    const char *identifier_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    size_t identifier_length = 5;

    node *head = initialize_arrays(array_size, range_start, range_end, identifier_chars, identifier_length);

    // Example usage: Export records to a file
    export_to_file("records.txt", head);

    cleanup_records(&head);

    return 0;
}
