void* allocate_memory(size_t long_size, size_t int_size, size_t record_size, time_t seed_interval) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static time_t last_seed_time = 0;
    static unsigned int seed = time(NULL);

    // Lock the mutex to ensure thread-safe access
    pthread_mutex_lock(&mutex);

    if (time(NULL) - last_seed_time > seed_interval) {
        seed = time(NULL);
        last_seed_time = time(NULL);
    }

    srand(seed);

    long* offsets = (long*)malloc(long_size * sizeof(long));
    int* keys = (int*)malloc(int_size * sizeof(int));
    Record* records = (Record*)malloc(record_size * sizeof(Record));

    if (!offsets || !keys || !records) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    for (size_t i = 0; i < long_size; ++i) {
        offsets[i] = rand();
    }

    for (size_t i = 0; i < int_size; ++i) {
        keys[i] = rand() % 1000; // Example range
    }

    for (size_t i = 0; i < record_size; ++i) {
        records[i].value = rand() % 1000; // Example range
    }

    pthread_mutex_unlock(&mutex);

    return (void*)records;
}
