    pthread_mutex_init(&lock, NULL);

    srand(time(NULL));
    for (size_t i = 0; i < num_elements; ++i) {
        (*offsets)[i] = rand() % range_end + range_start;
        (*keys)[i] = rand() % range_end + range_start;

        pthread_mutex_lock(&lock);
        (*records)[i].value = rand() % (range_end - range_start) + range_start;
        pthread_mutex_unlock(&lock);

        // Periodically reset PRNG state
        if ((i + 1) % 10000 == 0) {
            srand(time(NULL));
        }
    }

    pthread_mutex_destroy(&lock);
    return NULL;
