#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    int value;
} Record;

typedef struct session {
    unsigned long id;
} Session;

typedef struct user {
    char* name;
    char* email;
    Session sessionId;
} User;

typedef struct transaction {
    unsigned long timestamp;
    double amount;
    char* description;
    User* userProfile;
} Transaction;

typedef struct hash_table_entry {
    unsigned long key;
    void* value;
    struct hash_table_entry* next;
} HashTableEntry;

typedef struct hash_table {
    HashTableEntry** buckets;
    size_t bucket_count;
    size_t size;
    float load_factor_threshold;
    pthread_mutex_t mutex;
} HashTable;

unsigned long custom_hash_function(const void* key, size_t seed) {
    // Implement a performance-optimized hash function
    // Example: Jenkins one-at-a-time hash
    unsigned long h = seed;
    const char *str = (const char*)key;
    while (*str) {
        h += *str++;
        h += (h << 10);
        h ^= (h >> 6);
    }
    h += (h << 3);
    h ^= (h >> 11);
    h += (h << 15);
    return h;
}

HashTable* hash_table_create(size_t initial_size, float load_factor_threshold) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }
    table->buckets = (HashTableEntry**)calloc(initial_size, sizeof(HashTableEntry*));
    if (!table->buckets) {
        free(table);
        perror("Failed to allocate memory for buckets");
        exit(EXIT_FAILURE);
    }
    table->bucket_count = initial_size;
    table->size = 0;
    table->load_factor_threshold = load_factor_threshold;
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

void hash_table_insert(HashTable* table, unsigned long key, void* value) {
    pthread_mutex_lock(&table->mutex);
    if (table->size / (float)table->bucket_count >= table->load_factor_threshold) {
        // Resize the hash table
        HashTableEntry** old_buckets = table->buckets;
        size_t old_bucket_count = table->bucket_count;
        table->bucket_count *= 2;
        table->buckets = (HashTableEntry**)calloc(table->bucket_count, sizeof(HashTableEntry*));
        if (!table->buckets) {
            free(old_buckets);
            perror("Failed to allocate memory for resized buckets");
            exit(EXIT_FAILURE);
        }
        table->size = 0;
        // Rehash all entries
        for (size_t i = 0; i < old_bucket_count; ++i) {
            HashTableEntry* entry = old_buckets[i];
            while (entry) {
                HashTableEntry* next_entry = entry->next;
                unsigned long new_index = custom_hash_function(&entry->key, table->bucket_count);
                entry->next = table->buckets[new_index];
                table->buckets[new_index] = entry;
                ++table->size;
                entry = next_entry;
            }
        }
        free(old_buckets);
    }
    unsigned long index = custom_hash_function(&key, table->bucket_count);
    HashTableEntry* new_entry = (HashTableEntry*)malloc(sizeof(HashTableEntry));
    if (!new_entry) {
        pthread_mutex_unlock(&table->mutex);
        perror("Failed to allocate memory for hash table entry");
        exit(EXIT_FAILURE);
    }
    new_entry->key = key;
    new_entry->value = value;
    new_entry->next = table->buckets[index];
    table->buckets[index] = new_entry;
    ++table->size;
    pthread_mutex_unlock(&table->mutex);
}

void* hash_table_get(HashTable* table, unsigned long key) {
    pthread_mutex_lock(&table->mutex);
    unsigned long index = custom_hash_function(&key, table->bucket_count);
    HashTableEntry* entry = table->buckets[index];
    while (entry) {
        if (entry->key == key) {
            pthread_mutex_unlock(&table->mutex);
            return entry->value;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&table->mutex);
    return NULL;
}

void hash_table_free(HashTable* table) {
    pthread_mutex_lock(&table->mutex);
    for (size_t i = 0; i < table->bucket_count; ++i) {
        HashTableEntry* entry = table->buckets[i];
        while (entry) {
            HashTableEntry* next_entry = entry->next;
            free(entry);
            entry = next_entry;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->mutex);
    free(table);
}

// Example usage
int main() {
    HashTable* table = hash_table_create(1024, 0.75);
    // Insert data into the hash table
    hash_table_insert(table, 123456, "Value");
    // Retrieve data from the hash table
    char* value = (char*)hash_table_get(table, 123456);
    if (value) {
        printf("Retrieved value: %s\n", value);
    }
    hash_table_free(table);
    return 0;
}
```

This code snippet provides a basic implementation of a hash table in C. It includes functions to create, insert, retrieve, and free the hash table. The hash function uses a performance-optimized Jenkins one-at-a-time hash algorithm. The hash table supports dynamic resizing based on a load factor threshold. The `main` function demonstrates how to use the hash table by inserting and retrieving a value. Additional features such as thread safety, memory alignment optimization, and external PRNG integration are not included in this basic implementation but can be added as needed for more advanced functionality.']

