Config* initialize_config(const char *interface, int level, float threshold) {
    Config *config = malloc(sizeof(Config));
    if (config == NULL) {
        fprintf(stderr, "Memory allocation failed for config\n");
        return NULL;
    }

    config->network_interface = strdup(interface);
    if (config->network_interface == NULL) {
        free(config);
        fprintf(stderr, "Memory allocation failed for network interface\n");
        return NULL;
    }

    config->logging_level = level;
    config->alert_threshold = threshold;

    return config;
}

void update_config(Config *config, const char *interface, int level, float threshold) {
    if (config->network_interface != NULL) {
        free(config->network_interface);
    }
    config->network_interface = strdup(interface);
    if (config->network_interface == NULL) {
        fprintf(stderr, "Memory allocation failed for network interface\n");
        return;
    }

    config->logging_level = level;
    config->alert_threshold = threshold;
}

void destroy_config(Config *config) {
    if (config->network_interface != NULL) {
        free(config->network_interface);
    }
    free(config);
}
