    max_size = new_size;

    // Reseed PRNG after resizing for consistent randomness
    reseed_prng();
}

void add_record(int buffer_len, int log_level) {
    pthread_mutex_lock(&mutex);
    if (array_size >= max_size) {
        resize_array(max_size * 2);
    }
    dynamic_array[array_size++] = *create_record(buffer_len, log_level);
    pthread_mutex_unlock(&mutex);
}

Record* get_record(int index) {
    if (index < 0 || index >= array_size) {
        // Handle out-of-bounds access
        return NULL;
    }
    pthread_mutex_lock(&mutex);
    Record* record = &dynamic_array[index];
    pthread_mutex_unlock(&mutex);
    return record;
}

void destroy_records() {
    for (int i = 0; i < array_size; i++) {
        free(dynamic_array[i].buffer); // Assuming buffer is dynamically allocated
    }
    free(dynamic_array);
}
