#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MIN_STRING_LEN 10
#define MAX_STRING_LEN 50

typedef struct {
    int id;
    double value;
    uint64_t uid;
    char *data;
} record;

typedef struct {
    record *records[MAX_RECORDS];
    int capacity;
    int size;
    pthread_mutex_t lock;
} lru_cache;

lru_cache *create_cache(int capacity) {
    lru_cache *cache = (lru_cache *)malloc(sizeof(lru_cache));
    if (!cache) {
        fprintf(stderr, "Memory allocation failed for cache\n");
        return NULL;
    }
    cache->capacity = capacity;
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
    memset(cache->records, 0, sizeof(cache->records));
    return cache;
}

void free_cache(lru_cache *cache) {
    for (int i = 0; i < cache->capacity; i++) {
        if (cache->records[i]) {
            free(cache->records[i]->data);
            free(cache->records[i]);
        }
    }
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

record *create_record(int id, double value, uint64_t uid, const char *data) {
    record *rec = (record *)malloc(sizeof(record));
    if (!rec) {
        fprintf(stderr, "Memory allocation failed for record\n");
        return NULL;
    }
    rec->id = id;
    rec->value = value;
    rec->uid = uid;
    rec->data = strdup(data);
    return rec;
}

void free_record(record *rec) {
    free(rec->data);
    free(rec);
}

int hash_function(uint64_t key, int capacity) {
    return (key % capacity);
}

void insert_into_cache(lru_cache *cache, record *rec) {
    pthread_mutex_lock(&cache->lock);
    if (cache->size == cache->capacity) {
        // Evict least recently used item
        for (int i = 0; i < cache->capacity; i++) {
            free_record(cache->records[i]);
            cache->records[i] = NULL;
        }
        cache->size = 0;
    }
    int index = hash_function(rec->uid, cache->capacity);
    while (cache->records[index]) {
        index = (index + 1) % cache->capacity;
    }
    cache->records[index] = rec;
    cache->size++;
    pthread_mutex_unlock(&cache->lock);
}

record *get_from_cache(lru_cache *cache, uint64_t uid) {
    pthread_mutex_lock(&cache->lock);
    int index = hash_function(uid, cache->capacity);
    while (cache->records[index] && cache->records[index]->uid != uid) {
        index = (index + 1) % cache->capacity;
    }
    if (!cache->records[index]) {
        pthread_mutex_unlock(&cache->lock);
        return NULL;
    }
    record *rec = cache->records[index];
    // Move to front for LRU
    while (index > 0) {
        cache->records[index] = cache->records[index - 1];
        index--;
    }
    cache->records[0] = rec;
    pthread_mutex_unlock(&cache->lock);
    return rec;
}

int main() {
    srand(time(NULL));
    lru_cache *cache = create_cache(100);

    // Example usage
    record *rec = create_record(rand(), (double)rand() / RAND_MAX, (uint64_t)rand(), "example_data");
    insert_into_cache(cache, rec);
    record *retrieved_rec = get_from_cache(cache, rec->uid);

    if (retrieved_rec) {
        printf("Retrieved record: ID=%d, Value=%.2f, UID=%lu, Data=%s\n", retrieved_rec->id, retrieved_rec->value, retrieved_rec->uid, retrieved_rec->data);
    }

    free_record(rec);
    free_cache(cache);

    return 0;
}
```

This code provides a basic implementation of the requested functionality. It includes error handling for memory allocation failures and demonstrates how to create and manipulate an LRU cache using mutex locks for thread safety. The `main` function shows how to insert and retrieve records from the cache.']

