    if (size <= 0) {
        return NULL;
    }

    DataItem* array = malloc(size * sizeof(DataItem));
    if (!array) {
        return NULL; // Memory allocation failed
    }

    srand(seed); // Initialize random number generator with a seed

    for (int i = 0; i < size; ++i) {
