void* allocate_memory(int max_size, int num_profiles, int num_records, int initial_record_size) {
    // Allocate memory for user profiles
    User_Profile **profiles = (User_Profile **)malloc(num_profiles * sizeof(User_Profile *));
    if (!profiles) {
        perror("Failed to allocate memory for user profiles");
        return NULL;
    }

    // Allocate memory for long offset values
    long *offsets = (long *)malloc(num_records * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        free(profiles);
        return NULL;
    }

    // Allocate memory for int keys
    int *keys = (int *)malloc(num_records * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(profiles);
        free(offsets);
        return NULL;
    }

    // Allocate memory for records with initial size estimation
    Record **records = (Record **)malloc(initial_record_size * sizeof(Record *));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(profiles);
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize user profiles with unique session IDs
    for (int i = 0; i < num_profiles; i++) {
        profiles[i] = (User_Profile *)malloc(sizeof(User_Profile));
        if (!profiles[i]) {
            perror("Failed to allocate memory for user profile");
            for (int j = 0; j < i; j++)
                free(profiles[j]);
            free(profiles);
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
        profiles[i]->name = "User";
        profiles[i]->email = "user@example.com";
        profiles[i]->session_id = (char *)malloc(32 * sizeof(char));
        if (!profiles[i]->session_id) {
            perror("Failed to allocate memory for session ID");
            for (int j = 0; j <= i; j++)
                free(profiles[j]);
            free(profiles);
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
        srand(time(NULL));
        sprintf(profiles[i]->session_id, "%ld", rand());
    }

    // Initialize records with random values
    for (int i = 0; i < initial_record_size; i++) {
        records[i] = (Record *)malloc(sizeof(Record));
        if (!records[i]) {
            perror("Failed to allocate memory for record");
            for (int j = 0; j <= i; j++)
                free(records[j]);
            for (int j = 0; j < num_profiles; j++)
                free(profiles[j]->session_id);
            for (int j = 0; j < num_profiles; j++)
                free(profiles[j]);
            free(offsets);
            free(keys);
            return NULL;
        }
        records[i]->value = rand() % initial_record_size;
        records[i]->timestamp = time(NULL);
        records[i]->metadata[0] = time(NULL);
        records[i]->metadata[1] = 0;
        records[i]->metadata[2] = i;
    }

    // Loop to set the value of each record's int field to a random value within a given range
    for (int i = 0; i < initial_record_size; i++) {
        records[i]->value = rand() % initial_record_size;
    }

    // Return pointer to allocated structures
    return profiles;
}

void free_memory(User_Profile **profiles, long *offsets, int *keys, Record **records) {
    for (int i = 0; i < num_profiles; i++)
        free(profiles[i]->session_id);
    for (int i = 0; i < num_profiles; i++)
        free(profiles[i]);
    free(offsets);
    free(keys);
    for (int i = 0; i < initial_record_size; i++)
        free(records[i]);
    free(records);
}

// Example usage
int main() {
    int max_size = 1024 * 1024 * 1024; // 1GB
    int num_profiles = 1000;
    int num_records = 5000;
    int initial_record_size = 100;

    void *allocated_memory = allocate_memory(max_size, num_profiles, num_records, initial_record_size);
    if (allocated_memory) {
        // Use allocated memory
        free_memory((User_Profile **)allocated_memory, offsets, keys, records);
    }

    return 0;
}
