    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;

        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // Should never happen, but just in case...
            fprintf(stderr, "Unsupported address family: %d\n", p->ai_family);
            freeaddrinfo(res);
            return -1;
        }

        inet_ntop(p->ai_family, addr, (char *)ip_address, INET_ADDRSTRLEN);
    }
    freeaddrinfo(res);

    return 0;
}

int allocate_and_populate_structs(int num_structs, MyStruct **array, u_char *ip_address) {
    int i;

    if ((*array = (MyStruct *)malloc(num_structs * STRUCT_SIZE)) == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    for (i = 0; i < num_structs; i++) {
        (*array)[i].id = i + 1;

        if (generate_random_value(&(*array)[i].value)) {
            free(*array);
            fprintf(stderr, "Failed to generate random value\n");
            return -1;
        }
    }

    if (resolve_hostname(HOSTNAME, ip_address)) {
        free(*array);
        fprintf(stderr, "Failed to resolve hostname\n");
        return -1;
    }

    return 0;
}

int main() {
    int num_structs = 5;
    MyStruct *my_array = NULL;
    u_char ip_address[INET_ADDRSTRLEN];

    if (allocate_and_populate_structs(num_structs, &my_array, ip_address) == 0) {
        printf("Successfully allocated and populated structs\n");
        for (int i = 0; i < num_structs; i++) {
            printf("Struct %d: ID=%d, Value=%lu\n", i + 1, my_array[i].id, my_array[i].value);
        }
        printf("Hostname IP address: %s\n", ip_address);

        free(my_array);
    } else {
        fprintf(stderr, "Failed to allocate and populate structs or resolve hostname\n");
    }

    return 0;
}
