#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000000

typedef struct {
    long offset;
    int key;
    unsigned int value;
} record;

record* create_record_pool(long start_offset, long end_offset, int verbosity, FILE* log_file) {
    if (end_offset - start_offset + 1 > MAX_RECORDS) {
        fprintf(log_file, "Error: Timestamp range exceeds maximum allowed records.\n");
        return NULL;
    }

    record* pool = malloc((end_offset - start_offset + 1) * sizeof(record));
    if (!pool) {
        fprintf(log_file, "Error: Failed to allocate memory for record pool.\n");
        return NULL;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    time_t seed = time(NULL);
    srand(seed);

    for (long i = start_offset; i <= end_offset; ++i) {
        pthread_mutex_lock(&mutex);
        pool[i - start_offset].offset = i;
        pool[i - start_offset].key = rand() % 1000; // Simplified key generation
        pool[i - start_offset].value = rand();
        pthread_mutex_unlock(&mutex);

        if (verbosity > 0) {
            printf("Record initialized: offset=%ld, key=%d, value=%u\n", i, pool[i - start_offset].key, pool[i - start_offset].value);
        }
    }

    pthread_mutex_destroy(&mutex);
    return pool;
}
