size_t initialize_records(record** records, long** offsets, int** keys, size_t offset_size, size_t key_size, int range_min, int range_max) {
    if (range_min < 0 || range_max > INT_MAX || range_min >= range_max) {
        fprintf(stderr, "Invalid range for record values\n");
        return 0;
    }

    *records = (record*)malloc(offset_size * sizeof(record));
    *offsets = allocate_long_array(key_size);
    *keys = allocate_int_array(key_size);

    if (!*records || !*offsets || !*keys) {
        free(*records);
        free(*offsets);
        free(*keys);
        return 0;
    }

    srand(time(NULL));
    size_t count = 0;

    for (size_t i = 0; i < offset_size; ++i) {
