void manipulateForwardList(std::forward_list<std::string>& lst, const std::string& target, const std::string& insertStr) {
    auto it = std::find(lst.begin(), lst.end(), target);
    if (it != lst.end()) {
        lst.insert_after(it, insertStr);
    } else {
        lst.push_back(insertStr);
    }
}

void initializeArraysAndInsert(std::forward_list<std::string>& lst, const std::string& target, const std::string& insertStr,
                               long timestampRange, int keyRange, unsigned int valueRange) {
    try {
        size_t numRecords = timestampRange / 1000; // Simplified example
        record* records = new record[numRecords];

        std::ofstream logFile("memory_allocation_errors.log", std::ios::app);
        if (!records) {
            logFile << "Failed to allocate memory for records." << std::endl;
            return;
        }

        unsigned int seed = static_cast<unsigned int>(std::time(0));
        // Use Mersenne Twister engine with a good quality
        std::mt19937 gen(seed);
        std::uniform_int_distribution<> timestampDist(0, timestampRange);
        std::uniform_int_distribution<> keyDist(0, keyRange);
        std::uniform_int_distribution<unsigned int> valueDist(0, valueRange);

        for (size_t i = 0; i < numRecords; ++i) {
            records[i].offset = timestampDist(gen);
            records[i].key = keyDist(gen);
            records[i].value = valueDist(gen);
        }

        // Perform operations with records
        // ...

        delete[] records;
    } catch (const std::bad_alloc& e) {
        std::ofstream logFile("memory_allocation_errors.log", std::ios::app);
        logFile << "Memory allocation failed: " << e.what() << std::endl;
    }
}

int main() {
    std::forward_list<std::string> lst = {"apple", "banana", "cherry"};
    manipulateForwardList(lst, "banana", "grape");
    initializeArraysAndInsert(lst, "banana", "orange", 86400, 10, 100);

    for (const auto& item : lst) {
        std::cout << item << std::endl;
    }

    return 0;
}
