#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    int level;
    unsigned int payload;
} log_record;

typedef struct {
    log_record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} log_pool;

void init_log_pool(log_pool* pool, size_t initial_capacity) {
    pool->records = (log_record*)malloc(initial_capacity * sizeof(log_record));
    if (!pool->records) {
        perror("Failed to allocate memory for log pool");
        exit(EXIT_FAILURE);
    }
    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void free_log_pool(log_pool* pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->records);
    pool->records = NULL;
    pool->capacity = 0;
    pool->size = 0;
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

void log_record_init(log_record* record, long timestamp, int level, unsigned int payload) {
    record->timestamp = timestamp;
    record->level = level;
    record->payload = payload;
}

unsigned int fast_prng(unsigned int seed) {
    return (seed * 1664525 + 1013904223) % UINT_MAX;
}

void log_message(log_pool* pool, long timestamp, int level, unsigned int payload) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size == pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        log_record* new_records = (log_record*)realloc(pool->records, new_capacity * sizeof(log_record));
        if (!new_records) {
            perror("Failed to allocate memory for log pool resize");
            pthread_mutex_unlock(&pool->lock);
            return;
        }
        pool->records = new_records;
        pool->capacity = new_capacity;
    }
    log_record_init(&pool->records[pool->size], timestamp, level, payload);
    pool->size++;
    pthread_mutex_unlock(&pool->lock);
}

void* log_thread(void* arg) {
    log_pool* pool = (log_pool*)arg;
    unsigned int seed = time(NULL);
    while (1) {
        long timestamp = time(NULL);
        int level = rand() % 5; // Random log level between 0 and 4
        unsigned int payload = fast_prng(seed++);
        log_message(pool, timestamp, level, payload);
        usleep(100); // Simulate work
    }
    return NULL;
}

int main() {
    log_pool pool;
    init_log_pool(&pool, 1024);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, log_thread, &pool) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    free_log_pool(&pool);

    return 0;
}
```

This code snippet provides a basic implementation of a high-performance logging framework in C. It includes functions to initialize and free the log pool, log messages with timestamps, levels, and payloads, and manage concurrent access using pthreads. The `fast_prng` function is used for generating pseudo-random numbers for payload values. The main function creates multiple threads that continuously generate and log messages.']

