// Function to generate unique identifiers using a PRNG
unsigned long generate_id() {
    return rand();
}

// Function to allocate memory for an array of long integers
long* allocate_long_array(size_t size) {
    if (size == 0) {
        fprintf(stderr, "Error: Size cannot be zero\n");
        return NULL;
    }
    long* array = (long*)malloc(size * sizeof(long));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    for (size_t i = 0; i < size; i++) {
        array[i] = generate_id();
    }
    return array;
}

// Function to allocate memory for an array of char strings
char** allocate_char_array(size_t size, const char* prefix) {
    if (size == 0 || prefix == NULL) {
        fprintf(stderr, "Error: Invalid input\n");
        return NULL;
    }
    char** array = (char**)malloc(size * sizeof(char*));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    for (size_t i = 0; i < size; i++) {
        size_t len = strlen(prefix);
        array[i] = (char*)malloc((len + 10) * sizeof(char)); // Extra space for digits
        if (array[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
        snprintf(array[i], len + 10, "%s%d", prefix, generate_id());
    }
    return array;
}

