        fprintf(stderr, "Error: Size cannot be zero\n");
        return NULL;
    }
    Config* array = (Config*)malloc(size * sizeof(Config));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    for (size_t i = 0; i < size; i++) {
        array[i].probability = ((double)rand() / RAND_MAX);
