        if (name == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
        snprintf(name, 50, "config%d", generate_id());
        array[i].name = name;
    }
    return array;
}

// Function to free memory allocated for long arrays
void free_long_array(long* array, size_t size) {
    if (array != NULL) {
        free(array);
    }
}

// Function to free memory allocated for char arrays
void free_char_array(char** array, size_t size) {
    if (array != NULL) {
        for (size_t i = 0; i < size; i++) {
            if (array[i] != NULL) {
                free(array[i]);
            }
        }
        free(array);
    }
}

// Function to free memory allocated for config arrays
void free_config_array(Config* array, size_t size) {
    if (array != NULL) {
        for (size_t i = 0; i < size; i++) {
            if (array[i].name != NULL) {
                free(array[i].name);
            }
        }
        free(array);
    }
}

// Example usage
int main() {
    srand(time(NULL)); // Initialize PRNG with current time

    size_t size = 10;
    long* long_array = allocate_long_array(size);
    char** char_array = allocate_char_array(size, "config");
    Config* config_array = allocate_config_array(size);

    if (long_array != NULL) {
        free_long_array(long_array, size);
    }
    if (char_array != NULL) {
        free_char_array(char_array, size);
    }
    if (config_array != NULL) {
        free_config_array(config_array, size);
    }

    return 0;
}
