    session *s = (session *)malloc(sizeof(session));
    if (!s) {
        perror("Memory allocation failed");
        return NULL;
    }
    // Generate token using CSPRNG
    srand(time(NULL)); // For simplicity, use time as seed in this example
    for (int i = 0; i < 64; i++) {
        s->token[i] = rand() % 256;
    }
    return s;
}

