    if (!new_users) {
        perror("Memory reallocation failed");
        exit(EXIT_FAILURE);
    }
    users = new_users;
    max_users = new_size;
    log_memory_allocation("User", sizeof(user_profile *), max_users);
}

void resize_transactions(int new_size) {
    transaction_record **new_transactions = realloc(transactions, new_size * sizeof(transaction_record *));
    if (!new_transactions) {
        perror("Memory reallocation failed");
        exit(EXIT_FAILURE);
    }
    transactions = new_transactions;
    max_transactions = new_size;
    log_memory_allocation("Transaction", sizeof(transaction_record *), max_transactions);
}

void log_memory_allocation(const char *type, size_t size, int count) {
    if (!log_file) {
        log_file = fopen("memory_log.txt", "a");
        if (!log_file) {
            perror("Failed to open log file");
            return;
        }
    }

    time_t now = time(NULL);
    fprintf(log_file, "%s %ld bytes allocated for %d %ss on %s\n", type, size * count, count, type, ctime(&now));
}

