#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/rand.h>

#define MAX_USERS 1000
#define MAX_SESSIONS 10000
#define MAX_TRANSACTIONS 50000

typedef struct {
    char name[256];
    char* email;
    int session_id;
} UserProfile;

typedef struct {
    time_t timestamp;
    double amount;
    char description[512];
    UserProfile* user;
} TransactionRecord;

void init_memory_pool(int pool_size);
void* allocate_from_pool(size_t size);

int allocate_session_ids(int** session_ids, int size) {
    *session_ids = (int*)allocate_from_pool(size * sizeof(int));
    if (*session_ids == NULL) {
        perror("Failed to allocate session IDs");
        return -1;
    }
    for (int i = 0; i < size; i++) {
        if (!RAND_bytes((unsigned char*)&(*session_ids)[i], sizeof((*session_ids)[i]))) {
            perror("Failed to generate random session ID");
            free(*session_ids);
            *session_ids = NULL;
            return -1;
        }
    }
    return 0;
}

int allocate_user_profiles(UserProfile** users, int size) {
    *users = (UserProfile*)allocate_from_pool(size * sizeof(UserProfile));
    if (*users == NULL) {
        perror("Failed to allocate user profiles");
        return -1;
    }
    for (int i = 0; i < size; i++) {
        (*users)[i].email = (char*)allocate_from_pool(256);
        if ((*users)[i].email == NULL) {
            perror("Failed to allocate email for user profile");
            free(*users);
            *users = NULL;
            return -1;
        }
    }
    return 0;
}

int allocate_transaction_records(TransactionRecord** transactions, int size, UserProfile* users, int users_size) {
    *transactions = (TransactionRecord*)allocate_from_pool(size * sizeof(TransactionRecord));
    if (*transactions == NULL) {
        perror("Failed to allocate transaction records");
        return -1;
    }
    for (int i = 0; i < size; i++) {
        (*transactions)[i].user = &users[rand() % users_size];
        (*transactions)[i].description = (char*)allocate_from_pool(512);
        if ((*transactions)[i].description == NULL) {
            perror("Failed to allocate description for transaction record");
            free(*transactions);
            *transactions = NULL;
            return -1;
        }
    }
    return 0;
}

int main() {
    int session_ids[MAX_SESSIONS];
    UserProfile users[MAX_USERS];
    TransactionRecord transactions[MAX_TRANSACTIONS];

    if (allocate_session_ids(session_ids, MAX_SESSIONS) != 0 ||
        allocate_user_profiles(users, MAX_USERS) != 0 ||
        allocate_transaction_records(transactions, MAX_TRANSACTIONS, users, MAX_USERS) != 0) {
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    // Use allocated memory here...

    for (int i = 0; i < MAX_SESSIONS; i++) {
        free(session_ids + i);
    }
    for (int i = 0; i < MAX_USERS; i++) {
        free(users[i].email);
    }
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        free(transactions[i].description);
    }

    return EXIT_SUCCESS;
}
