#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_CONFIGS 1000

typedef struct {
    double probability;
    char* name;
} Config;

unsigned long custom_pseudo_random(unsigned long seed) {
    // Implement a fast and high-quality pseudo-random number generator
    return (seed * 25214903917ull + 11) % 4294967296ull;
}

int allocate_memory(long* long_array, char** str_array, Config* config_array, int size) {
    // Allocate memory for each data structure
    *long_array = (long*)malloc(size * sizeof(long));
    if (*long_array == NULL) return 1;

    *str_array = (char*)malloc(size * sizeof(char));
    if (*str_array == NULL) {
        free(*long_array);
        return 1;
    }

    *config_array = (Config*)malloc(size * sizeof(Config));
    if (*config_array == NULL) {
        free(*str_array);
        free(*long_array);
        return 1;
    }

    // Initialize memory
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        (*long_array)[i] = i * 2;
        snprintf((*str_array) + i, 50, "String%d", i);
        double seed = i;
        (*config_array)[i].probability = custom_pseudo_random(seed) / (double)4294967296.0;
        (*config_array)[i].name = strdup((*str_array) + i);
    }

    return 0;
}

void free_memory(long* long_array, char** str_array, Config* config_array, int size) {
    // Free allocated memory
    for (int i = 0; i < size; i++) {
        free(config_array[i].name);
    }
    free(*config_array);
    free(*str_array);
    free(*long_array);
}

void* allocate_memory_thread(void* arg) {
    int* size = (int*)arg;
    long* long_array;
    char** str_array;
    Config* config_array;

    if (allocate_memory(&long_array, &str_array, &config_array, *size) == 0) {
        printf("Memory allocation successful\n");
        free_memory(&long_array, &str_array, &config_array, *size);
    } else {
        printf("Memory allocation failed\n");
    }

    return NULL;
}

int main() {
    pthread_t threads[MAX_CONFIGS];
    int sizes[MAX_CONFIGS] = {100, 200, 300}; // Example sizes for demonstration

    for (int i = 0; i < MAX_CONFIGS && sizes[i] > 0; i++) {
        pthread_create(&threads[i], NULL, allocate_memory_thread, &sizes[i]);
    }

    for (int i = 0; i < MAX_CONFIGS && sizes[i] > 0; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
