#define MAX_RECORDS 5000

typedef struct {
    int value;
} record;

unsigned long custom_prng_seed = 0;
unsigned long custom_prng_state = 1;

void init_custom_prng() {
    custom_prng_seed = (time(NULL) * getpid()) ^ ((unsigned long)getpid() << 16);
}

unsigned int custom_prng_generate() {
    custom_prng_state = custom_prng_state * 1664525 + 1013904223;
    return (unsigned int)(custom_prng_state >> 16) % 4294967296U;
}

int main() {
    int num_offsets, num_records, min_value, max_value;
    long *offsets;
    record *records;
    unsigned int seed;

    printf("Enter number of offsets (max %d): ", MAX_OFFSETS);
    scanf("%d", &num_offsets);
    if (num_offsets < 1 || num_offsets > MAX_OFFSETS) {
        fprintf(stderr, "Invalid number of offsets\n");
        return EXIT_FAILURE;
    }

    printf("Enter number of records (max %d): ", MAX_RECORDS);
    scanf("%d", &num_records);
    if (num_records < 1 || num_records > MAX_RECORDS) {
        fprintf(stderr, "Invalid number of records\n");
        return EXIT_FAILURE;
    }

    printf("Enter minimum value for random numbers: ");
    scanf("%d", &min_value);
    printf("Enter maximum value for random numbers: ");
    scanf("%d", &max_value);
    if (min_value > max_value || min_value < -1000000 || max_value > 1000000) {
        fprintf(stderr, "Invalid range for random numbers\n");
        return EXIT_FAILURE;
    }

    offsets = malloc(num_offsets * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return EXIT_FAILURE;
    }

    records = malloc(num_records * sizeof(record));
    if (!records) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed for records\n");
        return EXIT_FAILURE;
    }

    init_custom_prng();
    printf("Enter seed for PRNG (0 to use automatic seeding): ");
    scanf("%u", &seed);
    if (seed == 0) {
        seed = custom_prng_seed;
    }

    srand(seed);

    for (int i = 0; i < num_records; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    free(offsets);
    free(records);

    return EXIT_SUCCESS;
}
