typedef struct {
    char *name;
    char *email;
    unsigned long session_id;
} User;

typedef struct {
    time_t timestamp;
    double amount;
    char *description;
    User *user_profile;
} Transaction;

unsigned long generate_session_id() {
    unsigned long id;
    if (!RAND_bytes((unsigned char *)&id, sizeof(id))) {
        fprintf(stderr, "Error generating session ID\n");
        exit(EXIT_FAILURE);
    }
    return id;
}

User* create_user(const char *name, const char *email) {
    User *user = (User *)malloc(sizeof(User));
    if (!user) {
        fprintf(stderr, "Memory allocation failed for user profile\n");
        return NULL;
    }
    user->name = strdup(name);
    user->email = strdup(email);
    user->session_id = generate_session_id();
    return user;
}

Transaction* create_transaction(time_t timestamp, double amount, const char *description, User *user) {
    Transaction *transaction = (Transaction *)malloc(sizeof(Transaction));
    if (!transaction) {
        fprintf(stderr, "Memory allocation failed for transaction record\n");
        free(user->name);
        free(user->email);
        free(user);
        return NULL;
    }
    transaction->timestamp = timestamp;
    transaction->amount = amount;
    transaction->description = strdup(description);
    transaction->user_profile = user;
    return transaction;
}

void destroy_user(User *user) {
    if (user) {
        free(user->name);
        free(user->email);
        free(user);
    }
}

void destroy_transaction(Transaction *transaction) {
    if (transaction) {
        free(transaction->description);
        destroy_user(transaction->user_profile);
        free(transaction);
    }
}
