// Define a simple Octree Node structure for demonstration purposes
struct OctreeNode {
    int* data;
    OctreeNode** children;
};

Octree initializeOctreeWithRecords(int featureSize, int numLeafNodes) {
    if (featureSize <= 0 || numLeafNodes <= 0) {
        throw std::invalid_argument("Feature size and number of leaf nodes must be positive.");
    }

    Octree octree;
    try {
        // Allocate memory for the octree structure
        octree.root = new OctreeNode;
        octree.prefixLeafs = new int[numLeafNodes];
        octree.dataArray = new int[numLeafNodes];

        // Seed the PRNG for consistent random numbers
        std::srand(std::time(0));

        // Initialize data and prefix leafs with random integers
        for (int i = 0; i < numLeafNodes; ++i) {
            octree.dataArray[i] = std::rand() % featureSize;
            octree.prefixLeafs[i] = i;

            // Optionally, initialize children if the structure requires it
            octree.root->children = new OctreeNode*[8];
            for (int j = 0; j < 8; ++j) {
                octree.root->children[j] = nullptr;
            }
        }

    } catch (const std::bad_alloc& e) {
        // Handle memory allocation failure
        std::cerr << "Memory allocation failed: " << e.what() << std::endl;
        if (octree.root) delete[] octree.root;
        if (octree.prefixLeafs) delete[] octree.prefixLeafs;
        if (octree.dataArray) delete[] octree.dataArray;
        throw;
    }

    return octree;
}

// Example usage
int main() {
    try {
        Octree octree = initializeOctreeWithRecords(100, 128);
        // Use the octree for further processing
        // ...
        delete octree.root;
        delete[] octree.prefixLeafs;
        delete[] octree.dataArray;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
