#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    long offset;
    int key;
    int value;
} Record;

typedef struct resourceManager {
    Record* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ResourceManager;

ResourceManager* resourceManager_init(size_t initialCapacity) {
    ResourceManager* rm = (ResourceManager*)malloc(sizeof(ResourceManager));
    if (!rm) return NULL;
    rm->records = (Record*)calloc(initialCapacity, sizeof(Record));
    if (!rm->records) {
        free(rm);
        return NULL;
    }
    rm->capacity = initialCapacity;
    rm->count = 0;
    pthread_mutex_init(&rm->lock, NULL);
    return rm;
}

void resourceManager_free(ResourceManager* rm) {
    pthread_mutex_lock(&rm->lock);
    free(rm->records);
    pthread_mutex_unlock(&rm->lock);
    pthread_mutex_destroy(&rm->lock);
    free(rm);
}

int resourceManager_put(ResourceManager* rm, int key, Record newRecord) {
    pthread_mutex_lock(&rm->lock);
    for (size_t i = 0; i < rm->count; ++i) {
        if (rm->records[i].key == key) {
            rm->records[i] = newRecord;
            pthread_mutex_unlock(&rm->lock);
            return 0;
        }
    }
    if (rm->count >= rm->capacity) {
        Record* newRecords = realloc(rm->records, rm->capacity * 2 * sizeof(Record));
        if (!newRecords) {
            pthread_mutex_unlock(&rm->lock);
            return -1;
        }
        rm->records = newRecords;
        rm->capacity *= 2;
    }
    rm->records[rm->count++] = newRecord;
    pthread_mutex_unlock(&rm->lock);
    return 0;
}

int resourceManager_delete(ResourceManager* rm, int key) {
    pthread_mutex_lock(&rm->lock);
    for (size_t i = 0; i < rm->count; ++i) {
        if (rm->records[i].key == key) {
            rm->records[i] = rm->records[--rm->count];
            pthread_mutex_unlock(&rm->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&rm->lock);
    return -1;
}
