    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity, size_t element_size) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->data = malloc(initial_capacity * element_size);
    if (!array->data) {
        free(array);
        return NULL;
    }
    array->element_size = element_size;
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array) {
        free(array->data);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

int add_to_array(DynamicArray* array, const void* element) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        void* new_data = realloc(array->data, new_capacity * array->element_size);
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    memcpy((char*)array->data + array->size * array->element_size, element, array->element_size);
    array->size++;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

