#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_SIZE 10

typedef struct {
    int id;
} Session;

typedef struct {
    char username[50];
} User;

typedef struct {
    int session_id;
    float amount;
    time_t timestamp;
} Transaction;

Session* sessions = NULL;
User* users = NULL;
Transaction* transactions = NULL;

int sessions_count = 0, sessions_size = INITIAL_SIZE;
int users_count = 0, users_size = INITIAL_SIZE;
int transactions_count = 0, transactions_size = INITIAL_SIZE;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void resize_sessions() {
    pthread_mutex_lock(&mutex);
    sessions_size *= 2;
    Session* new_sessions = realloc(sessions, sessions_size * sizeof(Session));
    if (!new_sessions) {
        perror("Failed to resize sessions");
        exit(EXIT_FAILURE);
    }
    sessions = new_sessions;
    pthread_mutex_unlock(&mutex);
}

void resize_users() {
    pthread_mutex_lock(&mutex);
    users_size *= 2;
    User* new_users = realloc(users, users_size * sizeof(User));
    if (!new_users) {
        perror("Failed to resize users");
        exit(EXIT_FAILURE);
    }
    users = new_users;
    pthread_mutex_unlock(&mutex);
}

void resize_transactions() {
    pthread_mutex_lock(&mutex);
    transactions_size *= 2;
    Transaction* new_transactions = realloc(transactions, transactions_size * sizeof(Transaction));
    if (!new_transactions) {
        perror("Failed to resize transactions");
        exit(EXIT_FAILURE);
    }
    transactions = new_transactions;
    pthread_mutex_unlock(&mutex);
}

void add_session(int id) {
    if (sessions_count >= sessions_size)
        resize_sessions();
    sessions[sessions_count++] = (Session){id};
}

void add_user(const char* username) {
    if (users_count >= users_size)
        resize_users();
    strncpy(users[users_count].username, username, sizeof(users[users_count].username) - 1);
    users[users_count].username[sizeof(users[users_count].username) - 1] = '\0';
    users_count++;
}

void add_transaction(int session_id, float amount) {
    if (transactions_count >= transactions_size)
        resize_transactions();
    transactions[transactions_count++] = (Transaction){session_id, amount, time(NULL)};
}

void* thread_function(void* arg) {
    // Simulate adding data
    add_session(rand());
    add_user("user1");
    add_transaction(rand(), 100.0);
    return NULL;
}

int main() {
    pthread_t threads[5];
    srand(time(NULL));

    for (int i = 0; i < 5; ++i)
        pthread_create(&threads[i], NULL, thread_function, NULL);

    for (int i = 0; i < 5; ++i)
        pthread_join(threads[i], NULL);

    // Free allocated memory
    free(sessions);
    free(users);
    free(transactions);

    return 0;
}
