#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int id;
} record;

// Custom pseudo-random number generator with a state variable
unsigned long long rand_state = 1234567890;
int custom_rand() {
    rand_state = rand_state * 6364136223809643521 + 1;
    return (rand_state >> 32) % 2147483647; // Return a 32-bit pseudo-random number
}

// Function to initialize and manage memory for three arrays
int initialize_arrays(long **offsets, int **keys, record ***records, int size, int range_start, int range_end) {
    if (size <= 0 || range_start > range_end) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }

    *offsets = malloc(size * sizeof(long));
    *keys = malloc(size * sizeof(int));
    *records = malloc(size * sizeof(record*));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(*offsets);
        free(*keys);
        free(*records);
        return -1;
    }

    int used_ids[range_end - range_start + 1] = {0}; // Array to track used IDs
    for (int i = 0; i < size; ) {
        int id = custom_rand() % (range_end - range_start + 1) + range_start;
        if (!used_ids[id - range_start]) {
            (*records)[i] = malloc(sizeof(record));
            if ((*records)[i] == NULL) {
                fprintf(stderr, "Memory allocation failed for record\n");
                // Free already allocated memory and continue
                for (int j = 0; j < i; ++j) free((*records)[j]);
                free(*offsets);
                free(*keys);
                free(*records);
                return -1;
            }
            (*records)[i]->id = id;
            used_ids[id - range_start] = 1;
            (*offsets)[i] = i * sizeof(record); // Assuming contiguous memory layout
            (*keys)[i] = id; // Assuming key and ID are the same for simplicity
            ++i;
        }
    }

    return 0;
}

// Example usage
int main() {
    long *offsets;
    int *keys;
    record **records;

    if (initialize_arrays(&offsets, &keys, &records, 1000, 1, 10000) == 0) {
        printf("Initialization successful\n");
        // Use offsets, keys, and records as needed
        for (int i = 0; i < 1000; ++i) {
            free(records[i]);
        }
    } else {
        printf("Initialization failed\n");
    }

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
