        records[i].value = rand() % key_range + 1;
    }

    *offset = 0;
    return records;
}

void add_record(Record** records, int* offset, int key_range, int max_records, int threshold) {
    if (*offset >= max_records || !records || *offset < 0) return;

    Record new_record = {rand() % key_range + 1};
    if ((*records[*offset].value + new_record.value) > threshold) {
        printf("Threshold exceeded. No record added.\n");
        return;
    }

    (*records)[*offset] = new_record;
    (*offset)++;
}

void garbage_collect(Record** records, int* offset) {
    if (!records || *offset <= 0) return;

    Record* temp_records = (Record*)realloc(*records, (*offset / 2) * sizeof(Record));
    if (temp_records) {
        *records = temp_records;
        *offset /= 2;
    }
}

void print_records(const Record* records, int offset) {
    printf("Records:\n");
    for (int i = 0; i < offset; ++i) {
        printf("%d ", records[i].value);
    }
    printf("\n");
}

int main() {
    int offset;
    Record* records = create_records(&offset, 100, MAX_RECORDS);

    if (!records) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    print_records(records, offset);

    add_record(&records, &offset, 100, MAX_RECORDS, THRESHOLD);
    garbage_collect(&records, &offset);

    print_records(records, offset);

    free(records);

    return 0;
}
