#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    char *buffer;
    size_t length;
} Record;

typedef struct RecordManager {
    Record **records;
    size_t count;
    size_t capacity;
    FILE *log_file;
} RecordManager;

void log_event(RecordManager *manager, const char *event) {
    if (manager->log_file) {
        fprintf(manager->log_file, "%s\n", event);
    }
}

void init_record_manager(RecordManager *manager, size_t initial_capacity) {
    manager->records = (Record **)malloc(initial_capacity * sizeof(Record *));
    manager->count = 0;
    manager->capacity = initial_capacity;
    manager->log_file = fopen("memory_log.txt", "w");
    log_event(manager, "Initialized record manager with capacity: %zu", initial_capacity);
}

void add_record(RecordManager *manager, size_t length) {
    if (manager->count == manager->capacity) {
        manager->capacity *= 2;
        manager->records = (Record **)realloc(manager->records, manager->capacity * sizeof(Record *));
        log_event(manager, "Increased capacity to: %zu", manager->capacity);
    }

    Record *new_record = (Record *)malloc(sizeof(Record));
    new_record->buffer = (char *)malloc(length);
    new_record->length = length;

    // Initialize buffer with random bytes
    srand(time(NULL)); // Seed the PRNG with a weak source for simplicity
    for (size_t i = 0; i < length; ++i) {
        new_record->buffer[i] = rand() % 256;
    }

    manager->records[manager->count++] = new_record;
    log_event(manager, "Added record with length: %zu", length);
}

void free_record_manager(RecordManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i]->buffer);
        free(manager->records[i]);
    }
    free(manager->records);
    fclose(manager->log_file);
    log_event(manager, "Freed all records and closed log file");
}

int main() {
    RecordManager manager;
    init_record_manager(&manager, 10);

    add_record(&manager, 1024);
    add_record(&manager, 2048);
    add_record(&manager, 3072);

    free_record_manager(&manager);

    return 0;
}
