    free(longArr);
    free(intArr);
    free(doubleArr);
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (recordArr[i].strValue != NULL) {
            free(recordArr[i].strValue);
        }
    }
    free(recordArr);
}

void initPRNG() {
    srand(time(NULL));
}

long randomLong(long min, long max) {
    return min + rand() % (max - min + 1);
}

int randomInt(int min, int max) {
    return min + rand() % (max - min + 1);
}

double randomDouble(double min, double max) {
    return min + ((double)rand() / RAND_MAX) * (max - min);
}

Record* createRandomRecords(long* longArr, int* intArr, double* doubleArr, Record* recordArr, int threshold) {
    initPRNG();
    int totalSum = 0;
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (totalSum + randomInt(1, 100) > threshold) break;
        longArr[i] = randomLong(-1000000, 1000000);
        intArr[i] = randomInt(1, 1000);
        doubleArr[i] = randomDouble(0.0, 100.0);
