```python
import json

class JsonParser:
    factories = {}

    @staticmethod
    def register_factory(id, factory):
        JsonParser.factories[id] = factory

    @classmethod
    def create_instance(cls, id, *args, **kwargs):
        if id not in cls.factories:
            raise ValueError("Factory for ID {} not registered".format(id))
        return cls.factories[id](*args, **kwargs)

    def to_json(self):
        return json.dumps(self.__dict__)

    @classmethod
    def from_json(cls, json_str):
        data = json.loads(json_str)
        instance = cls()
        for key, value in data.items():
            setattr(instance, key, value)
        return instance

# Example usage:
JsonParser.register_factory('example', JsonParser)

# Creating an instance using the factory
instance = JsonParser.create_instance('example')
instance.value = 42
json_str = instance.to_json()
print(json_str)

new_instance = JsonParser.from_json(json_str)
print(new_instance.__dict__)
