#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    int key;
    uint64_t random_number;
} data_record;

void log_memory_allocation(const char* type, size_t size) {
    clock_t start = clock();
    // Simulate memory allocation
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Failed to allocate %s of size %zu\n", type, size);
        return;
    }
    free(ptr);
    clock_t end = clock();
    double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;
    printf("Allocated %s of size %zu in %.6f seconds\n", type, size, time_taken);
}

void allocate_and_initialize_memory(size_t maxOffsets, size_t maxKeys, size_t maxRandoms, int minValue, int maxValue) {
    if (maxOffsets == 0 || maxKeys == 0 || maxRandoms == 0 || minValue > maxValue) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    log_memory_allocation("long offsets", maxOffsets * sizeof(long));
    long* offsets = malloc(maxOffsets * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return;
    }

    log_memory_allocation("int keys", maxKeys * sizeof(int));
    int* keys = malloc(maxKeys * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        fprintf(stderr, "Failed to allocate memory for keys\n");
        return;
    }

    log_memory_allocation("uint64_t random numbers", maxRandoms * sizeof(uint64_t));
    uint64_t* random_numbers = malloc(maxRandoms * sizeof(uint64_t));
    if (random_numbers == NULL) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Failed to allocate memory for random numbers\n");
        return;
    }

    log_memory_allocation("data_record structures", maxRecords * sizeof(data_record));
    data_record* records = malloc(maxRecords * sizeof(data_record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        free(random_numbers);
        fprintf(stderr, "Failed to allocate memory for records\n");
        return;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Set random numbers in the records
    for (size_t i = 0; i < maxRecords; i++) {
        records[i].key = keys[i % maxKeys];
        records[i].random_number = (uint64_t)rand() * (maxValue - minValue + 1ULL) / RAND_MAX + minValue;
    }

    // Cleanup
    free(offsets);
    free(keys);
    free(random_numbers);
    free(records);
}

int main() {
    allocate_and_initialize_memory(10, 5, 20, 100, 1000);
    return 0;
}
