unsigned long custom_prng_seed() {
    unsigned int pid = getpid();
    unsigned long tv_usec = (time(NULL) * 1000000L) + (gettimeofday(NULL)->tv_usec / 10);
    return ((unsigned long)pid ^ tv_usec);
}

