// Function to initialize records with random values
std::pair<Record*, std::pair<long*, int*>> initializeAndCountDisjointPairs(int count, int range) {
    if (count <= 0 || range <= 0) {
        throw std::invalid_argument("Invalid input parameters");
    }

    // Initialize PRNG
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, range - 1);

    // Allocate memory for records and arrays
    Record* records = new Record[count];
    long* offsets = new long[count];
    int* keys = new int[count];

    if (!records || !offsets || !keys) {
        throw std::bad_alloc();
    }

    // Initialize records with random values
    for (int i = 0; i < count; ++i) {
        records[i].offset = dis(gen);
        records[i].key = dis(gen);
    }

    // Return pointers to allocated arrays and record structure array
    return {records, {offsets, keys}};
}

// Function to count disjoint pairs using Union-Find data structure
int countDisjointPairs(int* arr, int size) {
    if (!arr || size <= 0) {
        throw std::invalid_argument("Invalid input parameters");
    }

    // Initialize Union-Find data structure
    std::vector<int> parent(size);
    for (int i = 0; i < size; ++i) {
        parent[i] = i;
    }

    // Function to find root with path compression
    auto findRoot = [&](int x) -> int {
        if (parent[x] != x) {
            parent[x] = findRoot(parent[x]);
        }
        return parent[x];
    };

    // Union operation
    auto unionSet = [&](int x, int y) {
        int rootX = findRoot(x);
        int rootY = findRoot(y);
        if (rootX != rootY) {
            parent[rootX] = rootY;
        }
    };

    // Union all pairs
    for (int i = 0; i < size - 1; ++i) {
        unionSet(arr[i], arr[i + 1]);
    }

    // Count disjoint sets
    int disjointCount = std::distance(parent.begin(), std::unique(parent.begin(), parent.end()));
    return disjointCount;
}

// Function to send HTTP GET requests using Boost.ASIO
void sendHttpGetRequests(boost::asio::io_context& io_context, const std::string& url) {
    boost::asio::ip::tcp::resolver resolver(io_context);
    boost::asio::ip::tcp::resolver::results_type endpoints = resolver.resolve(url);

    boost::asio::ip::tcp::socket socket(io_context);
    boost::asio::connect(socket, endpoints);

    std::string request = "GET / HTTP/1.1\r\nHost: " + url + "\r\nConnection: close\r\n\r\n";
    boost::asio::write(socket, boost::asio::buffer(request));

    boost::asio::streambuf response;
    boost::asio::read_until(socket, response, "\r\n");

    std::istream response_stream(&response);
    std::string http_version;
    unsigned int status_code;
    std::string status_message;

    response_stream >> http_version;
    response_stream >> status_code;
    std::getline(response_stream, status_message);

    if (!response_stream || http_version.substr(0, 5) != "HTTP/") {
        throw std::runtime_error("Invalid HTTP response");
    }

    // Continue reading and processing the response
}
