#include <stdlib.h>
#include <string.h>
#include <openssl/rand.h>

#define MAX_USERS 100
#define MAX_TRANSACTIONS 500

typedef struct {
    char name[256];
    char email[256];
    char dob[11]; // YYYY-MM-DD format
} User;

typedef struct {
    char timestamp[20]; // ISO 8601 format
    double amount;
    char description[256];
    struct Account *account;
} Transaction;

typedef struct {
    char token[32];
    User users[MAX_USERS];
    int user_count;
    Transaction transactions[MAX_TRANSACTIONS];
    int transaction_count;
} Account;

void init_account(Account *acc, int initial_users, int initial_transactions) {
    if (RAND_bytes(acc->token, sizeof(acc->token)) != 1) {
        // Handle error: failed to generate random token
        exit(EXIT_FAILURE);
    }

    acc->user_count = initial_users;
    acc->transaction_count = initial_transactions;

    memset(acc->users, 0, sizeof(acc->users));
    memset(acc->transactions, 0, sizeof(acc->transactions));
}

void add_user(Account *acc, User user) {
    if (acc->user_count >= MAX_USERS) {
        // Handle error: no space for more users
        return;
    }
    acc->users[acc->user_count++] = user;
}

void add_transaction(Account *acc, Transaction transaction) {
    if (acc->transaction_count >= MAX_TRANSACTIONS) {
        // Handle error: no space for more transactions
        return;
    }
    transaction.account = acc;
    acc->transactions[acc->transaction_count++] = transaction;
}
```

