    int offset;
    int key;
} Record;

int manage_memory(long *offsets, int *keys, Record **records, size_t count, int min_value, int max_value) {
    if (count == 0) return -1; // Invalid input

    // Seed for random number generator
    time_t seed = time(NULL);
    srand(seed);

    // Allocate memory for records
    *records = malloc(count * sizeof(Record));
    if (*records == NULL) return -2; // Memory allocation failed

    int *offset_used = (int *)calloc(count, sizeof(int));
    int *key_used = (int *)calloc(count, sizeof(int));

    if (offset_used == NULL || key_used == NULL) {
        free(*records);
        return -3; // Memory allocation failed
    }

    for (size_t i = 0; i < count; ++i) {
        (*records)[i].value = rand_r(&seed) % (max_value - min_value + 1) + min_value;
        do {
            (*records)[i].offset = rand_r(&seed) % count;
        } while (offset_used[(*records)[i].offset]);
        offset_used[(*records)[i].offset] = 1;

        do {
            (*records)[i].key = rand_r(&seed) % count;
        } while (key_used[(*records)[i].key]);
        key_used[(*records)[i].key] = 1;
    }

    free(offset_used);
    free(key_used);

    return 0; // Success
}
```

This code snippet defines a function `manage_memory` that initializes three arrays: one for 'long' offsets, one for 'int' keys, and one for 'record' structures. Each record is populated with a cryptographically secure pseudo-random integer within a specified range using the current time as a seed to enhance randomness. The function ensures that each offset and key value is utilized exactly once across the records. It handles potential memory allocation failures gracefully by releasing any previously allocated resources before returning. The function returns the records and a status indicating the success of the operation, providing diagnostics if memory allocation fails."]

