#define MAX_RECORDS 1000
#define RECORD_SIZE sizeof(record)
typedef struct {
    long offset;
    int key;
    int value;
} record;

record* resourceManager(int seed, int range) {
    static record records[MAX_RECORDS];
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    static int initialized = 0;

    if (!initialized) {
        srand(seed);
        for (int i = 0; i < MAX_RECORDS; i++) {
            records[i].offset = rand() % range;
            records[i].key = rand();
            records[i].value = rand();
        }
        initialized = 1;
    }

    pthread_mutex_lock(&lock);
    // Simulate concurrent access
    usleep(rand() % 1000);
    pthread_mutex_unlock(&lock);

    return records;
}

record updateResource(record* records, int key, record new_data) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].key == key) {
            pthread_mutex_lock(&records[i].mutex);
            memcpy(&records[i], &new_data, RECORD_SIZE);
            pthread_mutex_unlock(&records[i].mutex);
            return records[i];
        }
    }
    // Handle invalid identifier
    printf("Invalid identifier\n");
    exit(1);
}

record deleteResource(record* records, int key) {
    record new_record = {0};
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].key == key) {
            pthread_mutex_lock(&records[i].mutex);
            memset(&records[i], 0, RECORD_SIZE);
            pthread_mutex_unlock(&records[i].mutex);
            break;
        }
    }
    return new_record;
}

int main() {
    record* records = resourceManager(42, 1000);

    record update_data = {500, 789, 654};
    record updated_record = updateResource(records, 123, update_data);

    record deleted_record = deleteResource(records, 456);

    return 0;
}
