#define MAX_SESSIONS 10000000

typedef struct {
    char *session_id;
    char name[256];
    char email[256];
} User;

typedef struct {
    time_t timestamp;
    double amount;
    char description[256];
    User *user_profile;
} Transaction;

void generate_session_id(char **session_id) {
    if (!RAND_bytes(*session_id, 16)) {
        fprintf(stderr, "Error generating session ID\n");
        exit(1);
    }
}

User *create_user(const char *name, const char *email) {
    User *user = (User *)malloc(sizeof(User));
    if (!user) {
        fprintf(stderr, "Memory allocation failed for user\n");
        exit(1);
    }
    strcpy(user->name, name);
    strcpy(user->email, email);
    generate_session_id(&user->session_id);
    return user;
}

Transaction *create_transaction(time_t timestamp, double amount, const char *description, User *user_profile) {
    Transaction *transaction = (Transaction *)malloc(sizeof(Transaction));
    if (!transaction) {
        fprintf(stderr, "Memory allocation failed for transaction\n");
        exit(1);
    }
    transaction->timestamp = timestamp;
    transaction->amount = amount;
    strcpy(transaction->description, description);
    transaction->user_profile = user_profile;
    return transaction;
}

void free_user(User *user) {
    if (user->session_id) {
        free(user->session_id);
    }
    free(user);
}

void free_transaction(Transaction *transaction) {
    free(transaction->user_profile);
    free(transaction);
}

int main() {
    User *users[MAX_SESSIONS];
    Transaction *transactions[MAX_SESSIONS];

    srand(time(NULL));

    for (int i = 0; i < MAX_SESSIONS; i++) {
        users[i] = create_user("User", "user@example.com");
        transactions[i] = create_transaction(time(NULL), 10.0, "Transaction Description", users[i]);
    }

    for (int i = 0; i < MAX_SESSIONS; i++) {
        free_transaction(transactions[i]);
        free_user(users[i]);
    }

    return 0;
}
