#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000000

typedef struct {
    double probability;
    char* name;
} config;

typedef struct {
    int value;
} record;

typedef struct memory_pool_t {
    void* pool;
    size_t block_size;
    size_t num_blocks;
    size_t used_blocks;
} memory_pool_t;

memory_pool_t* create_memory_pool(size_t block_size, size_t initial_blocks) {
    memory_pool_t* pool = (memory_pool_t*)malloc(sizeof(memory_pool_t));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->num_blocks = initial_blocks;
    pool->used_blocks = 0;
    pool->pool = malloc(initial_blocks * block_size);

    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    return pool;
}

void* memory_pool_alloc(memory_pool_t* pool, size_t size) {
    if (size > pool->block_size) {
        fprintf(stderr, "Size exceeds block size\n");
        return NULL;
    }

    if (pool->used_blocks == pool->num_blocks) {
        pool->num_blocks *= 2;
        void* new_pool = realloc(pool->pool, pool->num_blocks * pool->block_size);
        if (!new_pool) {
            fprintf(stderr, "Memory reallocation failed\n");
            return NULL;
        }
        pool->pool = new_pool;
    }

    void* block = (char*)pool->pool + pool->used_blocks * pool->block_size;
    pool->used_blocks++;
    return block;
}

void memory_pool_free(memory_pool_t* pool, void* block) {
    // No-op for simplicity
}

config* allocate_config(memory_pool_t* config_pool, double probability, const char* name) {
    config* new_config = (config*)memory_pool_alloc(config_pool, sizeof(config));
    if (!new_config) return NULL;

    new_config->probability = probability;
    new_config->name = strdup(name);
    if (!new_config->name) {
        memory_pool_free(config_pool, new_config);
        return NULL;
    }

    return new_config;
}

void free_config(memory_pool_t* config_pool, config* config) {
    free(config->name);
    memory_pool_free(config_pool, config);
}

record* allocate_record(memory_pool_t* record_pool, int value) {
    record* new_record = (record*)memory_pool_alloc(record_pool, sizeof(record));
    if (!new_record) return NULL;

    new_record->value = value;

    return new_record;
}

void free_record(memory_pool_t* record_pool, record* record) {
    memory_pool_free(record_pool, record);
}

int main() {
    srand(time(NULL));

    memory_pool_t* config_pool = create_memory_pool(sizeof(config), 1024);
    memory_pool_t* record_pool = create_memory_pool(sizeof(record), 1024);

    if (!config_pool || !record_pool) {
        fprintf(stderr, "Failed to create memory pools\n");
        return 1;
    }

    config** configs = (config**)calloc(1000, sizeof(config*));
    record** records = (record**)calloc(1000, sizeof(record*));

    if (!configs || !records) {
        fprintf(stderr, "Failed to allocate arrays for data structures\n");
        return 1;
    }

    for (int i = 0; i < 1000; i++) {
        configs[i] = allocate_config(config_pool, ((double)i / 1000.0), "config_name");
        if (!configs[i]) {
            fprintf(stderr, "Failed to allocate config structure\n");
            return 1;
        }

        records[i] = allocate_record(record_pool, rand() % 1001);
        if (!records[i]) {
            fprintf(stderr, "Failed to allocate record structure\n");
            return 1;
        }
    }

    for (int i = 0; i < 1000; i++) {
        free_config(config_pool, configs[i]);
        free_record(record_pool, records[i]);
    }

    free(configs);
    free(records);

    memory_pool_free(config_pool, NULL);
    memory_pool_free(record_pool, NULL);

    return 0;
}
