// Define structures
typedef struct {
    double probability;
    char* name;
    int timeout;
    int unique_id;
} config;

typedef struct {
    time_t timestamp;
    char* description;
    config* cfg;
} event;

// Function prototypes
void log_memory_allocation(const char* message, size_t memory_used);
int init_config_array(config** array, size_t initial_size, size_t* current_size);
int init_event_array(event** array, size_t initial_size, size_t* current_size);
void cleanup_arrays(config** config_array, event** event_array, size_t config_size, size_t event_size);

// Main function
void manage_memory(size_t initial_config_size, size_t initial_event_size) {
    srand(time(NULL)); // Seed PRNG

    config* config_array = NULL;
    event* event_array = NULL;

    if (init_config_array(&config_array, initial_config_size, &initial_config_size) != 0) {
        cleanup_arrays(&config_array, &event_array, initial_config_size, initial_event_size);
        return;
