#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/rand.h>

#define MAX_CONFIGS 100
#define MAX_EVENTS 500

typedef struct {
    double probability;
    char* name;
    int timeout;
    unsigned long id;
} config;

typedef struct {
    time_t timestamp;
    char* description;
    config* config_ptr;
} event;

int generate_unique_id(unsigned long range, unsigned long* ids, size_t count) {
    while (1) {
        if (!RAND_bytes((unsigned char*)&ids[count], sizeof(ids[count]))) return -1;
        ids[count] %= range;
        int i;
        for (i = 0; i < count; ++i) {
            if (ids[i] == ids[count]) break;
        }
        if (i == count) return 0;
    }
}

void* safe_malloc(size_t size, const char* file, int line) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed at %s:%d\n", file, line);
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void log_memory_usage(const char* description, size_t allocated_size) {
    static time_t start_time = 0;
    if (start_time == 0) start_time = time(NULL);

    static unsigned long total_allocated = 0;
    total_allocated += allocated_size;

    printf("Memory usage: %s - Allocated %zu bytes (Total: %lu)\n", description, allocated_size, total_allocated);
}

config* allocate_configs(size_t count) {
    config* configs = safe_malloc(count * sizeof(config), __FILE__, __LINE__);
    unsigned long ids[MAX_CONFIGS];
    if (generate_unique_id(MAX_CONFIGS, ids, count)) {
        free(configs);
        return NULL;
    }
    for (size_t i = 0; i < count; ++i) {
        configs[i].probability = (double)i / count;
        configs[i].name = safe_malloc(50 * sizeof(char), __FILE__, __LINE__);
        snprintf(configs[i].name, 50, "Config%d", i);
        configs[i].timeout = (int)(1000 * rand() / RAND_MAX);
        configs[i].id = ids[i];
    }
    log_memory_usage("Configs allocated", count * sizeof(config));
    return configs;
}

event* allocate_events(size_t count) {
    event* events = safe_malloc(count * sizeof(event), __FILE__, __LINE__);
    for (size_t i = 0; i < count; ++i) {
        events[i].timestamp = time(NULL);
        events[i].description = safe_malloc(100 * sizeof(char), __FILE__, __LINE__);
        snprintf(events[i].description, 100, "Event%d", i);
        events[i].config_ptr = &allocate_configs(1)[0]; // Simulate allocation of config
    }
    log_memory_usage("Events allocated", count * sizeof(event));
    return events;
}

void free_configs(config* configs, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(configs[i].name);
    }
    free(configs);
    log_memory_usage("Configs freed", -count * sizeof(config));
}

void free_events(event* events, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(events[i].description);
    }
    free(events);
    log_memory_usage("Events freed", -count * sizeof(event));
}

int main() {
    srand(time(NULL));
    if (!RAND_seed((unsigned char*)&srand, sizeof(srand))) return 1;

    size_t config_count = 10;
    size_t event_count = 20;

    config* configs = allocate_configs(config_count);
    if (!configs) return 1;

    event* events = allocate_events(event_count);
    if (!events) {
        free_configs(configs, config_count);
        return 1;
    }

    // Simulate usage of configs and events
    for (size_t i = 0; i < config_count; ++i) {
        printf("Config %lu: Probability=%f, Name='%s', Timeout=%d\n", configs[i].id, configs[i].probability, configs[i].name, configs[i].timeout);
    }

    for (size_t i = 0; i < event_count; ++i) {
        printf("Event %zu: Timestamp=%ld, Description='%s'\n", i, events[i].timestamp, events[i].description);
    }

    free_events(events, event_count);
    free_configs(configs, config_count);

    return 0;
}
