void processFinancialTransaction(long id, int amount, char* description, time_t timestamp) {
    if (id == -1) {
        id = prng();
    }
    for (int i = 0; i < transaction_count; i++) {
        if (transactions[i].id == id) {
            printf("Duplicate transaction ID detected.\n");
            return;
        }
    }
    if (transaction_count >= MAX_TRANSACTIONS) {
        printf("Transaction collection is full.\n");
        return;
    }
    transactions[transaction_count].id = id;
    transactions[transaction_count].amount = amount;
    strcpy(transactions[transaction_count].description, description);
    transactions[transaction_count].timestamp = timestamp;
    transaction_count++;
}

