#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define PRNG(seed) ((seed = (seed * 1103515245 + 12345)) % UINT_MAX)

typedef struct {
    int id;
} Record;

Record* create_records(long long count, unsigned int seed, int range_start, int range_end, long** offsets, int** keys) {
    if (count > INT_MAX || range_end - range_start < count) {
        return NULL; // Handle invalid input
    }

    Record* records = (Record*)malloc(count * sizeof(Record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    long* offset_values = (long*)malloc(count * sizeof(long));
    int* key_values = (int*)malloc(count * sizeof(int));
    if (!offset_values || !key_values) {
        free(records);
        free(offset_values);
        free(key_values);
        return NULL; // Memory allocation failed
    }

    unsigned int current_seed = seed;
    for (long long i = 0; i < count; ++i) {
        records[i].id = PRNG(current_seed) % (range_end - range_start + 1) + range_start;
        while (i > 0 && records[i].id == records[i-1].id) { // Avoid duplicates
            current_seed = PRNG(seed);
            records[i].id = PRNG(current_seed) % (range_end - range_start + 1) + range_start;
        }
        offset_values[i] = i * sizeof(Record); // Example offset calculation
        key_values[i] = records[i].id;
    }

    *offsets = offset_values;
    *keys = key_values;

    return records;
}

void free_records(Record* records, long* offsets, int* keys) {
    if (records) free(records);
    if (offsets) free(offsets);
    if (keys) free(keys);
}
