#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

typedef struct {
    int value;
} record;

void* allocate_and_initialize_arrays(size_t size, EVP_CIPHER* cipher, const unsigned char* key, const unsigned char* iv) {
    // Allocate memory for arrays
    long* offset_array = (long*)malloc(size * sizeof(long));
    int* key_array = (int*)malloc(size * sizeof(int));
    record* record_array = (record*)malloc(size * sizeof(record));

    if (!offset_array || !key_array || !record_array) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Initialize arrays with cryptographically strong random numbers
    for (size_t i = 0; i < size; ++i) {
        if (!RAND_bytes((unsigned char*)&offset_array[i], sizeof(long)) ||
            !RAND_bytes((unsigned char*)&key_array[i], sizeof(int))) {
            perror("Failed to generate random number");
            free(offset_array);
            free(key_array);
            free(record_array);
            return NULL;
        }

        // Encrypt data
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) {
            perror("EVP_CIPHER_CTX_new failed");
            free(offset_array);
            free(key_array);
            free(record_array);
            return NULL;
        }

        if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
            perror("EVP_EncryptInit_ex failed");
            EVP_CIPHER_CTX_free(ctx);
            free(offset_array);
            free(key_array);
            free(record_array);
            return NULL;
        }

        if (1 != EVP_EncryptUpdate(ctx, (unsigned char*)&record_array[i].value, &key_array[i], (const unsigned char*)&offset_array[i], sizeof(long))) {
            perror("EVP_EncryptUpdate failed");
            EVP_CIPHER_CTX_free(ctx);
            free(offset_array);
            free(key_array);
            free(record_array);
            return NULL;
        }

        if (1 != EVP_EncryptFinal_ex(ctx, (unsigned char*)&record_array[i].value + key_array[i], &key_array[i])) {
            perror("EVP_EncryptFinal_ex failed");
            EVP_CIPHER_CTX_free(ctx);
            free(offset_array);
            free(key_array);
            free(record_array);
            return NULL;
        }

        EVP_CIPHER_CTX_free(ctx);

        // Calculate checksum
        unsigned char digest[EVP_MAX_MD_SIZE];
        int digest_len;
        if (!EVP_Digest((unsigned char*)&record_array[i], sizeof(record), digest, &digest_len, EVP_md5(), NULL)) {
            perror("EVP_Digest failed");
            free(offset_array);
            free(key_array);
            free(record_array);
            return NULL;
        }

        // Store checksum in key array
        memcpy(&key_array[i], digest, sizeof(int));
    }

    return (void*)record_array;
}

int execute_command(const char* command) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork failed");
        return 0;
    } else if (pid == 0) {
        // Child process
        execlp(command, command, NULL);
        perror("execlp failed");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        wait(&status);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 1 : 0;
    }
}
