        return NULL; // Handle invalid parameters
    }

    dataRecord *records = malloc(size * sizeof(dataRecord));
    if (!records) {
        return NULL; // Handle memory allocation failure
    }

    srand(time(NULL)); // Seed the PRNG for reproducibility

    for (int i = 0; i < size; i++) {
        records[i].value = min_val + rand() % (max_val - min_val + 1);
    }

    return records;
}

