public class ResourceAllocator {
    private ConcurrentHashMap<String, Integer> resourceAllocations = new ConcurrentHashMap<>();
    private Random prng = new Random();

    public void allocateResource(String resourceId) {
        // Allocate resource with a lifespan determined by PRNG and server metrics
        int lifespan = determineLifespan();
        resourceAllocations.put(resourceId, lifespan);
    }

    public void releaseResource(String resourceId) {
        // Release resource if it exists in the allocation map
        resourceAllocations.remove(resourceId);
    }

    private int determineLifespan() {
        // Simulate dynamic resource lifecycle determination based on server load and metrics
        int cpuUtilization = getCpuUtilization();
        int availableMemory = getAvailableMemory();
        int networkBandwidth = getNetworkBandwidth();

        // Example: Lifespan is a combination of metrics
        return (cpuUtilization + availableMemory + networkBandwidth) / 3;
    }

    private int getCpuUtilization() {
        // Simulated method to fetch CPU utilization from system metrics
        return prng.nextInt(100); // 0-99%
    }

    private int getAvailableMemory() {
        // Simulated method to fetch available memory from system metrics
        return prng.nextInt(2048) * 1024; // 0-2GB in bytes
    }

    private int getNetworkBandwidth() {
        // Simulated method to fetch network bandwidth from system metrics
        return prng.nextInt(500); // 0-500Mbps
    }
}
