#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <time.h>

#define MAX_CLIENTS 100
#define PORT 8080

typedef struct {
    int id;
    int socket;
} ClientSession;

ClientSession sessions[MAX_CLIENTS];
int session_count = 0;

pthread_mutex_t lock;
pthread_cond_t cond;
int connection_pool_size = MAX_CLIENTS;

void* handle_client(void* arg) {
    int new_socket = *(int*)arg;
    free(arg);

    // Assign a unique session ID using a non-cryptographic PRNG
    pthread_mutex_lock(&lock);
    sessions[session_count].id = rand();
    sessions[session_count].socket = new_socket;
    session_count++;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);

    // Handle client communication here

    return NULL;
}

void start_server() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, MAX_CLIENTS) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        pthread_t thread;
        int* new_socket_ptr = malloc(sizeof(int));
        *new_socket_ptr = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen);

        if (*new_socket_ptr < 0) {
            perror("accept");
            free(new_socket_ptr);
            continue;
        }

        pthread_create(&thread, NULL, handle_client, new_socket_ptr);
    }
}

int main() {
    srand(time(NULL));
    pthread_mutex_init(&lock, NULL);
    pthread_cond_init(&cond, NULL);

    start_server();

    pthread_mutex_destroy(&lock);
    pthread_cond_destroy(&cond);

    return 0;
}
