// Global PRNG state
struct prng_state {
    unsigned long seed;
};
static struct prng_state prng_state = {0};

// Function to initialize the PRNG with a given seed
void init_prng(unsigned long seed) {
    prng_state.seed = seed;
}

// Non-cryptographic pseudo-random number generator using Xorshift algorithm
unsigned long next_random() {
    prng_state.seed ^= prng_state.seed << 13;
    prng_state.seed ^= prng_state.seed >> 7;
    prng_state.seed ^= prng_state.seed << 17;
    return prng_state.seed;
}

// Function to allocate memory for an array of long integers
long* allocate_long_array(size_t size) {
    long* array = (long*)malloc(size * sizeof(long));
    if (!array) {
        // Handle allocation failure
        return NULL;
    }
    return array;
}

// Function to allocate memory for an array of char strings
char** allocate_char_array(size_t size, size_t string_length) {
    char** array = (char**)malloc(size * sizeof(char*));
    if (!array) {
        // Handle allocation failure
        return NULL;
    }
    for (size_t i = 0; i < size; ++i) {
        array[i] = (char*)malloc(string_length);
        if (!array[i]) {
            // Free previously allocated memory on failure
            for (size_t j = 0; j < i; ++j) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }
    }
    return array;
}

// Function to allocate memory for an array of Config structures
Config* allocate_config_array(size_t size) {
    Config* array = (Config*)malloc(size * sizeof(Config));
    if (!array) {
        // Handle allocation failure
        return NULL;
    }
    for (size_t i = 0; i < size; ++i) {
        array[i].config_name = (char*)malloc(256); // Assuming max name length of 255
        if (!array[i].config_name) {
            // Free previously allocated memory on failure
            for (size_t j = 0; j < i; ++j) {
                free(array[j].config_name);
            }
            free(array);
            return NULL;
        }
    }
