// Thread-safe function to add an entry to an array
int thread_safe_add(void** array, size_t* size, size_t new_size, void (*alloc_func)(size_t)) {
    pthread_mutex_lock(&mutex); // Lock the mutex before resizing
    *array = realloc(*array, new_size);
    if (!*array) {
        pthread_mutex_unlock(&mutex);
        return -1; // Handle allocation failure
    }
    *size = new_size;
    pthread_mutex_unlock(&mutex); // Unlock the mutex after resizing
    return 0;
}

// Thread-safe function to remove an entry from an array
int thread_safe_remove(void** array, size_t* size, size_t index) {
    pthread_mutex_lock(&mutex); // Lock the mutex before removing
    if (index >= *size) {
        pthread_mutex_unlock(&mutex);
        return -1; // Invalid index
    }
    memmove(array + index, array + index + 1, (*size - index - 1) * sizeof(void*));
    *size -= 1;
    pthread_mutex_unlock(&mutex); // Unlock the mutex after removing
    return 0;
}

