} MemoryPool;

int generate_session_id() {
    return rand(); // Simplified for example purposes
}

MemoryPool* create_memory_pool(int initial_size) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pool->session_ids = (int*)calloc(initial_size, sizeof(int));
    pool->num_sessions = initial_size;

    for (int i = 0; i < initial_size; i++) {
        pool->session_ids[i] = generate_session_id();
    }

    for (int i = 0; i < initial_size; i++) {
        pool->users[i] = NULL;
    }
    pool->num_users = initial_size;

    for (int i = 0; i < initial_size; i++) {
        pool->transactions[i] = NULL;
    }
    pool->num_transactions = initial_size;

    return pool;
}

void add_user(MemoryPool *pool, char *name, char *email) {
    if (pool->num_users >= MAX_USERS) {
        printf("User array is full\n");
        return;
    }

    User *new_user = (User*)malloc(sizeof(User));
    if (!new_user) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_user->name = strdup(name);
    new_user->email = strdup(email);
    new_user->session_id = pool->session_ids[pool->num_users];

    pool->users[pool->num_users] = new_user;
    pool->num_users++;
}

void add_transaction(MemoryPool *pool, time_t timestamp, double amount, char *description) {
    if (pool->num_transactions >= MAX_TRANSACTIONS) {
        printf("Transaction array is full\n");
        return;
    }

    Transaction *new_transaction = (Transaction*)malloc(sizeof(Transaction));
    if (!new_transaction) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_transaction->timestamp = timestamp;
    new_transaction->amount = amount;
    strncpy(new_transaction->description, description, sizeof(new_transaction->description));

    User *user = pool->users[pool->num_users - 1]; // Assuming last user for simplicity
    new_transaction->user_profile = user;

    pool->transactions[pool->num_transactions] = new_transaction;
    pool->num_transactions++;
}

void free_memory_pool(MemoryPool *pool) {
    for (int i = 0; i < pool->num_users; i++) {
        free(pool->users[i]->name);
        free(pool->users[i]->email);
        free(pool->users[i]);
    }

    for (int i = 0; i < pool->num_transactions; i++) {
        free(pool->transactions[i]);
    }

    free(pool->session_ids);
    free(pool);
}

int main() {
    srand(time(NULL)); // Seed the PRNG
    MemoryPool *pool = create_memory_pool(10);

    add_user(pool, "John Doe", "john@example.com");
    add_transaction(pool, time(NULL), 100.50, "Initial deposit");

    free_memory_pool(pool);
    return 0;
}
