void* dynamic_memory_manager(int data_type, size_t count, void* config) {
    switch (data_type) {
        case 'l': // Array of 'long' integers
            return malloc(count * sizeof(long));
        case 'i': // Array of 'int' keys
            return malloc(count * sizeof(int));
        case 's': // Array of 'char' strings
            return malloc(count * sizeof(char*));
        case 'r': // Array of 'record' structures
            Record* records = (Record*)malloc(count * sizeof(Record));
            if (records) {
                for (size_t i = 0; i < count; ++i) {
                    records[i].random_int = ((rand() % ((int*)config)[1]) + ((int*)config)[0]);
                    records[i].multiple_of_prime = ((long*)config)[0] * (i + 1);
                    records[i].probability = (double)(rand()) / RAND_MAX;
                }
            }
            return records;
        default:
            return NULL;
    }
}

int main() {
    srand(time(0)); // Initialize random seed

    int config_ints[] = {1, 100}; // Range for random_int
    long config_primes[] = {2};   // Prime number for multiple_of_prime

    void* data = dynamic_memory_manager('r', 5, (void*)config_ints);
    if (data) {
        Record* records = (Record*)data;
        for (size_t i = 0; i < 5; ++i) {
            printf("Random Int: %d, Multiple of Prime: %ld, Probability: %.2f\n", 
                   records[i].random_int, records[i].multiple_of_prime, records[i].probability);
        }
        free(records);
    }

    return 0;
}
