#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct record {
    int value;
} record;

typedef struct linked_list_node {
    record *data;
    struct linked_list_node *next;
} linked_list_node;

typedef struct linked_list {
    linked_list_node *head;
    pthread_mutex_t lock;
} linked_list;

linked_list_node* create_linked_list_node(record *data) {
    linked_list_node *node = (linked_list_node*) malloc(sizeof(linked_list_node));
    node->data = data;
    node->next = NULL;
    return node;
}

void insert_into_linked_list(linked_list *list, record *data) {
    pthread_mutex_lock(&list->lock);
    linked_list_node *new_node = create_linked_list_node(data);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void delete_from_linked_list(linked_list *list, record *data) {
    pthread_mutex_lock(&list->lock);
    linked_list_node *current = list->head;
    linked_list_node *previous = NULL;

    while (current != NULL) {
        if (current->data == data) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void traverse_linked_list(linked_list *list) {
    pthread_mutex_lock(&list->lock);
    linked_list_node *current = list->head;
    while (current != NULL) {
        // Process current->data
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

