typedef struct Node {
    int identifier;
    long timestamp;
    struct Node* left;
    struct Node* right;
} Node;

Node* create_node(int identifier, long timestamp) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed for new node\n");
        exit(EXIT_FAILURE);
    }
    node->identifier = identifier;
    node->timestamp = timestamp;
    node->left = node->right = NULL;
    return node;
}

Node* insert_node(Node* root, int identifier, long timestamp) {
    if (root == NULL)
        return create_node(identifier, timestamp);

    if (identifier < root->identifier)
        root->left = insert_node(root->left, identifier, timestamp);
    else if (identifier > root->identifier)
        root->right = insert_node(root->right, identifier, timestamp);

    return root;
}

