// Non-cryptographic PRNG function for performance optimization
static inline unsigned xorshift128plus(uint32_t *x, uint32_t *y) {
    uint64_t t = (*x + *y);
    *x = y[0];
    *y = t;
    t ^= (t << 5);
    return (t >> 19) + (t << 24);
}

// Initialize a set of records with random numbers in the specified range
RecordSet* initialize_record_sets(int num_sets, long** offsets, int** keys, int lower_bound, int upper_bound, size_t record_count) {
    if (lower_bound >= upper_bound || record_count == 0) {
        return NULL; // Invalid range or count
    }

    RecordSet* sets = malloc(num_sets * sizeof(RecordSet));
    if (!sets) {
        return NULL; // Memory allocation failed
    }

    uint32_t x[2] = {time(NULL), (uint32_t)getpid()};
    uint32_t y[2] = {time(NULL) + 1, (uint32_t)getpid() + 1};

    for (int i = 0; i < num_sets; i++) {
        sets[i].offset = offsets[i];
        sets[i].key = keys[i];
        sets[i].data = malloc(record_count * sizeof(record));
        if (!sets[i].data) {
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(sets[j].data);
            }
            free(sets);
            return NULL; // Memory allocation failed for a set
        }

        for (size_t j = 0; j < record_count; j++) {
            uint32_t r = xorshift128plus(&x[0], &y[0]);
            sets[i].data[j].value = lower_bound + (r % (upper_bound - lower_bound + 1));
        }
    }

    return sets;
}

// Clean-up function to free all allocated memory
void cleanup_record_sets(RecordSet* sets, int num_sets) {
    if (sets) {
        for (int i = 0; i < num_sets; i++) {
            if (sets[i].data) {
                free(sets[i].data);
            }
        }
        free(sets);
    }
}
