class ConfigManager {
private:
    struct ConfigSetting {
        int retryInterval;
        int connectionTimeout;
        std::string logLevel;
    };

    std::mutex configMutex;
    std::unordered_map<std::string, ConfigSetting> settingsMap;

public:
    void setConfig(const std::string& profileName, const ConfigSetting& setting) {
        std::lock_guard<std::mutex> lock(configMutex);
        settingsMap[profileName] = setting;
    }

    ConfigSetting getConfig(const std::string& profileName) {
        std::lock_guard<std::mutex> lock(configMutex);
        return settingsMap[profileName];
    }

    void updateConfigBasedOnLoad(int currentLoad) {
        for (auto& [key, value] : settingsMap) {
            std::mt19937 gen(currentLoad);
            std::uniform_int_distribution<> dis(10, 100);
            value.retryInterval = dis(gen);
            value.connectionTimeout = dis(gen);
        }
    }

    void monitorConfigSystem() {
        while (true) {
            // Check for inconsistencies and apply updates if necessary
            std::lock_guard<std::mutex> lock(configMutex);
            for (auto& [key, value] : settingsMap) {
                if (value.retryInterval < 0 || value.connectionTimeout < 0) {
                    // Handle error or apply default values
                    value.retryInterval = 10;
                    value.connectionTimeout = 10;
                }
            }
            std::this_thread::sleep_for(std::chrono::seconds(10));
        }
    }

    static int findMaxInArray(const std::vector<int>& arr) {
        if (arr.empty()) return 0;
        return *std::max_element(arr.begin(), arr.end());
    }
};

int main() {
    ConfigManager manager;
    manager.setConfig("default", {5, 15, "INFO"});

    // Update configuration based on simulated load
    std::thread monitorThread(&ConfigManager::monitorConfigSystem, &manager);
    std::vector<int> inputArray = {3, 8, 2, 9, 4};
    int maxVal = ConfigManager::findMaxInArray(inputArray);

    // Output the largest integer from the array
    std::cout << "Largest Integer in Array: " << maxVal << std::endl;

    monitorThread.join();
    return 0;
}
