    firmwares = (Firmware**)malloc(capacity * sizeof(Firmware*));
    events = (Event**)malloc(capacity * sizeof(Event*));

    if (devices == NULL || firmwares == NULL || events == NULL) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    for (size_t i = 0; i < capacity; ++i) {
        Device* device = init_device();
        Firmware* firmware = init_firmware(device);
        Event* event = init_event(firmware, "Initial Event", 1);

        if (device == NULL || firmware == NULL || event == NULL) {
            printf("Failed to initialize device or firmware.\n");
            return 1;
        }

        devices[i] = device;
        firmwares[i] = firmware;
        events[i] = event;

        log_message("Device and Firmware initialized successfully.", 1, verbosity);
    }

    // Simulate adding more data
    capacity *= 2;
    devices = resize_array(devices, capacity / 2, capacity, sizeof(Device*));
    firmwares = resize_array(firmwares, capacity / 2, capacity, sizeof(Firmware*));
    events = resize_array(events, capacity / 2, capacity, sizeof(Event*));

    if (devices == NULL || firmwares == NULL || events == NULL) {
        printf("Memory reallocation failed.\n");
        return 1;
    }

    for (size_t i = capacity / 2; i < capacity; ++i) {
        Device* device = init_device();
        Firmware* firmware = init_firmware(device);
        Event* event = init_event(firmware, "Additional Event", 2);

        if (device == NULL || firmware == NULL || event == NULL) {
            printf("Failed to initialize device or firmware.\n");
