#include <stdlib.h>
#include <time.h>

typedef struct {
    int intValue;
    long longValue;
    double doubleValue;
} Record;

void* allocateMemory(int dataSize, char dataType) {
    void* memory = NULL;

    switch (dataType) {
        case 'l':
            memory = malloc(dataSize * sizeof(long));
            break;
        case 'i':
            memory = malloc(dataSize * sizeof(int));
            break;
        case 's':
            memory = malloc(dataSize * sizeof(char *));
            for (int i = 0; i < dataSize; i++) {
                ((char **)memory)[i] = malloc(256);
            }
            break;
        case 'r':
            memory = malloc(dataSize * sizeof(Record));
            for (int i = 0; i < dataSize; i++) {
                ((Record *)memory)[i].intValue = rand() % 100 + 1; // Random int between 1 and 100
                ((Record *)memory)[i].longValue = ((rand() % 17) + 1) * (233); // Multiple of a prime number
                ((Record *)memory)[i].doubleValue = (double)(rand()) / RAND_MAX; // Double between 0.0 and 1.0
            }
            break;
        default:
            printf("Invalid data type\n");
            break;
    }

    if (memory == NULL) {
        printf("Memory allocation failed\n");
    } else {
        printf("Memory allocated successfully\n");
    }

    return memory;
}

void deallocateMemory(void* memory, char dataType, int dataSize) {
    switch (dataType) {
        case 'l':
            free(memory);
            break;
        case 'i':
            free(memory);
            break;
        case 's':
            for (int i = 0; i < dataSize; i++) {
                free(((char **)memory)[i]);
            }
            free(memory);
            break;
        case 'r':
            free(memory);
            break;
        default:
            printf("Invalid data type\n");
            break;
    }

    printf("Memory deallocated successfully\n");
}

int main() {
    srand(time(NULL)); // Seed for PRNG

    int dataSize = 5;

    void* longArray = allocateMemory(dataSize, 'l');
    void* intArray = allocateMemory(dataSize, 'i');
    void* charArray = allocateMemory(dataSize, 's');
    void* recordArray = allocateMemory(dataSize, 'r');

    deallocateMemory(longArray, 'l', dataSize);
    deallocateMemory(intArray, 'i', dataSize);
    deallocateMemory(charArray, 's', dataSize);
    deallocateMemory(recordArray, 'r', dataSize);

    return 0;
}
