#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <cryptgenrandom.h>

typedef struct {
    int key;
    long offset;
} record;

record* allocate_records(size_t size) {
    return (record*)malloc(size * sizeof(record));
}

void initialize_records(record* records, size_t size, int min_key, int max_key, long min_offset, long max_offset) {
    HCRYPTPROV hProv;
    CryptAcquireContext(&hProv, NULL, NULL, PROV_RSA_FULL, CRYPT_VERIFYCONTEXT);

    for (size_t i = 0; i < size; ++i) {
        records[i].key = rand_s(hProv) % (max_key - min_key + 1) + min_key;
        records[i].offset = rand_s(hProv) % (max_offset - min_offset + 1) + min_offset;
    }

    CryptReleaseContext(hProv, 0);
}

void resize_records(record** records, size_t old_size, size_t new_size) {
    record* new_records = allocate_records(new_size);
    if (*records != NULL) {
        memcpy(new_records, *records, old_size * sizeof(record));
        free(*records);
    }
    *records = new_records;
}

void reseed_random_generator() {
    HCRYPTPROV hProv;
    CryptAcquireContext(&hProv, NULL, NULL, PROV_RSA_FULL, CRYPT_VERIFYCONTEXT | CRYPT_NEWKEYSET);
    CryptReleaseContext(hProv, 0);
}

void deallocate_records(record* records) {
    free(records);
}
```

