    fast_prng_state = (fast_prng_state * 1103515245 + 12345) % 4294967296;
    return fast_prng_state;
}

void secure_prng(unsigned long *state, unsigned char *buffer, size_t length) {
    // Implement a CSPRNG like ChaCha20 or use a library function
    // For simplicity, using a non-cryptographic PRNG here
    for (size_t i = 0; i < length; i++) {
        *state = (*state * 1103515245 + 12345) % 4294967296;
        buffer[i] = *state & 0xFF;
    }
}

void initialize_arrays(long **offsets, int **keys, record **records, unsigned char **flags, enum priority **priorities, size_t count) {
    *offsets = (long *)malloc(count * sizeof(long));
    *keys = (int *)malloc(count * sizeof(int));
    *records = (record *)malloc(count * sizeof(record));
    *flags = (unsigned char *)malloc(count * sizeof(unsigned char));
    *priorities = (enum priority *)malloc(count * sizeof(enum priority));

    srand(time(NULL));

    for (size_t i = 0; i < count; i++) {
        (*offsets)[i] = fast_prng() % 1000;
        if (i % MAX_ITERATIONS == 0) secure_prng((unsigned long *)keys, (unsigned char *)&(*keys)[i], sizeof(int));
        else (*keys)[i] = rand();

        time_t now = time(NULL);
        (*records)[i].value = fast_prng() % 100;
        if (i % MAX_ITERATIONS == 0) secure_prng((unsigned long *)&now, (unsigned char *)&(*records)[i].timestamp, sizeof(time_t));
        else (*records)[i].timestamp = now;

        *flags[i] = rand() % 2 ? 0x1 : 0x0;
        *priorities[i] = (enum priority)(rand() % 3);
    }
