#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} record;

typedef struct {
    record* records;
    char** logs;
    size_t capacity;
    size_t size;
    time_t last_seed_time;
    size_t total_memory_usage;
} dynamic_array;

dynamic_array* create_dynamic_array(size_t initial_capacity) {
    dynamic_array* array = (dynamic_array*)malloc(sizeof(dynamic_array));
    if (!array) return NULL;

    array->records = (record*)calloc(initial_capacity, sizeof(record));
    array->logs = (char**)calloc(initial_capacity, sizeof(char*));
    array->capacity = initial_capacity;
    array->size = 0;
    array->last_seed_time = time(NULL);
    array->total_memory_usage = 0;

    return array;
}

void destroy_dynamic_array(dynamic_array* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->logs[i]);
    }
    free(array->records);
    free(array->logs);
    free(array);
}

int resize_dynamic_array(dynamic_array* array, size_t new_capacity) {
    record* new_records = (record*)realloc(array->records, new_capacity * sizeof(record));
    char** new_logs = (char**)realloc(array->logs, new_capacity * sizeof(char*));

    if (!new_records || !new_logs) {
        free(new_records);
        free(new_logs);
        return -1;
    }

    array->records = new_records;
    array->logs = new_logs;
    array->capacity = new_capacity;

    return 0;
}

void seed_prng(time_t seed_time) {
    srand(seed_time);
}

int init_dynamic_array(dynamic_array* array, int key_range_start, int key_range_end, size_t initial_size) {
    if (array->size > 0) return -1; // Initialize only once

    time_t current_time = time(NULL);

    if (current_time - array->last_seed_time > 60) { // Re-seed every minute
        seed_prng(current_time);
        array->last_seed_time = current_time;
    }

    for (size_t i = 0; i < initial_size; ++i) {
        if (array->size == array->capacity) {
            if (resize_dynamic_array(array, array->capacity * 2) != 0) return -1;
        }

        array->records[i].key = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        array->records[i].offset = i;

        char* log_message = malloc(100 * sizeof(char));
        sprintf(log_message, "Initialized record at index %zu with key %d", i, array->records[i].key);
        array->logs[array->size++] = log_message;

        // Calculate total memory usage
        array->total_memory_usage += sizeof(record) + 100 * sizeof(char); // Approximation
    }

    return 0;
}

void validate_dynamic_array(dynamic_array* array) {
    for (size_t i = 0; i < array->size - 1; ++i) {
        if (array->records[i].offset != i) {
            printf("Validation failed at index %zu\n", i);
            return;
        }
    }
    printf("Validation passed\n");
}
