// Define transaction structure
typedef struct {
    long id;
    int amount;
    char description[256];
    time_t timestamp;
} Transaction;

// Initialize a dynamic array to hold transactions
Transaction* transactions = NULL;
int transaction_count = 0;
int transaction_capacity = 0;

// Function to add a new transaction
void processFinancialTransaction(long id, int amount, const char* description) {
    if (id <= 0 || amount <= 0 || description == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Resize the dynamic array if needed
    if (transaction_count >= transaction_capacity) {
        if (transaction_capacity == 0) {
            transaction_capacity = 16;
        } else {
            transaction_capacity *= 2;
        }
        transactions = realloc(transactions, transaction_capacity * sizeof(Transaction));
    }

    // Add the new transaction
    Transaction* new_transaction = &transactions[transaction_count++];
    new_transaction->id = id;
    new_transaction->amount = amount;
    strncpy(new_transaction->description, description, sizeof(new_transaction->description) - 1);
    new_transaction->description[sizeof(new_transaction->description) - 1] = '\0';
    new_transaction->timestamp = time(NULL);

    // Log the transaction
    printf("Transaction processed: ID=%ld, Amount=%d, Description=%s\n", id, amount, description);
}

// Function to retrieve transactions (simulating HTTP GET)
void getTransactions(int page, int pageSize) {
    if (page < 1 || pageSize <= 0) {
        fprintf(stderr, "Invalid pagination parameters\n");
        return;
    }

    // Simulate a paginated response
    for (int i = (page - 1) * pageSize; i < transaction_count && i < page * pageSize; ++i) {
        printf("Transaction ID: %ld, Amount: %d, Description: %s, Timestamp: %s\n",
               transactions[i].id, transactions[i].amount, transactions[i].description,
               ctime(&transactions[i].timestamp));
    }
}

// Function to update a transaction (simulating HTTP PUT)
void updateTransaction(long id, int amount, const char* description) {
    for (int i = 0; i < transaction_count; ++i) {
        if (transactions[i].id == id) {
            transactions[i].amount = amount;
            strncpy(transactions[i].description, description, sizeof(transactions[i].description) - 1);
            transactions[i].description[sizeof(transactions[i].description) - 1] = '\0';
            transactions[i].timestamp = time(NULL);

            printf("Transaction updated: ID=%ld, Amount=%d, Description=%s\n", id, amount, description);
            return;
        }
    }

    fprintf(stderr, "Transaction not found: ID=%ld\n", id);
}

// Function to perform a health check
void performHealthCheck() {
    if (transactions == NULL) {
        printf("System is not initialized.\n");
    } else {
        printf("System is healthy with %d transactions.\n", transaction_count);
    }
}
