        free(keys);
        free(timestamps);
        return NULL;
    }

    record* records = (record*)malloc(recordsSize * sizeof(record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(stats);
        free(keys);
        free(timestamps);
        return NULL;
    }

