#define ERR_NONE 0
#define ERR_MEM_ALLOC 1

typedef struct {
    int value;
} record;

typedef enum {
    PRNG_XORSHIFT,
    PRNG_MT19937,
    // Add more PRNG options as needed
} prng_type;

long *allocate_long_array(size_t size, int *error) {
    long *array = (long *)malloc(size * sizeof(long));
    if (!array) {
        *error = ERR_MEM_ALLOC;
        return NULL;
    }
    for (size_t i = 0; i < size; i++) {
        array[i] = 0L;
    }
    *error = ERR_NONE;
    return array;
}

int *allocate_int_array(size_t size, int *error) {
    int *array = (int *)malloc(size * sizeof(int));
    if (!array) {
        *error = ERR_MEM_ALLOC;
        return NULL;
    }
    for (size_t i = 0; i < size; i++) {
        array[i] = 0;
    }
    *error = ERR_NONE;
    return array;
}

record *allocate_record_array(size_t size, int *error) {
    record *array = (record *)malloc(size * sizeof(record));
    if (!array) {
        *error = ERR_MEM_ALLOC;
        return NULL;
    }
    for (size_t i = 0; i < size; i++) {
        array[i].value = 0;
    }
    *error = ERR_NONE;
    return array;
}

void xorshift PRNG(uint64_t *state, uint32_t range) {
    *state ^= (*state << 13);
    *state ^= (*state >> 7);
    *state ^= (*state << 17);
    return (*state % (range + 1));
}

int initialize_records(record *records, size_t count, prng_type type, uint64_t seed, uint32_t range) {
    if (!records || !count) return ERR_MEM_ALLOC;

    switch (type) {
        case PRNG_XORSHIFT:
            srand(seed);
            for (size_t i = 0; i < count; i++) {
                records[i].value = xorshift(&seed, range);
            }
            break;
        // Add more PRNG types as needed
        default:
            return ERR_MEM_ALLOC;
    }

    return ERR_NONE;
}

int create_records(long *offsets, int *keys, record **records_ptr, size_t count, prng_type type, uint64_t seed, uint32_t range, size_t max_count) {
    if (count > max_count) return ERR_MEM_ALLOC;

    int error = ERR_NONE;
    offsets = allocate_long_array(count, &error);
    if (error != ERR_NONE) return error;

    keys = allocate_int_array(count, &error);
    if (error != ERR_NONE) {
        free(offsets);
        return error;
    }

    *records_ptr = allocate_record_array(count, &error);
    if (error != ERR_NONE) {
        free(offsets);
        free(keys);
        return error;
    }

    offsets[0] = 0L;
    for (size_t i = 1; i < count; i++) {
        offsets[i] = offsets[i - 1] + keys[i - 1];
    }

    error = initialize_records(*records_ptr, count, type, seed, range);
    if (error != ERR_NONE) {
        free(offsets);
        free(keys);
        free(*records_ptr);
        *records_ptr = NULL;
        return error;
    }

    return ERR_NONE;
}

// Example usage:
int main() {
    long offsets[10];
    int keys[10];
    record *records;

    int result = create_records(offsets, keys, &records, 10, PRNG_XORSHIFT, time(NULL), 100, 100);
    if (result != ERR_NONE) {
        printf("Error: %d\n", result);
        return 1;
    }

    // Use the records...

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
