#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

unsigned long xorshift128plus(unsigned long *x, unsigned long *y) {
    unsigned long s0 = x[0];
    unsigned long s1 = y[0];
    unsigned long result = s0 + s1;

    s0 ^= s0 << 13;
    s1 ^= s1 >> 7;
    s0 ^= s0 ^ (s0 << 4);
    s1 ^= s1 ^ (s1 >> 19);

    x[0] = s0;
    y[0] = s1;

    return result + ++result;
}

int* allocateAndInitializeIntArray(int size, int minVal, int maxVal) {
    if (size <= 0 || minVal > maxVal) {
        fprintf(stderr, "Invalid size or value range.\n");
        return NULL;
    }

    int* array = (int*)malloc(size * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for integer array.\n");
        return NULL;
    }

    unsigned long seed[2] = {time(NULL), time(NULL)};
    for (int i = 0; i < size; ++i) {
        array[i] = xorshift128plus(seed + 0, seed + 1) % (maxVal - minVal + 1) + minVal;
    }

    return array;
}

long* allocateAndInitializeLongArray(int size) {
    if (size <= 0) {
        fprintf(stderr, "Invalid size for long array.\n");
        return NULL;
    }

    long* array = (long*)malloc(size * sizeof(long));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for long array.\n");
        return NULL;
    }

    // Initialize with timestamps or any other logic
    for (int i = 0; i < size; ++i) {
        array[i] = time(NULL);
    }

    return array;
}

double* allocateAndInitializeDoubleArray(int size) {
    if (size <= 0) {
        fprintf(stderr, "Invalid size for double array.\n");
        return NULL;
    }

    double* array = (double*)malloc(size * sizeof(double));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for double array.\n");
        return NULL;
    }

    // Initialize with statistical analysis values or any other logic
    for (int i = 0; i < size; ++i) {
        array[i] = ((double)xorshift128plus(seed + 0, seed + 1)) / UINT_MAX;
    }

    return array;
}

Record* allocateAndInitializeRecordArray(int size, int minVal, int maxVal) {
    if (size <= 0 || minVal > maxVal) {
        fprintf(stderr, "Invalid size or value range.\n");
        return NULL;
    }

    Record* array = (Record*)malloc(size * sizeof(Record));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for record array.\n");
        return NULL;
    }

    unsigned long seed[2] = {time(NULL), time(NULL)};
    for (int i = 0; i < size; ++i) {
        array[i].value = xorshift128plus(seed + 0, seed + 1) % (maxVal - minVal + 1) + minVal;
    }

    return array;
}

void resizeArray(void** array, int* currentSize, int newSize, size_t elementSize) {
    if (newSize <= 0) {
        fprintf(stderr, "Invalid new size for array.\n");
        return;
    }

    void* newArray = realloc(*array, newSize * elementSize);
    if (!newArray && newSize != 0) {
        fprintf(stderr, "Memory allocation failed for resizing array.\n");
        return;
    }

    *array = newArray;
    *currentSize = newSize;
}
