#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_THREADS 10

typedef struct {
    char *filename;
    int count_chars;
    FILE *output_file;
    pthread_mutex_t lock;
} ThreadData;

void* process_file(void* arg) {
    ThreadData *data = (ThreadData *)arg;
    FILE *file = fopen(data->filename, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    char line[1024];
    long offset = 0;
    int total_lines = 0;

    while (fgets(line, sizeof(line), file)) {
        if (data->count_chars) {
            fprintf(data->output_file, "Line %ld: Length = %zu\n", ++total_lines, strlen(line));
        } else {
            fprintf(data->output_file, "Line %ld: %s", ++total_lines, line);
        }
        offset += strlen(line);
    }

    fclose(file);

    pthread_mutex_lock(&data->lock);
    // Simulate adding to a shared total_line_count
    static int shared_total_lines = 0;
    shared_total_lines += total_lines;
    pthread_mutex_unlock(&data->lock);

    printf("Processed %s with %d lines\n", data->filename, total_lines);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <options> <file1> [<file2> ...]\n", argv[0]);
        return 1;
    }

    ThreadData thread_data[MAX_THREADS];
    pthread_t threads[MAX_THREADS];
    int thread_count = 0;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--help") == 0) {
            printf("Options:\n");
            printf("--help\tDisplay usage information\n");
            printf("-c\tCount the number of characters per line\n");
            printf("-o <output_file>\tSpecify an output file for results\n");
            return 1;
        } else if (strcmp(argv[i], "-c") == 0) {
            // Handle -c option
            continue; // Placeholder for handling the option
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            // Handle -o <output_file> option
            if (i + 1 >= argc) {
                fprintf(stderr, "Output file not specified\n");
                return 1;
            }
            char *output_filename = argv[++i];
            FILE *output_file = fopen(output_filename, "w");
            if (!output_file) {
                perror("Error opening output file");
                return 1;
            }

            for (int j = 0; j < thread_count; ++j) {
                thread_data[j].output_file = output_file;
            }
        } else {
            if (thread_count >= MAX_THREADS) {
                fprintf(stderr, "Too many files. Max %d\n", MAX_THREADS);
                return 1;
            }

            ThreadData *data = &thread_data[thread_count];
            data->filename = argv[i];
            data->count_chars = 0; // Placeholder for handling the option
            pthread_mutex_init(&data->lock, NULL);

            if (pthread_create(&threads[thread_count], NULL, process_file, data) != 0) {
                perror("Error creating thread");
                return 1;
            }

            ++thread_count;
        }
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
        pthread_mutex_destroy(&thread_data[i].lock);
    }

    printf("Total lines processed: %d\n", shared_total_lines);

    return 0;
}
