package com.service.management;

import java.util.HashMap;
import java.util.Map;
import java.util.Random;

public class ServiceManager {
    private static final Random prng = new Random();
    private Map<String, ServiceConfig> serviceConfigs = new HashMap<>();

    public synchronized ServiceConfig getServiceConfig(String serviceId) {
        return serviceConfigs.getOrDefault(serviceId, new ServiceConfig());
    }

    public synchronized void updateServiceConfig(String serviceId, ServiceConfig updatedConfig) {
        serviceConfigs.put(serviceId, updatedConfig);
        applyResourceThresholds(prng.nextDouble(), updatedConfig);
    }

    public synchronized ServiceConfig deleteServiceConfig(String serviceId) {
        if (serviceConfigs.containsKey(serviceId)) {
            serviceConfigs.remove(serviceId);
        }
        return new ServiceConfig();
    }

    private void applyResourceThresholds(double loadFactor, ServiceConfig config) {
        // Adjust resource thresholds based on system load
        double cpuThreshold = 0.5 + loadFactor * 0.3;
        double memoryThreshold = 0.4 + loadFactor * 0.2;
        double networkLatencyThreshold = 100 + (int)(loadFactor * 50);

        config.setCpuThreshold(cpuThreshold);
        config.setMemoryThreshold(memoryThreshold);
        config.setNetworkLatencyThreshold(networkLatencyThreshold);
    }

    public static class ServiceConfig {
        private double cpuThreshold;
        private double memoryThreshold;
        private int networkLatencyThreshold;

        // Getters and setters for thresholds
        public double getCpuThreshold() {
            return cpuThreshold;
        }

        public void setCpuThreshold(double cpuThreshold) {
            this.cpuThreshold = cpuThreshold;
        }

        public double getMemoryThreshold() {
            return memoryThreshold;
        }

        public void setMemoryThreshold(double memoryThreshold) {
            this.memoryThreshold = memoryThreshold;
        }

        public int getNetworkLatencyThreshold() {
            return networkLatencyThreshold;
        }

        public void setNetworkLatencyThreshold(int networkLatencyThreshold) {
            this.networkLatencyThreshold = networkLatencyThreshold;
        }
    }
}
