#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define PRIME_NUMBER 101

typedef struct {
    int value;
    long id;
    double probability;
} Record;

void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_record(Record* record, int min_val, int max_val, long prime) {
    record->value = rand() % (max_val - min_val + 1) + min_val;
    record->id = (record->value * PRIME_NUMBER) % prime;
    record->probability = ((double)rand()) / RAND_MAX;
}

void* allocate_data(int data_type, size_t count) {
    void* ptr = custom_malloc(count * sizeof(Record));
    if (data_type == 'l') {
        long* long_ptr = custom_malloc(count * sizeof(long));
        for (size_t i = 0; i < count; ++i) {
            long_ptr[i] = rand() % PRIME_NUMBER;
        }
        return long_ptr;
    } else if (data_type == 'i') {
        int* int_ptr = custom_malloc(count * sizeof(int));
        for (size_t i = 0; i < count; ++i) {
            int_ptr[i] = rand();
        }
        return int_ptr;
    } else if (data_type == 'd') {
        double* double_ptr = custom_malloc(count * sizeof(double));
        for (size_t i = 0; i < count; ++i) {
            double_ptr[i] = ((double)rand()) / RAND_MAX;
        }
        return double_ptr;
    } else if (data_type == 'r') {
        Record* record_ptr = ptr;
        for (size_t i = 0; i < count; ++i) {
            initialize_record(&record_ptr[i], 1, 100, PRIME_NUMBER);
        }
        return ptr;
    } else {
        fprintf(stderr, "Invalid data type\n");
        exit(EXIT_FAILURE);
    }
}

void free_data(void* ptr, char data_type) {
    if (data_type == 'l' || data_type == 'i' || data_type == 'd') {
        free(ptr);
    } else if (data_type == 'r') {
        Record* record_ptr = ptr;
        for (size_t i = 0; i < sizeof(Record) / sizeof(int); ++i) {
            free(record_ptr + i);
        }
        free(ptr);
    }
}

int main() {
    srand(time(NULL));

    int count = 10;

    long* long_array = allocate_data('l', count);
    int* int_array = allocate_data('i', count);
    double* double_array = allocate_data('d', count);
    Record* record_array = allocate_data('r', count);

    // Use the arrays...

    free_data(long_array, 'l');
    free_data(int_array, 'i');
    free_data(double_array, 'd');
    free_data(record_array, 'r');

    return 0;
}
