#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long session_id;
    char *name;
    char *email;
} User;

typedef struct {
    time_t timestamp;
    double amount;
    char *description;
    User *user_profile;
} Transaction;

typedef struct {
    double probability;
    char *config_name;
    int timeout_duration;
} Config;

typedef struct {
    size_t allocated_size;
    size_t used_size;
    void *pool;
} MemoryPool;

void initialize_memory_pool(MemoryPool *pool, size_t initial_size) {
    pool->allocated_size = initial_size;
    pool->used_size = 0;
    pool->pool = malloc(initial_size);
}

void *allocate_from_pool(MemoryPool *pool, size_t size) {
    if (pool->used_size + size > pool->allocated_size) {
        // Handle out of memory scenario
        return NULL;
    }
    void *ptr = (char *)pool->pool + pool->used_size;
    pool->used_size += size;
    return ptr;
}

void generate_session_id(unsigned long *session_id) {
    static unsigned long counter = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    (*session_id)++;
    pthread_mutex_unlock(&mutex);
}

void log_memory_allocation(void *ptr, size_t size) {
    time_t now = time(NULL);
    printf("Allocated %zu bytes at %p, Time: %s", size, ptr, ctime(&now));
}

Config *allocate_config(MemoryPool *pool) {
    Config *config = allocate_from_pool(pool, sizeof(Config));
    if (config != NULL) {
        log_memory_allocation(config, sizeof(Config));
    }
    return config;
}

User *allocate_user(MemoryPool *pool, char *name, char *email, unsigned long session_id) {
    User *user = allocate_from_pool(pool, sizeof(User));
    if (user != NULL) {
        user->session_id = session_id;
        user->name = strdup(name);
        user->email = strdup(email);
        log_memory_allocation(user, sizeof(User));
    }
    return user;
}

Transaction *allocate_transaction(MemoryPool *pool, time_t timestamp, double amount, char *description, User *user) {
    Transaction *transaction = allocate_from_pool(pool, sizeof(Transaction));
    if (transaction != NULL) {
        transaction->timestamp = timestamp;
        transaction->amount = amount;
        transaction->description = strdup(description);
        transaction->user_profile = user;
        log_memory_allocation(transaction, sizeof(Transaction));
    }
    return transaction;
}

void free_all(MemoryPool *pool) {
    free(pool->pool);
}

int main() {
    MemoryPool pool;
    initialize_memory_pool(&pool, 1024 * 1024); // 1MB initial size

    Config *config = allocate_config(&pool);
    if (config != NULL) {
        config->probability = 0.5;
        strcpy(config->config_name, "DefaultConfig");
        config->timeout_duration = 60;

        unsigned long session_id;
        generate_session_id(&session_id);

        User *user = allocate_user(&pool, "John Doe", "john.doe@example.com", session_id);
        if (user != NULL) {
            Transaction *transaction = allocate_transaction(&pool, time(NULL), 100.0, "Payment made", user);
            if (transaction != NULL) {
                // Use the transaction
            }
        }

        free(user); // Manually free User and its strings
    }

    free_all(&pool);

    return 0;
}
```

