#include <time.h>
#include <openssl/rand.h>

#define MAX_SESSIONS 1024

typedef struct {
    double probability;
    char* name;
    int timeout;
    unsigned long token;
} config;

typedef struct {
    time_t timestamp;
    char* description;
    config* cfg;
    unsigned long token;
} event;

typedef unsigned long session_token;

session_token generate_session_token() {
    unsigned long token;
    while (!RAND_bytes((unsigned char*)&token, sizeof(token)));
    return token;
}

void allocate_and_initialize_memory(long num_configs, long num_events, long initial_size) {
    // Allocate memory
    long* long_array = (long*)malloc(initial_size * sizeof(long));
    if (long_array == NULL) {
        fprintf(stderr, "Failed to allocate memory for long array\n");
        return;
    }

    char** string_array = (char**)malloc(initial_size * sizeof(char*));
    if (string_array == NULL) {
        free(long_array);
        fprintf(stderr, "Failed to allocate memory for string array\n");
        return;
    }

    config* config_array = (config*)malloc(num_configs * sizeof(config));
    if (config_array == NULL) {
        free(long_array);
        free(string_array);
        fprintf(stderr, "Failed to allocate memory for config array\n");
        return;
    }

    event* event_array = (event*)malloc(num_events * sizeof(event));
    if (event_array == NULL) {
        free(long_array);
        free(string_array);
        free(config_array);
        fprintf(stderr, "Failed to allocate memory for event array\n");
        return;
    }

    session_token* session_array = (session_token*)malloc(initial_size * sizeof(session_token));
    if (session_array == NULL) {
        free(long_array);
        free(string_array);
        free(config_array);
        free(event_array);
        fprintf(stderr, "Failed to allocate memory for session array\n");
        return;
    }

    // Initialize structures
    for (long i = 0; i < num_configs; i++) {
        config_array[i].probability = rand() / (double)RAND_MAX;
        config_array[i].name = strdup("ConfigName");
        config_array[i].timeout = rand();
        config_array[i].token = generate_session_token();
    }

    for (long i = 0; i < num_events; i++) {
        event_array[i].timestamp = time(NULL);
        event_array[i].description = strdup("EventDescription");
        event_array[i].cfg = &config_array[rand() % num_configs];
        event_array[i].token = generate_session_token();
    }

    for (long i = 0; i < initial_size; i++) {
        session_array[i] = generate_session_token();
    }

    // Free allocated memory
    free(long_array);
    free(string_array);
    for (long i = 0; i < num_configs; i++) {
        free(config_array[i].name);
    }
    free(config_array);
    for (long i = 0; i < num_events; i++) {
        free(event_array[i].description);
    }
    free(event_array);
    free(session_array);
}
