import io.grpc.ManagedChannel;
import io.grpc.ManagedChannelBuilder;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class ResourceAllocator {
    private final ManagedChannel channel;
    private final ResourcePolicyServiceGrpc.ResourcePolicyServiceBlockingStub stub;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
    private AllocationProfile currentProfile;

    public ResourceAllocator(String host, int port) {
        this.channel = ManagedChannelBuilder.forAddress(host, port).usePlaintext().build();
        this.stub = ResourcePolicyServiceGrpc.newBlockingStub(channel);
    }

    public void readAllocationPolicy() {
        lock.readLock().lock();
        try {
            AllocationProfile profile = stub.getAllocationPolicy(ResourcePolicyRequest.getDefaultInstance());
            updateCurrentProfile(profile);
        } finally {
            lock.readLock().unlock();
        }
    }

    public void updateAllocationPolicy(AllocationProfile newProfile) {
        lock.writeLock().lock();
        try {
            stub.updateAllocationPolicy(ResourcePolicyUpdateRequest.newBuilder()
                    .setProfile(newProfile)
                    .build());
            updateCurrentProfile(newProfile);
        } finally {
            lock.writeLock().unlock();
        }
    }

    private void updateCurrentProfile(AllocationProfile profile) {
        this.currentProfile = profile;
    }

    public AllocationProfile getCurrentProfile() {
        lock.readLock().lock();
        try {
            return currentProfile;
        } finally {
            lock.readLock().unlock();
        }
    }

    public void monitorHealthAndAdjustPolicies() {
        // Implement health monitoring and policy adjustments logic here
    }
}
