// Define structures for transaction, account, and operation log
typedef struct {
    int id;
    long timestamp;
    int account_id;
} Transaction;

typedef struct {
    int number;
    char name[100];
    double balance;
} Account;

typedef struct {
    int id;
    long timestamp;
    char description[256];
    int transaction_id;
    int account_id;
} OperationLog;

// Function to dynamically allocate and initialize memory for the data structures
void manage_memory(size_t num_transactions, size_t num_accounts, size_t num_logs) {
    // Allocate memory for arrays
    Transaction* transactions = (Transaction*)malloc(num_transactions * sizeof(Transaction));
    Account* accounts = (Account*)malloc(num_accounts * sizeof(Account));
    OperationLog* logs = (OperationLog*)malloc(num_logs * sizeof(OperationLog));

    if (!transactions || !accounts || !logs) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Initialize arrays
    for (size_t i = 0; i < num_transactions; ++i) {
        transactions[i].id = i + 1;
        transactions[i].timestamp = time(NULL);
        transactions[i].account_id = rand() % num_accounts + 1;
    }

    for (size_t i = 0; i < num_accounts; ++i) {
        accounts[i].number = i + 1000;
        snprintf(accounts[i].name, sizeof(accounts[i].name), "Customer%d", i + 1);
        accounts[i].balance = 1000.0 * (i + 1);
    }

    for (size_t i = 0; i < num_logs; ++i) {
        logs[i].id = i + 1;
        logs[i].timestamp = time(NULL);
        snprintf(logs[i].description, sizeof(logs[i].description), "Log%d", i + 1);
        logs[i].transaction_id = rand() % num_transactions + 1;
        logs[i].account_id = rand() % num_accounts + 1;
    }

    // Free allocated memory
    free(transactions);
    free(accounts);
    free(logs);
}

int main() {
    size_t num_transactions = 1000;
    size_t num_accounts = 500;
    size_t num_logs = 2000;

    manage_memory(num_transactions, num_accounts, num_logs);

    return 0;
}
