    if (num_configs == 0) {
        fprintf(stderr, "Error: Number of configurations must be greater than zero.\n");
        return NULL;
    }

    srand(time(NULL) + getpid() * get_nprocs_conf());

    long* long_array = malloc(num_configs * sizeof(long));
    char** string_array = malloc(num_configs * sizeof(char*));
    config* config_array = malloc(num_configs * sizeof(config));

    if (long_array == NULL || string_array == NULL || config_array == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for data structures.\n");
        free(long_array);
        free(string_array);
        free(config_array);
        return NULL;
    }

    for (size_t i = 0; i < num_configs; ++i) {
        long_array[i] = rand();
        string_array[i] = malloc(256 * sizeof(char));
        if (string_array[i] == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for string array.\n");
            for (size_t j = 0; j < i; ++j) {
                free(string_array[j]);
            }
            free(long_array);
            free(string_array);
            free(config_array);
