        config_array[i].name = string_array[i];

        // Log memory allocation details
        fprintf(log_file, "Allocated long: %ld at address %p\n", long_array[i], (void*)&long_array[i]);
        fprintf(log_file, "Allocated string: %s at address %p\n", string_array[i], (void*)string_array[i]);
