['```java
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class SystemMonitor {
    private Map<String, Map<String, Object>> profiles;
    private Lock readLock;
    private Lock writeLock;

    public SystemMonitor() {
        this.profiles = new HashMap<>();
        this.readLock = new ReentrantReadWriteLock().readLock();
        this.writeLock = new ReentrantReadWriteLock().writeLock();
    }

    public Map<String, Object> updateProfile(String profileId, Map<String, Object> updatedData) {
        writeLock.lock();
        try {
            profiles.put(profileId, updatedData);
            return profiles.get(profileId);
        } finally {
            writeLock.unlock();
        }
    }

    public Map<String, Object> deleteProfile(String profileId) {
        writeLock.lock();
        try {
            Map<String, Object> defaultProfile = new HashMap<>();
            // Set default values for the deleted profile
            defaultProfile.put("monitoringInterval", 60);
            defaultProfile.put("alertThreshold", 80);
            profiles.remove(profileId);
            return defaultProfile;
        } finally {
            writeLock.unlock();
        }
    }

    public Map<String, Object> getProfile(String profileId) {
        readLock.lock();
        try {
            return profiles.getOrDefault(profileId, new HashMap<>());
        } finally {
            readLock.unlock();
        }
    }
}
