// Function to initialize arrays with timestamps and random strings
int initialize_arrays(long start_timestamp, size_t array_size, long **timestamps, char ***descriptions) {
    if (array_size == 0 || start_timestamp == 0 || !timestamps || !descriptions) return -1;

    *timestamps = (long *)malloc(array_size * sizeof(long));
    *descriptions = (char **)malloc(array_size * sizeof(char *));

    if (!*timestamps || !*descriptions) {
        free(*timestamps);
        free(*descriptions);
        return -2;
    }

    srand(time(NULL)); // Seed the PRNG

    for (size_t i = 0; i < array_size; ++i) {
        (*timestamps)[i] = start_timestamp + i * 86400L; // One day in seconds
        size_t str_len = rand() % 129; // Random length up to 128 characters
        (*descriptions)[i] = (char *)malloc((str_len + 1) * sizeof(char));

        if (!(*descriptions)[i]) {
            for (size_t j = 0; j < i; ++j) free((*descriptions)[j]);
            free(*timestamps);
            free(*descriptions);
            return -2;
        }

        for (size_t j = 0; j < str_len; ++j) (*descriptions)[i][j] = random_ascii();
        (*descriptions)[i][str_len] = '\0';
    }

    return 0;
}

