typedef struct {
    long offset;
    int key;
    int value;
} record;

int allocate_records(record **array, size_t num_records) {
    if (num_records == 0) {
        *array = NULL;
        return 0;
    }

    *array = (record *)calloc(num_records, sizeof(record));
    if (*array == NULL) {
        return -1; // Memory allocation failed
    }

    if (!RAND_status()) {
        fprintf(stderr, "PRNG not seeded with sufficient randomness.\n");
        free(*array);
        *array = NULL;
        return -2;
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*array)[i].offset = (long)RAND_int64();
        (*array)[i].key = RAND_int32();
        (*array)[i].value = RAND_int32();
    }

    return (int)num_records;
}

void free_records(record *array, size_t num_records) {
    if (array != NULL && num_records > 0) {
        free(array);
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator for non-crypto purposes
    RAND_add(&time(NULL), sizeof(time_t), 1); // Add time to PRNG entropy pool

    size_t num_records = 1000;
    record *records = NULL;

    int allocated = allocate_records(&records, num_records);
    if (allocated == -1) {
        printf("Failed to allocate memory for records.\n");
        return 1;
    } else if (allocated == -2) {
        printf("PRNG not seeded with sufficient randomness, no records generated.\n");
        return 1;
    }

    printf("Successfully allocated %d records.\n", allocated);

    // Use the records array...

    free_records(records, num_records);
    printf("Records freed.\n");

    return 0;
}
