// Define a structure to hold records
typedef struct {
    int key;
    unsigned long long random_number;
} record;

// Custom pseudo-random number generator (PRNG)
unsigned long long prng(unsigned long long seed) {
    return seed * 6364136223846793005ULL + 1; // XORShift PRNG
}

// Function to initialize and populate the arrays
void init_and_populate(int long_size, int int_size, unsigned long long random_seed, record **records) {
    if (long_size <= 0 || int_size <= 0) {
        fprintf(stderr, "Invalid size input\n");
        return;
    }

    // Allocate memory for the arrays
    long *offsets = malloc(long_size * sizeof(*offsets));
    int *keys = malloc(int_size * sizeof(*keys));
    unsigned long long *random_numbers = malloc(int_size * sizeof(*random_numbers));
    record *records_arr = realloc(NULL, int_size * sizeof(record)); // Realloc can be used to allocate new memory without copying existing content

    if (!offsets || !keys || !random_numbers || !records_arr) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize the arrays
    for (int i = 0; i < long_size; i++) {
        offsets[i] = i * 10000; // Example initialization logic
    }
    for (int i = 0; i < int_size; i++) {
        keys[i] = prng(random_seed + i); // Initialize key using PRNG
        random_numbers[i] = prng(random_seed + i * 2); // Initialize random number using PRNG
    }

    // Populate the record array
    for (int i = 0; i < int_size; i++) {
        records_arr[i].key = keys[i];
        records_arr[i].random_number = random_numbers[i];
    }

    // Assign the populated arrays to the output parameter
    *records = records_arr;

    // Free the temporary arrays
    free(offsets);
    free(keys);
    free(random_numbers);
}

int main() {
    int long_size = 10;
    int int_size = 5;
    unsigned long long random_seed = 123456789;
    record *records;

    init_and_populate(long_size, int_size, random_seed, &records);

    // Print the records to verify
    for (int i = 0; i < int_size; i++) {
        printf("Key: %d, Random Number: %llu\n", records[i].key, records[i].random_number);
    }

    free(records); // Free the allocated memory

    return 0;
}
