unsigned long hash_function(int value, size_t index) {
    return (unsigned long)value * index;
}

void* allocate_and_initialize(size_t num_elements, unsigned long seed, size_t *max_memory_usage, size_t initial_size) {
    if (!RAND_bytes((unsigned char*)&seed, sizeof(seed))) {
        fprintf(stderr, "Error seeding CSPRNG\n");
        exit(EXIT_FAILURE);
    }

    long *offsets = malloc(initial_size * sizeof(long));
    int *keys = malloc(initial_size * sizeof(int));
    Record *records = malloc(initial_size * sizeof(Record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        exit(EXIT_FAILURE);
    }

    size_t current_size = initial_size;
    for (size_t i = 0; i < num_elements; ++i) {
        if (i >= current_size) {
            current_size *= 2;
            offsets = realloc(offsets, current_size * sizeof(long));
            keys = realloc(keys, current_size * sizeof(int));
            records = realloc(records, current_size * sizeof(Record));

            if (!offsets || !keys || !records) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(offsets);
                free(keys);
                free(records);
                exit(EXIT_FAILURE);
            }

            *max_memory_usage = (current_size * sizeof(long)) + (current_size * sizeof(int)) + (current_size * sizeof(Record));
        }

        offsets[i] = i * 10; // Example offset calculation
        keys[i] = hash_function(rand(), i); // Example key calculation

        if (!RAND_bytes((unsigned char*)&records[i].value, sizeof(records[i].value))) {
            fprintf(stderr, "Error generating random number\n");
            free(offsets);
            free(keys);
            free(records);
            exit(EXIT_FAILURE);
        }
    }

    *max_memory_usage = (current_size * sizeof(long)) + (current_size * sizeof(int)) + (current_size * sizeof(Record));
    return records;
}

int main() {
    size_t num_elements = 1000000; // Example number of elements
    unsigned long seed = 0; // Example seed
    size_t max_memory_usage;

    Record *records = allocate_and_initialize(num_elements, seed, &max_memory_usage, 1024);

    printf("Max Memory Usage: %zu bytes\n", max_memory_usage);
    free(records);

    return 0;
}
```

