long *offsets;
int *keys;
record *records;

void allocate_and_initialize(long offsets_size, int keys_size) {
    offsets = (long *)malloc(offsets_size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        exit(EXIT_FAILURE);
    }

    keys = (int *)malloc(keys_size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    records = (record *)aligned_alloc(16, records_size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Failed to allocate aligned memory for records\n");
        free(keys);
        free(offsets);
        exit(EXIT_FAILURE);
    }
}

void initialize_records(int records_size, int range_min, int range_max) {
    srand(time(NULL));
    for (int i = 0; i < records_size; i++) {
        records[i].value = rand() % (range_max - range_min + 1) + range_min;
    }
}

void free_memory() {
    free(records);
    free(keys);
    free(offsets);
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <offsets_size> <keys_size> <records_size>\n", argv[0]);
        return EXIT_FAILURE;
