        sessions[i].timestamp = time(NULL);
        sessions[i].sessionId = rand(); // Generate a pseudo-random session ID
        strncpy(sessions[i].sessionData, DEFAULT_SESSION_DATA, SESSION_DATA_SIZE);
        sessions[i].sessionData[SESSION_DATA_SIZE - 1] = '\0'; // Ensure null-termination
    }

    return sessions;
}

void freeSessions(Session* sessions, int numSessions) {
    if (sessions) {
        free(sessions);
    }
}

