int filter_transactions(long* offsets, int* keys, record* records, int* max_weighted_sum, int* max_id) {
    *max_weighted_sum = 0;
    *max_id = -1;

    for (int i = 0; i < MAX_RECORDS; i++) {
        // Example filter criteria: transaction age less than 5 seconds
        if ((time(NULL) - offsets[i]) < 5) {
            int weighted_sum = keys[i] + records[i].value;
            if (weighted_sum > *max_weighted_sum) {
                *max_weighted_sum = weighted_sum;
                *max_id = i;
            }
        }
    }

    return *max_id;
}

