#include <string.h>
#include <time.h>

#define NUM_SESSIONS 1000

typedef struct {
    unsigned int id;
    char token[16];
} session;

void generate_random_token(char *token) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (int i = 0; i < 15; i++) {
        token[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    token[15] = '\0';
}

void populate_sessions(session *sessions, unsigned int num_sessions) {
    srand(time(NULL));
    for (unsigned int i = 0; i < num_sessions; i++) {
        sessions[i].id = rand();
        generate_random_token(sessions[i].token);
    }
}

void print_sessions(const session *sessions, unsigned int num_sessions) {
    for (unsigned int i = 0; i < num_sessions; i++) {
        printf("Session ID: %u, Token: %s\n", sessions[i].id, sessions[i].token);
    }
}

int main() {
    session *sessions = malloc(num_sessions * sizeof(session));
    if (!sessions) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    populate_sessions(sessions, num_sessions);

    print_sessions(sessions, num_sessions);

    free(sessions);
    return 0;
}
