#define MAX_SESSION_DATA_SIZE 1024

typedef struct {
    long timestamp;
    int session_id;
    char session_data[MAX_SESSION_DATA_SIZE];
} Session;

Session* create_sessions(int initial_size, int *error_code) {
    if (initial_size <= 0) {
        *error_code = -1; // Invalid size
        return NULL;
    }

    Session *sessions = malloc(initial_size * sizeof(Session));
    if (sessions == NULL) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG with current time

    for (int i = 0; i < initial_size; ++i) {
        sessions[i].timestamp = time(NULL);
        sessions[i].session_id = rand(); // Generate a pseudo-random session ID
        snprintf(sessions[i].session_data, MAX_SESSION_DATA_SIZE, "Default Data");
    }

    *error_code = 0; // Success
    return sessions;
}

int resize_sessions(Session **sessions_ptr, int current_size, int new_size, int *error_code) {
    if (new_size <= current_size) {
        *error_code = -3; // New size must be greater than current size
        return -1;
    }

    Session *new_sessions = realloc(*sessions_ptr, new_size * sizeof(Session));
    if (new_sessions == NULL) {
        *error_code = -2; // Memory allocation failed
        return -1;
    }

    srand(time(NULL)); // Seed the PRNG with current time

    for (int i = current_size; i < new_size; ++i) {
        new_sessions[i].timestamp = time(NULL);
        new_sessions[i].session_id = rand(); // Generate a pseudo-random session ID
        snprintf(new_sessions[i].session_data, MAX_SESSION_DATA_SIZE, "Default Data");
    }

    *sessions_ptr = new_sessions;
    *error_code = 0; // Success
    return 0;
}

void free_sessions(Session **sessions_ptr) {
    if (*sessions_ptr != NULL) {
        free(*sessions_ptr);
        *sessions_ptr = NULL;
    }
}
