#include <stdlib.h>
#include <time.h>

// Define structures for device, firmware, and event
typedef struct Device {
    int id;
} Device;

typedef struct Firmware {
    char version[20];
    time_t build_date;
    Device *device;
} Firmware;

typedef struct Event {
    time_t timestamp;
    char description[100];
    int severity;
    Firmware *firmware;
} Event;

// Function to generate a unique device ID using a PRNG
int generate_device_id() {
    // Initialize random seed if not already done
    static int seeded = 0;
    if (!seeded) {
        srand(time(NULL));
        seeded = 1;
    }
    return rand();
}

// Function to create and initialize a list of devices
Device** create_devices(int count) {
    Device **devices = (Device**)malloc(count * sizeof(Device*));
    for (int i = 0; i < count; i++) {
        devices[i] = (Device*)malloc(sizeof(Device));
        devices[i]->id = generate_device_id();
    }
    return devices;
}

// Function to create and initialize an array of firmware versions
Firmware** create_firmware(int count, Device **devices) {
    Firmware **firmwares = (Firmware**)malloc(count * sizeof(Firmware*));
    for (int i = 0; i < count; i++) {
        firmwares[i] = (Firmware*)malloc(sizeof(Firmware));
        snprintf(firmwares[i]->version, 20, "V%d.%d", rand() % 10, rand() % 10);
        firmwares[i]->build_date = time(NULL) - (rand() % 365 * 86400);
        firmwares[i]->device = devices[rand() % count];
    }
    return firmwares;
}

// Function to create and initialize a collection of event logs
Event** create_events(int count, Firmware **firmwares) {
    Event **events = (Event**)malloc(count * sizeof(Event*));
    for (int i = 0; i < count; i++) {
        events[i] = (Event*)malloc(sizeof(Event));
        events[i]->timestamp = time(NULL);
        snprintf(events[i]->description, 100, "Event %d", i);
        events[i]->severity = rand() % 5;
        events[i]->firmware = firmwares[rand() % count];
    }
    return events;
}

// Function to free dynamically allocated memory
void free_memory(Device **devices, int device_count, Firmware **firmwares, int firmware_count, Event **events, int event_count) {
    for (int i = 0; i < device_count; i++) {
        free(devices[i]);
    }
    free(devices);

    for (int i = 0; i < firmware_count; i++) {
        free(firmwares[i]);
    }
    free(firmwares);

    for (int i = 0; i < event_count; i++) {
        free(events[i]);
    }
    free(events);
}
