}

KeyStruct* create_key_array(size_t size) {
    KeyStruct* keys = malloc(size * sizeof(KeyStruct));
    if (!keys) {
        perror("Failed to allocate memory for key array");
        free(create_offset_array(size)); // Clean up on failure
        return NULL;
    }
    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < size; ++i) {
        keys[i].key = rand() % (RAND_MAX + 1);
