#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int identifier;
} Event;

void* allocate_resource(size_t size, const char* resource_type) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Failed to allocate memory for %s\n", resource_type);
    } else {
        fprintf(stdout, "Successfully allocated memory for %s\n", resource_type);
    }
    return ptr;
}

void init_array(void** array, size_t* size, size_t element_size, const char* resource_type) {
    *array = allocate_resource(*size * element_size, resource_type);
    if (*array != NULL) {
        memset(*array, 0, *size * element_size);
    }
}

long* allocate_long_array(size_t* size, const char* resource_type) {
    init_array((void**)size, size, sizeof(long), resource_type);
    return (long*)*array;
}

char** allocate_char_array(size_t* size, const char* resource_type) {
    init_array((void**)size, size, sizeof(char), resource_type);
    return (char**)*array;
}

Event* allocate_event_array(size_t* size, const char* resource_type) {
    init_array((void**)size, size, sizeof(Event), resource_type);
    return (Event*)*array;
}

void seed_prng(unsigned long seed) {
    srand(seed);
}

unsigned long generate_prng_number() {
    return rand();
}

unsigned long generate_csprng_number(size_t performance_settings) {
    // Simulate CSPRNG with configurable performance
    static unsigned long state = time(NULL);
    for (size_t i = 0; i < performance_settings; i++) {
        state = (state * 1664525 + 1013904223) % 4294967296;
    }
    return state;
}

void* allocate_memory_block(size_t size, const char* resource_type, int use_csprng, size_t csprng_performance_settings) {
    void* ptr = NULL;
    if (use_csprng) {
        seed_prng(generate_csprng_number(csprng_performance_settings));
        ptr = allocate_resource(size, resource_type);
    } else {
        seed_prng(time(NULL));
        ptr = allocate_resource(size, resource_type);
    }
    return ptr;
}

int main() {
    size_t array_size = 10;
    long* long_array = allocate_long_array(&array_size, "long array");
    char** char_array = allocate_char_array(&array_size, "char array");
    Event* event_array = allocate_event_array(&array_size, "event array");

    unsigned long prng_number = generate_prng_number();
    printf("PRNG number: %lu\n", prng_number);

    unsigned long csprng_number = generate_csprng_number(10);
    printf("CSPRNG number with performance settings 10: %lu\n", csprng_number);

