#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CONFIG_MAX_SIZE 1000

typedef struct {
    double probability;
    char* name;
} Config;

double prng(double seed) {
    // Custom pseudo-random number generator implementation
    return (seed * 3.141592653589793 + 2.718281828459045) / (seed + 1.0);
}

Config* init_config_array(int* size, int initial_size, double entropy_source) {
    Config* config_array = (Config*)malloc(initial_size * sizeof(Config));
    if (!config_array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < initial_size; ++i) {
        config_array[i].probability = prng(entropy_source);
        config_array[i].name = (char*)malloc(256 * sizeof(char));
        if (!config_array[i].name) {
            fprintf(stderr, "Memory allocation failed for config name\n");
            // Clean up previously allocated memory
            for (int j = 0; j < i; ++j) free(config_array[j].name);
            free(config_array);
            return NULL;
        }
        snprintf(config_array[i].name, 256, "config_%d", i);
    }

    *size = initial_size;
    return config_array;
}

void* resize_config_array(Config** config_ptr, int* size, double entropy_source) {
    *size *= 2; // Double the size for simplicity
    Config* new_config_array = (Config*)realloc(*config_ptr, *size * sizeof(Config));
    if (!new_config_array) {
        fprintf(stderr, "Memory reallocation failed\n");
        return NULL;
    }

    *config_ptr = new_config_array;

    int old_size = *size / 2;
    for (int i = old_size; i < *size; ++i) {
        (*config_ptr)[i].probability = prng(entropy_source);
        (*config_ptr)[i].name = (char*)malloc(256 * sizeof(char));
        if (!(*config_ptr)[i].name) {
            fprintf(stderr, "Memory allocation failed for config name\n");
            // Clean up previously allocated memory
            for (int j = old_size; j < i; ++j) free((*config_ptr)[j].name);
            return NULL;
        }
        snprintf((*config_ptr)[i].name, 256, "config_%d", i);
    }

    return *config_ptr;
}

// Example usage and testing
int main() {
    int size = 0;
    Config* config_array = init_config_array(&size, 10, 42.0);

    if (config_array) {
        printf("Initial array size: %d\n", size);
        for (int i = 0; i < size; ++i) {
            printf("Config %d: Probability = %.2f, Name = %s\n", i, config_array[i].probability, config_array[i].name);
            free(config_array[i].name);
        }
        free(config_array);
    }

    // Example resizing
    Config* new_config_array = resize_config_array(&config_array, &size, 98.0);

    if (new_config_array) {
        printf("Resized array size: %d\n", size);
        for (int i = 10; i < size; ++i) {
            printf("Config %d: Probability = %.2f, Name = %s\n", i, new_config_array[i].probability, new_config_array[i].name);
            free(new_config_array[i].name);
        }
        free(new_config_array);
    }

    return 0;
}
