    session* sessions = (session*)malloc(initial_size * sizeof(session));
    if (!sessions) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Initialize each session with a unique ID and default values
    for (size_t i = 0; i < initial_size; ++i) {
        sessions[i].id = rand();
        sessions[i].name = NULL;
        sessions[i].duration = 0.0;
    }

    // Set up logging if requested
    if (log_file != NULL) {
        *log_file = fopen("session_log.txt", "w");
        if (*log_file == NULL) {
            fprintf(stderr, "Failed to open log file for writing.\n");
            free(sessions);
            return NULL;
        }
    }

    // Log session creation details
    if (log_file != NULL && *log_file != NULL) {
        time_t start_time = time(NULL);
        fprintf(*log_file, "Session array created at %s", ctime(&start_time));
        fprintf(*log_file, "Initial size: %zu\n", initial_size);
        fprintf(*log_file, "Max size: %zu\n", max_size);
    }

    return sessions;
}

