    // Free memory for each session
    for (size_t i = 0; sessions[i].name != NULL; ++i) {
        free(sessions[i].name);
    }

    // Free the session array
    free(sessions);

    // Log session destruction details if logging is enabled
    if (log_file != NULL && *log_file != NULL) {
        time_t end_time = time(NULL);
        fprintf(log_file, "Session array destroyed at %s", ctime(&end_time));
        fclose(log_file);
