#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    char* id;
} record;

unsigned long fastPRNG(unsigned long seed) {
    return seed * 1664525 + 1013904223;
}

record* initializeRecords(int numRecords, int keyRangeMin, int keyRangeMax, unsigned long initialSeed) {
    if (numRecords <= 0 || keyRangeMin > keyRangeMax) {
        return NULL;
    }

    record* records = (record*)malloc(numRecords * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return NULL;
    }

    unsigned long seed = initialSeed;

    for (int i = 0; i < numRecords; ++i) {
        records[i].value = keyRangeMin + fastPRNG(seed) % (keyRangeMax - keyRangeMin + 1);
        seed = fastPRNG(seed);

        int idLength = 5 + rand() % 6;
        records[i].id = (char*)malloc(idLength * sizeof(char));
        if (!records[i].id) {
            fprintf(stderr, "Memory allocation failed for record ID\n");
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(records[j].id);
            }
            free(records);
            return NULL;
        }

        for (int j = 0; j < idLength - 1; ++j) {
            records[i].id[j] = 'a' + rand() % ('z' - 'a' + 1);
        }
        records[i].id[idLength - 1] = '\0';
    }

    return records;
}

void freeRecords(record* records, int numRecords) {
    for (int i = 0; i < numRecords; ++i) {
        free(records[i].id);
    }
    free(records);
}
```

### Explanation:
- **fastPRNG**: A simple linear congruential generator (LCG) used for generating pseudo-random numbers. It's not suitable for cryptographic purposes but is fast and efficient.
- **initializeRecords**: Initializes an array of `record` structures with random integer values within a specified range and unique string identifiers.
  - **Memory Allocation**: Allocates memory for the records and their IDs.
  - **Random Number Generation**: Uses a non-cryptographic PRNG to generate random numbers.
  - **Error Handling**: Checks for successful memory allocation and handles errors gracefully.
- **freeRecords**: Frees all dynamically allocated memory associated with the `record` structures.

This code provides a basic implementation that meets the specified requirements. For production use, consider using a more secure random number generator if cryptographic security is necessary.']

