        return NULL;
    }

    Config *config_pool = malloc(10 * record_count * sizeof(Config));
    if (config_pool == NULL) {
        free(long_array);
        free(char_array);
        fprintf(stderr, "Memory allocation failed for config pool\n");
        return NULL;
    }

    Record *record_array = malloc(record_count * sizeof(Record));
    if (record_array == NULL) {
        free(long_array);
        free(char_array);
        free(config_pool);
        fprintf(stderr, "Memory allocation failed for record array\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < record_count; i++) {
