            fprintf(stderr, "Memory allocation failed for char string\n");
            return NULL;
        }
        record_array[i].value = rand() % (max_value - min_value + 1) + min_value;

        config_pool[i].probability = ((double)rand()) / RAND_MAX;
        config_pool[i].name = malloc(256 * sizeof(char)); // Assuming maximum name length is 255
        if (config_pool[i].name == NULL) {
            free(long_array);
            for (int j = 0; j < i; j++) {
                free(char_array[j]);
            }
            free(char_array);
            free(config_pool + i * sizeof(Config)); // Free previously allocated configs
            free(record_array);
            fprintf(stderr, "Memory allocation failed for config name\n");
            return NULL;
        }
    }

    void* result = malloc(sizeof(void*) * 4);
    if (result == NULL) {
        free(long_array);
        for (int i = 0; i < record_count; i++) {
            free(char_array[i]);
            free(config_pool[i].name);
        }
        free(char_array);
        free(config_pool);
        free(record_array);
        fprintf(stderr, "Memory allocation failed for result pointer\n");
        return NULL;
    }

    ((void**)result)[0] = long_array;
    ((void**)result)[1] = char_array;
    ((void**)result)[2] = config_pool;
    ((void**)result)[3] = record_array;

    return result;
}

int main() {
