uint32_t hash_function(const void* key, size_t len) {
    // Simple hash function for demonstration purposes
    uint32_t hash = 5381;
    const char* str = (const char*)key;
    while (*str) {
        hash = ((hash << 5) + hash) + *str++;
    }
    return hash % len;
}

void* safe_malloc(size_t size, void** ptr) {
    *ptr = malloc(size);
    if (!*ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return *ptr;
}

void manage_memory() {
    size_t size = INITIAL_SIZE;
    long* offsets = (long*)safe_malloc(size * sizeof(long), NULL);
    int* keys = (int*)safe_malloc(size * sizeof(int), NULL);
    Record* records = (Record*)safe_malloc(size * sizeof(Record), NULL);

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand();
        keys[i] = rand();
        records[i].value = rand();

        // Example of using a CSPRNG (e.g., OpenSSL's RAND_bytes)
        unsigned char buffer[4];
        if (!RAND_bytes(buffer, sizeof(buffer))) {
            fprintf(stderr, "Failed to generate random bytes\n");
            exit(EXIT_FAILURE);
        }
        records[i].value = *(int*)buffer;
    }

    // Example of using a hash function
    for (size_t i = 0; i < size; ++i) {
        uint32_t id = hash_function(&records[i], sizeof(Record));
        printf("Record %zu ID: %u\n", i, id);
    }

    free(offsets);
    free(keys);
    free(records);
}
