void generateDataRecords(long* timestamps, int* statuses, DataRecord** data, size_t num_records, unsigned long seed) {
    if (num_records > MAX_MEMORY_USAGE / sizeof(DataRecord)) {
        fprintf(stderr, "Too many records requested. Adjusting to fit memory constraints.\n");
        num_records = MAX_MEMORY_USAGE / sizeof(DataRecord);
    }

    *data = malloc(num_records * sizeof(DataRecord));
    if (*data == NULL) {
        perror("Memory allocation failed");
        return;
    }

    srand(seed);

    for (size_t i = 0; i < num_records; ++i) {
        timestamps[i] = time(NULL);
        statuses[i] = rand() % 100;

        (*data)[i].value = ((float)rand()) / RAND_MAX * 2.0f - 1.0f;
        (*data)[i].label = malloc(32 * sizeof(char));
        if ((*data)[i].label == NULL) {
            perror("Memory allocation failed for label");
            return;
        }
        snprintf((*data)[i].label, 32, "Record %zu", i);
    }

    // Simulate hash function based on value, index, and timestamp
    for (size_t i = 0; i < num_records; ++i) {
        size_t hash = (*data)[i].value * 1000 + i * 100 + timestamps[i];
        printf("Record %zu: Value %.2f, Label %s, Hash %zu\n", i, (*data)[i].value, (*data)[i].label, hash);
    }
}

void freeDataRecords(size_t num_records, DataRecord* data) {
    for (size_t i = 0; i < num_records; ++i) {
        free(data[i].label);
    }
    free(data);
}

int main() {
    long timestamps[10];
    int statuses[10];
    DataRecord* data;

    generateDataRecords(timestamps, statuses, &data, 10, time(NULL));

    freeDataRecords(10, data);

    return 0;
}
