import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.List;

public class UserProfileInitializer {

    private static final SecureRandom CSPRNG = new SecureRandom();
    private static final String USERNAME_PREFIX = "user_";
    private static final int MAX_COLLECTION_SIZE = 1000;
    private static final double MEMORY_THRESHOLD = 0.8;

    public List<UserProfile> initializeUserProfiles(int targetSize) {
        List<UserProfile> userProfiles = new ArrayList<>();
        long availableMemory = Runtime.getRuntime().freeMemory();

        while (userProfiles.size() < targetSize && availableMemory > MAX_COLLECTION_SIZE * 1024 * 1024) {
            try {
                long uniqueIdentifier = CSPRNG.nextLong();
                String username = USERNAME_PREFIX + hash(uniqueIdentifier);
                userProfiles.add(new UserProfile(uniqueIdentifier, username));
                availableMemory = Runtime.getRuntime().freeMemory();
            } catch (OutOfMemoryError e) {
                if (userProfiles.size() == 0) {
                    throw new RuntimeException("Initialization failed due to insufficient memory.");
                }
                reduceCollectionSize(userProfiles);
                availableMemory = Runtime.getRuntime().freeMemory();
            }
        }

        return userProfiles;
    }

    private String hash(long uniqueIdentifier) {
        // Simple hash function for demonstration
        return Long.toString(uniqueIdentifier).hashCode() % 1000 + "";
    }

    private void reduceCollectionSize(List<UserProfile> userProfiles) {
        int sizeToReduce = (int) (userProfiles.size() * 0.2);
        if (sizeToReduce > 0) {
            userProfiles.remove(userProfiles.size() - sizeToReduce);
        }
    }

    static class UserProfile {
        private long uniqueIdentifier;
        private String username;

        public UserProfile(long uniqueIdentifier, String username) {
            this.uniqueIdentifier = uniqueIdentifier;
            this.username = username;
        }

        // Getters and setters
    }
}
