typedef struct {
    double probability;
    char* name;
} Config;

// Function to initialize a new transaction
Transaction* createTransaction(long id, int amount, const char* description) {
    Transaction* trans = (Transaction*)malloc(sizeof(Transaction));
    if (trans == NULL) return NULL;
    trans->id = id;
    trans->amount = amount;
    strncpy(trans->description, description, 100);
    trans->timestamp = time(NULL);
    return trans;
}

// Function to initialize a new config
Config* createConfig(double probability, const char* name) {
    Config* conf = (Config*)malloc(sizeof(Config));
    if (conf == NULL) return NULL;
    conf->probability = probability;
    conf->name = strdup(name); // Allocate memory for the string
    if (conf->name == NULL) {
        free(conf);
        return NULL;
    }
    return conf;
}

// Function to add transaction to a dynamic array
Transaction** addToTransactions(Transaction** transactions, int* count, Transaction* trans) {
    *count += 1;
    Transaction** newTransactions = (Transaction**)realloc(transactions, (*count) * sizeof(Transaction*));
    if (newTransactions == NULL) {
        free(trans);
        return NULL;
    }
    newTransactions[*count - 1] = trans;
    transactions = newTransactions;
    return transactions;
}

// Function to add config to a dynamic array
Config** addToConfigs(Config** configs, int* count, Config* conf) {
    *count += 1;
    Config** newConfigs = (Config**)realloc(configs, (*count) * sizeof(Config*));
    if (newConfigs == NULL) {
        free(conf);
        return NULL;
    }
    newConfigs[*count - 1] = conf;
    configs = newConfigs;
    return configs;
}

