#include <stdlib.h>
#include <time.h>

typedef struct device {
    unsigned long id;
} Device;

typedef struct firmware {
    char version[20];
    time_t build_date;
    Device* device;
} Firmware;

typedef struct event_log {
    time_t timestamp;
    char description[100];
    int severity;
    Firmware* firmware;
} EventLog;

typedef struct memory_pool {
    void* start;
    size_t size;
    size_t used;
} MemoryPool;

Device* create_device(MemoryPool* pool) {
    Device* dev = (Device*)memory_alloc(pool, sizeof(Device));
    if (dev == NULL) return NULL;
    dev->id = prng_next();
    return dev;
}

Firmware* create_firmware(MemoryPool* pool, const char* version, time_t build_date, Device* device) {
    Firmware* fw = (Firmware*)memory_alloc(pool, sizeof(Firmware));
    if (fw == NULL) return NULL;
    strcpy(fw->version, version);
    fw->build_date = build_date;
    fw->device = device;
    return fw;
}

EventLog* create_event_log(MemoryPool* pool, time_t timestamp, const char* description, int severity, Firmware* firmware) {
    EventLog* log = (EventLog*)memory_alloc(pool, sizeof(EventLog));
    if (log == NULL) return NULL;
    log->timestamp = timestamp;
    strcpy(log->description, description);
    log->severity = severity;
    log->firmware = firmware;
    return log;
}

void memory_pool_init(MemoryPool* pool, void* start, size_t size) {
    pool->start = start;
    pool->size = size;
    pool->used = 0;
}

void* memory_alloc(MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->size) return NULL;
    void* ptr = (char*)pool->start + pool->used;
    pool->used += size;
    return ptr;
}

unsigned long prng_next() {
    static unsigned long seed = time(NULL);
    seed = seed * 1664525 + 1013904223;
    return seed % 1000000000; // Adjust range as needed
}
