        (*keys)[i] = rand() % 1000;          // Example initialization
        (*records)[i].value = rand() % 1000;   // Populate record with random int value
    }

    return 0;  // Success
}

void free_arrays(long *offsets, int *keys, record *records) {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
