#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define record structure
typedef struct {
    int integer_value;
    double float_value;
    char string[129];
    char *unique_id;
} Record;

// Function to generate random integers within a specified range
int generate_random_int(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to generate a random floating-point number from a normal distribution
double generate_normal_double(double mean, double std_dev) {
    // Implementation of Box-Muller transform
    static double next = 0.0;
    double u1, u2, s;

    if (next == 0.0) {
        do {
            u1 = rand() / (RAND_MAX + 1.0);
            u2 = rand() / (RAND_MAX + 1.0);
            s = u1 * u1 + u2 * u2;
        } while (s >= 1.0);

        next = sqrt(-2 * log(s)) * cos(2 * M_PI * u2);
        return mean + std_dev * sqrt(-2 * log(s)) * sin(2 * M_PI * u2);
    } else {
        double result = mean + std_dev * next;
        next = 0.0;
        return result;
    }
}

// Function to generate a random alphanumeric string of length 'length'
void generate_random_string(char *str, int length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()";
    for (int i = 0; i < length; ++i) {
        str[i] = charset[rand() % strlen(charset)];
    }
    str[length] = '\0';
}

// Function to generate a URL-safe base64 encoded string
char *generate_unique_id(int length) {
    // Use a secure random token generation library here
    char *unique_id = (char *)malloc(length + 1);
    if (unique_id != NULL) {
        generate_random_string(unique_id, length);
        unique_id[length] = '\0';
    }
    return unique_id;
}

// Function to dynamically allocate memory for and initialize data structures
void initialize_data_structures(int num_records, int min_int, int max_int, double mean, double std_dev, int string_length) {
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].integer_value = generate_random_int(min_int, max_int);
        records[i].float_value = generate_normal_double(mean, std_dev);
        generate_random_string(records[i].string, string_length);
        records[i].unique_id = generate_unique_id(16); // Fixed length URL-safe base64 encoded string
    }

    for (int i = 0; i < num_records; ++i) {
        printf("Record %d: integer_value=%d, float_value=%.2f, string='%s', unique_id='%s'\n",
               i, records[i].integer_value, records[i].float_value, records[i].string, records[i].unique_id);
    }

    for (int i = 0; i < num_records; ++i) {
        free(records[i].unique_id);
    }
    free(records);
}

int main() {
    srand(time(NULL));
    initialize_data_structures(10, -100, 100, 5.0, 2.0, 64);
    return 0;
}
