record* manage_memory(const char* file_path, int key_range_start, int key_range_end) {
    FILE* file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    // Step 1: Initialize offsets array from binary file
    long num_offsets = 0;
    fscanf(file, "%ld", &num_offsets);
    long* offsets = (long*)malloc(num_offsets * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        fclose(file);
        return NULL;
    }

    // Read and initialize offsets
    for (size_t i = 0; i < num_offsets; ++i) {
        if (fscanf(file, "%ld,", &offsets[i]) != 1) {
            fprintf(stderr, "Invalid data in file at offset %zu\n", i);
            free(offsets);
            fclose(file);
            return NULL;
        }
    }

    // Step 2: Initialize keys array with random numbers
    size_t num_keys = (size_t)(key_range_end - key_range_start + 1);
    int* keys = (int*)malloc(num_keys * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        fclose(file);
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG
    for (size_t i = 0; i < num_keys; ++i) {
        keys[i] = key_range_start + rand() % num_keys;
    }

    // Step 3: Initialize record array with random values
    record* records = (record*)malloc(num_keys * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        fclose(file);
