#define NUM_RECORDS 100
#define USER_ID_LENGTH 32

typedef struct {
    int value;
    char *userID;
} record;

int compare_userIDs(const void *a, const void *b) {
    return strcmp(((record *)a)->userID, ((record *)b)->userID);
}

void regenerate_random_seed() {
    srand(time(NULL));
}

char* generate_unique_userID(int *usedIDs, int numUsedIDs) {
    char userID[USER_ID_LENGTH];
    while (1) {
        for (int i = 0; i < USER_ID_LENGTH - 1; ++i) {
            userID[i] = 'a' + rand() % 26;
        }
        userID[USER_ID_LENGTH - 1] = '\0';

        int isUnique = 1;
        for (int i = 0; i < numUsedIDs; ++i) {
            if (strcmp(userID, usedIDs[i]) == 0) {
                isUnique = 0;
                break;
            }
        }

        if (isUnique) {
            return strdup(userID);
        }
    }
}

record* initialize_records(int minVal, int maxVal, int *usedIDs, int *numUsedIDs) {
    record *records = malloc(NUM_RECORDS * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_RECORDS; ++i) {
        records[i].value = minVal + rand() % (maxVal - minVal + 1);
        records[i].userID = generate_unique_userID(usedIDs, *numUsedIDs);
        usedIDs[(*numUsedIDs)++] = atoi(records[i].userID);
    }

    qsort(records, NUM_RECORDS, sizeof(record), compare_userIDs);

    return records;
}

void print_records(record *records) {
    for (int i = 0; i < NUM_RECORDS; ++i) {
        printf("Record %d: Value = %d, UserID = %s\n", i, records[i].value, records[i].userID);
    }
}

void free_records(record *records) {
    for (int i = 0; i < NUM_RECORDS; ++i) {
        free(records[i].userID);
    }
    free(records);
}

int main() {
    regenerate_random_seed();

    int usedIDs[NUM_RECORDS];
    int numUsedIDs = 0;

    record *records = initialize_records(1, 1000, usedIDs, &numUsedIDs);

    print_records(records);

    free_records(records);

    return 0;
}
