// Custom PRNG function
double custom_prng(double min, double max) {
    return min + (max - min) * ((double)rand() / RAND_MAX);
}

int manage_arrays(long** timestamps, int** sequence_numbers, Transaction** transactions, size_t count, double min_amount, double max_amount) {
    if (count == 0) return -1; // Handle zero or negative counts

    *timestamps = (long*)malloc(count * sizeof(long));
    *sequence_numbers = (int*)malloc(count * sizeof(int));
    *transactions = (Transaction*)malloc(count * sizeof(Transaction));

    if (!*timestamps || !*sequence_numbers || !*transactions) {
        free(*timestamps);
        free(*sequence_numbers);
        free(*transactions);
        return -1; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the PRNG

    for (size_t i = 0; i < count; ++i) {
        (*timestamps)[i] = time(NULL); // Use current time as timestamp
        (*sequence_numbers)[i] = i + 1;
        (*transactions)[i].amount = custom_prng(min_amount, max_amount);
        (*transactions)[i].status = 'P'; // Pending status
    }

    return 0; // Success
}
