    int max;
    int min;
    double average;
} Summary;

Summary* processLog(const char* fileName, int idRangeMin, int idRangeMax) {
    FILE* file = fopen(fileName, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    // Dynamically allocate memory for structures
    TimeStamp* timestamps = (TimeStamp*)malloc(100 * sizeof(TimeStamp));
    Identifier* identifiers = (Identifier*)malloc(100 * sizeof(Identifier));
    LogEntry* logEntries = (LogEntry*)malloc(100 * sizeof(LogEntry));
    Summary* summary = (Summary*)malloc(sizeof(Summary));

    if (!timestamps || !identifiers || !logEntries || !summary) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    // Initialize values
    for (int i = 0; i < 100; i++) {
        timestamps[i].timestamp = 0;
        identifiers[i].identifier = idRangeMin + rand() % (idRangeMax - idRangeMin + 1);
        logEntries[i].value = rand() % (idRangeMax - idRangeMin + 1);
    }

    // Calculate summary statistics
    int maxVal = INT_MIN, minVal = INT_MAX;
    double sum = 0.0;
    for (int i = 0; i < 100; i++) {
        if (logEntries[i].value > maxVal) maxVal = logEntries[i].value;
        if (logEntries[i].value < minVal) minVal = logEntries[i].value;
        sum += logEntries[i].value;
    }
    summary->max = maxVal;
    summary->min = minVal;
    summary->average = sum / 100.0;

    fclose(file);
    return summary;
}
