    char path[256];
    size_t size;
    time_t mod_time;
} settings;

settings* manage_file_memory(int num_files, const char** file_paths) {
    settings* file_settings = (settings*)malloc(num_files * sizeof(settings));
    if (!file_settings) {
        perror("Failed to allocate memory for file settings");
        return NULL;
    }

    long* offsets = (long*)malloc(num_files * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        free(file_settings);
        return NULL;
    }

    record* records = (record*)malloc(num_files * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(file_settings);
        free(offsets);
        return NULL;
    }

    srand(time(NULL)); // Seed PRNG with current time
    int key_range = 1000; // Example range for keys

    for (int i = 0; i < num_files; i++) {
        FILE* file = fopen(file_paths[i], "r");
        if (!file) {
            fprintf(stderr, "Failed to open file: %s\n", file_paths[i]);
            memset(offsets + i, 0, sizeof(long));
            continue;
        }

        // Read offsets from the file
        long offset;
        int num_read = fscanf(file, "%ld,", &offset);
        if (num_read != 1) {
            fprintf(stderr, "Invalid data in file: %s\n", file_paths[i]);
            memset(offsets + i, 0, sizeof(long));
            fclose(file);
            continue;
        }

        offsets[i] = offset;

        // Generate random key for the record
        records[i].key = rand() % key_range;

        // Close the file
        fclose(file);
    }

    for (int i = 0; i < num_files; i++) {
        file_settings[i].path = strdup(file_paths[i]);
        if (!file_settings[i].path) {
            perror("Failed to allocate memory for path");
            free(file_settings);
            free(offsets);
            free(records);
            return NULL;
        }
        file_settings[i].size = sizeof(settings);
        time_t current_time;
        time(&current_time);
        file_settings[i].mod_time = current_time;
    }

    // Free temporary arrays
    free(offsets);
    free(records);

    return file_settings;
}
