void initializeSystem(int worldSize, float cameraSpeed, int logFrequency) {
    // Initialize PRNG with the specified type
    PRNGType prngType = FAST_PRNG; // Change to CSRNG for critical operations

    // Allocate memory for arrays
    long* offsets = (long*)malloc(worldSize * sizeof(long));
    int* keys = (int*)malloc(worldSize * sizeof(int));
    Record* records = (Record*)malloc(worldSize * sizeof(Record));
    EventTimestamp* events = (EventTimestamp*)malloc(worldSize / logFrequency * sizeof(EventTimestamp));

    // Check for memory allocation failures
    if (offsets == NULL || keys == NULL || records == NULL || events == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Initialize arrays with appropriate values and timestamps
    srand(time(NULL)); // Seed PRNG for initial setup

    for (int i = 0; i < worldSize; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 256; // Example range
        records[i].value = prngType == CSRNG ? arc4random_uniform(256) : rand() % 256;
        events[i / logFrequency] = time(NULL);
    }

    // Log performance and memory usage
    printf("Initialization complete. Memory used: %zu bytes\n", sizeof(offsets) + sizeof(keys) + sizeof(records) + sizeof(events));

    // Update random values and event timestamps based on configuration settings
    for (int i = 0; i < worldSize; i++) {
        records[i].value = prngType == CSRNG ? arc4random_uniform(256) : rand() % 256;
        if ((i % logFrequency) == 0) {
            events[i / logFrequency] = time(NULL);
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(events);
}
