// Function to initialize memory pool
void init_memory_pool(MemoryPool* pool, size_t size) {
    pool->base = malloc(size);
    if (pool->base == NULL) {
        // Handle error
    }
    pool->size = size;
    pool->used = 0;
}

// Function to allocate memory from the pool
void* allocate_from_pool(MemoryPool* pool, size_t size) {
    void* ptr = ((char*)pool->base) + pool->used;
    if (pool->used + size > pool->size) {
        // Handle error
        return NULL;
    }
    pool->used += size;
    return ptr;
}

// Function to generate a cryptographically secure pseudo-random number
