        if (payments[i].transaction != NULL) {
            free(payments[i].transaction);
        }
    }
    free(payments);
}

int main() {
    size_t initial_size = 100;
    Transaction* transactions = init_transactions(initial_size);
    User* users = init_users(initial_size);
    Payment* payments = init_payments(initial_size);

    // Example usage
    if (transactions != NULL && users != NULL && payments != NULL) {
        // Perform operations with the allocated structures
        free_transactions(transactions, initial_size);
        free_users(users, initial_size);
        free_payments(payments, initial_size);
    }

    return 0;
}
