DeviceConfig** allocateDeviceConfigs(int numDevices, const char* manufacturer, const char* features[], int featureCount) {
    if (numDevices <= 0 || manufacturer == NULL || features == NULL || featureCount <= 0) {
        return NULL; // Invalid input
    }

    DeviceConfig** deviceArray = (DeviceConfig**)malloc(numDevices * sizeof(DeviceConfig*));
    if (deviceArray == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL)); // Initialize PRNG

    for (int i = 0; i < numDevices; i++) {
        deviceArray[i] = (DeviceConfig*)malloc(sizeof(DeviceConfig));
        if (deviceArray[i] == NULL) {
            printf("Memory allocation failed for device %d\n", i);
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(deviceArray[j]);
            }
            free(deviceArray);
            return NULL;
        }

        deviceArray[i]->deviceID = i + 1;
        deviceArray[i]->manufacturerName = strdup(manufacturer);
        if (deviceArray[i]->manufacturerName == NULL) {
            printf("Memory allocation failed for manufacturer name\n");
            // Free previously allocated memory
            for (int j = 0; j <= i; j++) {
                free(deviceArray[j]);
                free((char*)deviceArray[j]->manufacturerName);
            }
            free(deviceArray);
            return NULL;
        }

        deviceArray[i]->features = (char**)malloc(featureCount * sizeof(char*));
        if (deviceArray[i]->features == NULL) {
            printf("Memory allocation failed for features\n");
            // Free previously allocated memory
            free((char*)deviceArray[i]->manufacturerName);
            for (int j = 0; j <= i; j++) {
                free(deviceArray[j]);
            }
            free(deviceArray);
            return NULL;
        }

        for (int j = 0; j < featureCount; j++) {
            deviceArray[i]->features[j] = strdup(features[j]);
            if (deviceArray[i]->features[j] == NULL) {
                printf("Memory allocation failed for feature %d\n", j);
                // Free previously allocated memory
                free((char*)deviceArray[i]->manufacturerName);
                for (int k = 0; k <= i; k++) {
                    free(deviceArray[k]);
                    free((char*)deviceArray[k]->manufacturerName);
                    for (int l = 0; l < featureCount; l++) {
                        free(deviceArray[k]->features[l]);
                    }
                    free(deviceArray[k]->features);
                }
                free(deviceArray);
                return NULL;
            }
        }

        deviceArray[i]->activationKey = rand() % 1000000000UL; // Example PRNG for simplicity
    }

    return deviceArray;
}

