#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define structures
typedef struct {
    char *name;
    char *email;
    uint64_t session_id;
} user_profile;

typedef struct {
    time_t timestamp;
    double amount;
    char *description;
    user_profile *user;
} transaction_record;

// Global variables for memory management
#define MIN_BLOCK_SIZE 1024
#define GROWTH_FACTOR 2

uint32_t *session_ids = NULL;
user_profile **user_profiles = NULL;
transaction_record **transactions = NULL;

size_t session_count = 0, user_count = 0, transaction_count = 0;
size_t session_capacity = MIN_BLOCK_SIZE, user_capacity = MIN_BLOCK_SIZE, transaction_capacity = MIN_BLOCK_SIZE;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate cryptographically secure random number
uint64_t generate_session_id() {
    static uint64_t seed = 0;
    if (seed == 0) {
        srand(time(NULL));
        seed = rand();
    }
    return (seed++) * time(NULL);
}

// Function to initialize memory allocation
int initialize_memory(size_t initial_size) {
    session_ids = (uint64_t *)malloc(initial_size * sizeof(uint64_t));
    user_profiles = (user_profile **)malloc(initial_size * sizeof(user_profile *));
    transactions = (transaction_record **)malloc(initial_size * sizeof(transaction_record *));

    if (!session_ids || !user_profiles || !transactions) {
        return -1; // Allocation failed
    }

    memset(session_ids, 0, initial_size * sizeof(uint64_t));
    memset(user_profiles, 0, initial_size * sizeof(user_profile *));
    memset(transactions, 0, initial_size * sizeof(transaction_record *));

    session_count = user_count = transaction_count = initial_size;
    session_capacity = user_capacity = transaction_capacity = initial_size;

    return 0; // Success
}

// Function to allocate and initialize a new session
int allocate_session() {
    if (session_count >= session_capacity) {
        size_t new_capacity = session_capacity * GROWTH_FACTOR;
        uint64_t *new_ids = realloc(session_ids, new_capacity * sizeof(uint64_t));
        if (!new_ids) return -1; // Realloc failed

        user_profile **new_profiles = realloc(user_profiles, new_capacity * sizeof(user_profile *));
        if (!new_profiles) {
            free(new_ids);
            return -1; // Realloc failed
        }

        session_ids = new_ids;
        user_profiles = new_profiles;

        memset(session_ids + session_count, 0, (new_capacity - session_count) * sizeof(uint64_t));
        memset(user_profiles + session_count, 0, (new_capacity - session_count) * sizeof(user_profile *));

        session_capacity = new_capacity;
    }

    session_ids[session_count] = generate_session_id();
    user_profiles[session_count] = NULL;

    session_count++;
    return 0; // Success
}

// Function to allocate and initialize a new user profile
int allocate_user(char *name, char *email) {
    if (user_count >= user_capacity) {
        size_t new_capacity = user_capacity * GROWTH_FACTOR;
        user_profile **new_profiles = realloc(user_profiles, new_capacity * sizeof(user_profile *));
        if (!new_profiles) return -1; // Realloc failed

        user_profiles = new_profiles;

        memset(user_profiles + user_count, 0, (new_capacity - user_count) * sizeof(user_profile *));

        user_capacity = new_capacity;
    }

    user_profiles[user_count] = (user_profile *)malloc(sizeof(user_profile));
    if (!user_profiles[user_count]) return -1; // Malloc failed

    user_profiles[user_count]->name = strdup(name);
    user_profiles[user_count]->email = strdup(email);
    user_profiles[user_count]->session_id = generate_session_id();

    user_count++;
    return 0; // Success
}

// Function to allocate and initialize a new transaction record
int allocate_transaction(time_t timestamp, double amount, char *description, user_profile *user) {
    if (transaction_count >= transaction_capacity) {
        size_t new_capacity = transaction_capacity * GROWTH_FACTOR;
        transaction_record **new_transactions = realloc(transactions, new_capacity * sizeof(transaction_record *));
        if (!new_transactions) return -1; // Realloc failed

        transactions = new_transactions;

        memset(transactions + transaction_count, 0, (new_capacity - transaction_count) * sizeof(transaction_record *));

        transaction_capacity = new_capacity;
    }

    transactions[transaction_count] = (transaction_record *)malloc(sizeof(transaction_record));
    if (!transactions[transaction_count]) return -1; // Malloc failed

    transactions[transaction_count]->timestamp = timestamp;
    transactions[transaction_count]->amount = amount;
    transactions[transaction_count]->description = strdup(description);
    transactions[transaction_count]->user = user;

    transaction_count++;
    return 0; // Success
}

// Function to free allocated memory
void free_memory() {
    for (size_t i = 0; i < session_count; i++) {
        if (user_profiles[i]) {
            free(user_profiles[i]->name);
            free(user_profiles[i]->email);
            free(user_profiles[i]);
        }
    }

    free(session_ids);
    free(user_profiles);
    free(transactions);

    session_ids = user_profiles = transactions = NULL;
    session_count = user_count = transaction_count = 0;
}

// Thread-safe function to allocate a new session
int thread_safe_allocate_session() {
    pthread_mutex_lock(&mutex);
    int result = allocate_session();
    pthread_mutex_unlock(&mutex);
    return result;
}

// Thread-safe function to allocate a new user profile
int thread_safe_allocate_user(char *name, char *email) {
    pthread_mutex_lock(&mutex);
    int result = allocate_user(name, email);
    pthread_mutex_unlock(&mutex);
    return result;
}

// Thread-safe function to allocate a new transaction record
int thread_safe_allocate_transaction(time_t timestamp, double amount, char *description, user_profile *user) {
    pthread_mutex_lock(&mutex);
    int result = allocate_transaction(timestamp, amount, description, user);
    pthread_mutex_unlock(&mutex);
    return result;
}
