// Global variables for pool management
#define POOL_SIZE 10000
long long* id_pool = NULL;
int pool_index = 0;

pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to generate unique identifiers using a CSPRNG
long long generate_id() {
    pthread_mutex_lock(&pool_lock);
    if (pool_index >= POOL_SIZE) {
        pthread_mutex_unlock(&pool_lock);
        fprintf(stderr, "ID pool exhausted!\n");
        exit(EXIT_FAILURE);
    }
    return id_pool[pool_index++];
    pthread_mutex_unlock(&pool_lock);
}

// Function to initialize 'config' structures
config* init_config(long long count) {
    config* configs = (config*)malloc(count * sizeof(config));
    if (!configs) {
        perror("Failed to allocate memory for 'config' structures");
        exit(EXIT_FAILURE);
    }
    for (long long i = 0; i < count; ++i) {
        configs[i].probability = rand() / (double)RAND_MAX;
        configs[i].name = malloc(256); // Assuming maximum name length of 255
        if (!configs[i].name) {
            perror("Failed to allocate memory for 'config' names");
            free(configs);
            exit(EXIT_FAILURE);
        }
        snprintf(configs[i].name, 256, "Config_%lld", i);
    }
    return configs;
}

// Function to initialize 'record' structures
record* init_record(long long count) {
    record* records = (record*)malloc(count * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for 'record' structures");
        exit(EXIT_FAILURE);
    }
    for (long long i = 0; i < count; ++i) {
        records[i].value = generate_id() % 1001;
    }
    return records;
}

