    long long count = 10000000; // Example count

    id_pool = (long long*)malloc(POOL_SIZE * sizeof(long long));
    if (!id_pool) {
        perror("Failed to allocate memory for ID pool");
        return EXIT_FAILURE;
    }
    srand(time(NULL)); // Seed the PRNG
    for (int i = 0; i < POOL_SIZE; ++i) {
        id_pool[i] = rand();
    }

    if (pthread_create(&thread, NULL, init_structures, &count)) {
        perror("Failed to create thread");
        free(id_pool);
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    free(id_pool);

    return EXIT_SUCCESS;
}
