    manager->sessions = NULL;
    manager->capacity = 0;
    manager->count = 0;
}

int generateUniqueToken(char *token, size_t tokenLength) {
    // Implement a fast PRNG for generating tokens
    static int seed = time(NULL);
    srand(seed++);
    return sprintf(token, "%08d%08d", rand(), rand()) == tokenLength - 1;
}

void createSession(SessionManager *manager, int userId) {
    if (manager->count >= manager->capacity) {
        // Resize the session array
        size_t newCapacity = manager->capacity * 2;
        UserSession *newSessions = (UserSession *)realloc(manager->sessions, newCapacity * sizeof(UserSession));
        if (!newSessions) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(1);
        }
        manager->sessions = newSessions;
        manager->capacity = newCapacity;
    }

    UserSession *session = &manager->sessions[manager->count++];
    session->userId = userId;
    session->lastActivity = time(NULL);
    while (!generateUniqueToken(session->token, sizeof(session->token)));
