typedef struct {
    double probability;
    char* name;
    unsigned long id;
} config;

// Pseudo-random number generator function
unsigned long prng(unsigned long seed) {
    return (seed * 1103515245 + 12345) % 2147483647;
}

// Function to initialize a config structure
config* init_config(double probability, const char* name, unsigned long id) {
    config* cfg = (config*)malloc(sizeof(config));
    if (!cfg) return NULL;

    cfg->probability = probability;
    cfg->name = strdup(name);
    cfg->id = id;

    if (!cfg->name) {
        free(cfg);
        return NULL;
    }

    return cfg;
}

// Function to reallocate the config array
config** realloc_config(config** arr, size_t* size, size_t new_size, unsigned long seed) {
    config** new_arr = (config**)realloc(arr, new_size * sizeof(config*));
    if (!new_arr) return NULL;

    for (size_t i = *size; i < new_size; i++) {
        unsigned long id = prng(seed);
        new_arr[i] = init_config(0.5, "default", id); // Example initialization
        if (!new_arr[i]) {
            while (i--) free(new_arr[i]);
            free(new_arr);
            return NULL;
        }
    }

    *size = new_size;
    return new_arr;
}

// Function to validate config integrity using a simple checksum
unsigned long checksum_config(config* cfg) {
    unsigned long sum = 0;
    sum += (unsigned long)(cfg->probability * 1000);
    for (int i = 0; cfg->name[i]; i++) sum += (unsigned long)cfg->name[i];
    sum += cfg->id;

    return sum;
}

// Function to log allocation and validation activities
void log_activity(const char* message, size_t size, const char* error_message) {
    time_t now = time(NULL);
    printf("Timestamp: %s, Size: %zu, Error: %s\n", ctime(&now), size, error_message ? error_message : "None");
}

// Main function to demonstrate the use of the above functions
int main() {
    size_t config_size = 5;
    unsigned long seed = time(NULL);
    config** config_array = (config**)malloc(config_size * sizeof(config*));
    if (!config_array) {
        log_activity("Failed to allocate memory for config array", config_size, "Memory allocation failed");
        return -1;
    }

    for (size_t i = 0; i < config_size; i++) {
        unsigned long id = prng(seed);
        config_array[i] = init_config(0.5, "default", id); // Example initialization
        if (!config_array[i]) {
            while (i--) free(config_array[i]);
            free(config_array);
            log_activity("Failed to initialize config structure", i + 1, "Initialization failed");
            return -1;
        }
    }

    unsigned long new_size = 10;
    config_array = realloc_config(config_array, &config_size, new_size, seed);
    if (!config_array) {
        log_activity("Failed to reallocate memory for config array", new_size, "Memory allocation failed");
        return -1;
    }

    for (size_t i = 5; i < new_size; i++) {
        unsigned long id = prng(seed);
        config_array[i] = init_config(0.5, "default", id); // Example initialization
        if (!config_array[i]) {
            while (i--) free(config_array[i]);
            free(config_array);
            log_activity("Failed to initialize config structure", i + 1, "Initialization failed");
            return -1;
        }
    }

    for (size_t i = 0; i < new_size; i++) {
        if (checksum_config(config_array[i]) != checksum_config(config_array[i])) {
            log_activity("Config integrity check failed", sizeof(config), NULL);
            break;
        }
    }

    for (size_t i = 0; i < new_size; i++) {
        free(config_array[i]->name);
        free(config_array[i]);
    }
    free(config_array);

    return 0;
}
