#include <stdlib.h>
#include <string.h>
#include <openssl/rand.h>

#define MAX_CONFIGS 1000
#define MIN_MEMORY_POOL_SIZE 64 * 1024 * 1024

typedef struct {
    double probability;
    char* name;
    short status_code;
} Config;

typedef struct {
    void** memory_pool;
    size_t pool_size;
    size_t used_memory;
    size_t item_size;
} MemoryPool;

MemoryPool* create_memory_pool(size_t item_size, size_t initial_size) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->memory_pool = malloc(initial_size * sizeof(void*));
    if (!pool->memory_pool) {
        free(pool);
        return NULL;
    }

    pool->pool_size = initial_size;
    pool->used_memory = 0;
    pool->item_size = item_size;

    for (size_t i = 0; i < initial_size; ++i) {
        pool->memory_pool[i] = malloc(item_size);
        if (!pool->memory_pool[i]) {
            for (size_t j = 0; j < i; ++j) free(pool->memory_pool[j]);
            free(pool->memory_pool);
            free(pool);
            return NULL;
        }
    }

    return pool;
}

void* memory_pool_alloc(MemoryPool* pool) {
    if (pool->used_memory == pool->pool_size) {
        size_t new_size = pool->pool_size * 2;
        void** new_memory_pool = realloc(pool->memory_pool, new_size * sizeof(void*));
        if (!new_memory_pool) return NULL;

        for (size_t i = pool->pool_size; i < new_size; ++i) {
            new_memory_pool[i] = malloc(pool->item_size);
            if (!new_memory_pool[i]) {
                for (size_t j = pool->pool_size; j < i; ++j) free(new_memory_pool[j]);
                free(new_memory_pool);
                return NULL;
            }
        }

        pool->memory_pool = new_memory_pool;
        pool->pool_size = new_size;
    }

    void* item = pool->memory_pool[pool->used_memory++];
    memset(item, 0, pool->item_size); // Initialize memory
    return item;
}

void destroy_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->pool_size; ++i) free(pool->memory_pool[i]);
    free(pool->memory_pool);
    free(pool);
}

long* allocate_long_array(size_t size, MemoryPool* pool) {
    return memory_pool_alloc(pool);
}

char** allocate_char_array(size_t size, MemoryPool* pool) {
    char** array = memory_pool_alloc(pool);
    for (size_t i = 0; i < size; ++i) array[i] = malloc(256); // Example size
    return array;
}

Config* allocate_config_array(size_t size, MemoryPool* pool) {
    Config* array = memory_pool_alloc(pool);
    for (size_t i = 0; i < size; ++i) {
        array[i].name = malloc(256); // Example size
        RAND_bytes((unsigned char*)&array[i], sizeof(Config));
    }
    return array;
}

short* allocate_status_flag_array(size_t size, MemoryPool* pool) {
    short* array = memory_pool_alloc(pool);
    for (size_t i = 0; i < size; ++i) RAND_bytes((unsigned char*)&array[i], sizeof(short));
    return array;
}
