#include <time.h>

typedef struct {
    int value;
    long key;
    double probability;
} Record;

void* allocateMemory(int type, size_t size, int range_start, int range_end, long prime) {
    void* memory = NULL;
    switch (type) {
        case 'l': // Allocate array of long integers
            memory = malloc(size * sizeof(long));
            if (memory == NULL) {
                fprintf(stderr, "Failed to allocate memory for long array\n");
                return NULL;
            }
            for (size_t i = 0; i < size; ++i) {
                ((long*)memory)[i] = prime * i % size; // Example initialization
            }
            break;
        case 'i': // Allocate array of int keys
            memory = malloc(size * sizeof(int));
            if (memory == NULL) {
                fprintf(stderr, "Failed to allocate memory for int array\n");
                return NULL;
            }
            srand(time(NULL)); // Seed the PRNG
            for (size_t i = 0; i < size; ++i) {
                ((int*)memory)[i] = rand() % range_end + range_start;
            }
            break;
        case 'c': // Allocate array of char strings
            memory = malloc(size * sizeof(char*));
            if (memory == NULL) {
                fprintf(stderr, "Failed to allocate memory for char array\n");
                return NULL;
            }
            for (size_t i = 0; i < size; ++i) {
                ((char**)memory)[i] = (char*)malloc(256 * sizeof(char)); // Allocate enough space for strings
                if (((char**)memory)[i] == NULL) {
                    fprintf(stderr, "Failed to allocate memory for char string\n");
                    return NULL;
                }
                sprintf(((char**)memory)[i], "Config%d", i); // Example initialization
            }
            break;
        case 'r': // Allocate array of record structures
            memory = malloc(size * sizeof(Record));
            if (memory == NULL) {
                fprintf(stderr, "Failed to allocate memory for record array\n");
                return NULL;
            }
            srand(time(NULL)); // Seed the PRNG
            for (size_t i = 0; i < size; ++i) {
                ((Record*)memory)[i].value = rand() % range_end + range_start;
                ((Record*)memory)[i].key = prime * i % size;
                ((Record*)memory)[i].probability = (double)rand() / RAND_MAX; // Random double between 0.0 and 1.0
            }
            break;
        default:
            fprintf(stderr, "Invalid type specified\n");
            return NULL;
    }
    return memory;
}

void freeMemory(void* memory, int type, size_t size) {
    if (memory == NULL) return;

    switch (type) {
        case 'l': // Free array of long integers
            free(memory);
            break;
        case 'i': // Free array of int keys
            for (size_t i = 0; i < size; ++i) {
                free(((int*)memory)[i]);
            }
            free(memory);
            break;
        case 'c': // Free array of char strings
            for (size_t i = 0; i < size; ++i) {
                free(((char**)memory)[i]);
            }
            free(memory);
            break;
        case 'r': // Free array of record structures
            free(memory);
            break;
        default:
            fprintf(stderr, "Invalid type specified\n");
            break;
    }
}

int main() {
    size_t size = 100;
    int range_start = 0;
    int range_end = 100;
    long prime = 3;

    // Example usage
    void* long_array = allocateMemory('l', size, range_start, range_end, prime);
    void* int_array = allocateMemory('i', size, range_start, range_end, prime);
    void* char_array = allocateMemory('c', size, range_start, range_end, prime);
    void* record_array = allocateMemory('r', size, range_start, range_end, prime);

    // Free allocated memory
    freeMemory(long_array, 'l', size);
    freeMemory(int_array, 'i', size);
    freeMemory(char_array, 'c', size);
    freeMemory(record_array, 'r', size);

    return 0;
}
