#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_SESSIONS 1024
#define MAX_USERS 1024
#define MAX_TRANSACTIONS 1024

typedef struct {
    int id;
    char name[256];
    char email[256];
    int session_id;
} User;

typedef struct {
    time_t timestamp;
    double amount;
    char description[256];
    User* user;
} Transaction;

int session_ids[MAX_SESSIONS];
User users[MAX_USERS];
Transaction transactions[MAX_TRANSACTIONS];

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_memory() {
    srand(time(NULL));
    for (int i = 0; i < MAX_SESSIONS; i++) {
        session_ids[i] = rand();
    }
}

User* create_user(const char* name, const char* email) {
    User* user = malloc(sizeof(User));
    if (!user) {
        perror("Failed to allocate memory for user");
        return NULL;
    }
    strncpy(user->name, name, sizeof(user->name));
    strncpy(user->email, email, sizeof(user->email));
    user->session_id = session_ids[rand() % MAX_SESSIONS];
    pthread_mutex_lock(&mutex);
    users[user->session_id] = *user;
    pthread_mutex_unlock(&mutex);
    return user;
}

Transaction* create_transaction(time_t timestamp, double amount, const char* description, User* user) {
    Transaction* transaction = malloc(sizeof(Transaction));
    if (!transaction) {
        perror("Failed to allocate memory for transaction");
        return NULL;
    }
    transaction->timestamp = timestamp;
    transaction->amount = amount;
    strncpy(transaction->description, description, sizeof(transaction->description));
    transaction->user = user;
    pthread_mutex_lock(&mutex);
    transactions[transaction->user->session_id] = *transaction;
    pthread_mutex_unlock(&mutex);
    return transaction;
}

