#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    double probability;
    char* config_name;
    int timeout_duration;
} config;

typedef struct {
    time_t timestamp;
    char* event_description;
    config* config_ptr;
} event_record;

config* init_config_array(int size) {
    config* configs = malloc(size * sizeof(config));
    if (!configs) {
        fprintf(stderr, "Memory allocation failed for config array\n");
        return NULL;
    }
    return configs;
}

event_record* init_event_array(int size, config** configs) {
    event_record* events = malloc(size * sizeof(event_record));
    if (!events) {
        fprintf(stderr, "Memory allocation failed for event array\n");
        return NULL;
    }
    for (int i = 0; i < size; ++i) {
        events[i].timestamp = time(NULL);
        events[i].event_description = malloc(256 * sizeof(char));
        if (!events[i].event_description) {
            fprintf(stderr, "Memory allocation failed for event description %d\n", i);
            return NULL;
        }
        events[i].config_ptr = configs[rand() % size];
    }
    return events;
}

void free_config_array(config* configs, int size) {
    for (int i = 0; i < size; ++i) {
        free(configs[i].config_name);
    }
    free(configs);
}

void free_event_array(event_record* events, int size) {
    for (int i = 0; i < size; ++i) {
        free(events[i].event_description);
    }
    free(events);
}

int main() {
    srand(time(NULL));
    int config_size = 100;
    int event_size = 200;

    config* configs = init_config_array(config_size);
    if (!configs) return 1;

    event_record* events = init_event_array(event_size, &configs);
    if (!events) {
        free_config_array(configs, config_size);
        return 1;
    }

    // Use the arrays...

    free_event_array(events, event_size);
    free_config_array(configs, config_size);

    return 0;
}
