int num_events = 0;
int max_configs;
int max_events;

void init_memory_management(int initial_configs, int initial_events) {
    max_configs = initial_configs;
    max_events = initial_events;

    long_array = (config**)malloc(max_configs * sizeof(config*));
    string_array = (char***)malloc(max_configs * sizeof(char***));
    config_array = (config**)malloc(max_configs * sizeof(config*));
    event_array = (event**)malloc(max_events * sizeof(event*));
    log_array = (log**)malloc(max_configs * sizeof(log*));

    if (!long_array || !string_array || !config_array || !event_array || !log_array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void add_config(double probability, char* name, int timeout) {
    if (num_configs >= max_configs) {
        max_configs *= 2;
        long_array = realloc(long_array, max_configs * sizeof(config*));
        string_array = realloc(string_array, max_configs * sizeof(char***));
        config_array = realloc(config_array, max_configs * sizeof(config*));
        log_array = realloc(log_array, max_configs * sizeof(log*));

        if (!long_array || !string_array || !config_array || !log_array) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    config* new_config = (config*)malloc(sizeof(config));
    new_config->probability = probability;
    new_config->name = strdup(name);
    new_config->timeout = timeout;

    log_entry* new_log = generate_unique_id();
    new_config->log_entry = new_log;

    long_array[num_configs] = NULL;
    string_array[num_configs] = NULL;
    config_array[num_configs++] = new_config;
}

void add_event(time_t timestamp, char* description, config* config_struct) {
    if (num_events >= max_events) {
        max_events *= 2;
        event_array = realloc(event_array, max_events * sizeof(event*));

        if (!event_array) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    event* new_event = (event*)malloc(sizeof(event));
    new_event->timestamp = timestamp;
    new_event->description = strdup(description);
    new_event->config_struct = config_struct;

    log_entry* new_log = generate_unique_id();
    new_event->log_entry = new_log;

    event_array[num_events++] = new_event;
}

log_entry* generate_unique_id() {
    uint64_t id;
    if (!RAND_bytes((unsigned char*)&id, sizeof(id))) {
        fprintf(stderr, "Failed to generate random number\n");
        exit(EXIT_FAILURE);
    }

    log_entry* new_log = (log_entry*)malloc(sizeof(log_entry));
    new_log->id = id;
    new_log->allocation_time = time(NULL);
    new_log->details = NULL;

    return new_log;
}

void free_memory() {
    for (int i = 0; i < num_configs; i++) {
        free(config_array[i]->name);
        free(log_array[i]);
        free(config_array[i]);
    }

    for (int i = 0; i < num_events; i++) {
        free(event_array[i]->description);
        if (event_array[i]->log_entry) {
            free(event_array[i]->log_entry);
        }
        free(event_array[i]);
    }

    free(long_array);
    free(string_array);
    free(config_array);
    free(event_array);
    free(log_array);

    long_array = NULL;
    string_array = NULL;
    config_array = NULL;
    event_array = NULL;
    log_array = NULL;

    num_configs = 0;
    num_events = 0;
    max_configs = 0;
    max_events = 0;
}
