import io.grpc.stub.StreamObserver;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class SchedulerManager {
    private ConcurrentHashMap<String, Worker> workers = new ConcurrentHashMap<>();
    private AtomicInteger taskCounter = new AtomicInteger();

    public void addWorker(Worker worker) {
        workers.put(worker.getId(), worker);
    }

    public void removeWorker(String workerId) {
        workers.remove(workerId);
    }

    public void assignTask(Task task) {
        String workerId = selectWorker(task);
        if (workerId != null) {
            workers.get(workerId).receiveTask(task);
        } else {
            System.out.println("No available workers to handle task: " + task.getId());
        }
    }

    private String selectWorker(Task task) {
        int taskId = taskCounter.incrementAndGet();
        return workers.keySet().toArray(new String[0])[(taskId * 137 % workers.size())];
    }

    public void monitorSystem() {
        for (Worker worker : workers.values()) {
            if (worker.isOverloaded()) {
                redistributeTasks(worker);
            }
        }
    }

    private void redistributeTasks(Worker overloadedWorker) {
        Task[] tasks = overloadedWorker.getPendingTasks();
        for (Task task : tasks) {
            String newWorkerId = selectWorker(task);
            if (newWorkerId != null) {
                workers.get(newWorkerId).receiveTask(task);
            }
        }
    }

    public void startSchedulingService(StreamObserver<Task> responseObserver) {
        // Start a gRPC server to handle task assignments
    }
}

class Worker {
    private String id;
    private boolean overloaded;

    public Worker(String id) {
        this.id = id;
        this.overloaded = false;
    }

    public String getId() {
        return id;
    }

    public boolean isOverloaded() {
        return overloaded;
    }

    public void receiveTask(Task task) {
        // Process the received task
        if (task.isHighPriority()) {
            System.out.println("Worker " + id + " processing high-priority task: " + task.getId());
        } else {
            System.out.println("Worker " + id + " processing task: " + task.getId());
        }
    }

    public Task[] getPendingTasks() {
        // Return the list of pending tasks
        return new Task[0];
    }
}

class Task {
    private String id;
    private boolean highPriority;

    public Task(String id, boolean highPriority) {
        this.id = id;
        this.highPriority = highPriority;
    }

    public String getId() {
        return id;
    }

    public boolean isHighPriority() {
        return highPriority;
    }
}
