#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define data structures
typedef struct {
    char *token;
} Session;

typedef struct {
    char name[256];
    char *email;
    Session *session;
} User;

typedef struct {
    time_t timestamp;
    double amount;
    char *description;
    User *user;
} Transaction;

// Function to allocate and initialize memory
int allocate_memory(int session_count, int user_count, int transaction_count) {
    // Allocate memory for sessions
    Session *sessions = (Session *)malloc(session_count * sizeof(Session));
    if (!sessions) {
        fprintf(stderr, "Failed to allocate memory for sessions\n");
        return -1;
    }

    // Allocate memory for users
    User *users = (User *)malloc(user_count * sizeof(User));
    if (!users) {
        free(sessions);
        fprintf(stderr, "Failed to allocate memory for users\n");
        return -1;
    }

    // Allocate memory for transactions
    Transaction *transactions = (Transaction *)malloc(transaction_count * sizeof(Transaction));
    if (!transactions) {
        free(sessions);
        free(users);
        fprintf(stderr, "Failed to allocate memory for transactions\n");
        return -1;
    }

    // Initialize sessions with cryptographically secure tokens
    srand(time(NULL)); // Seed the random number generator
    for (int i = 0; i < session_count; i++) {
        sessions[i].token = (char *)malloc(32); // Allocate space for a token
        if (!sessions[i].token) {
            free(sessions);
            free(users);
            free(transactions);
            fprintf(stderr, "Failed to allocate memory for session token\n");
            return -1;
        }
        snprintf(sessions[i].token, 32, "%d", rand());
    }

    // Initialize users with names, emails, and sessions
    for (int i = 0; i < user_count; i++) {
        users[i].name[0] = '\0'; // Initialize name as empty string
        users[i].email = NULL;
        users[i].session = &sessions[rand() % session_count];
    }

    // Initialize transactions with timestamps, amounts, descriptions, and users
    for (int i = 0; i < transaction_count; i++) {
        transactions[i].timestamp = time(NULL);
        transactions[i].amount = rand() / (double)RAND_MAX;
        transactions[i].description[0] = '\0'; // Initialize description as empty string
        transactions[i].user = &users[rand() % user_count];
    }

    // Free allocated memory
    for (int i = 0; i < session_count; i++) {
        free(sessions[i].token);
    }
    free(sessions);
    free(users);
    free(transactions);

    return 0;
}

// Main function to test memory allocation
int main() {
    int session_count = 1000;
    int user_count = 5000;
    int transaction_count = 25000;

    clock_t start_time = clock();
    if (allocate_memory(session_count, user_count, transaction_count) == -1) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }
    clock_t end_time = clock();

    double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;
    printf("Memory allocation took %f seconds\n", time_taken);

    return 0;
}
