#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_TRANSACTION_ID 1000000

typedef struct {
    long id;
    int amount;
    char description[256];
    time_t timestamp;
} Transaction;

Transaction* transactions[MAX_TRANSACTION_ID] = {NULL};
int transaction_count = 0;

unsigned long fast_prng() {
    static unsigned long seed = time(NULL);
    seed = (seed * 1103515245 + 12345) % MAX_TRANSACTION_ID;
    return seed;
}

void init_transaction(Transaction* tx, int amount, const char* description) {
    tx->id = fast_prng();
    tx->amount = amount;
    strncpy(tx->description, description, sizeof(tx->description) - 1);
    tx->timestamp = time(NULL);
    transactions[tx->id % MAX_TRANSACTION_ID] = tx;
}

Transaction* get_transaction(long id) {
    if (id < 0 || id >= MAX_TRANSACTION_ID) return NULL;
    return transactions[id % MAX_TRANSACTION_ID];
}

void update_transaction(long id, int new_amount, const char* new_description) {
    Transaction* tx = get_transaction(id);
    if (tx != NULL) {
        tx->amount = new_amount;
        strncpy(tx->description, new_description, sizeof(tx->description) - 1);
        tx->timestamp = time(NULL);
    }
}

void print_transactions() {
    for (int i = 0; i < transaction_count; i++) {
        if (transactions[i] != NULL) {
            printf("ID: %ld, Amount: %d, Description: %s, Timestamp: %s", 
                   transactions[i]->id, transactions[i]->amount, 
                   transactions[i]->description, ctime(&transactions[i]->timestamp));
        }
    }
}

int main() {
    init_transaction((Transaction*)malloc(sizeof(Transaction)), 100, "Initial Transaction");
    print_transactions();
    update_transaction(1, 200, "Updated Transaction");
    print_transactions();
    return 0;
}
