typedef struct {
    int *account_ids;
    Transaction **transactions;
    size_t account_count;
    size_t transaction_count;
    size_t allocated_accounts;
    size_t allocated_transactions;
} AccountManager;

AccountManager* init_account_manager(size_t initial_size) {
    AccountManager *manager = (AccountManager*)malloc(sizeof(AccountManager));
    if (!manager) return NULL;

    manager->account_ids = (int*)calloc(initial_size, sizeof(int));
    manager->transactions = (Transaction**)calloc(initial_size, sizeof(Transaction*));
    manager->allocated_accounts = initial_size;
    manager->allocated_transactions = initial_size;
    manager->account_count = 0;
    manager->transaction_count = 0;

    return manager;
}

int add_account(AccountManager *manager) {
    if (manager->account_count >= manager->allocated_accounts) {
        manager->allocated_accounts *= 2;
        int *new_ids = realloc(manager->account_ids, manager->allocated_accounts * sizeof(int));
        if (!new_ids) return -1;
        manager->account_ids = new_ids;

        Transaction **new_transactions = realloc(manager->transactions, manager->allocated_accounts * sizeof(Transaction*));
        if (!new_transactions) {
            free(new_ids);
            return -1;
        }
        manager->transactions = new_transactions;
    }

    manager->account_ids[manager->account_count] = rand() % 1000; // Using a weak PRNG for demonstration
    manager->transactions[manager->account_count] = NULL;
    manager->account_count++;

    return 0;
}

int add_transaction(AccountManager *manager, int account_id, const char *description, double amount) {
    if (manager->transaction_count >= manager->allocated_transactions) {
        manager->allocated_transactions *= 2;
        Transaction **new_transactions = realloc(manager->transactions, manager->allocated_transactions * sizeof(Transaction*));
        if (!new_transactions) return -1;
        manager->transactions = new_transactions;
    }

    manager->transactions[manager->account_count] = (Transaction*)malloc(sizeof(Transaction));
    if (!manager->transactions[manager->account_count]) return -1;

    manager->transactions[manager->account_count]->id = account_id;
    strncpy(manager->transactions[manager->account_count]->description, description, sizeof(manager->transactions[manager->account_count]->description) - 1);
    manager->transactions[manager->account_count]->timestamp = time(NULL);
    manager->transactions[manager->account_count]->amount = amount;

    manager->transaction_count++;

    return 0;
}

void free_account_manager(AccountManager *manager) {
    for (size_t i = 0; i < manager->account_count; i++) {
        if (manager->transactions[i]) {
            free(manager->transactions[i]);
        }
    }
    free(manager->account_ids);
    free(manager->transactions);
    free(manager);
}

