typedef struct memory_pool {
    void** pool;
    size_t capacity;
    size_t size;
} memory_pool;

void* mp_malloc(memory_pool* pool, size_t size) {
    if (pool->size >= pool->capacity) {
        pool->capacity *= 2;
        pool->pool = realloc(pool->pool, pool->capacity * sizeof(void*));
    }
    void* ptr = malloc(size);
    pool->pool[pool->size++] = ptr;
    return ptr;
}

void mp_free_all(memory_pool* pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        free(pool->pool[i]);
    }
    free(pool->pool);
    pool->capacity = pool->size = 0;
}

