    if (!configs) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < initial_size; i++) {
        configs[i] = (Config*)malloc(sizeof(Config));
        if (!configs[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free previously allocated memory
            for (int j = 0; j < i; j++) free(configs[j]);
            free(configs);
            return NULL;
        }
    }

