    unsigned long seed = time(NULL);
    for (int i = 0; i < initial_size; i++) {
        configs[i]->probability = generate_unique_id(seed, max_size) / (double)max_size;
        configs[i]->config_name = (char*)malloc(256 * sizeof(char));
        if (!configs[i]->config_name) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free previously allocated memory
            for (int j = 0; j <= i; j++) {
                free(configs[j]->config_name);
                free(configs[j]);
            }
            pthread_mutex_unlock(mutex);
            free(configs);
            return NULL;
        }
        sprintf(configs[i]->config_name, "Config_%d", i);
