#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define structures
typedef struct {
    unsigned long id;
    double amount;
    char* description;
} transaction;

typedef struct {
    time_t timestamp;
    char* operation_type;
    transaction* tx;
} log_entry;

// Fast, non-cryptographic PRNG function
unsigned long fast_prng(unsigned long seed) {
    return seed * 1103515245 + 12345;
}

// Function to manage memory allocation and initialization
int manage_memory(size_t initial_size_tx, size_t initial_size_log, FILE* log_file, int verbose) {
    unsigned long seed = time(NULL);
    transaction** tx_array = (transaction**)malloc(initial_size_tx * sizeof(transaction*));
    if (tx_array == NULL) {
        fprintf(stderr, "Memory allocation failed for transaction array.\n");
        return -1;
    }

    log_entry** log_array = (log_entry**)malloc(initial_size_log * sizeof(log_entry*));
    if (log_array == NULL) {
        fprintf(stderr, "Memory allocation failed for log entry array.\n");
        free(tx_array);
        return -2;
    }

    // Initialize arrays
    for (size_t i = 0; i < initial_size_tx; i++) {
        tx_array[i] = (transaction*)malloc(sizeof(transaction));
        if (tx_array[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for transaction %zu.\n", i);
            // Free previously allocated memory
            for (size_t j = 0; j < i; j++) free(tx_array[j]);
            free(tx_array);
            free(log_array);
            return -3;
        }
        tx_array[i]->id = fast_prng(seed++);
        tx_array[i]->amount = 0.0;
        tx_array[i]->description = (char*)malloc(100 * sizeof(char));
        if (tx_array[i]->description == NULL) {
            fprintf(stderr, "Memory allocation failed for transaction description %zu.\n", i);
            // Free previously allocated memory
            for (size_t j = 0; j <= i; j++) free(tx_array[j]);
            free(tx_array);
            free(log_array);
            return -4;
        }
    }

    for (size_t i = 0; i < initial_size_log; i++) {
        log_array[i] = (log_entry*)malloc(sizeof(log_entry));
        if (log_array[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for log entry %zu.\n", i);
            // Free previously allocated memory
            for (size_t j = 0; j < i; j++) free(log_array[j]);
            for (size_t j = 0; j < initial_size_tx; j++) {
                free(tx_array[j]->description);
                free(tx_array[j]);
            }
            free(tx_array);
            free(log_array);
            return -5;
        }
        log_array[i]->timestamp = time(NULL);
        log_array[i]->operation_type = (char*)malloc(10 * sizeof(char));
        if (log_array[i]->operation_type == NULL) {
            fprintf(stderr, "Memory allocation failed for operation type %zu.\n", i);
            // Free previously allocated memory
            for (size_t j = 0; j <= i; j++) free(log_array[j]);
            for (size_t j = 0; j < initial_size_tx; j++) {
                free(tx_array[j]->description);
                free(tx_array[j]);
            }
            free(tx_array);
            free(log_array);
            return -6;
        }
        log_array[i]->tx = tx_array[fast_prng(seed++) % initial_size_tx];
    }

    // Log allocation details
    if (log_file != NULL) {
        time_t start_time = time(NULL);
        fprintf(log_file, "Memory allocation started at: %s", ctime(&start_time));
        time_t end_time = time(NULL);
        fprintf(log_file, "Memory allocation ended at: %s", ctime(&end_time));
        fprintf(log_file, "Total memory used: %zu bytes\n", initial_size_tx * sizeof(transaction*) + initial_size_log * sizeof(log_entry*));
    }

    // Free allocated memory
    for (size_t i = 0; i < initial_size_tx; i++) {
        free(tx_array[i]->description);
        free(tx_array[i]);
    }
    free(tx_array);

    for (size_t i = 0; i < initial_size_log; i++) {
        free(log_array[i]->operation_type);
        free(log_array[i]);
    }
    free(log_array);

    return 0;
}

int main() {
    FILE* log_file = fopen("memory_allocation.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return -1;
    }

    int result = manage_memory(1000, 2000, log_file, 1);
    if (result != 0) {
        printf("Memory management failed with error code %d.\n", result);
    }

    fclose(log_file);
    return 0;
}
