#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

#define MAX_SIZE 1000
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct {
    int value;
} record;

void initialize_arrays(long **offsets, int **keys, record **records, int *size) {
    // Allocate memory for arrays
    *offsets = malloc(*size * sizeof(long));
    *keys = malloc(*size * sizeof(int));
    *records = malloc(*size * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
}

void free_arrays(long **offsets, int **keys, record **records, int *size) {
    // Free allocated memory
    free(*offsets);
    free(*keys);
    free(*records);
}

void resize_arrays(long **offsets, int **keys, record **records, int *size, int new_size) {
    if (new_size > MAX_SIZE) {
        fprintf(stderr, "New size exceeds maximum limit\n");
        return;
    }

    // Reallocate memory for arrays
    *offsets = realloc(*offsets, new_size * sizeof(long));
    *keys = realloc(*keys, new_size * sizeof(int));
    *records = realloc(*records, new_size * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        return;
    }

    // Initialize newly allocated elements
    for (int i = *size; i < new_size; ++i) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        (*records)[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    }

    *size = new_size;

    // Log the resized state of the arrays
    printf("Arrays resized to size: %d\n", *size);
    printf("Average offset value: %.2f\n", (float)(*offsets[*size / 2]) / (*size / 2));
    printf("Average key value: %.2f\n", (float)(*keys[*size / 2]) / (*size / 2));
    printf("Average record value: %.2f\n", (float)((*records[*size / 2]).value) / (*size / 2));
}

void *thread_function(void *arg) {
    // Simulate concurrent access
    long **offsets = (long **)arg;
    int **keys = (int **)arg;
    record **records = (record **)arg;
    int *size = (int *)arg;

    resize_arrays(offsets, keys, records, size, *size + 10);

    return NULL;
}

int main() {
    srand(time(NULL));

    long *offsets;
    int *keys;
    record *records;
    int size = 50;

    initialize_arrays(&offsets, &keys, &records, &size);

    for (int i = 0; i < size; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        records[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    }

    // Log the initial state of the arrays
    printf("Arrays initialized with size: %d\n", size);
    printf("Average offset value: %.2f\n", (float)(offsets[size / 2]) / (size / 2));
    printf("Average key value: %.2f\n", (float)(keys[size / 2]) / (size / 2));
    printf("Average record value: %.2f\n", (float)((records[size / 2]).value) / (size / 2));

    pthread_t threads[5];
    for (int i = 0; i < 5; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, &offsets) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            return 1;
        }
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_arrays(&offsets, &keys, &records, &size);

    return 0;
}
