#define MAX_USERNAME_LENGTH 16

typedef struct {
    long id;
    char username[MAX_USERNAME_LENGTH];
} user_record;

user_record* create_user_records(int num_users) {
    if (num_users <= 0) {
        fprintf(stderr, "Invalid number of users.\n");
        return NULL;
    }

    user_record* records = malloc(num_users * sizeof(user_record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < num_users; ++i) {
        records[i].id = i + 1; // Unique identifier
        int username_length = rand() % MAX_USERNAME_LENGTH + 1;
        for (int j = 0; j < username_length; ++j) {
            records[i].username[j] = 'a' + rand() % 36; // Random alphanumeric character
        }
        records[i].username[username_length] = '\0'; // Null-terminate the string
    }

    return records;
}

void free_user_records(user_record* records, int num_users) {
    if (records) {
        free(records);
    }
}

int main() {
    int num_users = 10; // Example number of users
    user_record* users = create_user_records(num_users);
    if (users) {
        for (int i = 0; i < num_users; ++i) {
            printf("User ID: %ld, Username: %s\n", users[i].id, users[i].username);
        }
        free_user_records(users, num_users);
    }
    return 0;
}
