typedef struct {
    time_t timestamp;
    double amount;
    unsigned int random_number;
} transaction;

// Custom PRNG function with good statistical properties
unsigned int custom_prng(unsigned int seed) {
    return (seed * 1664525 + 1013904223) % UINT_MAX;
}

// Function to initialize the array of transactions
transaction* init_transactions(size_t initial_capacity, unsigned int* seed) {
    transaction* trans = (transaction*)malloc(initial_capacity * sizeof(transaction));
    if (!trans) return NULL; // Handle memory allocation failure

    *seed = time(NULL); // Seed PRNG with current time for uniqueness
    for (size_t i = 0; i < initial_capacity; ++i) {
        trans[i].timestamp = time(NULL);
        trans[i].amount = ((double)rand() / RAND_MAX) * 1000.0; // Random amount between 0 and 1000
        trans[i].random_number = custom_prng(*seed + i); // Custom PRNG to avoid predictable patterns
    }
    return trans;
}

// Function to resize the array of transactions
transaction* resize_transactions(transaction** trans, size_t new_capacity, unsigned int* seed) {
    transaction* new_trans = (transaction*)realloc(*trans, new_capacity * sizeof(transaction));
    if (!new_trans) {
        free(*trans); // Free old memory on failure
        return NULL; // Handle memory allocation failure
    }
    *trans = new_trans;
    for (size_t i = (*trans)->timestamp / time(NULL); i < new_capacity; ++i) {
        (*trans)[i].timestamp = time(NULL);
        (*trans)[i].amount = ((double)rand() / RAND_MAX) * 1000.0; // Random amount between 0 and 1000
        (*trans)[i].random_number = custom_prng(*seed + i); // Custom PRNG to avoid predictable patterns
    }
    return *trans;
}

// Function to free the array of transactions
void free_transactions(transaction* trans) {
    free(trans);
}
