int fetch_transactions_from_source(transaction **transactions, size_t count) {
    // Simulate fetching from an external data source
    *transactions = malloc(count * sizeof(transaction));
    if (!*transactions) return -1;

    generate_random_numbers(*transactions, count);
    return 0;
}

int get_cached_transactions(transaction **transactions, size_t count) {
    pthread_mutex_lock(&cache_lock);
    if (transaction_cache.count >= count) {
        *transactions = transaction_cache.data;
        pthread_mutex_unlock(&cache_lock);
        return 0;
    }
    pthread_mutex_unlock(&cache_lock);

    return fetch_transactions_from_source(transactions, count);
}

void update_cached_transactions(transaction *new_data, size_t count) {
    pthread_mutex_lock(&cache_lock);
    if (count > MAX_CACHE_SIZE) count = MAX_CACHE_SIZE;

    for (size_t i = 0; i < count; ++i) {
        transaction_cache.data[i] = new_data[i];
    }
    transaction_cache.count = count;
    pthread_mutex_unlock(&cache_lock);
}

void free_transactions(transaction *transactions) {
    if (transactions) {
        free(transactions);
    }
}

int manage_transaction_memory(size_t count) {
    transaction *new_data = NULL;
    int result = get_cached_transactions(&new_data, count);

    if (result == 0 && new_data != NULL) {
        update_cached_transactions(new_data, count);
        free_transactions(new_data);
    }

    return result;
}
