#include <stdlib.h>
#include <time.h>

typedef struct {
    unsigned int timestamp;
    unsigned int unique_id;
} record;

typedef struct {
    unsigned long offset;
    short key;
    record* records;
    size_t capacity;
    size_t count;
} event_logger;

event_logger* initialize_event_logger(size_t initial_capacity) {
    event_logger* logger = (event_logger*)malloc(sizeof(event_logger));
    if (!logger) {
        return NULL; // Memory allocation failed
    }

    logger->records = (record*)malloc(initial_capacity * sizeof(record));
    if (!logger->records) {
        free(logger);
        return NULL; // Memory allocation failed
    }

    logger->offset = 0;
    logger->key = 1;
    logger->capacity = initial_capacity;
    logger->count = 0;

    return logger;
}

void destroy_event_logger(event_logger* logger) {
    if (logger) {
        free(logger->records);
        free(logger);
    }
}

int add_event(event_logger* logger, unsigned int timestamp, unsigned int unique_id) {
    if (logger->count >= logger->capacity) {
        // Resize the records array
        size_t new_capacity = logger->capacity * 2;
        record* new_records = (record*)realloc(logger->records, new_capacity * sizeof(record));
        if (!new_records) {
            return -1; // Memory allocation failed
        }
        logger->records = new_records;
        logger->capacity = new_capacity;
    }

    logger->records[logger->count].timestamp = timestamp;
    logger->records[logger->count].unique_id = unique_id;
    logger->count++;
    return 0; // Success
}

void periodic_cleanup(event_logger* logger) {
    if (logger && logger->count > 1000000) { // Example threshold for cleanup
        record* new_records = (record*)realloc(logger->records, logger->capacity * sizeof(record));
        if (new_records) {
            logger->records = new_records;
            logger->count -= 500000; // Remove half of the records as an example
        }
    }
}

int main() {
    event_logger* logger = initialize_event_logger(1000);
    if (!logger) {
        fprintf(stderr, "Failed to initialize event logger\n");
        return 1;
    }

    time_t now = time(NULL);
    unsigned int current_time_ms = (unsigned int)(now * 1000);

    for (size_t i = 0; i < 5; i++) {
        if (add_event(logger, current_time_ms + i, i) != 0) {
            fprintf(stderr, "Failed to add event\n");
            destroy_event_logger(logger);
            return 1;
        }
    }

    periodic_cleanup(logger);

    destroy_event_logger(logger);
    return 0;
}
