#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000

typedef struct {
    long timestamp;
    int index;
    int data_value;
    char status_flag;
} DataRecord;

typedef struct {
    DataRecord records[MAX_RECORDS];
    int count;
    pthread_mutex_t lock;
} RecordManager;

void init_record_manager(RecordManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int add_record(RecordManager *manager, int index, int data_value, char status_flag) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_RECORDS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: Manager is at capacity
    }
    manager->records[manager->count].timestamp = time(NULL) * 1000 - index;
    manager->records[manager->count].index = index;
    manager->records[manager->count].data_value = data_value;
    manager->records[manager->count].status_flag = status_flag;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int delete_record(RecordManager *manager, int index) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->records[i].index == index) {
            for (int j = i; j < manager->count - 1; j++) {
                manager->records[j] = manager->records[j + 1];
            }
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Error: Record not found
}

int update_record(RecordManager *manager, int index, int data_value, char status_flag) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->records[i].index == index) {
            manager->records[i].timestamp = time(NULL) * 1000 - index;
            manager->records[i].data_value = data_value;
            manager->records[i].status_flag = status_flag;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Error: Record not found
}

void log_operation(RecordManager *manager, const char *operation, int index) {
    // Placeholder for operation logging logic
    printf("Operation: %s, Index: %d\n", operation, index);
}
