#include <openssl/rand.h>

typedef struct {
    long offset;
    int key;
    int value;
} Record;

Record* create_records(int num_records) {
    if (num_records <= 0) {
        return NULL;
    }

    Record* records = malloc(num_records * sizeof(Record));
    if (records == NULL) {
        return NULL; // Memory allocation failed
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    srand(ts.tv_nsec ^ getpid());

    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand();
        records[i].key = rand();
        if (!RAND_bytes((unsigned char*)&records[i].value, sizeof(records[i].value))) {
            free(records);
            return NULL; // CSPRNG failed
        }
    }

    return records;
}

void free_records(Record* records) {
    free(records);
}
```

