u_char* resolve_dns(const char* hostname, int* error_code) {
    u_char* ip_address = malloc(4); // IPv4 address
    if (ip_address == NULL) {
        *error_code = -1; // Handle memory allocation failure
        return NULL;
    }

    struct hostent* host_info = gethostbyname(hostname);
    if (host_info == NULL) {
        *error_code = -2; // DNS resolution failed
        free(ip_address);
        return NULL;
