#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define NUM_RECORDS 10000
#define KEY_RANGE 1000
#define VALUE_RANGE 100

typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Custom PRNG structure
typedef struct {
    unsigned int seed;
    pthread_mutex_t mutex;
} PRNGState;

// Function to initialize PRNG
void prng_init(PRNGState *prng, unsigned int seed) {
    prng->seed = seed;
    pthread_mutex_init(&prng->mutex, NULL);
}

// Custom PRNG function using XORShift algorithm for speed and simplicity
unsigned int xorshift(PRNGState *prng) {
    unsigned int x = prng->seed;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    prng->seed = x;
    return x;
}

// Function to generate a random value within a given range
int gen_random_value(PRNGState *prng, int max) {
    unsigned int rand_val = xorshift(prng);
    return (rand_val % (max + 1));
}

// Function to dynamically manage memory for records
Record* create_records(unsigned int seed) {
    PRNGState prng;
    prng_init(&prng, seed);

    Record *records = (Record *)malloc(NUM_RECORDS * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < NUM_RECORDS; i++) {
        records[i].offset = i * 1024; // Example offset calculation
        records[i].key = xorshift(&prng) % KEY_RANGE;
        records[i].value = gen_random_value(&prng, VALUE_RANGE);
    }

    return records;
}

// Function to free allocated memory
void free_records(Record *records) {
    free(records);
}

int main() {
    unsigned int seed = time(NULL); // Use current time as seed for PRNG
    Record *records = create_records(seed);

    if (records) {
        // Process the records...
        free_records(records);
    }

    return 0;
}
