    if (!set) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    set->count = count;
    set->offsets = (long*)malloc(count * sizeof(long));
    set->keys = (int*)malloc(count * sizeof(int));
    set->records = (Record*)malloc(count * sizeof(Record));

    if (!set->offsets || !set->keys || !set->records) {
        fprintf(stderr, "Memory allocation failed.\n");
