    key[0] = seed & 0xFF;
    key[1] = (seed >> 8) & 0xFF;
    key[2] = (seed >> 16) & 0xFF;
    key[3] = (seed >> 24) & 0xFF;

    for (size_t i = 0; i < count; ++i) {
        // Generate random value for record using CSPRNG
        unsigned char output[sizeof(Record)];
        crypto_chacha20(output, sizeof(output), nonce, key);
