#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define NUM_RECORDS 1000
#define RANDOM_RANGE 100

typedef struct {
    int value;
} Record;

unsigned long xorshift64star(unsigned long *x) {
    unsigned long x_new = (*x ^= x << 21);
    x_new ^= x_new >> 35;
    return x_new ^ (x_new << 4);
}

void initialize_arrays(long **offsets, int **keys, Record **records, size_t num_records, unsigned long *prng_state) {
    *offsets = malloc(num_records * sizeof(long));
    *keys = malloc(num_records * sizeof(int));
    *records = malloc(num_records * sizeof(Record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*offsets)[i] = xorshift64star(prng_state) % 10000;
        (*keys)[i] = xorshift64star(prng_state) % RANDOM_RANGE;
        (*records)[i].value = xorshift64star(prng_state) % RANDOM_RANGE;
    }
}

void reseed_prng(unsigned long *prng_state, FILE *seed_source) {
    unsigned long new_seed;
    fread(&new_seed, sizeof(new_seed), 1, seed_source);
    *prng_state = new_seed;
}

int main() {
    size_t num_records = NUM_RECORDS;
    long *offsets;
    int *keys;
    Record *records;
    unsigned long prng_state = time(NULL);

    initialize_arrays(&offsets, &keys, &records, num_records, &prng_state);

    // Simulate reseeding periodically
    FILE *seed_source = fopen("/dev/urandom", "rb");
    if (seed_source != NULL) {
        for (size_t i = 0; i < num_records; i += num_records / 10) {
            reseed_prng(&prng_state, seed_source);
        }
        fclose(seed_source);
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
