typedef struct {
    long offset;
    int key;
    uint8_t* data;
    size_t dataSize;
} encryptionRecord;

encryptionRecord* createEncryptionRecords(size_t numRecords, size_t* offsets, int* keys, size_t* dataSizes) {
    encryptionRecord* records = malloc(numRecords * sizeof(encryptionRecord));
    if (records == NULL) {
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG

    for (size_t i = 0; i < numRecords; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];

        records[i].dataSize = dataSizes[i];
        records[i].data = malloc(records[i].dataSize);
        if (records[i].data == NULL) {
            // Clean up previously allocated memory on failure
            for (size_t j = 0; j < i; j++) {
                free(records[j].data);
            }
            free(records);
            return NULL;
        }

        // Initialize byte data with pseudo-random values
        for (size_t k = 0; k < records[i].dataSize; k++) {
            records[i].data[k] = rand() % 256;
        }
    }

    return records;
}

void freeEncryptionRecords(encryptionRecord* records, size_t numRecords) {
    for (size_t i = 0; i < numRecords; i++) {
        free(records[i].data);
    }
    free(records);
}
