int allocate_memory(long** offsets, int** keys, record** records, size_t size, int seed_interval) {
    *offsets = (long*)malloc(size * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        return -1;
    }

    *keys = (int*)malloc(size * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        return -2;
    }

    *records = (record*)malloc(size * sizeof(record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        fprintf(stderr, "Failed to allocate memory for records.\n");
        return -3;
    }

    srand(time(NULL));
    int seed_count = 0;
    time_t reseed_time = time(NULL);

    for (size_t i = 0; i < size; i++) {
        (*records)[i].value = rand() % 100 + 1; // Random number between 1 and 100

        if ((time(NULL) - reseed_time) >= seed_interval && ++seed_count % seed_interval == 0) {
            srand(time(NULL));
            reseed_time = time(NULL);
        }
    }

    return 0;
}

void free_memory(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    size_t size = 1000;
    int seed_interval = 60; // Re-seed every minute

    long* offsets;
    int* keys;
    record* records;

    if (allocate_memory(&offsets, &keys, &records, size, seed_interval) != 0) {
        fprintf(stderr, "Failed to allocate memory.\n");
        return 1;
    }

    // Use the allocated arrays and structures here

    free_memory(offsets, keys, records);
    return 0;
}
