#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define NUM_RECORDS 1000
#define SEED_INTERVAL 1000

typedef struct {
    int value;
} record;

long* long_offsets;
int* int_keys;
record* records;
unsigned int seed;
pthread_mutex_t mutex;

void init_prng() {
    seed = time(NULL) + pthread_self();
}

void reseed_prng() {
    pthread_mutex_lock(&mutex);
    srand(seed);
    seed++;
    pthread_mutex_unlock(&mutex);
}

int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void* init_records(void* arg) {
    long* offsets = malloc(NUM_RECORDS * sizeof(long));
    int* keys = malloc(NUM_RECORDS * sizeof(int));
    record* recs = malloc(NUM_RECORDS * sizeof(record));

    if (!offsets || !keys || !recs) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_RECORDS; i++) {
        offsets[i] = generate_random(0, 1000000);
        keys[i] = generate_random(0, 9999);
        recs[i].value = generate_random(0, 9999);

        if (i % SEED_INTERVAL == 0) {
            reseed_prng();
        }
    }

    long_offsets = offsets;
    int_keys = keys;
    records = recs;

    return NULL;
}

void validate_records() {
    // Placeholder for statistical validation logic
    printf("Validation logic goes here\n");
}

int main() {
    pthread_t thread;
    pthread_mutex_init(&mutex, NULL);

    if (pthread_create(&thread, NULL, init_records, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        exit(EXIT_FAILURE);
    }

    if (pthread_join(thread, NULL) != 0) {
        fprintf(stderr, "Failed to join thread\n");
        exit(EXIT_FAILURE);
    }

    validate_records();

    free(long_offsets);
    free(int_keys);
    free(records);

    pthread_mutex_destroy(&mutex);

    return 0;
}
