typedef struct {
    long timestamp;
    int identifier;
} record;

typedef struct {
    char* message;
    uint32_t event_type;
} event;

typedef struct {
    record** records;
    event** events;
    int num_events;
} session;

session* create_session(int num_events, int record_size) {
    if (num_events <= 0 || record_size <= 0) {
        return NULL; // Invalid input
    }

    session* s = malloc(sizeof(session));
    if (!s) {
        return NULL; // Memory allocation failed
    }

    s->records = malloc(num_events * sizeof(record*));
    if (!s->records) {
        free(s);
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_events; ++i) {
        record* r = malloc(sizeof(record));
        if (!r) {
            // Free previously allocated records
            for (int j = 0; j < i; ++j) {
                free(s->records[j]);
            }
            free(s->records);
            free(s);
            return NULL; // Memory allocation failed
        }
        s->records[i] = r;
    }

    s->events = malloc(num_events * sizeof(event*));
    if (!s->events) {
        // Free previously allocated records
        for (int i = 0; i < num_events; ++i) {
            free(s->records[i]);
        }
        free(s->records);
        free(s);
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_events; ++i) {
        event* e = malloc(sizeof(event));
        if (!e) {
            // Free previously allocated records and events
            for (int j = 0; j < num_events; ++j) {
                free(s->records[j]);
                if (j < i) {
                    free(s->events[j]);
                }
            }
            free(s->records);
            free(s->events);
            free(s);
            return NULL; // Memory allocation failed
        }

        e->message = malloc(record_size * sizeof(char));
        if (!e->message) {
            // Free previously allocated records, events, and message
            for (int j = 0; j < num_events; ++j) {
                free(s->records[j]);
                if (j < i) {
                    free(s->events[j]->message);
                    free(s->events[j]);
                }
            }
            free(s->records);
            free(s->events);
            free(s);
            return NULL; // Memory allocation failed
        }

        e->timestamp = time(NULL);
        e->event_type = (uint32_t)rand();

        s->events[i] = e;
    }

    s->num_events = num_events;

    return s;
}
