#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MAX_CONFIGS 50

typedef struct {
    int value;
} Record;

typedef struct {
    double probability;
    char* config_name;
    short status_code;
} Config;

typedef struct {
    void* memory_pool;
    size_t pool_size;
    size_t used_memory;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->memory_pool = malloc(initial_size);
    pool->pool_size = initial_size;
    pool->used_memory = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    void* ptr;
    pthread_mutex_lock(&pool->lock);
    if (pool->used_memory + size > pool->pool_size) {
        // Resize the pool dynamically
        pool->memory_pool = realloc(pool->memory_pool, pool->pool_size * 2);
        pool->pool_size *= 2;
    }
    ptr = (char*)pool->memory_pool + pool->used_memory;
    pool->used_memory += size;
    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

void initialize_data_structures(MemoryPool* pool, long* offsets, int* keys, Record* records, Config* configs) {
    srand(time(NULL)); // Seed the random number generator

    // Allocate and initialize arrays
    for (int i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = rand();
        keys[i] = rand();
        records[i].value = rand() % 100; // Random value between 0 and 99
    }

    // Allocate memory for configuration names using the custom memory pool
    char* config_names[MAX_CONFIGS];
    for (int i = 0; i < MAX_CONFIGS; i++) {
        config_names[i] = (char*)allocate_from_pool(pool, 256); // Assuming max name length of 255
        snprintf(config_names[i], 256, "Config_%d", rand() % 100);
    }

    // Initialize configuration structures
    for (int i = 0; i < MAX_CONFIGS; i++) {
        configs[i].probability = (double)rand() / RAND_MAX;
        configs[i].config_name = config_names[i];
        configs[i].status_code = rand() % 10; // Random status code between 0 and 9
    }
}

int main() {
    MemoryPool* pool = create_memory_pool(1024 * 1024); // Initial pool size of 1MB
    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];
    Record records[MAX_RECORDS];
    Config configs[MAX_CONFIGS];

    initialize_data_structures(pool, offsets, keys, records, configs);

    // Clean up
    for (int i = 0; i < MAX_CONFIGS; i++) {
        free((char*)configs[i].config_name); // Free memory allocated for configuration names
    }
    free(configs);
    free(records);
    pthread_mutex_destroy(&pool->lock);
    free(pool->memory_pool);
    free(pool);

    return 0;
}
