    return (seed * 1103515245 + 12345) % 2147483648;
}

void* allocate_records(void* arg) {
    int num_records = *(int*)arg;
    struct record* records = (struct record*)malloc(RECORD_SIZE * num_records);

    if (records == NULL) {
        perror("Failed to allocate memory");
        return NULL;
