    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].offset = i;
        records[i].key = custom_prng(rand());
        records[i].timestamp = time(NULL);
    }

    // Simulate record operations
    for (int i = 0; i < num_records; i++) {
        printf("Record %d: Key=%d, Timestamp=%.2f\n", i, records[i].key, records[i].timestamp);
        usleep(1000); // Simulate processing time
    }

    free(records);
    return NULL;
}

