['```rust
use tokio::task;
use std::time::{SystemTime, UNIX_EPOCH};
use rand::Rng;

#[derive(Debug)]
struct Record {
    offset: u64,
    key: i32,
    timestamp: f64,
}

fn generate_records(num_records: usize) -> Vec<Record> {
    let start_time = SystemTime::now();
    let mut rng = rand::XorShiftRng::from_seed([0; 16]); // Using XorShift for simplicity

    (0..num_records).map(|i| {
        let offset = i as u64;
        let key = rng.gen_range(-1000..=1000);
        let timestamp = start_time.duration_since(UNIX_EPOCH).unwrap().as_secs_f64() + (i as f64 * 0.1);

        Record { offset, key, timestamp }
    }).collect()
}

#[tokio::main]
async fn main() {
    let num_records: usize = std::env::args().nth(1).expect("Please provide a number of records").parse().unwrap();

    let records = generate_records(num_records);

    // Simulate asynchronous processing
    task::spawn(async move {
        for record in records {
            println!("Processing record {:?}", record);
            // Simulate some async operation
            tokio::time::sleep(tokio::time::Duration::from_secs(1)).await;
        }
    }).await.unwrap();
}
