typedef struct {
    long timestamp;
    int identifier;
} record;

typedef struct {
    char* message;
    uint32_t event_type;
} event;

typedef struct {
    record** records;
    int record_count;
    pthread_mutex_t record_lock;

    event** events;
    int event_count;
    pthread_mutex_t event_lock;

    session* session_ptr;
    pthread_mutex_t session_lock;
} session;

session* manage_memory(int num_events) {
    if (num_events <= 0) {
        return NULL; // Handle invalid input
    }

    session* sess = malloc(sizeof(session));
    if (!sess) {
        return NULL; // Memory allocation failed
    }
    memset(sess, 0, sizeof(session));

    pthread_mutex_init(&sess->record_lock, NULL);
    pthread_mutex_init(&sess->event_lock, NULL);
    pthread_mutex_init(&sess->session_lock, NULL);

    sess->records = malloc(num_events * sizeof(record*));
    if (!sess->records) {
        free(sess);
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_events; i++) {
        record* rec = malloc(sizeof(record));
        if (!rec) {
            // Handle partial allocation
            for (int j = 0; j < i; j++) {
                free(sess->records[j]);
            }
            free(sess->records);
            pthread_mutex_destroy(&sess->record_lock);
            pthread_mutex_destroy(&sess->event_lock);
            pthread_mutex_destroy(&sess->session_lock);
            free(sess);
            return NULL;
        }
        sess->records[i] = rec;

        rec->timestamp = time(NULL); // Initialize timestamp
        rec->identifier = i; // Assign identifier
    }

    sess->events = malloc(num_events * sizeof(event*));
    if (!sess->events) {
        for (int i = 0; i < num_events; i++) {
            free(sess->records[i]);
        }
        free(sess->records);
        pthread_mutex_destroy(&sess->record_lock);
        pthread_mutex_destroy(&sess->event_lock);
        pthread_mutex_destroy(&sess->session_lock);
        free(sess);
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_events; i++) {
        event* eve = malloc(sizeof(event));
        if (!eve) {
            // Handle partial allocation
            for (int j = 0; j <= i; j++) {
                free(sess->records[j]);
                free(sess->events[j]);
            }
            free(sess->records);
            free(sess->events);
            pthread_mutex_destroy(&sess->record_lock);
            pthread_mutex_destroy(&sess->event_lock);
            pthread_mutex_destroy(&sess->session_lock);
            free(sess);
            return NULL;
        }
        sess->events[i] = eve;

        eve->message = strdup("Event Message"); // Initialize message
        if (!eve->message) {
            for (int j = 0; j <= i; j++) {
                free(sess->records[j]);
                free(sess->events[j]);
            }
            free(sess->records);
            free(sess->events);
            pthread_mutex_destroy(&sess->record_lock);
            pthread_mutex_destroy(&sess->event_lock);
            pthread_mutex_destroy(&sess->session_lock);
            free(sess);
            return NULL; // Memory allocation failed
        }

        uint32_t random_type = (uint32_t)rand(); // Generate event type using PRNG
        eve->event_type = random_type;
    }

    sess->record_count = num_events;
    sess->event_count = num_events;

    return sess;
}

void free_memory(session* sess) {
    if (!sess) {
        return; // Handle invalid input
    }

    pthread_mutex_lock(&sess->record_lock);
    for (int i = 0; i < sess->record_count; i++) {
        free(sess->records[i]);
    }
    free(sess->records);
    pthread_mutex_unlock(&sess->record_lock);

    pthread_mutex_lock(&sess->event_lock);
    for (int i = 0; i < sess->event_count; i++) {
        free(sess->events[i]->message);
        free(sess->events[i]);
    }
    free(sess->events);
    pthread_mutex_unlock(&sess->event_lock);

    pthread_mutex_destroy(&sess->record_lock);
    pthread_mutex_destroy(&sess->event_lock);
    pthread_mutex_destroy(&sess->session_lock);

    free(sess);
}
