    int sessionID;
    char sessionData[MAX_SESSION_DATA_SIZE];
    int dataValue;
} session;

session* createSession(int* size, int newSessions) {
    static int nextID = 1;
    session* sessions = realloc(*size ? *size + newSessions : newSessions, sizeof(session));

    if (sessions == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    time_t now = time(NULL);
    for (int i = *size; i < *size + newSessions; i++) {
        sessions[i].timestamp = now;
        sessions[i].sessionID = nextID++;
        strcpy(sessions[i].sessionData, "Default Data");
        sessions[i].dataValue = rand() % 1000; // Fast PRNG for data value
    }

    *size += newSessions;
    return sessions;
}

void freeSessions(session* sessions, int* size) {
    free(sessions);
    *size = 0;
}
