unsigned long xorshift64star(unsigned long *state) {
    unsigned long x = *state;
    x ^= x >> 12;
    x ^= x << 25;
    x ^= x >> 27;
    return (*state = x) * 0x2545F4914F6CDD1DL;
}

unsigned long custom_rand(unsigned long *state, unsigned long min, unsigned long max) {
    unsigned long range = max - min + 1;
    unsigned long value = xorshift64star(state) % range;
    return min + value;
}

int initialize_arrays(long **timestamps, int **event_keys, event_record **records, size_t count) {
    srand(time(NULL));

    *timestamps = (long *)malloc(count * sizeof(long));
    *event_keys = (int *)malloc(count * sizeof(int));
