void init_logging_system() {
    srand(time(NULL) ^ getpid());

    timestamp_offsets = (long *)malloc(NUM_ENTRIES * sizeof(long));
    unique_ids = (unsigned int *)malloc(NUM_ENTRIES * sizeof(unsigned int));
    events = (event_info *)malloc(NUM_ENTRIES * sizeof(event_info));
    configs = (config_param *)malloc(NUM_ENTRIES * sizeof(config_param));

    if (!timestamp_offsets || !unique_ids || !events || !configs) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    for (int i = 0; i < NUM_ENTRIES; i++) {
        timestamp_offsets[i] = rand_r(&srand) % 1000000000L;
        unique_ids[i] = rand_r(&srand) & 0xFFFFFFFF;
        snprintf(events[i].message, sizeof(events[i].message), "Event %d", i);
        events[i].frequency = rand_r(&srand) % 10 + 1;
        snprintf(configs[i].buffer, sizeof(configs[i].buffer), "Config %d", i);
        configs[i].config_id = rand_r(&srand) & 0xFFFFFFFF;
    }
}

void free_logging_system() {
    free(timestamp_offsets);
    free(unique_ids);
    free(events);
    free(configs);
}
