// Function to initialize the arrays with pseudo-random values
void initialize_arrays(long *offsets, int *keys, record **records, long offset_size, int key_range) {
    if (offset_size <= 0 || key_range <= 0) {
        fprintf(stderr, "Error: Invalid input size or range\n");
        return;
    }

    // Initialize random seed
    srand(time(NULL));

    // Allocate memory for arrays
    offsets = (long *)malloc(offset_size * sizeof(long));
    keys = (int *)malloc((offset_size / 2) * sizeof(int));
    records = (record **)malloc(offset_size * sizeof(record *));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return;
    }

    // Initialize offsets
    for (long i = 0; i < offset_size; ++i) {
        offsets[i] = rand() % (offset_size * 10); // Example initialization logic
    }

    // Initialize keys with unique random values
    int used_keys[key_range];
    for (int i = 0; i < key_range; ++i) {
        used_keys[i] = 0;
    }

    int key_index = 0;
    for (long i = 0; i < offset_size / 2; ++i) {
        while (used_keys[keys[key_index]]) { // Ensure unique keys
            keys[key_index] = rand() % key_range;
        }
        used_keys[keys[key_index]] = 1;
        key_index++;
    }

    // Initialize records with pseudo-random values within a specified range
    for (long i = 0; i < offset_size; ++i) {
        records[i] = (record *)malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            return;
        }
        records[i]->value = rand() % key_range; // Example initialization logic
    }
}

int main() {
    long offset_size = 100;
    int key_range = 50;

    long *offsets = NULL;
    int *keys = NULL;
    record **records = NULL;

    initialize_arrays(offsets, keys, records, offset_size, key_range);

    // Free allocated memory
    for (long i = 0; i < offset_size; ++i) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);

    return 0;
}
