#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_RECORDS 1024

typedef struct {
    int key;
} record;

record* records[MAX_RECORDS];
long offsets[MAX_RECORDS];
int current_size = 0;
int max_size = MAX_RECORDS;
pthread_mutex_t lock;

void initialize_record_array(int initial_size) {
    if (initial_size > max_size) {
        fprintf(stderr, "Initial size exceeds maximum allowed.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < initial_size; i++) {
        records[i] = malloc(sizeof(record));
        offsets[i] = -1;
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record %d.\n", i);
            exit(EXIT_FAILURE);
        }
    }
    current_size = initial_size;
}

void* generate_random_values(void* arg) {
    pthread_mutex_lock(&lock);
    srand(time(NULL) ^ getpid());
    for (int i = 0; i < current_size; i++) {
        records[i]->key = rand() % ((int)arg + 1);
        offsets[i] = (long)records[i];
        log_event("Random value generated: key=%d, offset=%ld", records[i]->key, offsets[i]);
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

void verify_memory_integrity() {
    for (int i = 0; i < current_size; i++) {
        if (!records[i]) {
            fprintf(stderr, "Memory integrity check failed: record %d is NULL.\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

void set_max_records(int new_max) {
    pthread_mutex_lock(&lock);
    if (new_max > MAX_RECORDS) {
        fprintf(stderr, "New max size exceeds maximum allowed.\n");
        exit(EXIT_FAILURE);
    }
    max_size = new_max;
    pthread_mutex_unlock(&lock);
}

int main() {
    pthread_t thread_id;
    initialize_record_array(10);
    pthread_create(&thread_id, NULL, generate_random_values, (void*)100);
    pthread_join(thread_id, NULL);
    verify_memory_integrity();
    set_max_records(2048);
    return 0;
}
