#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double timestamp;
} record;

record* create_records(int n) {
    return (record*)malloc(n * sizeof(record));
}

void free_records(record* records, int n) {
    free(records);
}

int random_in_range(int min, int max) {
    static unsigned seed = 0;
    if (seed == 0) {
        seed = time(NULL); // Initialize seed with current time
    }
    return min + (rand_r(&seed) % (max - min + 1));
}

void initialize_records(record* records, int n, long offset_start) {
    for (int i = 0; i < n; ++i) {
        records[i].offset = offset_start + i;
        records[i].key = random_in_range(1, 100); // Adjust range as needed
        records[i].timestamp = time(NULL);
    }
}

void log_operation(const char* operation, int index, record* rec) {
    FILE* log_file = fopen("record_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s: Index %d, Offset %ld, Key %d, Timestamp %.2f\n", 
                operation, index, rec->offset, rec->key, rec->timestamp);
        fclose(log_file);
    }
}

void* update_record(void* arg) {
    record* records = (record*)arg;
    int n = 100; // Example number of updates
    for (int i = 0; i < n; ++i) {
        int index = random_in_range(0, n - 1);
        pthread_mutex_lock(&records[index].mutex);
        records[index].key = random_in_range(1, 100); // Adjust range as needed
        records[index].timestamp = time(NULL);
        log_operation("Update", index, &records[index]);
        pthread_mutex_unlock(&records[index].mutex);
    }
    return NULL;
}

int main() {
    int n = 1000; // Number of records
    record* records = create_records(n);

    initialize_records(records, n, 0);

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, update_record, records);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_records(records, n);

    return 0;
}
