void generate_unique_identifier(char *identifier, int length) {
    static const char alphanumeric[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    for (int i = 0; i < length; ++i) {
        identifier[i] = alphanumeric[rand() % sizeof(alphanumeric) - 1];
    }
    identifier[length] = '\0';
}

data_entry* initialize_data_entries(int num_entries, int *timestamps, float *values) {
    if (num_entries <= 0) return NULL;

    srand(time(NULL)); // Seed PRNG with system time

    data_entry *head = NULL;
    data_entry *current = NULL;

    for (int i = 0; i < num_entries; ++i) {
        data_entry *new_node = (data_entry *)malloc(sizeof(data_entry));
        if (!new_node) return NULL; // Handle memory allocation failure

        generate_unique_identifier(new_node->identifier, MAX_IDENTIFIER_LENGTH);

        new_node->next = NULL;
        if (i == 0) head = new_node;
        else current->next = new_node;

        current = new_node;
    }

    return head;
}

void free_data_entries(data_entry *head) {
    data_entry *current = head;
    while (current != NULL) {
        data_entry *temp = current;
        current = current->next;
        free(temp);
    }
}

int main() {
    int num_timestamps = 10;
    long timestamps[num_timestamps];
    float values[num_timestamps / 3];

    // Initialize timestamp and value arrays
    for (int i = 0; i < num_timestamps; ++i) {
        timestamps[i] = time(NULL) + i;
        values[i / 3] = (float)i * 1.23f;
    }

    data_entry *head = initialize_data_entries(num_timestamps, timestamps, values);
    if (!head) {
        fprintf(stderr, "Failed to initialize data entries.\n");
        return EXIT_FAILURE;
    }

    // Use the linked list as needed...

    free_data_entries(head);

    return EXIT_SUCCESS;
}
