#define MAX_SESSIONS 1000000
#define SESSION_DATA_SIZE 256

typedef struct {
    long timestamp;
    int sessionId;
    char sessionData[SESSION_DATA_SIZE];
    int metadata;
} Session;

Session* sessions = NULL;
int sessionCount = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initializeSessions() {
    sessions = (Session*)malloc(MAX_SESSIONS * sizeof(Session));
    if (!sessions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void destroySessions() {
    free(sessions);
}

long getOptimizedTime() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000; // milliseconds
}

int generateSessionId() {
    static int seed = time(NULL);
    pthread_mutex_lock(&lock);
    seed = (seed * 214013 + 2531011) % 0x7FFFFFFF;
    int sessionId = seed % MAX_SESSIONS;
    pthread_mutex_unlock(&lock);
    return sessionId;
}

void initializeSession(int index, int metadata) {
    Session* session = &sessions[index];
    session->timestamp = getOptimizedTime();
    session->sessionId = generateSessionId();
    snprintf(session->sessionData, SESSION_DATA_SIZE, "Default Data");
    session->metadata = metadata;
}

void resizeSessions() {
    int newCapacity = MAX_SESSIONS * 2;
    Session* newSessions = (Session*)realloc(sessions, newCapacity * sizeof(Session));
    if (!newSessions) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    sessions = newSessions;
    MAX_SESSIONS = newCapacity;
}

void addSession(int metadata) {
    pthread_mutex_lock(&lock);
    if (sessionCount >= MAX_SESSIONS) {
        resizeSessions();
    }
    initializeSession(sessionCount, metadata);
    sessionCount++;
    pthread_mutex_unlock(&lock);
}

void refreshPrngSeed() {
    pthread_mutex_lock(&lock);
    srand(time(NULL));
    pthread_mutex_unlock(&lock);
}

void handleAllocationFailure() {
    fprintf(stderr, "Memory allocation failed\n");
    exit(EXIT_FAILURE);
}
