record* manageSessions(int* offsets, int numOffsets, int keyRange) {
    if (numOffsets <= 0 || keyRange <= 0) return NULL;

    record* sessions = malloc(numOffsets * sizeof(record));
    if (!sessions) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < numOffsets; i++) {
        sessions[i].timestamp = time(NULL);
        sessions[i].sessionID = rand() % INT_MAX;
        strcpy(sessions[i].sessionData, "Default Data");
        sessions[i].randomValue = rand() % keyRange;
    }

    return sessions;
}

int* readOffsetsFromFile(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    int numOffsets;
    fscanf(file, "%d", &numOffsets);
    int* offsets = malloc(numOffsets * sizeof(int));
    if (!offsets) {
        fclose(file);
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < numOffsets; i++) {
        if (fscanf(file, "%ld,", &offsets[i]) != 1) {
            free(offsets);
            fclose(file);
            perror("Invalid data in file");
            return NULL;
        }
    }

    fclose(file);
    return offsets;
}

int main() {
    const char* filename = "offsets.txt";
    int* offsets = readOffsetsFromFile(filename);
    if (!offsets) return 1;

    record* sessions = manageSessions(offsets, strlen((char*)offsets), 1000);
    if (!sessions) {
        free(offsets);
        return 1;
    }

    // Process sessions...

    free(sessions);
    free(offsets);

    return 0;
}
