#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Custom PRNG function using a linear congruential generator for speed
unsigned long custom_prng(unsigned long *seed) {
    *seed = (*seed * 1664525 + 1013904223) % UINT_MAX;
    return *seed;
}

// Function to allocate and initialize arrays and records
int initialize_records(record **records, int *offsets, long **keys, int num_records, int range_start, int range_end, unsigned long seed) {
    if (range_end <= range_start || (range_end - range_start) < 10) {
        fprintf(stderr, "Invalid range for random numbers.\n");
        return -1;
    }

    *records = (record *)malloc(num_records * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        return -1;
    }

    *offsets = (int *)malloc(num_records * sizeof(int));
    if (*offsets == NULL) {
        free(*records);
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return -1;
    }

    *keys = (long *)malloc(num_records * sizeof(long));
    if (*keys == NULL) {
        free(*offsets);
        free(*records);
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return -1;
    }

    for (int i = 0; i < num_records; i++) {
        (*keys)[i] = seed;
        custom_prng(&seed);
        (*records)[i].value = range_start + custom_prng(&seed) % (range_end - range_start + 1);
    }

    return 0;
}

// Function to free allocated memory
void free_records(record *records, int *offsets, long *keys, int num_records) {
    if (records != NULL) free(records);
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
}
