            log_message(log_file, "Failed to allocate memory for config name.");
            for (size_t j = 0; j < i; ++j) {
                free(arr[j].name);
            }
            free(arr);
            return NULL;
        }
        snprintf(arr[i].name, 256, "Config %zu", i);
    }

    log_message(log_file, "Config array initialized successfully.");
    return arr;
}

void cleanup_resources(long* long_arr, char** char_arr, config* config_arr, FILE* log_file) {
    if (log_file) {
        fclose(log_file);
    }
    free(long_arr);
    for (size_t i = 0; i < char_size; ++i) {
        free(char_arr[i]);
    }
    free(char_arr);
    for (size_t i = 0; i < config_size; ++i) {
