#define NUM_RECORDS 5

typedef struct {
    double probability;
    char* name;
} config;

unsigned long custom_prng(unsigned long seed) {
    // Implement a simple non-cryptographic PRNG for performance
    return (seed * 1103515245 + 12345) % 4294967296;
}

int allocate_and_initialize_data(char*** char_array, long*** long_array, config** config_array,
                                long*** offset_array, int*** key_array, unsigned long seed) {
    *char_array = (char**)malloc(NUM_RECORDS * sizeof(char*));
    *long_array = (long**)malloc(NUM_RECORDS * sizeof(long*));
    *config_array = (config*)malloc(NUM_RECORDS * sizeof(config));
    *offset_array = (long**)malloc(NUM_RECORDS * sizeof(long*));
    *key_array = (int**)malloc(NUM_RECORDS * sizeof(int*));

    if (!(*char_array) || !(*long_array) || !(*config_array) || !(*offset_array) || !(*key_array)) {
        return 0; // Memory allocation failed
    }

    long offset = 0;
    int key;

    for (int i = 0; i < NUM_RECORDS; i++) {
        (*char_array)[i] = (char*)malloc(256 * sizeof(char));
        (*long_array)[i] = (long*)malloc(sizeof(long));
        (*offset_array)[i] = (long*)malloc(sizeof(long));
        (*key_array)[i] = (int*)malloc(sizeof(int));

        if (!(*char_array)[i] || !(*long_array)[i] || !(*offset_array)[i] || !(*key_array)[i]) {
            // Free previously allocated memory in case of failure
            for (int j = 0; j < i; j++) {
                free((*char_array)[j]);
                free((*long_array)[j]);
                free((*offset_array)[j]);
                free((*key_array)[j]);
            }
            free(*char_array);
            free(*long_array);
            free(*config_array);
            free(*offset_array);
            free(*key_array);
            return 0; // Memory allocation failed
        }

        (*config_array)[i].probability = (double)custom_prng(seed + i) / 4294967295.0;
        snprintf((*config_array)[i].name, 256, "Config%ld", i);

        while (1) {
            key = custom_prng(seed + i * 100) % 100; // Generate a random key
            if (!find_key(*key_array, i - 1, key)) break; // Ensure uniqueness
        }

        seed = custom_prng(seed); // Update the seed for next iteration

        (*long_array)[i][0] = (long)custom_prng(seed + i * 200);
        (*offset_array)[i][0] = offset;
        (*key_array)[i][0] = key;

        offset += sizeof(long);
    }

    return 1; // Success
}

// Helper function to check if a key is already in use
int find_key(int** keys, int count, int key) {
    for (int i = 0; i <= count; i++) {
        if (keys[i][0] == key) return 0;
    }
    return 1;
}

// Main function to demonstrate the usage of allocate_and_initialize_data
int main() {
    char** char_array;
    long** long_array;
    config* config_array;
    long** offset_array;
    int** key_array;

    unsigned long seed = time(NULL);
    int success = allocate_and_initialize_data(&char_array, &long_array, &config_array,
                                             &offset_array, &key_array, seed);

    if (success) {
        printf("Data initialized successfully.\n");
        // Free allocated memory when done
        for (int i = 0; i < NUM_RECORDS; i++) {
            free(char_array[i]);
            free(long_array[i]);
            free(offset_array[i]);
            free(key_array[i]);
        }
        free(char_array);
        free(long_array);
        free(config_array);
        free(offset_array);
        free(key_array);
    } else {
        printf("Failed to initialize data.\n");
    }

    return 0;
}
