void DynamicMemoryManager(int* longArray, int arraySize, int primeMultiple, long long* intArray, double* doubleArray, Record** recordArray, int recordCount, int minIntValue, int maxIntValue) {
    // Allocate memory for arrays
    *longArray = (int*)malloc(arraySize * sizeof(int));
    *intArray = (long long*)malloc(arraySize * sizeof(long long));
    *doubleArray = (double*)malloc(arraySize * sizeof(double));

    if (*longArray == NULL || *intArray == NULL || *doubleArray == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Initialize arrays
    srand(time(NULL)); // Seed for PRNG
    for (int i = 0; i < arraySize; i++) {
        (*longArray)[i] = i * primeMultiple;
        (*intArray)[i] = minIntValue + rand() % (maxIntValue - minIntValue + 1);
        (*doubleArray)[i] = ((double)rand()) / RAND_MAX;
    }

    // Allocate memory for record array
    *recordArray = (Record*)malloc(recordCount * sizeof(Record));
    if (*recordArray == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Initialize record array with random values and probabilities
    srand(time(NULL)); // Seed for PRNG
    for (int i = 0; i < recordCount; i++) {
        (*recordArray)[i].value = minIntValue + rand() % (maxIntValue - minIntValue + 1);
        (*recordArray)[i].id = i * primeMultiple;
        (*recordArray)[i].probability = ((double)rand()) / RAND_MAX;
    }
}

// Example usage
