    s->timestamp = current_time;

    // Pseudo-random number generator for session ID
    *session_id_counter += 1;
    s->session_id = (*session_id_counter) % INT_MAX;

    // Initialize default data
    snprintf(s->data, DEFAULT_DATA_SIZE, "Default Data");
}

record* create_record_array(int size) {
