#define DEFAULT_TASK_DETAILS "No details available"
#define MAX_TASK_DETAILS_LENGTH 256

typedef struct {
    long timestamp;
    int task_id;
    char details[MAX_TASK_DETAILS_LENGTH];
} Task;

typedef struct {
    int progress;
} Status;

void initialize_tasks(Task** tasks, size_t* size, size_t capacity) {
    if (*tasks == NULL) {
        *size = 0;
        *capacity = 10; // Initial capacity
        *tasks = (Task*)malloc(*capacity * sizeof(Task));
        if (*tasks == NULL) {
            perror("Failed to allocate memory for tasks");
            exit(EXIT_FAILURE);
        }
    }

    time_t current_time = time(NULL);
    srand(current_time); // Seed PRNG with current time

    for (size_t i = *size; i < capacity; ++i) {
        (*tasks)[i].timestamp = current_time;
        (*tasks)[i].task_id = rand(); // Pseudo-random task ID
        strncpy((*tasks)[i].details, DEFAULT_TASK_DETAILS, MAX_TASK_DETAILS_LENGTH - 1);
    }

    *size = capacity;
}

void initialize_statuses(Status** statuses, size_t* size, size_t capacity) {
    if (*statuses == NULL) {
        *size = 0;
        *capacity = 10; // Initial capacity
        *statuses = (Status*)malloc(*capacity * sizeof(Status));
        if (*statuses == NULL) {
            perror("Failed to allocate memory for statuses");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = *size; i < capacity; ++i) {
        (*statuses)[i].progress = rand() % 100; // Random progress between 0 and 99
    }

    *size = capacity;
}

void resize_array(void** array, size_t* size, size_t new_capacity) {
    void* new_array = realloc(*array, new_capacity);
    if (new_array == NULL) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    *array = new_array;
    *size = new_capacity;
}

void manage_task_memory(Task** tasks, Status** statuses, size_t* task_size, size_t* status_size, size_t desired_size) {
    if (desired_size > *task_size) {
        resize_array((void**)tasks, task_size, desired_size);
    }
    if (desired_size > *status_size) {
        resize_array((void**)statuses, status_size, desired_size);
    }

    initialize_tasks(tasks, task_size, desired_size);
    initialize_statuses(statuses, status_size, desired_size);
}
