#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    struct Record *next;
} Record;

typedef struct ArrayManager {
    long *offsets;
    int *keys;
    Record **records;
    size_t capacity;
    size_t size;
} ArrayManager;

ArrayManager* create_array_manager(size_t initial_capacity) {
    ArrayManager *manager = (ArrayManager*)malloc(sizeof(ArrayManager));
    if (!manager) return NULL;

    manager->offsets = (long*)calloc(initial_capacity, sizeof(long));
    manager->keys = (int*)calloc(initial_capacity, sizeof(int));
    manager->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    manager->capacity = initial_capacity;
    manager->size = 0;

    if (!manager->offsets || !manager->keys || !manager->records) {
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        free(manager);
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG

    return manager;
}

void destroy_array_manager(ArrayManager *manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        Record *current = manager->records[i];
        while (current) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager);
}

void resize_array_manager(ArrayManager *manager, size_t new_capacity) {
    long *new_offsets = (long*)realloc(manager->offsets, new_capacity * sizeof(long));
    int *new_keys = (int*)realloc(manager->keys, new_capacity * sizeof(int));
    Record **new_records = (Record**)realloc(manager->records, new_capacity * sizeof(Record*));

    if (!new_offsets || !new_keys || !new_records) {
        // Handle realloc failure
        free(new_offsets);
        free(new_keys);
        free(new_records);
        return;
    }

    manager->offsets = new_offsets;
    manager->keys = new_keys;
    manager->records = new_records;
    manager->capacity = new_capacity;
}

Record* insert_record(ArrayManager *manager, int key) {
    if (manager->size == manager->capacity) {
        resize_array_manager(manager, manager->capacity * 2);
    }

    Record *new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return NULL;

    new_record->value = rand() % 100; // Random value in the range [0, 99]
    new_record->next = manager->records[key % manager->capacity];
    manager->records[key % manager->capacity] = new_record;
    manager->keys[manager->size++] = key;

    return new_record;
}

Record* find_record(ArrayManager *manager, int key) {
    for (int i = 0; i < manager->size; ++i) {
        Record *current = manager->records[i];
        while (current) {
            if (current->key == key) {
                return current;
            }
            current = current->next;
        }
    }

    return NULL;
}

void delete_record(ArrayManager *manager, int key) {
    for (int i = 0; i < manager->size; ++i) {
        Record **current_ptr = &manager->records[i];
        while (*current_ptr) {
            Record *current = *current_ptr;
            if (current->key == key) {
                *current_ptr = current->next;
                free(current);
                break;
            }
            current_ptr = &current->next;
        }
    }

    // Rehash the keys to maintain integrity
    for (int i = 0; i < manager->size; ++i) {
        Record **new_record_ptr = &manager->records[manager->keys[i] % manager->capacity];
        *new_record_ptr = manager->records[i];
    }
}

void reset_prng() {
    srand(time(NULL)); // Seed the PRNG
}

// Example usage:
int main() {
    ArrayManager *manager = create_array_manager(10);
    if (!manager) return 1;

    insert_record(manager, 123);
    Record *record = find_record(manager, 123);
    delete_record(manager, 123);

    destroy_array_manager(manager);
    return 0;
}
```

This code provides a basic structure for managing three arrays and a linked list of records with dynamic resizing. It uses the standard library's `rand()` function as a simple PRNG, which is suitable for non-security-sensitive applications. The example usage in the `main` function demonstrates how to create an instance, insert, find, and delete records."]

