#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_USER_IDS 1000
#define RETRY_LIMIT 10

typedef struct {
    long offset;
    int key;
    int userID;
} record;

record* allocate_user_ids(long* offsets, int* keys, int num_records) {
    if (num_records > MAX_USER_IDS) {
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];

        int retry_count = 0;
        while (retry_count < RETRY_LIMIT) {
            records[i].userID = rand() % MAX_USER_IDS;
            bool is_unique = true;

            for (int j = 0; j < i && is_unique; ++j) {
                if (records[j].userID == records[i].userID) {
                    is_unique = false;
                }
            }

            if (is_unique) {
                break;
            }

            retry_count++;
        }

        if (retry_count >= RETRY_LIMIT) {
            free(records);
            return NULL;
        }
    }

    return records;
}
```

