typedef struct Record {
    int value;
    unsigned long id;
} Record;

typedef struct Dataset {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Dataset;

Dataset* create_dataset(size_t initial_capacity) {
    Dataset* dataset = (Dataset*)malloc(sizeof(Dataset));
    if (!dataset) return NULL;

    dataset->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!dataset->records) {
        free(dataset);
        return NULL;
    }

    dataset->capacity = initial_capacity;
    dataset->size = 0;
    pthread_mutex_init(&dataset->lock, NULL);

    return dataset;
}

void destroy_dataset(Dataset* dataset) {
    if (dataset->records) {
        free(dataset->records);
    }
    pthread_mutex_destroy(&dataset->lock);
    free(dataset);
}

int add_record(Dataset* dataset, int value) {
    pthread_mutex_lock(&dataset->lock);

    if (dataset->size == dataset->capacity) {
        size_t new_capacity = dataset->capacity ? dataset->capacity * 2 : 1;
        Record* new_records = (Record*)realloc(dataset->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&dataset->lock);
            return -1; // Allocation failure
        }
        dataset->records = new_records;
        dataset->capacity = new_capacity;
    }

    dataset->records[dataset->size].value = value;
    dataset->records[dataset->size].id = dataset->size + 1; // Simple unique ID generation
    dataset->size++;

    pthread_mutex_unlock(&dataset->lock);
    return 0;
}

int get_record_value(Dataset* dataset, unsigned long id) {
    pthread_mutex_lock(&dataset->lock);

    for (size_t i = 0; i < dataset->size; i++) {
        if (dataset->records[i].id == id) {
            int value = dataset->records[i].value;
            pthread_mutex_unlock(&dataset->lock);
            return value;
        }
    }

    pthread_mutex_unlock(&dataset->lock);
    return -1; // Record not found
}
