Transaction* allocate_transaction(int size, User **users, int user_count) {
    Transaction *transactions = (Transaction*)malloc(size * sizeof(Transaction));
    if (!transactions) {
        log_memory_allocation("Allocation failed", size);
        return NULL;
    }
    for (int i = 0; i < size; ++i) {
        transactions[i].user_profile = users[rand() % user_count];
        transactions[i].timestamp = time(NULL);
        transactions[i].amount = rand() / (double)RAND_MAX * 1000.0;
        snprintf(transactions[i].description, sizeof(transactions[i].description), "Transaction %d", i);
    }
    log_memory_allocation("Transaction allocation successful", size * sizeof(Transaction));
    return transactions;
}

void free_resources(Session **sessions, User **users, Transaction **transactions) {
    for (int i = 0; sessions && i < session_count; ++i) {
        free(sessions[i]);
    }
    for (int i = 0; users && i < user_count; ++i) {
        free(users[i]->session_id);
        free(users[i]);
    }
    for (int i = 0; transactions && i < transaction_count; ++i) {
        free(transactions[i]);
    }
}

void manage_memory(int session_count, int user_count, int transaction_count) {
    Session *sessions = allocate_session(session_count);
    User *users = allocate_user(user_count);
    Transaction *transactions = allocate_transaction(transaction_count, users, user_count);

    // Use the allocated structures here

    free_resources(&sessions, &users, &transactions);
}
