record* initialize_records(size_t count, unsigned long seed) {
    if (count == 0) return NULL;

    record* records = (record*)malloc(count * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(seed);

    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand();
        memset(records[i].buffer, 0, sizeof(records[i].buffer));
    }

    return records;
}

void free_records(record* records, size_t count) {
    if (records) {
        free(records);
    }
}

int main() {
    unsigned long seed = time(NULL);
    size_t count = 10; // Example size

    record* records = initialize_records(count, seed);
    if (!records) return EXIT_FAILURE;

    for (size_t i = 0; i < count; ++i) {
        printf("Record %zu: Value=%d, Buffer='%.*s'\n", 
               i, records[i].value, 64, records[i].buffer);
    }

    free_records(records, count);

    return EXIT_SUCCESS;
}
```

