    getrusage(RUSAGE_SELF, &usage);
    return usage.ru_rss * 1024; // Convert KB to bytes
}

void logHook(const char* message) {
    printf("Log: %s\n", message);
}

int compileCFile(const char* sourceFile, const char* outputExe) {
    FILE* pipe = popen((char*)"gcc -o " outputExe " " sourceFile, "r");
    if (!pipe) return -1;

    int exitCode = pclose(pipe);
    if (exitCode != 0) {
        fprintf(stderr, "Compilation failed with exit code %d\n", exitCode);
    }

    return exitCode;
}

