        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    initializeRecords(recordArray, arraySize, 0, 100); // Example range

    struct timeval startTime, endTime;
    gettimeofday(&startTime, NULL);
    int initialRSS = getRSS();

    // Perform operations...

    gettimeofday(&endTime, NULL);
    int finalRSS = getRSS();

    printf("Execution time: %ld microseconds\n", (endTime.tv_sec - startTime.tv_sec) * 1000000 + (endTime.tv_usec - startTime.tv_usec));
    printf("Initial RSS: %d bytes\n", initialRSS);
    printf("Final RSS: %d bytes\n", finalRSS);

    free(offsetArray);
    free(keyArray);
    free(recordArray);

    return compileCFile("example.c", "output");
}
