typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    long timestamp;
    int session_id;
    char *data;
} session;

record* allocate_and_initialize_records(int count) {
    // Allocate memory for records
    record *records = (record *)malloc(count * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    // Initialize records with pseudo-random values
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i].offset = rand();
        records[i].key = rand() % 1000;
    }

    return records;
}

session* allocate_and_initialize_sessions(int count, int *new_count) {
    // Allocate memory for sessions
    session *sessions = (session *)malloc(count * sizeof(session));
    if (!sessions) {
        perror("Failed to allocate memory for sessions");
        return NULL;
    }

    // Initialize sessions with current time and default data
    srand(time(NULL));
    int i = 0;
    while (i < count && new_count != NULL) {
        sessions[i].timestamp = time(NULL);
        sessions[i].session_id = rand() % 1000;

        // Allocate memory for session data with a default string
        sessions[i].data = (char *)malloc(SESSION_DATA_MAX_SIZE * sizeof(char));
        if (!sessions[i].data) {
            perror("Failed to allocate memory for session data");
            return NULL;
        }
        strncpy(sessions[i].data, DEFAULT_SESSION_DATA, SESSION_DATA_MAX_SIZE - 1);
        sessions[i].data[SESSION_DATA_MAX_SIZE - 1] = '\0';

        i++;
    }

    *new_count = i;
    return sessions;
}

void free_sessions(session *sessions, int count) {
    for (int i = 0; i < count; i++) {
        if (sessions[i].data) {
            free(sessions[i].data);
        }
    }
    free(sessions);
}
