#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

Record* create_records(long offset, long count, int min_val, int max_val) {
    if (count <= 0) {
        fprintf(stderr, "Error: Count must be greater than zero.\n");
        return NULL;
    }

    // Allocate memory for offsets and keys
    long* offsets = malloc(count * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets.\n");
        return NULL;
    }

    int* keys = malloc(count * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: Failed to allocate memory for keys.\n");
        free(offsets);
        return NULL;
    }

    // Allocate memory for records
    Record* records = malloc(count * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize PRNG with a seed based on time and offset
    srand(time(NULL) + offset);

    // Populate arrays with pseudo-random values
    for (long i = 0; i < count; i++) {
        offsets[i] = offset + i;
        keys[i] = rand() % (max_val - min_val + 1) + min_val;
        records[i].value = keys[i]; // Example assignment, can be modified as needed
    }

    // Return the populated arrays
    return records;
}

void free_records(Record* records, long count) {
    if (!records || count <= 0) {
        fprintf(stderr, "Error: Invalid input for freeing records.\n");
        return;
    }

    free(records);
}

int main() {
    long offset = 100;
    long count = 10;
    int min_val = 1;
    int max_val = 100;

    Record* records = create_records(offset, count, min_val, max_val);
    if (records) {
        // Use the records as needed
        free_records(records, count);
    }

    return 0;
}
