void generate_records(long offset_count, long record_count, int min_value, int max_value) {
    if (offset_count <= 0 || record_count <= 0) {
        fprintf(stderr, "Invalid count values\n");
        return;
    }

    long* offsets = malloc(offset_count * sizeof(long));
    int* keys = malloc(keys_count * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        return;
    }

    record* records = malloc(record_count * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        return;
    }

    // Seed the PRNG
    if (RAND_bytes((unsigned char*)&seed, sizeof(seed)) != 1) {
        fprintf(stderr, "PRNG seeding failed\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Populate records with random values
    for (long i = 0; i < record_count; ++i) {
        records[i].value = rand_r(&seed) % (max_value - min_value + 1) + min_value;
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}
