int initialize_arrays(long* *offsets, int* *keys, Record** records, int num_elements) {
    if (num_elements <= 0) {
        fprintf(stderr, "Invalid input: number of elements must be positive.\n");
        return -1;
    }

    *offsets = (long*)malloc(num_elements * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return -2;
    }

    *keys = (int*)malloc(num_elements * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return -3;
    }

    *records = (Record*)malloc(num_elements * sizeof(Record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        fprintf(stderr, "Memory allocation failed for records.\n");
        return -4;
    }

    srand(time(NULL)); // Seed the PRNG
    for (int i = 0; i < num_elements; i++) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % 100; // Random value between 0 and 99
        (*records)[i].value = rand() % 1000; // Random value between 0 and 999
    }

    printf("Arrays initialized successfully.\n");
    return 0;
}

void update_records(Record* records, int num_elements) {
    if (num_elements <= 0 || records == NULL) {
        fprintf(stderr, "Invalid input: records must be non-null and number of elements must be positive.\n");
        return;
    }

    for (int i = 0; i < num_elements; i++) {
        records[i].value = rand() % 1000; // Update with new random value
    }

    printf("Records updated successfully.\n");
}

void log_event(const char* message, int level) {
    if (level == 1) {
        printf("INFO: %s\n", message);
    } else if (level == 2) {
        printf("WARNING: %s\n", message);
    } else if (level == 3) {
        printf("ERROR: %s\n", message);
    }
}

int main() {
    int num_elements = 5;
    long* offsets;
    int* keys;
    Record* records;

    int result = initialize_arrays(&offsets, &keys, &records, num_elements);
    if (result != 0) {
        printf("Initialization failed with error code: %d\n", result);
        return result;
    }

    log_event("Arrays initialized successfully.", 1);

    // Simulate periodic updates
    for (int i = 0; i < 3; i++) {
        update_records(records, num_elements);
        log_event("Records updated.", 1);
        sleep(1); // Sleep for 1 second to simulate time passing
    }

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
