#include <time.h>
#include <string.h>

typedef struct {
    int id;
    time_t timestamp;
} DataPoint;

// Custom PRNG function using Xorshift algorithm for balance between performance and randomness quality
uint32_t xorshift32(uint32_t *state) {
    uint32_t x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return (*state = x);
}

DataPoint* initialize_data_points(int count, time_t start_time, time_t end_time, int seed) {
    if (count <= 0 || start_time >= end_time) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    DataPoint *data = malloc(count * sizeof(DataPoint));
    if (!data) {
        perror("Memory allocation failed.");
        return NULL;
    }

    uint32_t state = seed;
    for (int i = 0; i < count; ++i) {
        data[i].id = i + 1;
        // Generate a timestamp within the specified range
        data[i].timestamp = start_time + xorshift32(&state) % (end_time - start_time);
    }

    return data;
}

void free_data_points(DataPoint *data, int count) {
    if (data) {
        free(data);
    }
}

int main() {
    srand(time(NULL)); // Seed for PRNG
    time_t current_time = time(NULL);

    int count = 10000;
    DataPoint *data = initialize_data_points(count, current_time - 86400, current_time, rand());
    if (data) {
        // Process data...
        free_data_points(data, count);
    }

    return 0;
}
