int initialize_arrays(int num_elements, float** offsets, char** statuses, Event** events, double** timestamps, LogEntry** logs) {
    if (num_elements <= 0 || num_elements > MAX_LOG_ENTRIES) {
        return -1; // Invalid input
    }

    *offsets = (float*)malloc(num_elements * sizeof(float));
    *statuses = (char*)malloc(num_elements * sizeof(char));
    *events = (Event*)malloc(num_elements * sizeof(Event));
    *timestamps = (double*)malloc(num_elements * sizeof(double));
    *logs = (LogEntry*)malloc(num_elements * sizeof(LogEntry));

    if (*offsets == NULL || *statuses == NULL || *events == NULL || *timestamps == NULL || *logs == NULL) {
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < num_elements; i++) {
        (*offsets)[i] = ((float)rand() / RAND_MAX) * 100.0f;
        (*statuses)[i] = 'A' + rand() % 26;
        (*events)[i].offset = (*offsets)[i];
        (*events)[i].status_code = (*statuses)[i];
        (*timestamps)[i] = (double)rand() / RAND_MAX * time(NULL);
        (*logs)[i].message = NULL; // Lazy initialization of message
        (*logs)[i].timestamp = 0;
    }

    return 0; // Success
}

int main() {
    int num_elements;
    float* offsets;
    char* statuses;
    Event* events;
    double* timestamps;
    LogEntry* logs;

    printf("Enter the number of elements: ");
    scanf("%d", &num_elements);

    int result = initialize_arrays(num_elements, &offsets, &statuses, &events, &timestamps, &logs);
    if (result == -1) {
        printf("Invalid input.\n");
    } else if (result == -2) {
        printf("Memory allocation failed.\n");
    } else {
        printf("Arrays initialized successfully.\n");
        // Further operations with the arrays
        free(offsets);
        free(statuses);
        free(events);
        free(timestamps);
        for (int i = 0; i < num_elements; i++) {
            free(logs[i].message);
        }
        free(logs);
    }

    return 0;
}
