    int key;
    int value;
} Record;

// Function to initialize records with random values
void initializeRecords(Record* records, int count) {
    srand(time(NULL)); // Seed PRNG
    for (int i = 0; i < count; i++) {
        records[i].offset = rand();
        records[i].key = rand() % 100;
        records[i].value = rand() % 1000;
    }
}

// Function to update records with new values from an external data source
void updateRecords(Record* records, int count) {
    // Simulate updating records with new values from an external data source
    for (int i = 0; i < count; i++) {
        records[i].value += rand() % 10;
    }
}

// Function to handle HTTP PUT operation for updating a resource
void updateResource(Record* records, int count, int key, Record newData) {
    for (int i = 0; i < count; i++) {
        if (records[i].key == key) {
            records[i] = newData;
            break;
        }
    }
}

// Function to handle HTTP DELETE operation for deleting a resource
void deleteResource(Record* records, int* count, int key) {
    for (int i = 0; i < *count; i++) {
        if (records[i].key == key) {
            // Shift elements to remove the deleted record
            for (int j = i; j < *count - 1; j++) {
                records[j] = records[j + 1];
            }
            (*count)--;
            break;
        }
    }
}

// Function to log initialization and updates
void logEvent(const char* message) {
    printf("Log: %s\n", message);
}

int main() {
    const int count = 10; // Number of records
    Record* records = (Record*)malloc(count * sizeof(Record));

    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    initializeRecords(records, count);
    logEvent("Records initialized with random values");

    updateRecords(records, count);
    logEvent("Records updated with new values");

    Record newData = {12345, 99, 1001};
    updateResource(records, count, 99, newData);
    logEvent("Resource updated using HTTP PUT method");

    deleteResource(records, &count, 99);
    logEvent("Resource deleted using HTTP DELETE method");

    free(records);

    return EXIT_SUCCESS;
}
