#include <stdlib.h>
#include <time.h>
#include <openssl/rand.h>

typedef struct {
    long offset;
    int key;
    int value;
    time_t timestamp;
    unsigned int checksum;
} record;

void generate_random_value(record *rec, int range) {
    if (!RAND_bytes((unsigned char *)&rec->value, sizeof(rec->value))) {
        fprintf(stderr, "Error generating random number\n");
        exit(EXIT_FAILURE);
    }
    rec->value %= range;
}

record* create_records(int initial_size, int *current_size, int max_size, int range) {
    record *records = (record *)malloc(initial_size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (*current_size = 0; *current_size < initial_size; (*current_size)++) {
        records[*current_size].offset = *current_size;
        records[*current_size].key = rand() % range;
        generate_random_value(&records[*current_size], range);
        records[*current_size].timestamp = time(NULL);
        if (!RAND_bytes((unsigned char *)&records[*current_size].checksum, sizeof(records[*current_size].checksum))) {
            fprintf(stderr, "Error generating checksum\n");
            exit(EXIT_FAILURE);
        }
    }
    return records;
}

void resize_records(record **records, int *current_size, int new_size, int range) {
    record *new_records = (record *)realloc(*records, new_size * sizeof(record));
    if (!new_records) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (; *current_size < new_size; (*current_size)++) {
        new_records[*current_size].offset = *current_size;
        new_records[*current_size].key = rand() % range;
        generate_random_value(&new_records[*current_size], range);
        new_records[*current_size].timestamp = time(NULL);
        if (!RAND_bytes((unsigned char *)&new_records[*current_size].checksum, sizeof(new_records[*current_size].checksum))) {
            fprintf(stderr, "Error generating checksum\n");
            exit(EXIT_FAILURE);
        }
    }
    *records = new_records;
}

void free_records(record **records, int *current_size) {
    if (*records) {
        free(*records);
        *records = NULL;
        *current_size = 0;
    }
}
