    if (offsetSize <= 0 || keySize <= 0 || minVal > maxVal) {
        return NULL; // Handle invalid input gracefully
    }

    size_t totalSize = sizeof(long) * offsetSize + sizeof(int) * keySize + sizeof(record) * offsetSize;
    record* records = malloc(totalSize);
    if (records == NULL) {
        return NULL; // Memory allocation failure
    }

