        offsets[i] = i;
        keys[i] = i;
        records[i].value = minVal + rand() % (maxVal - minVal + 1);
    }

    // Memory initialization verification
    for (int i = 0; i < offsetSize; ++i) {
        if (offsets[i] != i || keys[i] != i || records[i].value < minVal || records[i].value > maxVal) {
            free(records); // Free allocated memory on failure
            return NULL;
        }
    }

    return records; // Return pointer to the first record
