int customPRNG(int range) {
    static unsigned long seed = 0;
    if (seed == 0) seed = time(NULL);
    seed = seed * 1664525 + 1013904223;
    return seed % range;
}

int allocateAndInitializeRecords(Record **records, int count, int minRange, int maxRange) {
    if (count <= 0 || minRange > maxRange) {
        printf("Invalid input.\n");
        return -1;
    }

    *records = (Record *)malloc(count * sizeof(Record));
    if (*records == NULL) {
        printf("Memory allocation failed.\n");
        return 0;
    }

    int initializedCount = 0;
    for (int i = 0; i < count; i++) {
        int value;
        do {
            value = customPRNG(maxRange - minRange + 1) + minRange;
        } while (value < minRange || value > maxRange);

        (*records)[i].value = value;
        initializedCount++;
    }

    for (int i = 0; i < initializedCount; i++) {
        printf("Record %d: %d\n", i, (*records)[i].value);
    }

    return initializedCount;
}

int main() {
    Record *records;
    int count = 10;
    int minRange = -50;
    int maxRange = 50;

    int successfulRecords = allocateAndInitializeRecords(&records, count, minRange, maxRange);

    if (successfulRecords != -1) {
        free(records);
    }

    return 0;
