#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} Record;

int* allocateLongs(size_t size) {
    // Allocate memory for 'long' offset values
    long* offsets = (long*)malloc(size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for longs.\n");
        return NULL;
    }
    // Initialize with sequential integers
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = i;
    }
    return (int*)offsets; // Cast to int* as per function signature
}

int* allocateInts(size_t size) {
    // Allocate memory for 'int' keys
    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for ints.\n");
        return NULL;
    }
    // Initialize with sequential integers
    for (size_t i = 0; i < size; ++i) {
        keys[i] = i;
    }
    return keys;
}

Record* allocateRecords(size_t size, int minVal, int maxVal) {
    // Allocate memory for 'record' structures
    Record* records = (Record*)malloc(size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        return NULL;
    }
    srand(time(NULL)); // Seed PRNG once per function call
    // Initialize with pseudo-random integers
    for (size_t i = 0; i < size; ++i) {
        records[i].value = minVal + rand() % (maxVal - minVal + 1);
    }
    return records;
}

int verifyMemory(Record* records, size_t size, int minVal, int maxVal) {
    // Verify memory integrity using a simple checksum
    int checksum = 0;
    for (size_t i = 0; i < size; ++i) {
        if (records[i].value < minVal || records[i].value > maxVal) {
            fprintf(stderr, "Memory corruption detected.\n");
            return 0;
        }
        checksum ^= records[i].value;
    }
    printf("Checksum: %d\n", checksum);
    return 1;
}

Record* manageMemory(size_t size, int minVal, int maxVal, int logFailures) {
    if (size <= 0) {
        fprintf(stderr, "Invalid size provided.\n");
        return NULL;
    }

    Record* records = allocateRecords(size, minVal, maxVal);
    if (!records) {
        if (logFailures) {
            printf("Allocation failed. Retrying with reduced size...\n");
        }
        size /= 2; // Reduce size and retry
        records = manageMemory(size, minVal, maxVal, logFailures);
    }

    int* offsets = allocateInts(size);
    int* keys = allocateLongs(size);

    if (!records || !offsets || !keys) {
        fprintf(stderr, "Failed to manage memory.\n");
        return NULL;
    }

    if (logFailures) {
        printf("Memory managed successfully.\n");
    }

    if (!verifyMemory(records, size, minVal, maxVal)) {
        free(records);
        free(offsets);
        free(keys);
        return NULL;
    }

    return records; // Return pointer to 'record' array
}

int main() {
    int* offsets = allocateInts(10);
    if (!offsets) {
        fprintf(stderr, "Failed to manage memory in main.\n");
        return 1;
    }
    free(offsets);

    Record* records = manageMemory(20, 1, 100, 1);
    if (records) {
        printf("Records managed successfully.\n");
        free(records);
    }

    return 0;
}
```

