#include <time.h>

#define MAX_RANGE 100000

typedef struct {
    int value;
} record;

// Function to check if a number is prime
bool is_prime(int num) {
    if (num <= 1) return false;
    if (num <= 3) return true;
    if (num % 2 == 0 || num % 3 == 0) return false;
    for (int i = 5; i * i <= num; i += 6) {
        if (num % i == 0 || num % (i + 2) == 0)
            return false;
    }
    return true;
}

// Function to generate an array of unique prime numbers within a given range
int* allocate_primes(int range_start, int range_end, size_t* count) {
    if (range_start > range_end || range_end - range_start + 1 > MAX_RANGE) {
        *count = 0;
        return NULL;
    }
    int* primes = malloc((range_end - range_start + 1) * sizeof(int));
    if (!primes) {
        *count = 0;
        return NULL;
    }
    size_t index = 0;
    for (int i = range_start; i <= range_end; ++i) {
        if (is_prime(i)) {
            primes[index++] = i;
        }
    }
    *count = index;
    primes = realloc(primes, index * sizeof(int));
    return primes;
}

// Function to allocate and initialize an array of long integers representing unique offsets
long* allocate_offsets(long range_start, long range_end, size_t* count) {
    if (range_start > range_end || range_end - range_start + 1 > MAX_RANGE) {
        *count = 0;
        return NULL;
    }
    long* offsets = malloc((range_end - range_start + 1) * sizeof(long));
    if (!offsets) {
        *count = 0;
        return NULL;
    }
    for (size_t i = 0; i < range_end - range_start + 1; ++i) {
        offsets[i] = range_start + i;
    }
    *count = range_end - range_start + 1;
    return offsets;
}

// Function to allocate and initialize an array of record structures with random values
record* allocate_records(int min_value, int max_value, size_t count) {
    if (min_value > max_value || count > MAX_RANGE) {
        return NULL;
    }
    record* records = malloc(count * sizeof(record));
    if (!records) {
        return NULL;
    }
    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
    return records;
}

// Function to retrieve the nth prime from the primes array
int get_nth_prime(int* primes, size_t count, size_t n) {
    if (n >= count) {
        return -1; // Invalid index
    }
    return primes[n];
}

// Function to find a record by offset in the offsets array
record* find_record_by_offset(long* offsets, record* records, size_t offsets_count, long target_offset) {
    for (size_t i = 0; i < offsets_count; ++i) {
        if (offsets[i] == target_offset) {
            return &records[i];
        }
    }
    return NULL;
}

// Function to free all allocated memory
void free_all(int* primes, long* offsets, record* records, size_t primes_count, size_t offsets_count) {
    free(primes);
    free(offsets);
    free(records);
}
