#include <time.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 1000

typedef struct {
    time_t timestamp;
    int amount;
    int status; // 0 for failure, 1 for success
} record;

typedef struct {
    long offset;
    int key;
    record rec;
} transaction;

record generate_random_transaction(int min_amount, int max_amount) {
    record r;
    time(&r.timestamp);
    r.amount = rand() % (max_amount - min_amount + 1) + min_amount;
    r.status = rand() % 2; // Randomly choose success or failure
    return r;
}

void log_transaction(record rec) {
    printf("Transaction Amount: %d, Timestamp: %ld, Status: %s\n", 
           rec.amount, (long)rec.timestamp, rec.status ? "Success" : "Failure");
}

int process_transactions(transaction *trans, int num_trans) {
    srand(time(NULL)); // Seed the PRNG
    int processed = 0;
    for (int i = 0; i < num_trans; ++i) {
        trans[i].rec = generate_random_transaction(1, 100); // Generate random transaction amount
        log_transaction(trans[i].rec);
        processed++;
    }
    return processed;
}

void *transaction_thread(void *arg) {
    int *num_trans_ptr = (int *)arg;
    int num_trans = *num_trans_ptr;
    transaction trans[MAX_TRANSACTIONS];
    pthread_exit((void *)(long)process_transactions(trans, num_trans));
}

int main() {
    int num_trans = 5; // Number of transactions to process
    pthread_t thread;
    int status;

    if (pthread_create(&thread, NULL, transaction_thread, &num_trans) != 0) {
        perror("Thread creation failed");
        return 1;
    }

    if ((status = pthread_join(thread, NULL)) != 0) {
        perror("Thread join failed");
        return 1;
    }

    printf("Total transactions processed: %d\n", num_trans);
    return 0;
}
