#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <limits.h>

#define RECORD_SIZE sizeof(record)
#define INITIAL_CAPACITY 1024

typedef struct {
    long offset;
    int key;
    int value;
} record;

record* create_record_array(int capacity) {
    record* arr = (record*)malloc(capacity * RECORD_SIZE);
    if (!arr) {
        perror("Memory allocation failed");
        return NULL;
    }
    for (int i = 0; i < capacity; ++i) {
        arr[i].offset = rand();
        arr[i].key = rand() % INT_MAX;
        arr[i].value = rand() % INT_MAX;
    }
    printf("Successfully allocated memory for %d records.\n", capacity);
    return arr;
}

void resize_record_array(record** array, int* capacity) {
    *capacity *= 2;
    record* new_arr = (record*)realloc(*array, *capacity * RECORD_SIZE);
    if (!new_arr) {
        perror("Memory reallocation failed");
        return;
    }
    for (int i = (*capacity / 2); i < *capacity; ++i) {
        new_arr[i].offset = rand();
        new_arr[i].key = rand() % INT_MAX;
        new_arr[i].value = rand() % INT_MAX;
    }
    printf("Successfully reallocated memory to %d records.\n", *capacity);
    *array = new_arr;
}

void free_record_array(record* array) {
    if (array) {
        free(array);
        printf("Memory for record array freed successfully.\n");
    }
}

int main() {
    int capacity = INITIAL_CAPACITY;
    record* arr = create_record_array(capacity);

    while (arr == NULL && capacity < INT_MAX / RECORD_SIZE) {
        capacity *= 2;
        arr = create_record_array(capacity);
    }

    if (arr != NULL) {
        resize_record_array(&arr, &capacity);
        free_record_array(arr);
