#include <pthread.h>

// Define data structures
typedef struct {
    double probability;
    char* name;
    int timeout;
} config;

typedef struct {
    time_t timestamp;
    char* description;
    config* settings;
} event;

// Memory pool structure for efficient allocation
typedef struct {
    void* memory;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} memory_pool;

// Initialize memory pool
void init_memory_pool(memory_pool* pool, size_t size) {
    pool->memory = malloc(size);
    if (pool->memory == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    pool->size = size;
    pool->used = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

// Allocate memory from the memory pool
void* allocate_from_pool(memory_pool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used + size > pool->size) {
        fprintf(stderr, "Memory allocation failed. Pool is full.\n");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    void* addr = ((char*)pool->memory) + pool->used;
    pool->used += size;
    pthread_mutex_unlock(&pool->lock);
    return addr;
}

// Free all memory allocated by the memory pool
void free_memory_pool(memory_pool* pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->memory);
    pool->memory = NULL;
    pool->size = 0;
    pool->used = 0;
    pthread_mutex_destroy(&pool->lock);
}

// Function to manage memory allocation and initialization
void allocate_and_initialize(memory_pool* pool, size_t num_configs, size_t num_events) {
    // Allocate space for arrays of data structures
    long* long_array = (long*)allocate_from_pool(pool, num_configs * sizeof(long));
    char** string_array = (char**)allocate_from_pool(pool, num_configs * sizeof(char*));
    config* config_array = (config*)allocate_from_pool(pool, num_configs * sizeof(config));
