#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define data structures
typedef struct {
    char* name;
    char* email;
    int session_id;
} User;

typedef struct {
    time_t timestamp;
    double amount;
    char* description;
    User* user_profile;
} Transaction;

typedef struct {
    // Session management structure
} SessionManager;

// Function to initialize memory for arrays
void init_memory_management(SessionManager** sessions, User*** users, Transaction*** transactions) {
    *sessions = NULL;
    *users = NULL;
    *transactions = NULL;

    // Allocate initial memory
    *sessions = (SessionManager*)malloc(sizeof(SessionManager));
    if (*sessions == NULL) {
        fprintf(stderr, "Memory allocation failed for sessions\n");
        exit(EXIT_FAILURE);
    }

    *users = (User**)malloc(sizeof(User*) * 10); // Initial size
    if (*users == NULL) {
        fprintf(stderr, "Memory allocation failed for users\n");
        free(*sessions);
        exit(EXIT_FAILURE);
    }
    memset(*users, 0, sizeof(User*) * 10);

    *transactions = (Transaction**)malloc(sizeof(Transaction*) * 20); // Initial size
    if (*transactions == NULL) {
        fprintf(stderr, "Memory allocation failed for transactions\n");
        free(*sessions);
        free(*users);
        exit(EXIT_FAILURE);
    }
    memset(*transactions, 0, sizeof(Transaction*) * 20);
}

// Function to resize arrays dynamically
void resize_memory(User*** users, Transaction*** transactions) {
    // Example resizing logic
    User** new_users = (User**)realloc(*users, sizeof(User*) * (*users ? 2 * *users : 10));
    if (new_users == NULL) {
        fprintf(stderr, "Memory reallocation failed for users\n");
        exit(EXIT_FAILURE);
    }
    *users = new_users;

    Transaction** new_transactions = (Transaction**)realloc(*transactions, sizeof(Transaction*) * (*transactions ? 2 * *transactions : 20));
    if (new_transactions == NULL) {
        fprintf(stderr, "Memory reallocation failed for transactions\n");
        exit(EXIT_FAILURE);
    }
    *transactions = new_transactions;
}

// Function to clean up allocated memory
void cleanup_memory(User** users, Transaction** transactions) {
