} memory_pool;

void *allocate_memory(memory_pool *pool, size_t element_size) {
    if (pool->size >= pool->capacity) {
        pool->capacity *= 2;
        pool->data = realloc(pool->data, pool->capacity * sizeof(void *));
    }
    void *new_element = malloc(element_size);
    if (new_element == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->data[pool->size++] = new_element;
    return new_element;
}

