#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define structures
typedef struct {
    int accountID;
} User;

typedef struct {
    time_t timestamp;
    double amount;
    char description[256];
    User* userAccount;
} Transaction;

typedef struct {
    char action[128];
    int transactionID;
    User* user;
} Audit;

// Function to generate pseudo-random account ID
int generateAccountID() {
    static unsigned long seed = 0;
    if (seed == 0) seed = time(NULL);
    return rand_r(&seed);
}

// Function to create and initialize memory for data structures
int initMemory(int numUsers, int numTransactions, int numAudits) {
    User* users = malloc(numUsers * sizeof(User));
    Transaction* transactions = malloc(numTransactions * sizeof(Transaction));
    Audit* audits = malloc(numAudits * sizeof(Audit));

    if (users == NULL || transactions == NULL || audits == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    for (int i = 0; i < numUsers; i++) {
        users[i].accountID = generateAccountID();
    }

    for (int i = 0; i < numTransactions; i++) {
        transactions[i].timestamp = time(NULL);
        transactions[i].amount = rand() % 1000 / 100.0;
        sprintf(transactions[i].description, "Transaction %d", i);
        transactions[i].userAccount = &users[rand() % numUsers];
    }

    for (int i = 0; i < numAudits; i++) {
        strcpy(audits[i].action, "Action");
        audits[i].transactionID = rand() % numTransactions;
        audits[i].user = &users[rand() % numUsers];
    }

    free(users);
    free(transactions);
    free(audits);

    return 0;
}

int main() {
    int numUsers = 1000;
    int numTransactions = 5000;
    int numAudits = 2500;

    if (initMemory(numUsers, numTransactions, numAudits) == -1) {
        fprintf(stderr, "Failed to initialize memory\n");
        return EXIT_FAILURE;
    }

    printf("Memory initialization successful\n");

    return EXIT_SUCCESS;
}
