#include <mutex>
#include <unordered_map>
#include <random>
#include <thread>

class ConfigManager {
public:
    static ConfigManager& getInstance() {
        static ConfigManager instance;
        return instance;
    }

    void updateConfig(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        config_[key] = value;
        cache_.clear(); // Invalidate cache on config change
    }

    std::string getConfig(const std::string& key) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            return it->second; // Return cached value
        }
        auto configIt = config_.find(key);
        if (configIt != config_.end()) {
            cache_[key] = configIt->second; // Cache the value
            return configIt->second;
        }
        return ""; // Key not found
    }

private:
    ConfigManager() {}
    ~ConfigManager() {}

    std::mutex mutex_;
    std::unordered_map<std::string, std::string> config_;
    std::unordered_map<std::string, std::string> cache_;
};

class PRNG {
public:
    static unsigned int getRandomNumber() {
        static std::mt19937 gen(std::random_device{}());
        static std::uniform_int_distribution<> dis(0, 100);
        return dis(gen);
    }
};

int main() {
    ConfigManager& configManager = ConfigManager::getInstance();
    configManager.updateConfig("network_param", "192.168.1.1");
    std::cout << "Network Param: " << configManager.getConfig("network_param") << std::endl;

    unsigned int randomValue = PRNG::getRandomNumber();
    std::cout << "Random Value: " << randomValue << std::endl;

    return 0;
}
