typedef struct {
    int id;
} Device;

typedef struct {
    char version[10];
    time_t build_date;
    Device *device;
} Firmware;

typedef struct {
    time_t timestamp;
    char description[100];
    int severity_level;
    Firmware *firmware;
} EventLog;

typedef struct MemoryPool {
    void* pool;
    size_t size;
    size_t block_size;
} MemoryPool;

Device* create_device(MemoryPool* pool) {
    Device* device = (Device*)memory_pool_alloc(pool, sizeof(Device));
    if (device == NULL) return NULL;
    device->id = rand();
    return device;
}

Firmware* create_firmware(MemoryPool* pool, const char* version, time_t build_date, Device* device) {
    Firmware* firmware = (Firmware*)memory_pool_alloc(pool, sizeof(Firmware));
    if (firmware == NULL) return NULL;
    snprintf(firmware->version, sizeof(firmware->version), "%s", version);
    firmware->build_date = build_date;
    firmware->device = device;
    return firmware;
}

EventLog* create_event_log(MemoryPool* pool, time_t timestamp, const char* description, int severity_level, Firmware* firmware) {
    EventLog* event = (EventLog*)memory_pool_alloc(pool, sizeof(EventLog));
    if (event == NULL) return NULL;
    event->timestamp = timestamp;
    snprintf(event->description, sizeof(event->description), "%s", description);
    event->severity_level = severity_level;
    event->firmware = firmware;
    return event;
}

void memory_pool_init(MemoryPool* pool, void* memory, size_t size, size_t block_size) {
    pool->pool = memory;
    pool->size = size;
    pool->block_size = block_size;
}

void* memory_pool_alloc(MemoryPool* pool, size_t size) {
    if (size > pool->block_size || pool->block_size == 0) return NULL;
    void* ptr = pool->pool;
    pool->pool += size;
    pool->size -= size;
    return ptr;
}

int main() {
    srand(time(NULL));

    MemoryPool pool;
    char memory[1024];
    memory_pool_init(&pool, memory, sizeof(memory), 64);

    Device* device = create_device(&pool);
    if (device == NULL) {
        fprintf(stderr, "Failed to allocate memory for device\n");
        return EXIT_FAILURE;
    }

    Firmware* firmware = create_firmware(&pool, "1.0", time(NULL), device);
    if (firmware == NULL) {
        fprintf(stderr, "Failed to allocate memory for firmware\n");
        free(device);
        return EXIT_FAILURE;
    }

    EventLog* event = create_event_log(&pool, time(NULL), "Device initialized", 1, firmware);
    if (event == NULL) {
        fprintf(stderr, "Failed to allocate memory for event log\n");
        free(firmware->device);
        free(firmware);
        return EXIT_FAILURE;
    }

    printf("Event log created successfully\n");

    // Free allocated memory
    free(event->firmware->device);
    free(event->firmware);
    free(event);

    return EXIT_SUCCESS;
}
