Record* createNewRecord() {
    Record *newRecord = (Record*)malloc(sizeof(Record));
    if (newRecord == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    newRecord->next = NULL;
    return newRecord;
}

void insertRandomValue(LinkedList *list, int min, int max) {
    Record *newRecord = createNewRecord();
    if (newRecord == NULL) {
        // Handle error in creating new record
        return;
    }

    // Use a simple PRNG for efficiency
    srand(time(NULL));
    newRecord->value = rand() % (max - min + 1) + min;

    if (list->head == NULL) {
        list->head = newRecord;
    } else {
        Record *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newRecord;
    }
}

void freeLinkedList(LinkedList *list) {
    Record *current = list->head;
    Record *temp;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
}
