// Function to initialize and populate the linked list from an external data source
Record* initialize_and_populate_list(int start, int end, int max_records) {
    // Seed the pseudo-random number generator
    srand(time(NULL));

    // Allocate memory for the head of the linked list
    Record* head = NULL;
    Record** current = &head;

    // Populate the linked list with random values within the specified range
    while (*current == NULL && start <= end) {
        *current = (Record*)malloc(sizeof(Record));
        if (*current != NULL) {
            (*current)->value = rand() % (end - start + 1) + start;
            (*current)->next = NULL;

            // Move to the next record
            current = &((*current)->next);

            // Check for maximum records limit
            if ((max_records > 0 && *current != NULL) && (--max_records == 0)) {
                break;
            }
        } else {
            printf("Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }
    }

    return head;
}

// Function to free the memory allocated for the linked list
void free_list(Record* head) {
