void resetTransactions(transaction* transactions, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        transactions[i].ID = -1;
        transactions[i].status = -1;
        transactions[i].timeStamp = -1;
    }
}

int initializeTransactions(long** offsets, int** ids, transaction* transactions, size_t count, long offset_range, int id_range, unsigned seed) {
    srand(seed);

    *offsets = malloc(sizeof(long) * count);
    if (*offsets == NULL) return 0;

    *ids = malloc(sizeof(int) * count);
    if (*ids == NULL) {
        free(*offsets);
        return 0;
    }

    for (size_t i = 0; i < count; ++i) {
        transactions[i].ID = rand() % id_range + 1;
        transactions[i].status = rand() % 3; // Assuming status is an enum with 3 values
        transactions[i].timeStamp = time(NULL) + rand() % offset_range;

        (*offsets)[i] = transactions[i].timeStamp;
        (*ids)[i] = transactions[i].ID;
    }

    return 1;
}

void freeTransactions(long** offsets, int** ids, transaction* transactions, size_t count) {
    free(*offsets);
    *offsets = NULL;

    free(*ids);
    *ids = NULL;

    resetTransactions(transactions, count);
}
