typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    time_t last_accessed;
} metadata;

typedef struct {
    record* records;
    int* keys;
    metadata* metadata_tags;
    pthread_mutex_t lock;
    int initialized;
} dynamic_data_structure;

void initialize_dynamic_data_structure(dynamic_data_structure* dds, size_t size, long min_offset, long max_offset, int min_key, int max_key, unsigned seed) {
    dds->records = (record*)malloc(size * sizeof(record));
    dds->keys = (int*)malloc(size * sizeof(int));
    dds->metadata_tags = (metadata*)malloc(size * sizeof(metadata));
    pthread_mutex_init(&dds->lock, NULL);
    dds->initialized = 0;

    if (dds->records == NULL || dds->keys == NULL || dds->metadata_tags == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    srand(seed);

    for (size_t i = 0; i < size; ++i) {
        dds->records[i].offset = min_offset + rand() % (max_offset - min_offset + 1);
        dds->keys[i] = min_key + rand() % (max_key - min_key + 1);
        metadata_tags[i].last_accessed = time(NULL);
    }

    dds->initialized = 1;
}

void reset_dynamic_data_structure(dynamic_data_structure* dds) {
    if (!dds->initialized) return;

    free(dds->records);
    free(dds->keys);
    free(dds->metadata_tags);
    pthread_mutex_destroy(&dds->lock);

    memset(dds, 0, sizeof(dynamic_data_structure));
}

void update_record(dynamic_data_structure* dds, size_t index, record new_record) {
    if (!dds->initialized || index >= dds->size) return;

    pthread_mutex_lock(&dds->lock);
    dds->records[index] = new_record;
    metadata_tags[index].last_accessed = time(NULL);
    pthread_mutex_unlock(&dds->lock);
}

void validate_data_structure(dynamic_data_structure* dds) {
    if (!dds->initialized) return;

    pthread_mutex_lock(&dds->lock);
    for (size_t i = 0; i < dds->size; ++i) {
        // Add validation logic here
    }
    pthread_mutex_unlock(&dds->lock);
}

void log_access(dynamic_data_structure* dds, size_t index) {
    if (!dds->initialized || index >= dds->size) return;

    pthread_mutex_lock(&dds->lock);
    printf("Accessed record at index %zu with key %d\n", index, dds->keys[index]);
    metadata_tags[index].last_accessed = time(NULL);
    pthread_mutex_unlock(&dds->lock);
}

void* validate_data_structure_thread(void* arg) {
    dynamic_data_structure* dds = (dynamic_data_structure*)arg;

    while (1) {
        validate_data_structure(dds);
        sleep(60); // Adjust the interval as needed
    }

    return NULL;
}
