void initialize_data_structures(long** long_array, char*** string_array, Config** config_array, AuditLog** audit_log_array) {
    *long_array = (long*)malloc(MAX_CONFIGS * sizeof(long));
    if (*long_array == NULL) {
        fprintf(stderr, "Memory allocation failed for long array\n");
        return;
    }

    *string_array = (char**)malloc(MAX_CONFIGS * sizeof(char*));
    if (*string_array == NULL) {
        fprintf(stderr, "Memory allocation failed for string array\n");
        free(*long_array);
        return;
    }

    *config_array = (Config*)malloc(MAX_CONFIGS * sizeof(Config));
    if (*config_array == NULL) {
        fprintf(stderr, "Memory allocation failed for config array\n");
        free(*long_array);
        free(*string_array);
        return;
    }

    *audit_log_array = (AuditLog*)malloc(MAX_AUDIT_LOGS * sizeof(AuditLog));
    if (*audit_log_array == NULL) {
        fprintf(stderr, "Memory allocation failed for audit log array\n");
        free(*long_array);
        free(*string_array);
        free(*config_array);
        return;
    }

    for (int i = 0; i < MAX_CONFIGS; i++) {
        (*long_array)[i] = i * 10;
        (*string_array)[i] = (char*)malloc(20 * sizeof(char));
        if ((*string_array)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for string array element %d\n", i);
            for (int j = 0; j < i; j++) free((*string_array)[j]);
            free(*long_array);
            free(*string_array);
            free(*config_array);
            return;
        }
        snprintf((*string_array)[i], 20, "Config%d", i);

        (*config_array)[i].probability = ((double)rand() / RAND_MAX) * 1.0;
        (*config_array)[i].config_name = (*string_array)[i];
        (*config_array)[i].unique_id = generate_unique_id();

        (*audit_log_array)[i].timestamp = time(NULL);
        (*audit_log_array)[i].config_id = (*config_array)[i].unique_id;
        snprintf((*audit_log_array)[i].status_message, 50, "Initialized");
    }
}

void archive_old_logs(AuditLog** audit_log_array, int* log_count) {
    if (*log_count > MAX_AUDIT_LOGS / 2) {
        *log_count = MAX_AUDIT_LOGS;
    } else {
        *log_count *= 2;
    }

    AuditLog* new_audit_logs = (AuditLog*)realloc(*audit_log_array, *log_count * sizeof(AuditLog));
    if (new_audit_logs == NULL) {
        fprintf(stderr, "Memory reallocation failed for audit log array\n");
        return;
    }
    *audit_log_array = new_audit_logs;

    // Clear old logs and update timestamps
    for (int i = 0; i < MAX_AUDIT_LOGS / 2; i++) {
        memset(&(*audit_log_array)[i], 0, sizeof(AuditLog));
    }

    time_t current_time = time(NULL);
    for (int i = MAX_AUDIT_LOGS / 2; i < *log_count; i++) {
        (*audit_log_array)[i].timestamp = current_time;
        snprintf((*audit_log_array)[i].status_message, 50, "Archived");
    }
}

void free_all_memory(long* long_array, char** string_array, Config* config_array, AuditLog* audit_log_array) {
    for (int i = 0; i < MAX_CONFIGS; i++) free(string_array[i]);
    free(long_array);
    free(string_array);
    free(config_array);
    free(audit_log_array);
}

int main() {
    srand(time(NULL));

    long* long_array;
    char** string_array;
    Config* config_array;
    AuditLog* audit_log_array;

    initialize_data_structures(&long_array, &string_array, &config_array, &audit_log_array);

    int log_count = MAX_AUDIT_LOGS;
    archive_old_logs(&audit_log_array, &log_count);

    free_all_memory(long_array, string_array, config_array, audit_log_array);

    return 0;
}
