#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_USERS 1000

typedef struct {
    int id;
    char username[50];
    char email[100];
} User;

User* users[MAX_USERS];
int user_count = 0;

// Function to generate a pseudo-random ID
int generate_unique_id() {
    static unsigned long seed = 42; // Initial seed, can be changed for better randomness
    return (seed = seed * 1664525 + 1013904223) % MAX_USERS;
}

// Function to add a user account
int add_user(const char* username, const char* email) {
    if (user_count >= MAX_USERS) return -1; // No space available

    User* new_user = malloc(sizeof(User));
    if (!new_user) return -2; // Memory allocation failed

    new_user->id = generate_unique_id();
    strncpy(new_user->username, username, sizeof(new_user->username));
    strncpy(new_user->email, email, sizeof(new_user->email));

    users[user_count++] = new_user;
    return 0; // Success
}

// Function to remove a user account by ID
int remove_user(int id) {
    for (int i = 0; i < user_count; i++) {
        if (users[i]->id == id) {
            free(users[i]);
            for (int j = i; j < user_count - 1; j++) {
                users[j] = users[j + 1];
            }
            user_count--;
            return 0; // Success
        }
    }
    return -3; // User not found
}

// Function to free all allocated memory
void free_users() {
    for (int i = 0; i < user_count; i++) {
        free(users[i]);
    }
    user_count = 0;
}
