int* allocate_key_array(size_t size) {
    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for key array");
        return NULL;
    }
    // Initialize keys with zero or a default value
    for (size_t i = 0; i < size; ++i) {
        keys[i] = 0; // Example initialization
    }
    return keys;
}

record* allocate_record_array(size_t size, int* keys, size_t key_size) {
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for record array");
        return NULL;
    }

    // Assign unique keys to each record
    for (size_t i = 0; i < size; ++i) {
        int key;
        do {
            key = rand() % key_size; // Using a cryptographically weak PRNG
        } while (keys[key] != 0); // Check for uniqueness

        records[i].value = key; // Assign unique key to record
        keys[key] = key + 1; // Mark key as used
    }

    return records;
}

