    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

void log_memory_allocation(const char* message, size_t size) {
    printf("Allocated %zu bytes for %s\n", size, message);
}

int generate_secure_random(int min, int max) {
    // Implement cryptographically secure PRNG here
    // For simplicity, using rand() as an example
    return min + rand() % (max - min + 1);
}

void initialize_records(Record* records, int num_records, int min_value, int max_value) {
    srand(time(NULL)); // Seed for non-cryptographically secure PRNG

    for (int i = 0; i < num_records; ) {
        int key = generate_secure_random(min_value, max_value);
        bool is_unique = true;

        for (int j = 0; j < i; j++) {
            if (records[j].value == key) {
                is_unique = false;
                break;
            }
        }

        if (is_unique) {
            records[i].value = key;
            i++;
        }
    }
}

void* manage_memory(size_t initial_size, int min_value, int max_value) {
    size_t total_size = initial_size * sizeof(Record);
    Record* records = allocate_memory(total_size);

    log_memory_allocation("records", total_size);

    initialize_records(records, initial_size, min_value, max_value);

    return records;
