#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_KEYS 1000
#define RETRY_LIMIT 10

typedef struct {
    int key;
    long offset;
    int value;
} Record;

typedef struct {
    Record *data;
    size_t capacity;
    size_t count;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->capacity = 16;
    array->count = 0;
    array->data = (Record*)malloc(array->capacity * sizeof(Record));
    return array;
}

void resize_dynamic_array(DynamicArray *array) {
    array->capacity *= 2;
    Record *new_data = (Record*)realloc(array->data, array->capacity * sizeof(Record));
    if (new_data) {
        array->data = new_data;
    }
}

int insert_record(DynamicArray *array, int key, long offset, int value) {
    for (int i = 0; i < RETRY_LIMIT; i++) {
        int found = 0;
        for (size_t j = 0; j < array->count; j++) {
            if (array->data[j].key == key) {
                found = 1;
                break;
            }
        }
        if (!found) {
            if (array->count >= array->capacity) {
                resize_dynamic_array(array);
            }
            array->data[array->count].key = key;
            array->data[array->count].offset = offset;
            array->data[array->count].value = value;
            array->count++;
            return 1;
        } else {
            // Retry with a new key using a custom PRNG
            key = (key * 23 + 47) % MAX_KEYS; // Example PRNG
        }
    }
    return 0;
}

void free_dynamic_array(DynamicArray *array) {
    free(array->data);
    free(array);
}
