public class RandomValueGenerator
{
    private int lowerBound;
    private int upperBound;

    public RandomValueGenerator(int lower, int upper)
    {
        if (lower > upper) throw new ArgumentException("Lower bound cannot be greater than upper bound.");
        lowerBound = lower;
        upperBound = upper;
    }

    public float GetRandomFloat()
    {
        return lowerBound + ((float)Math.random() * (upperBound - lowerBound));
    }

    public int GetRandomInt()
    {
        if (lowerBound == upperBound) return lowerBound;
        return lowerBound + RandomNumberGenerator.GetInt32(0, upperBound - lowerBound);
    }

    public int GetSecureRandomInt()
    {
        using (RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider())
        {
            byte[] randomNumber = new byte[4];
            rng.GetBytes(randomNumber);
            return BitConverter.ToInt32(randomNumber, 0) % (upperBound - lowerBound + 1) + lowerBound;
        }
    }
}

public struct Record
{
    public int Value { get; set; }
}

public class Program
{
    public static void Main()
    {
        RandomValueGenerator generator = new RandomValueGenerator(0, 100);
        Record[] records = InitializeRecords(100, false);
        for (int i = 0; i < records.Length; i++)
        {
            if (i % 2 == 0)
                records[i].Value = generator.GetRandomInt();
            else
                records[i].Value = generator.GetSecureRandomInt();
        }
    }

    public static Record[] InitializeRecords(int count, bool secure)
    {
        long[] offsets = new long[count];
        int[] keys = new int[count];
        Record[] records = new Record[count];

        for (int i = 0; i < count; i++)
        {
            offsets[i] = i;
            keys[i] = i * 2;
            records[i] = new Record();
        }

        return records;
    }
}
