#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} Record;

Record* create_records(int count, int min_value, int max_value) {
    if (count <= 0 || min_value > max_value) {
        return NULL; // Handle invalid input
    }

    Record* records = (Record*)malloc(count * sizeof(Record));
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(time(NULL)); // Seed PRNG with current time

    for (int i = 0; i < count; i++) {
        records[i].offset = rand(); // Use non-cryptographic PRNG
        records[i].key = rand() % (max_value - min_value + 1) + min_value;
    }

    return records;
}
