### C# `RandomValueGenerator` Class Code

```csharp
using System;

public class RandomValueGenerator
{
    private readonly Random _nonCryptoRandom;
    private readonly RNGCryptoServiceProvider _cryptoRandom;

    public int MinValue { get; set; }
    public int MaxValue { get; set; }

    public RandomValueGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentException("MinValue must be less than or equal to MaxValue");
        }

        _nonCryptoRandom = new Random();
        _cryptoRandom = new RNGCryptoServiceProvider();
        MinValue = minValue;
        MaxValue = maxValue;
    }

    public int GetNonCryptoRandomInt()
    {
        return _nonCryptoRandom.Next(MinValue, MaxValue + 1);
    }

    public float GetNonCryptoRandomFloat()
    {
        return (float)_nonCryptoRandom.NextDouble() * (MaxValue - MinValue) + MinValue;
    }

    public int GetCryptoRandomInt()
    {
        byte[] data = new byte[4];
        _cryptoRandom.GetBytes(data);
        uint result = BitConverter.ToUInt32(data, 0);
        return (int)(result % (uint)(MaxValue - MinValue + 1)) + MinValue;
    }

    public float GetCryptoRandomFloat()
    {
        byte[] data = new byte[4];
        _cryptoRandom.GetBytes(data);
        uint result = BitConverter.ToUInt32(data, 0);
        return (float)result / uint.MaxValue * (MaxValue - MinValue) + MinValue;
    }
}
```

