long generate_unique_id() {
    static unsigned long last_id = 0;
    if (!RAND_bytes((unsigned char*)&last_id, sizeof(last_id))) {
        // Handle error
        return -1;
    }
    return ++last_id;
}

config* initialize_data_structures(size_t num_configs) {
    if (num_configs > MAX_CONFIGS) {
        // Handle error: too many configurations
        return NULL;
    }

    long* long_array = malloc(num_configs * sizeof(long));
    char** string_array = malloc(num_configs * sizeof(char*));
    config* config_array = malloc(num_configs * sizeof(config));

    if (!long_array || !string_array || !config_array) {
        // Handle allocation failure
        free(long_array);
        free(string_array);
        free(config_array);
        return NULL;
    }

    srand(time(NULL));  // Initialize random seed

    for (size_t i = 0; i < num_configs; ++i) {
        long_array[i] = generate_unique_id();
        string_array[i] = malloc(128 * sizeof(char));
        sprintf(string_array[i], "Config%d", i);
        config_array[i].probability = (double)rand() / RAND_MAX;
        config_array[i].name = string_array[i];
    }

    return config_array;
}

// Example usage
int main() {
    size_t num_configs = 512;
    config* configs = initialize_data_structures(num_configs);
    if (!configs) {
        // Handle error
        return -1;
    }
    // Use the data structures as needed
    for (size_t i = 0; i < num_configs; ++i) {
        printf("Config %s, Probability: %.2f\n", configs[i].name, configs[i].probability);
        free(configs[i].name);  // Free allocated strings
    }
    free(configs);  // Free the array of config structures
    return 0;
}
```

