typedef struct {
    unsigned int id;
} Device;

typedef struct {
    time_t timestamp;
    float value;
    Device *device;
} SensorReading;

typedef struct {
    time_t timestamp;
    char description[256];
    SensorReading *sensor;
    int resolved;
} EventLog;

typedef struct MemoryPool {
    void *pool;
    size_t size;
    size_t used;
} MemoryPool;

Device* create_device(MemoryPool *pool) {
    Device *device = (Device*)memory_pool_alloc(pool, sizeof(Device));
    device->id = generate_unique_token(); // Assume generate_unique_token() is defined
    return device;
}

SensorReading* create_sensor_reading(MemoryPool *pool, time_t timestamp, float value, Device *device) {
    SensorReading *reading = (SensorReading*)memory_pool_alloc(pool, sizeof(SensorReading));
    reading->timestamp = timestamp;
    reading->value = value;
    reading->device = device;
    return reading;
}

EventLog* create_event_log(MemoryPool *pool, time_t timestamp, const char *description, SensorReading *sensor, int resolved) {
    EventLog *event = (EventLog*)memory_pool_alloc(pool, sizeof(EventLog));
    event->timestamp = timestamp;
    strncpy(event->description, description, sizeof(event->description) - 1);
    event->sensor = sensor;
    event->resolved = resolved;
    return event;
}

void* memory_pool_alloc(MemoryPool *pool, size_t size) {
    if (pool->used + size > pool->size) {
        resize_memory_pool(pool, pool->used + size); // Assume resize_memory_pool() is defined
    }
    void *ptr = (char*)pool->pool + pool->used;
    pool->used += size;
    return ptr;
}

void resize_memory_pool(MemoryPool *pool, size_t new_size) {
    pool->pool = realloc(pool->pool, new_size);
    if (pool->pool == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->size = new_size;
}

void log_memory_allocation(MemoryPool *pool) {
    time_t start_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Perform memory allocations here
    create_device(pool);
    create_sensor_reading(pool, time(NULL), 10.5, create_device(pool));
    create_event_log(pool, time(NULL), "Sensor reading received", create_sensor_reading(pool, time(NULL), 20.5, create_device(pool)), 0);

    clock_gettime(CLOCK_MONOTONIC, &end_time);
    double elapsed_time = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;

    printf("Memory allocation details:\n");
    printf("Start time: %ld.%09ld\n", start_time.tv_sec, start_time.tv_nsec);
    printf("End time: %ld.%09ld\n", end_time.tv_sec, end_time.tv_nsec);
    printf("Elapsed time: %.9f seconds\n", elapsed_time);
    printf("Total memory used: %zu bytes\n", pool->used);
}

int main() {
    MemoryPool pool = {NULL, 0, 0};
    log_memory_allocation(&pool);

    free(pool.pool); // Clean up the allocated memory
    return 0;
}
