import java.util.concurrent.ConcurrentHashMap;
import java.util.List;

public class LoadBalancer {
    private ConcurrentHashMap<String, Server> servers;
    private PRNG prng;

    public LoadBalancer() {
        this.servers = new ConcurrentHashMap<>();
        this.prng = new HighPerformancePRNG();
    }

    public void addServer(String serverId, int weight) {
        servers.put(serverId, new Server(serverId, weight));
    }

    public void removeServer(String serverId) {
        servers.remove(serverId);
    }

    public void updateServerWeight(String serverId, int newWeight) {
        if (servers.containsKey(serverId)) {
            servers.get(serverId).setWeight(newWeight);
        }
    }

    public Server getNextServer() {
        List<Server> healthyServers = getHealthyServers();
        if (!healthyServers.isEmpty()) {
            int index = prng.nextInt(healthyServers.size());
            return healthyServers.get(index);
        }
        return null;
    }

    private List<Server> getHealthyServers() {
        // Filter out unhealthy servers based on real-time metrics
        return servers.values().stream()
                .filter(Server::isHealthy)
                .toList();
    }

    public ConcurrentHashMap<String, Server> getConfig() {
        return new ConcurrentHashMap<>(servers);
    }

    public void updateConfig(ConcurrentHashMap<String, Server> config) {
        servers.clear();
        servers.putAll(config);
    }
}

class Server {
    private String id;
    private int weight;
    private boolean healthy;

    public Server(String id, int weight) {
        this.id = id;
        this.weight = weight;
        this.healthy = true;
    }

    public String getId() {
        return id;
    }

    public void setWeight(int weight) {
        this.weight = weight;
    }

    public int getWeight() {
        return weight;
    }

    public boolean isHealthy() {
        return healthy;
    }

    public void setHealthy(boolean healthy) {
        this.healthy = healthy;
    }
}

class HighPerformancePRNG implements PRNG {
    @Override
    public int nextInt(int bound) {
        // Implement high-performance PRNG logic here
        return (int) (Math.random() * bound);
    }
}

interface PRNG {
    int nextInt(int bound);
}
