#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char *key;
    union {
        char *str_val;
        int int_val;
        int bool_val;
    } value;
    int type; // 0 for string, 1 for integer, 2 for boolean
} ConfigEntry;

typedef struct {
    ConfigEntry **entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ConfigManager;

ConfigManager *config_manager_create(size_t initial_capacity) {
    ConfigManager *manager = (ConfigManager *)malloc(sizeof(ConfigManager));
    if (!manager) return NULL;

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->entries = (ConfigEntry **)calloc(initial_capacity, sizeof(ConfigEntry *));
    if (!manager->entries) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void config_manager_destroy(ConfigManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        ConfigEntry *entry = manager->entries[i];
        free(entry->key);
        switch (entry->type) {
            case 0: // string
                free(entry->value.str_val);
                break;
            default:
                break;
        }
        free(entry);
    }

    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int config_manager_set(ConfigManager *manager, const char *key, void *value, int type) {
    pthread_mutex_lock(&manager->lock);

    // Check if key already exists
    for (size_t i = 0; i < manager->count; ++i) {
        ConfigEntry *entry = manager->entries[i];
        if (strcmp(entry->key, key) == 0) {
            switch (type) {
                case 0:
                    entry->value.str_val = strdup((char *)value);
                    break;
                case 1:
                    entry->value.int_val = *(int *)value;
                    break;
                case 2:
                    entry->value.bool_val = *(int *)value;
                    break;
                default:
                    pthread_mutex_unlock(&manager->lock);
                    return -1; // Invalid type
            }
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    // Key does not exist, add new entry
    if (manager->count == manager->capacity) {
        manager->capacity *= 2;
        ConfigEntry **new_entries = (ConfigEntry **)realloc(manager->entries, manager->capacity * sizeof(ConfigEntry *));
        if (!new_entries) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->entries = new_entries;
    }

    ConfigEntry *entry = (ConfigEntry *)malloc(sizeof(ConfigEntry));
    entry->key = strdup(key);
    switch (type) {
        case 0:
            entry->value.str_val = strdup((char *)value);
            break;
        case 1:
            entry->value.int_val = *(int *)value;
            break;
        case 2:
            entry->value.bool_val = *(int *)value;
            break;
        default:
            free(entry->key);
            free(entry);
            pthread_mutex_unlock(&manager->lock);
            return -1; // Invalid type
    }
    entry->type = type;

    manager->entries[manager->count++] = entry;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Additional functions for getting values, resizing, logging, etc. can be implemented similarly.
