#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_POOL_SIZE 1024
#define MAX_LOG_LEVEL 3

typedef struct {
    int id;
    time_t timestamp;
} DataStruct;

typedef struct {
    DataStruct *pool;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
    FILE *log_file;
    int log_level;
} MemoryPool;

MemoryPool* create_memory_pool(int initial_size, int log_level) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = (DataStruct*)malloc(initial_size * sizeof(DataStruct));
    mp->size = initial_size;
    mp->count = 0;
    pthread_mutex_init(&mp->lock, NULL);
    mp->log_file = log_level > 0 ? fopen("memory_pool.log", "w") : NULL;
    mp->log_level = log_level;
    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    if (mp->log_file) fclose(mp->log_file);
    pthread_mutex_destroy(&mp->lock);
    free(mp->pool);
    free(mp);
}

DataStruct* allocate_data_struct(MemoryPool *mp, int min_id, int max_id, time_t min_timestamp, time_t max_timestamp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->count == mp->size) {
        mp->size *= 2;
        mp->pool = realloc(mp->pool, mp->size * sizeof(DataStruct));
    }
    DataStruct *ds = &mp->pool[mp->count++];
    ds->id = rand() % (max_id - min_id + 1) + min_id;
    ds->timestamp = (rand() % (max_timestamp - min_timestamp + 1)) + min_timestamp;
    if (mp->log_file && mp->log_level >= 1) fprintf(mp->log_file, "Allocated data struct with ID: %d and timestamp: %ld\n", ds->id, ds->timestamp);
    pthread_mutex_unlock(&mp->lock);
    return ds;
}

void log_memory_usage(MemoryPool *mp, int level) {
    if (mp->log_level >= level && mp->log_file) fprintf(mp->log_file, "Current memory usage: %zu/%zu\n", mp->count, mp->size);
}

int main() {
    srand(time(NULL));
    MemoryPool *mp = create_memory_pool(INITIAL_POOL_SIZE, MAX_LOG_LEVEL);

    for (int i = 0; i < 2048; i++) {
        DataStruct *ds = allocate_data_struct(mp, 1, 100000, time(NULL) - 365*24*3600, time(NULL));
        if (!ds) {
            printf("Failed to allocate data struct\n");
            break;
        }
    }

    log_memory_usage(mp, 2);
    destroy_memory_pool(mp);
    return 0;
}
