#include <stdlib.h>
#include <stdio.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} Record;

unsigned long fast_prng_state = 12345; // Initial seed for PRNG

// Fast PRNG function to generate pseudo-random numbers
unsigned long fast_prng() {
    fast_prng_state = fast_prng_state * 1664525 + 1013904223;
    return fast_prng_state >> 16; // Return a 16-bit value
}

// Function to allocate memory and initialize arrays using the PRNG
int manage_memory(long **offsets, int **keys, Record **records) {
    *offsets = (long *)malloc(MAX_RECORDS * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return -1;
    }

    *keys = (int *)malloc(MAX_RECORDS * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        fprintf(stderr, "Memory allocation failed for keys\n");
        return -2;
    }

    *records = (Record *)malloc(MAX_RECORDS * sizeof(Record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        fprintf(stderr, "Memory allocation failed for records\n");
        return -3;
    }

    // Initialize arrays using the PRNG
    for (int i = 0; i < MAX_RECORDS; i++) {
        (*offsets)[i] = fast_prng() % 1000000L; // Random offset value
        (*keys)[i] = fast_prng(); // Random key value
        (*records)[i].value = fast_prng(); // Random record value
