    }

    srand(seed);

    long* offset_array = malloc(size * sizeof(long));
    char** string_array = malloc(size * sizeof(char*));
    Config* config_array = malloc(size * sizeof(Config));

    if (offset_array == NULL || string_array == NULL || config_array == NULL) {
