    }

    for (int i = 0; i < size; i++) {
        offset_array[i] = rand();
        string_array[i] = malloc(50 * sizeof(char)); // Assuming max string length of 49
        if (string_array[i] == NULL) {
            for (int j = 0; j < i; j++) {
                free(string_array[j]);
            }
            free(offset_array);
            free(config_array);
            return NULL; // Memory allocation failed
        }

        snprintf(string_array[i], 50, "Config%d", rand());
        config_array[i].probability = ((double)rand()) / RAND_MAX;
        config_array[i].config_name = string_array[i];
    }

    return config_array;
}

