#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <unordered_map>
#include <random>
#include <chrono>
#include <string>

class ConfigManager {
public:
    void loadConfig(const std::string& profile);
    void saveConfig(const std::string& profile, const std::unordered_map<std::string, std::string>& settings);
    int getRetryInterval();
    void updateRetryInterval(int newInterval);
    // Additional methods for logging, monitoring, and error handling
private:
    std::mutex configMutex;
    std::condition_variable configCV;
    std::unordered_map<std::string, std::unordered_map<std::string, std::string>> configMap;
    std::random_device rd;
    std::mt19937 gen;
    int retryInterval = 500; // Default retry interval in milliseconds
};

void ConfigManager::loadConfig(const std::string& profile) {
    std::unique_lock<std::mutex> lock(configMutex);
    configCV.wait(lock, [this, &profile]{ return configMap.find(profile) != configMap.end(); });
    // Simulate loading config from a REST API
    // For demonstration, use hard-coded data
    if (profile == "default") {
        configMap[profile] = {{"network_port", "8080"}, {"service_timeout", "15000"}};
    }
}

void ConfigManager::saveConfig(const std::string& profile, const std::unordered_map<std::string, std::string>& settings) {
    std::unique_lock<std::mutex> lock(configMutex);
    configMap[profile] = settings;
    configCV.notify_all();
}

int ConfigManager::getRetryInterval() {
    return retryInterval;
}

void ConfigManager::updateRetryInterval(int newInterval) {
    std::unique_lock<std::mutex> lock(configMutex);
    retryInterval = newInterval;
}
