        printf("%s\n", message);
    }
}

int allocate_memory(long** long_array, char*** string_array, Config** config_array, size_t size, int verbose) {
    // Allocate memory for the arrays
    *long_array = malloc(size * sizeof(long));
    *string_array = malloc(size * sizeof(char*));
    *config_array = malloc(size * sizeof(Config));

    if (*long_array == NULL || *string_array == NULL || *config_array == NULL) {
        log_message("Memory allocation failed.", verbose);
        return -1;
    }

    // Initialize the arrays
    for (size_t i = 0; i < size; i++) {
        (*long_array)[i] = 0;
        (*string_array)[i] = NULL;
        (*config_array)[i].probability = 0.0;
        (*config_array)[i].config_name = NULL;
    }

    // Seed the CSPRNG
    if (!RAND_bytes((unsigned char*)&size, sizeof(size))) {
        log_message("Failed to seed the CSPRNG.", verbose);
        free(*long_array);
        free(*string_array);
        free(*config_array);
        return -1;
    }

    return 0;
}

