#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/rand.h>
#include <openssl/sha.h>

#define MAX_USERS 1024
#define USERNAME_LEN 64

typedef struct {
    unsigned int id;
    char username[USERNAME_LEN];
    unsigned char password_hash[SHA256_DIGEST_LENGTH];
} UserAccount;

UserAccount *users[MAX_USERS];
int user_count = 0;

unsigned int generate_secure_id() {
    unsigned int id;
    if (!RAND_bytes((unsigned char *)&id, sizeof(id))) {
        fprintf(stderr, "Failed to generate secure ID\n");
        exit(1);
    }
    return id;
}

void hash_password(const char *password, unsigned char *hash) {
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen(password));
    SHA256_Final(hash, &sha256);
}

int add_user(const char *username, const char *password) {
    if (user_count >= MAX_USERS) {
        fprintf(stderr, "User limit reached\n");
        return -1;
    }

    UserAccount *new_user = malloc(sizeof(UserAccount));
    if (!new_user) {
        fprintf(stderr, "Memory allocation failed\n");
        return -2;
    }

    new_user->id = generate_secure_id();
    strncpy(new_user->username, username, USERNAME_LEN);
    hash_password(password, new_user->password_hash);

    users[user_count++] = new_user;

    return 0;
}

void free_users() {
    for (int i = 0; i < user_count; ++i) {
        free(users[i]);
    }
    user_count = 0;
}
