#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/rand.h>

#define MAX_CONFIGS 100
#define MAX_LOGS 1000
#define MIN_PROBABILITY 0.0
#define MAX_PROBABILITY 1.0

typedef struct {
    double probability;
    char* name;
    int id;
} config;

typedef struct {
    time_t timestamp;
    int severity;
    const char* module;
    char* message;
} log_entry;

config* allocate_configs(int size) {
    if (size > MAX_CONFIGS) {
        fprintf(stderr, "Error: Maximum number of configurations exceeded.\n");
        exit(EXIT_FAILURE);
    }
    return (config*)malloc(size * sizeof(config));
}

log_entry* allocate_logs(int size) {
    if (size > MAX_LOGS) {
        fprintf(stderr, "Error: Maximum number of logs exceeded.\n");
        exit(EXIT_FAILURE);
    }
    return (log_entry*)malloc(size * sizeof(log_entry));
}

int generate_id() {
    int id;
    while (!RAND_bytes((unsigned char*)&id, sizeof(id))) {}
    return abs(id); // Ensure the ID is non-negative
}

config* init_configs(int size) {
    config* configs = allocate_configs(size);
    for (int i = 0; i < size; i++) {
        configs[i].probability = ((double)rand() / RAND_MAX) * (MAX_PROBABILITY - MIN_PROBABILITY) + MIN_PROBABILITY;
        configs[i].name = strdup("ConfigName");
        configs[i].id = generate_id();
    }
    return configs;
}

log_entry* init_logs(int size, const char* module) {
    log_entry* logs = allocate_logs(size);
    for (int i = 0; i < size; i++) {
        logs[i].timestamp = time(NULL);
