void copyDataFromChunks(Buffer** chunks, size_t numChunks, size_t numBytes, Buffer* output) {
    output->data = malloc(numBytes);
    if (output->data == NULL) {
        fprintf(stderr, "Memory allocation failed for output buffer\n");
        exit(EXIT_FAILURE);
    }

    size_t offset = 0;
    for (size_t i = 0; i < numChunks && offset < numBytes; ++i) {
        size_t bytesToCopy = numBytes - offset > chunks[i]->length ? chunks[i]->length : numBytes - offset;
        memcpy(output->data + offset, chunks[i]->data, bytesToCopy);
        offset += bytesToCopy;
    }

    output->length = numBytes;
}

void freeMemory(long* longArray, char** stringArray, Config** configArray, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(stringArray[i]);
    }
    free(*longArray);
    free(*stringArray);
    free(*configArray);
}
