function copyDataFromChunks(chunks, numBytes) {
    let outputBuffer = Buffer.allocUnsafe(numBytes);
    let offset = 0;

    chunks.forEach(chunk => {
        if (offset >= numBytes) return;
        let bytesToCopy = Math.min(chunk.length - chunk.offset, numBytes - offset);
        outputBuffer.copy(chunk, chunk.offset, offset, offset + bytesToCopy);
        offset += bytesToCopy;
    });

    return outputBuffer;
}
