typedef struct {
    time_t timestamp;
    double amount;
    unsigned long id;
} transaction_record;

typedef struct {
    char name[100];
    char email[100];
    unsigned long token;
} user_profile;

typedef struct {
    int max_users;
    int current_transactions;
    // Add other system configuration settings here
} system_config;

// Function to initialize memory for the data structures
int init_data_structures(int num_users, int max_transactions, system_config *config) {
    config->max_users = num_users;
    config->current_transactions = 0;

    transaction_record *transactions = (transaction_record *)malloc(num_users * sizeof(transaction_record));
    if (!transactions) return -1;

    user_profile *users = (user_profile *)malloc(num_users * sizeof(user_profile));
    if (!users) {
        free(transactions);
        return -2;
    }

    // Initialize transaction records
    for (int i = 0; i < num_users; ++i) {
        transactions[i].timestamp = time(NULL);
        transactions[i].amount = rand() / (double)RAND_MAX * 1000.0; // Simulated random amount
        transactions[i].id = rand_r((unsigned int *)&time(NULL)); // HRNG for ID
    }

    // Initialize user profiles
    for (int i = 0; i < num_users; ++i) {
        snprintf(users[i].name, sizeof(users[i].name), "User%d", i);
        snprintf(users[i].email, sizeof(users[i].email), "user%d@example.com", i);
        users[i].token = rand_r((unsigned int *)&time(NULL)); // HRNG for token
    }

    config->transactions = transactions;
    config->users = users;

    return 0;
}

// Function to reset all structures to default values
void reset_data_structures(system_config *config) {
    memset(config->transactions, 0, config->max_users * sizeof(transaction_record));
    memset(config->users, 0, config->max_users * sizeof(user_profile));
    config->current_transactions = 0;
}

// Function to free allocated memory for the data structures
void free_data_structures(system_config *config) {
    free(config->transactions);
    free(config->users);
}
