    if (num_configs <= 0 || !string_array) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    long* long_array = malloc(num_configs * sizeof(long));
    config* config_array = malloc(num_configs * sizeof(config));
    int* random_numbers = malloc(num_configs * sizeof(int));

    if (!long_array || !config_array || !random_numbers) {
        fprintf(stderr, "Memory allocation failed\n");
        free(long_array);
        free(config_array);
        free(random_numbers);
        return NULL;
