        long_array[i] = i * 1000; // Example initialization
        config_array[i].probability = ((double)rand() / RAND_MAX); // Random probability
        config_array[i].name = strdup(string_array[i]);
        config_array[i].identifier = generate_secure_random_number();
    }

    // Create a struct to hold all the allocated arrays and return it
    struct DataStructs {
        long* long_array;
        config* config_array;
        int* random_numbers;
    };

    struct DataStructs* data_structs = malloc(sizeof(struct DataStructs));
    if (!data_structs) {
        fprintf(stderr, "Memory allocation failed\n");
        free(long_array);
        free(config_array);
        free(random_numbers);
        return NULL;
    }

    data_structs->long_array = long_array;
    data_structs->config_array = config_array;
    data_structs->random_numbers = random_numbers;

    return data_structs;
