    double probability;
    char* configuration_name;
} Config;

// Function to generate a unique identifier using CSPRNG
unsigned long generate_unique_id(unsigned long range) {
    static unsigned long last_id = 0;
    while (1) {
        unsigned long new_id = arc4random_uniform(range);
        if (new_id != last_id) {
            last_id = new_id;
            return new_id;
        }
    }
}

// Function to manage dynamic memory allocation and initialization
void manage_memory(long* int_array, char** str_array, Config* config_array, size_t initial_size, size_t range) {
    // Allocate memory for arrays
    int_array = (long*)malloc(initial_size * sizeof(long));
    str_array = (char**)malloc(initial_size * sizeof(char*));
    config_array = (Config*)malloc(initial_size * sizeof(Config));

