        snprintf(str_array[i], 256, "String_%zu", i); // Example initialization

        config_array[i].probability = drand48(); // Initialize probability
        asprintf(&config_array[i].configuration_name, "Config_%zu", generate_unique_id(range)); // Initialize configuration name
    }

    // Example usage of the allocated memory
    for (size_t i = 0; i < initial_size; ++i) {
        printf("int_array[%zu] = %ld\n", i, int_array[i]);
        printf("str_array[%zu] = %s\n", i, str_array[i]);
        printf("config_array[%zu].probability = %f\n", i, config_array[i].probability);
        printf("config_array[%zu].configuration_name = %s\n", i, config_array[i].configuration_name);
    }

    // Clean up allocated memory
    for (size_t i = 0; i < initial_size; ++i) {
        free(str_array[i]);
        free(config_array[i].configuration_name);
