        return NULL;
    }

    Transaction *transactions = (Transaction *)malloc(num_transactions * sizeof(Transaction));
    if (!transactions) {
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_transactions; ++i) {
        pthread_mutex_lock(mutex);
        transactions[i].id = rand(); // Use a simple random number generator
        pthread_mutex_unlock(mutex);

        transactions[i].timestamp = time(NULL);
        transactions[i].amount = min_amount + ((double)(rand()) / RAND_MAX) * (max_amount - min_amount);
        int status_index = rand() % MAX_STATUS;
        switch (status_index) {
            case 0: transactions[i].status = STATUS_PENDING; break;
            case 1: transactions[i].status = STATUS_COMPLETED; break;
            case 2: transactions[i].status = STATUS_FAILED; break;
            case 3: transactions[i].status = STATUS_REFUNDED; break;
            case 4: transactions[i].status = STATUS_CANCELLED; break;
        }
    }

    return transactions;
}

