        records[i].value = random() % 10000; // Simplified CSPRNG for example purposes
    }
    return records;
}

long* allocate_long_array(size_t *array_size, size_t growth_factor, size_t *allocation_count) {
    long *longs = (long*)malloc(*array_size * sizeof(long));
    if (!longs) {
        perror("Failed to allocate long array");
        return NULL;
    }
    memset(longs, 0, *array_size * sizeof(long));
    *allocation_count += *array_size;
    return longs;
}

int* allocate_int_array(size_t *array_size, size_t growth_factor, size_t *allocation_count) {
    int *ints = (int*)malloc(*array_size * sizeof(int));
    if (!ints) {
        perror("Failed to allocate int array");
        return NULL;
    }
    memset(ints, 0, *array_size * sizeof(int));
    *allocation_count += *array_size;
    return ints;
}

void reset_allocation_count(size_t *allocation_count) {
    *allocation_count = 0;
}
