    int identifier;
} Config;

typedef struct {
    int id;
    long value;
    double ratio;
} Record;

// Function to generate random numbers securely using CSPRNG
int secure_random(int range) {
    return (rand() % range) + 1; // Simplified for example purposes
}

// Function to initialize data structures dynamically
void init_data_structures(long* long_array, char** str_array, Config* config_array, Record* record_array, int size) {
    if (size <= 0) {
        fprintf(stderr, "Invalid size provided.\n");
        return;
    }

    srand(time(NULL)); // Seed for CSPRNG

    for (int i = 0; i < size; i++) {
        long_array[i] = secure_random(1000); // Example allocation
        str_array[i] = malloc(sizeof(char) * 20);
        snprintf(str_array[i], 20, "Config_%d", i);

        config_array[i].probability = (double)rand() / RAND_MAX;
        config_array[i].config_name = strdup(str_array[i]);
        config_array[i].identifier = secure_random(100000); // Example identifier generation

        record_array[i].id = secure_random(100);
        record_array[i].value = 23 * i; // Example multiple of a prime
        record_array[i].ratio = (double)rand() / RAND_MAX;
    }
}

// Function to clean up allocated memory
void cleanup(long* long_array, char** str_array, Config* config_array, Record* record_array, int size) {
    for (int i = 0; i < size; i++) {
        free(str_array[i]);
        free(config_array[i].config_name);
    }
}

// Example usage in a larger system
