    const int array_size = 10;
    long* long_array = malloc(sizeof(long) * array_size);
    char** str_array = malloc(sizeof(char*) * array_size);
    Config* config_array = malloc(sizeof(Config) * array_size);
    Record* record_array = malloc(sizeof(Record) * array_size);

    if (long_array && str_array && config_array && record_array) {
        init_data_structures(long_array, str_array, config_array, record_array, array_size);

        // Perform operations with the allocated data structures

        cleanup(long_array, str_array, config_array, record_array, array_size);
    }

    free(long_array);
    free(str_array);
    free(config_array);
    free(record_array);

    return 0;
}
