#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    char status;
    int value;
} record;

record* initialize_records(int num_records, time_t seed) {
    if (num_records > 10000) {
        fprintf(stderr, "Error: Number of records exceeds limit.\n");
        return NULL;
    }

    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        perror("Memory allocation failed.");
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < num_records; i++) {
        records[i].offset = rand();
        records[i].key = rand() % 1000; // Random key between 0 and 999
        records[i].status = 'A' + (rand() % 26); // Random status between A and Z
        records[i].value = rand() % 10000; // Random value between 0 and 9999
    }

    return records;
}

void free_records(record* records) {
    free(records);
}

int main() {
    time_t seed = time(NULL);
    record* records = initialize_records(5000, seed);

    if (records) {
        for (int i = 0; i < 5000; i++) {
            printf("Record %d: offset=%ld, key=%d, status=%c, value=%d\n",
                   i, records[i].offset, records[i].key, records[i].status, records[i].value);
        }
        free_records(records);
    }

    return 0;
}
