    return (unsigned long*)calloc(count, sizeof(unsigned long));
}

unsigned int* allocate_sequence_numbers(size_t count) {
    return (unsigned int*)calloc(count, sizeof(unsigned int));
}

Transaction* allocate_transactions(size_t count) {
    return (Transaction*)calloc(count, sizeof(Transaction));
}

void initialize_transaction(Transaction* transaction, size_t index) {
    srand(time(NULL) + index); // Seed PRNG with a unique value per transaction
    transaction->timestamp = (unsigned long)rand();
    transaction->sequence_number = (unsigned int)rand();
}

int manage_memory(size_t count, unsigned long** timestamps, unsigned int** sequence_numbers, Transaction** transactions) {
    *timestamps = allocate_timestamps(count);
    if (*timestamps == NULL) return -1;

    *sequence_numbers = allocate_sequence_numbers(count);
    if (*sequence_numbers == NULL) {
        free(*timestamps);
        return -1;
    }

    *transactions = allocate_transactions(count);
    if (*transactions == NULL) {
        free(*timestamps);
        free(*sequence_numbers);
        return -1;
    }

    for (size_t i = 0; i < count; ++i) {
        initialize_transaction(&(*transactions)[i], i);
    }

