record* createClimateData(long numRecords, long minOffset, long maxOffset, int minValue, int maxValue, double minTemp, double maxTemp) {
    if (numRecords <= 0 || minOffset > maxOffset || minValue >= maxValue || minTemp > maxTemp) {
        return NULL;
    }

    long *offsets = malloc(numRecords * sizeof(long));
    int *keys = malloc(numRecords * sizeof(int));
    double *temps = malloc(numRecords * sizeof(double));
    record *records = malloc(numRecords * sizeof(record));

    if (offsets == NULL || keys == NULL || temps == NULL || records == NULL) {
        // Handle allocation failure
        free(offsets);
        free(keys);
        free(temps);
        return NULL;
    }

    srand(time(NULL)); // Seed for CSPRNG

    for (long i = 0; i < numRecords; ++i) {
        offsets[i] = minOffset + rand() % (maxOffset - minOffset + 1);
        keys[i] = minValue + rand() % (maxValue - minValue + 1);

        do {
            records[i].id = keys[i];
            for (int j = 0; j < 20; ++j) {
                char c = 'A' + rand() % 26;
                while ((j > 1 && records[i].location[j - 2] == records[i].location[j - 1] &&
                        records[i].location[j - 1] == c)) {
                    c = 'A' + rand() % 26;
                }
                records[i].location[j] = c;
            }
            records[i].location[20] = '\0';
        } while (isalpha(records[i].location[0]) && isdigit(records[i].location[1]));

        temps[i] = minTemp + ((double)rand() / RAND_MAX) * (maxTemp - minTemp);
        records[i].temperature = temps[i];
    }

    return records;
}

// Example usage:
int main() {
    long numRecords = 1000000;
    long minOffset = 0, maxOffset = 1000;
    int minValue = 1, maxValue = 100;
    double minTemp = -50.0, maxTemp = 50.0;

    record *climateData = createClimateData(numRecords, minOffset, maxOffset, minValue, maxValue, minTemp, maxTemp);

    if (climateData != NULL) {
        // Use the climateData array
        free(climateData);
    }

    return 0;
}
