Config* allocate_configs(int count, const char* name_prefix) {
    if (count <= 0 || !name_prefix) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    Config* configs = malloc(count * sizeof(Config));
    if (!configs) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG for better performance

    char buffer[256];
    for (int i = 0; i < count; ++i) {
        snprintf(buffer, sizeof(buffer), "%s_%d", name_prefix, i);
        configs[i].config_name = strdup(buffer);
        if (!configs[i].config_name) {
            perror("Memory allocation failed");
            goto cleanup;
        }

        configs[i].probability = (double)rand() / RAND_MAX;
        configs[i].identifier = rand();
    }

cleanup:
    for (int i = 0; i < i; ++i) {
        free(configs[i].config_name);
    }
    if (configs) {
        free(configs);
    }
    return NULL;
}

Record* allocate_records(int count, int min_value, int max_value, long prime_number) {
    if (count <= 0 || min_value > max_value || prime_number <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    Record* records = malloc(count * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG for better performance

    for (int i = 0; i < count; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
        records[i].multiple_of_prime = prime_number * (long)((double)rand() / RAND_MAX);
        records[i].precise_value = (double)rand() / (RAND_MAX * 2.0);
    }

    return records;
}
