['```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    unsigned long timestamp;
    unsigned int sequence_number;
    unsigned int event_id;
} Transaction;

typedef struct {
    unsigned long timestamp;
    unsigned int sequence_number;
    unsigned int event_id;
} Event;

typedef struct {
    unsigned long *timestamps;
    unsigned int *sequence_numbers;
    Transaction *transactions;
    Event *events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager* init_memory_manager(size_t initial_capacity) {
    MemoryManager *mm = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!mm) return NULL;

    mm->capacity = initial_capacity;
    mm->size = 0;

    mm->timestamps = (unsigned long*)malloc(initial_capacity * sizeof(unsigned long));
    mm->sequence_numbers = (unsigned int*)malloc(initial_capacity * sizeof(unsigned int));
    mm->transactions = (Transaction*)malloc(initial_capacity * sizeof(Transaction));
    mm->events = (Event*)malloc(initial_capacity * sizeof(Event));

    if (!mm->timestamps || !mm->sequence_numbers || !mm->transactions || !mm->events) {
        free(mm);
        return NULL;
    }

    pthread_mutex_init(&mm->lock, NULL);

    srand(time(NULL)); // Seed for PRNG
    return mm;
}

void resize_memory_manager(MemoryManager *mm) {
    size_t new_capacity = mm->capacity * 2;
    unsigned long *new_timestamps = (unsigned long*)realloc(mm->timestamps, new_capacity * sizeof(unsigned long));
    unsigned int *new_sequence_numbers = (unsigned int*)realloc(mm->sequence_numbers, new_capacity * sizeof(unsigned int));
    Transaction *new_transactions = (Transaction*)realloc(mm->transactions, new_capacity * sizeof(Transaction));
    Event *new_events = (Event*)realloc(mm->events, new_capacity * sizeof(Event));

    if (!new_timestamps || !new_sequence_numbers || !new_transactions || !new_events) {
        // Handle error: reallocation failed
        return;
    }

    mm->timestamps = new_timestamps;
    mm->sequence_numbers = new_sequence_numbers;
    mm->transactions = new_transactions;
    mm->events = new_events;
    mm->capacity = new_capacity;
}

void add_data(MemoryManager *mm, unsigned long timestamp, unsigned int sequence_number) {
    pthread_mutex_lock(&mm->lock);

    if (mm->size == mm->capacity) {
        resize_memory_manager(mm);
    }

    mm->timestamps[mm->size] = timestamp;
    mm->sequence_numbers[mm->size] = sequence_number;

    // Initialize transaction and event with random values
    mm->transactions[mm->size].timestamp = rand();
    mm->transactions[mm->size].sequence_number = rand();
    mm->transactions[mm->size].event_id = rand();

    mm->events[mm->size].timestamp = rand();
    mm->events[mm->size].sequence_number = rand();
    mm->events[mm->size].event_id = rand();

    mm->size++;

    pthread_mutex_unlock(&mm->lock);
}

void destroy_memory_manager(MemoryManager *mm) {
    if (mm) {
        free(mm->timestamps);
        free(mm->sequence_numbers);
        free(mm->transactions);
        free(mm->events);
        pthread_mutex_destroy(&mm->lock);
        free(mm);
    }
}
