#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    unsigned char flag;
} Record;

Record* initialize_records(int long_size, int int_size, int record_size, int range_start, int range_end, int sort_order) {
    srand(time(NULL));

    long* offsets = (long*)malloc(long_size * sizeof(long));
    int* keys = (int*)malloc(int_size * sizeof(int));
    Record* records = (Record*)malloc(record_size * sizeof(Record));

    if (!offsets || !keys || !records) {
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < record_size; i++) {
        offsets[i] = rand();
        keys[i] = rand() % (range_end - range_start + 1) + range_start;
        records[i].value = keys[i];
        records[i].flag = (i % 2 == 0) ? 1 : 0; // Example flag initialization
    }

    if (sort_order == 1) {
        qsort(records, record_size, sizeof(Record), ascending_compare);
    } else if (sort_order == -1) {
        qsort(records, record_size, sizeof(Record), descending_compare);
    }

    return records;
}

int ascending_compare(const void* a, const void* b) {
    Record rec_a = *(Record*)a;
    Record rec_b = *(Record*)b;

    if (rec_a.value < rec_b.value) return -1;
    if (rec_a.value > rec_b.value) return 1;
    return 0;
}

int descending_compare(const void* a, const void* b) {
    Record rec_a = *(Record*)a;
    Record rec_b = *(Record*)b;

    if (rec_a.value < rec_b.value) return 1;
    if (rec_a.value > rec_b.value) return -1;
    return 0;
}

void free_records(Record* records, int record_size) {
    free(records);
}
