    for (size_t i = 0; i < size; ++i) {
        // Generate a random offset within the specified range
        offsets[i] = rand() % (offset_range_end - offset_range_start + 1) + offset_range_start;

        // Initialize record value
        records[i].value = offsets[i];
    }

    // Clean up if allocation of record values fails
    if (!records) {
        free(offsets); // Free previously allocated offsets
        free(records); // Free previously allocated records
        return NULL; // Memory allocation failed
    }

    // Return the pointer to the array of records
