#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    unsigned char flag;
} record;

unsigned long xoroshiro128plus(unsigned long *s) {
    unsigned long s0 = s[0], s1 = s[1];
    unsigned long result = s0 + s1;
    s0 ^= s1;
    s[0] = ((s0 << 55) | (s0 >> 9)) ^ s1 ^ (s1 << 14);
    s[1] = (s1 << 36) ^ s0 ^ (s0 << 27);
    return result;
}

void shuffle(unsigned long *array, size_t n, unsigned long seed) {
    for (size_t i = n - 1; i > 0; --i) {
        unsigned long j = xoroshiro128plus(&seed) % (i + 1);
        unsigned long temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

record* initialize_records(size_t num_records, int min_value, int max_value, unsigned long seed) {
    if (num_records == 0 || min_value > max_value) return NULL;

    record *records = malloc(num_records * sizeof(record));
    int *keys = malloc(num_records * sizeof(int));
    long *offsets = malloc(num_records * sizeof(long));
    char *temp_buffer = malloc(num_records * sizeof(char));

    if (records == NULL || keys == NULL || offsets == NULL || temp_buffer == NULL) {
        free(records);
        free(keys);
        free(offsets);
        free(temp_buffer);
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = min_value + xoroshiro128plus(&seed) % (max_value - min_value + 1);
        keys[i] = records[i].value;
        offsets[i] = i * sizeof(record);
    }

    shuffle(keys, num_records, seed);

    for (size_t i = 0; i < num_records; ++i) {
        for (size_t j = 0; j < num_records; ++j) {
            if (records[j].value == keys[i]) {
                records[j].flag = 1;
                break;
            }
        }
    }

    return records;
}

void sort_records(record *records, size_t num_records) {
    for (size_t i = 0; i < num_records - 1; ++i) {
        for (size_t j = 0; j < num_records - i - 1; ++j) {
            if (records[j].value > records[j + 1].value) {
                record temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

void copy_records(record *source, record *destination, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        destination[i] = source[i];
    }
}

void free_memory(record *records, int *keys, long *offsets, char *temp_buffer) {
    free(records);
    free(keys);
    free(offsets);
    free(temp_buffer);
}
