typedef struct {
    int value;
    unsigned char flag;
    char status;
} record;

record* process_records(int long_offset_size, int int_key_size, int record_size, int metadata_tag_size, int random_range_start, int random_range_end, int load_conditions, int sort_order, char** external_data_source, char* filter_status) {
    // Dynamically allocate memory for arrays
    long* long_offsets = (long*)malloc(long_offset_size * sizeof(long));
    int* int_keys = (int*)malloc(int_key_size * sizeof(int));
    record* records = (record*)malloc(record_size * sizeof(record));
    char** metadata_tags = (char**)malloc(metadata_tag_size * sizeof(char*));

    // Initialize arrays and populate with random values
    srand(time(NULL)); // Seed for PRNG
    for (int i = 0; i < record_size; ++i) {
        records[i].value = rand() % (random_range_end - random_range_start + 1) + random_range_start;
        records[i].flag = (unsigned char)(rand() % 256);
        records[i].status = 'A' + (rand() % 3); // Assuming status can be A, B, or C
    }

    // Sort records based on integer values
    if (sort_order == 1) {
        qsort(records, record_size, sizeof(record), compare_asc);
    } else if (sort_order == -1) {
        qsort(records, record_size, sizeof(record), compare_desc);
    }

    // Filter records based on status indicator
    int filtered_size = 0;
    for (int i = 0; i < record_size; ++i) {
        if (records[i].status == filter_status[0]) {
            filtered_size++;
        }
    }
    record* filtered_records = (record*)malloc(filtered_size * sizeof(record));
    int j = 0;
    for (int i = 0; i < record_size; ++i) {
        if (records[i].status == filter_status[0]) {
            filtered_records[j++] = records[i];
        }
    }

    // Free allocated memory
    free(long_offsets);
    free(int_keys);
    free(metadata_tags);

    return filtered_records;
}

int compare_asc(const void* a, const void* b) {
    record* rec_a = (record*)a;
    record* rec_b = (record*)b;
    if (rec_a->value > rec_b->value) return 1;
    else if (rec_a->value < rec_b->value) return -1;
    else return 0;
}

int compare_desc(const void* a, const void* b) {
    record* rec_a = (record*)a;
    record* rec_b = (record*)b;
    if (rec_a->value > rec_b->value) return -1;
    else if (rec_a->value < rec_b->value) return 1;
    else return 0;
}
