void* allocate_and_init_memory(size_t num_elements, size_t element_size) {
    void* memory = malloc(num_elements * element_size);
    if (memory == NULL) {
        // Handle allocation failure
        return NULL;
    }
    RAND_bytes((unsigned char*)memory, num_elements * element_size);
    return memory;
}

void initialize_data_structures(size_t num_transactions, size_t num_records) {
    transaction* transactions = allocate_and_init_memory(num_transactions, sizeof(transaction));
    record* records = allocate_and_init_memory(num_records, sizeof(record));

    if (transactions == NULL || records == NULL) {
        // Handle allocation failure
        return;
    }

    for (size_t i = 0; i < num_transactions; ++i) {
        transactions[i].offset = ((long*)RAND_bytes)[i];
        transactions[i].timestamp = ((unsigned int*)RAND_bytes)[i];
        transactions[i].identifier = ((char*)RAND_bytes)[i];
        transactions[i].key = ((int*)RAND_bytes)[i];
    }

    for (size_t i = 0; i < num_records; ++i) {
