#define TOKEN_LENGTH 32

typedef struct SessionToken {
    char token[TOKEN_LENGTH];
    time_t expirationTime;
} SessionToken;

SessionToken *allocateSessionTokens(int count, int expirationMinutes) {
    if (count <= 0 || expirationMinutes <= 0) {
        fprintf(stderr, "Invalid input: count and expiration must be positive.\n");
        return NULL;
    }

    SessionToken *tokens = (SessionToken *)malloc(count * sizeof(SessionToken));
    if (tokens == NULL) {
        perror("Failed to allocate memory for session tokens.");
        return NULL;
    }

    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < count; i++) {
        for (int j = 0; j < TOKEN_LENGTH - 1; j++) {
            tokens[i].token[j] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"[rand() % 62];
        }
        tokens[i].token[TOKEN_LENGTH - 1] = '\0';
        tokens[i].expirationTime = time(NULL) + (expirationMinutes * 60);
    }

    return tokens;
}

void freeSessionTokens(SessionToken *tokens, int count) {
    if (tokens != NULL) {
        free(tokens);
    }
}

// Example usage
int main() {
    int tokenCount = 100;
    int expirationInMinutes = 30;

    SessionToken *sessionTokens = allocateSessionTokens(tokenCount, expirationInMinutes);
    if (sessionTokens != NULL) {
        printf("Session tokens allocated successfully.\n");
        // Use the session tokens...

        freeSessionTokens(sessionTokens, tokenCount);
        printf("Session tokens freed.\n");
    }

    return 0;
}
