typedef struct {
    long id;
    int amount;
    char description[256];
    time_t timestamp;
    int urgency; // Custom priority level for transactions
} Transaction;

typedef struct Node {
    Transaction data;
    struct Node* next;
} Node;

typedef struct {
    Node* front;
    Node* rear;
} Queue;

Queue* createQueue() {
    Queue* q = (Queue*)malloc(sizeof(Queue));
    if (q == NULL) return NULL;
    q->front = q->rear = NULL;
    return q;
}

int isEmpty(Queue* q) {
    return q->front == NULL;
}

void enqueue(Queue* q, Transaction data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) return;

    newNode->data = data;
    newNode->next = NULL;

    if (isEmpty(q)) {
        q->front = q->rear = newNode;
    } else {
        q->rear->next = newNode;
        q->rear = newNode;
    }
}

Transaction dequeue(Queue* q) {
    if (isEmpty(q)) return (Transaction){0};

    Node* temp = q->front;
    Transaction data = temp->data;

    q->front = q->front->next;
    if (q->front == NULL)
        q->rear = NULL;

    free(temp);
    return data;
}

// Function to generate a non-cryptographically secure pseudo-random number
long generateTransactionID() {
    static long seed = time(NULL); // Seed the generator with current time
    return (seed = seed * 123456789 + 987654321) % 1000000000; // Simple LCG algorithm
}

void processFinancialTransactions(Queue* transactionQueue, Transaction* transactions, int numTransactions) {
    for (int i = 0; i < numTransactions; i++) {
        if (!isValidTransaction(transactions[i])) {
            continue; // Skip invalid transactions
        }

        enqueue(transactionQueue, transactions[i]); // Add to the queue based on urgency
    }

    while (!isEmpty(transactionQueue)) {
        Transaction currentTransaction = dequeue(transactionQueue);
        processTransaction(currentTransaction); // Process each transaction in order of priority
    }
}

// Function to validate transaction data
int isValidTransaction(Transaction trans) {
    if (trans.id < 0 || trans.amount <= 0 || trans.description[255] != '\0') return 0;
    return 1; // Valid transaction
}

