#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/rand.h>

#define INITIAL_POOL_SIZE 16

typedef struct {
    double probability;
    char* name;
} config;

typedef struct {
    long* long_array;
    char** string_array;
    config* config_array;
    size_t count;
    size_t capacity;
    void (*allocator)(size_t);
    void (*deallocator)(void*);
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->long_array = (long*)malloc(initial_size * sizeof(long));
    pool->string_array = (char**)malloc(initial_size * sizeof(char*));
    pool->config_array = (config*)malloc(initial_size * sizeof(config));
    if (!pool->long_array || !pool->string_array || !pool->config_array) {
        free(pool);
        return NULL;
    }

    pool->count = 0;
    pool->capacity = initial_size;
    pool->allocator = realloc;
    pool->deallocator = free;

    return pool;
}

void resize_memory_pool(MemoryPool* pool, size_t new_capacity) {
    if (new_capacity <= pool->capacity) return;

    pool->long_array = (long*)pool->allocator(pool->long_array, new_capacity * sizeof(long));
    pool->string_array = (char**)pool->allocator(pool->string_array, new_capacity * sizeof(char*));
    pool->config_array = (config*)pool->allocator(pool->config_array, new_capacity * sizeof(config));

    if (!pool->long_array || !pool->string_array || !pool->config_array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    memset(pool->long_array + pool->capacity, 0, (new_capacity - pool->capacity) * sizeof(long));
    memset(pool->string_array + pool->capacity, 0, (new_capacity - pool->capacity) * sizeof(char*));
    memset(pool->config_array + pool->capacity, 0, (new_capacity - pool->capacity) * sizeof(config));

    pool->capacity = new_capacity;
}

void add_config(MemoryPool* pool, double probability, const char* name) {
    if (pool->count >= pool->capacity) resize_memory_pool(pool, pool->capacity * 2);

    config* conf = &pool->config_array[pool->count++];
    conf->probability = probability;

    size_t len = strlen(name) + 1;
    conf->name = (char*)malloc(len);
    if (!conf->name) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    strncpy(conf->name, name, len);

    // Generate unique identifier using CSPRNG
    unsigned char random_bytes[8];
    if (!RAND_bytes(random_bytes, sizeof(random_bytes))) {
        fprintf(stderr, "CSPRNG failure\n");
        exit(1);
    }
    conf->id = *(unsigned long*)random_bytes;
}

void free_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->config_array[i].name) free(pool->config_array[i].name);
    }

    pool->deallocator(pool->long_array);
    pool->deallocator(pool->string_array);
    pool->deallocator(pool->config_array);
    free(pool);
}
