#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double timestamp;
    char* event_type;
    int id;
} Event;

Event* create_event(double ts, const char* type) {
    Event* event = (Event*)malloc(sizeof(Event));
    if (!event) return NULL;

    event->timestamp = ts;
    event->event_type = strdup(type);
    event->id = rand(); // Using a non-cryptographic PRNG for simplicity
    return event;
}

void free_event(Event* event) {
    if (event->event_type) free(event->event_type);
    free(event);
}

Event** allocate_events(int count) {
    Event** events = (Event**)calloc(count, sizeof(Event*));
    if (!events) return NULL;

    for (int i = 0; i < count; ++i) {
        double ts = time(NULL); // Adjust timestamp as needed
        Event* event = create_event(ts, "default_type");
        if (!event) {
            free_events(events, i);
            return NULL;
        }
        events[i] = event;
    }

    return events;
}

void free_events(Event** events, int count) {
    for (int i = 0; i < count; ++i) {
        if (events[i]) free_event(events[i]);
    }
    free(events);
}
