#include <time.h>

typedef struct ConfigRecord {
    int id;
    long resourceId;
    double probability;
    char name[256];
} ConfigRecord;

ConfigRecord* allocateConfigRecords(int size, int minId, int maxId, long primeMultiple) {
    if (size <= 0 || minId >= maxId) {
        return NULL; // Handle invalid input
    }

    ConfigRecord* records = (ConfigRecord*)malloc(size * sizeof(ConfigRecord));
    if (records == NULL) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for PRNG

    for (int i = 0; i < size; ++i) {
        int id;
        do {
            id = minId + rand() % (maxId - minId);
        } while (alreadyExists(id, records, i)); // Ensure uniqueness

        records[i].id = id;
        records[i].resourceId = (primeMultiple * (i + 1)) % ((long)RAND_MAX); // Ensure multiple of prime
        records[i].probability = (double(rand()) / RAND_MAX);
        snprintf(records[i].name, sizeof(records[i].name), "Config%d", i);
    }

    return records;
}

int alreadyExists(int id, ConfigRecord* records, int count) {
    for (int i = 0; i < count; ++i) {
        if (records[i].id == id) {
            return 1; // ID already exists
        }
    }
    return 0;
}

void freeConfigRecords(ConfigRecord* records, int size) {
    if (records != NULL) {
        free(records);
    }
}
