        std::lock_guard<std::mutex> lock(configMutex);
        for (auto& pair : configSettings) {
            if (pair.first == "retryInterval" || pair.first == "connectionTimeout") {
                int adjustedValue = pair.second + distribution(prng) - 5;
                configSettings[pair.first] = std::max(1, adjustedValue);
            }
