typedef struct {
    char name[64];
    int* protocols;
    int protocol_count;
    char default_profile[256];
} DeviceConfig;

DeviceConfig** allocate_device_configs(int initial_size, int* allocated_size, FILE* log_file) {
    DeviceConfig** device_configs = (DeviceConfig**)malloc(initial_size * sizeof(DeviceConfig*));
    if (!device_configs) {
        fprintf(log_file, "Failed to allocate memory for device configs\n");
        return NULL;
    }
    *allocated_size = initial_size;

    srand(time(NULL)); // Seed the CSPRNG

    for (int i = 0; i < initial_size; ++i) {
        device_configs[i] = (DeviceConfig*)malloc(sizeof(DeviceConfig));
        if (!device_configs[i]) {
            fprintf(log_file, "Failed to allocate memory for device config %d\n", i);
            return NULL;
        }

        // Generate a unique token using CSPRNG
        uint64_t token = rand() * RAND_MAX + rand();
        snprintf(device_configs[i]->name, sizeof(device_configs[i]->name), "Device_%llu", token);

        // Initialize device configuration with default values or random values for testing
        device_configs[i]->protocol_count = rand() % 5; // Random protocol count between 0 and 4
        device_configs[i]->protocols = (int*)malloc(device_configs[i]->protocol_count * sizeof(int));
        for (int j = 0; j < device_configs[i]->protocol_count; ++j) {
            device_configs[i]->protocols[j] = rand() % 10; // Random protocol type between 0 and 9
        }
        snprintf(device_configs[i]->default_profile, sizeof(device_configs[i]->default_profile), "Profile_%d", i);

        fprintf(log_file, "Allocated memory for device config %d with token: %llu\n", i, token);
    }

    return device_configs;
}

void free_device_configs(DeviceConfig** device_configs, int size) {
    for (int i = 0; i < size; ++i) {
        if (device_configs[i]->protocols) {
            free(device_configs[i]->protocols);
        }
        free(device_configs[i]);
    }
    free(device_configs);
}

void resize_device_configs(DeviceConfig*** device_configs, int* allocated_size, int new_size, FILE* log_file) {
    DeviceConfig** new_configs = (DeviceConfig**)realloc(*device_configs, new_size * sizeof(DeviceConfig*));
    if (!new_configs) {
        fprintf(log_file, "Failed to reallocate memory for device configs\n");
        return;
    }
    *device_configs = new_configs;
    *allocated_size = new_size;

    // Initialize new configs with default values or random values for testing
    for (int i = (*allocated_size - 1); i < new_size; ++i) {
        (*device_configs)[i] = (DeviceConfig*)malloc(sizeof(DeviceConfig));
        if (!(*device_configs)[i]) {
            fprintf(log_file, "Failed to allocate memory for device config %d\n", i);
            return;
        }

        // Generate a unique token using CSPRNG
        uint64_t token = rand() * RAND_MAX + rand();
        snprintf((*device_configs)[i]->name, sizeof((*device_configs)[i]->name), "Device_%llu", token);

        (*device_configs)[i]->protocol_count = rand() % 5; // Random protocol count between 0 and 4
        (*device_configs)[i]->protocols = (int*)malloc((*device_configs)[i]->protocol_count * sizeof(int));
        for (int j = 0; j < (*device_configs)[i]->protocol_count; ++j) {
            (*device_configs)[i]->protocols[j] = rand() % 10; // Random protocol type between 0 and 9
        }
        snprintf((*device_configs)[i]->default_profile, sizeof((*device_configs)[i]->default_profile), "Profile_%d", i);

        fprintf(log_file, "Allocated memory for device config %d with token: %llu\n", i, token);
    }
}
