        perror("Failed to open configuration file");
        return NULL;
    }

    Record** records = malloc(num_records * sizeof(Record*));
    if (!records) {
        perror("Memory allocation failed for record pointers");
        fclose(config_file);
        return NULL;
    }

    srand(time(NULL)); // Seed for pseudo-random number generation

    for (int i = 0; i < num_records; ++i) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            perror("Memory allocation failed for record");
            free_records(records, i);
            fclose(config_file);
            return NULL;
        }

        records[i]->offset = rand() % 100000; // Example offset generation
        records[i]->key = rand() % 1000;    // Example key generation

        records[i]->token = malloc((max_token_len + 1) * sizeof(char));
        if (!records[i]->token) {
            perror("Memory allocation failed for token");
            free_records(records, i);
            fclose(config_file);
            return NULL;
        }

        // Generate a unique token using OpenSSL's RAND_bytes function
        if (RAND_bytes((unsigned char*)records[i]->token, max_token_len) != 1) {
            perror("Failed to generate random bytes for token");
            free_records(records, i);
            fclose(config_file);
            return NULL;
        }
    }

    // Fetch configuration parameters from the file
    int max_length;
    fscanf(config_file, "%d", &max_length);

    // Adjust token length if necessary
    if (max_token_len < max_length) {
        for (int i = 0; i < num_records; ++i) {
            free(records[i]->token);
            records[i]->token = realloc(records[i]->token, (max_length + 1) * sizeof(char));
            if (!records[i]->token) {
                perror("Memory reallocation failed for token");
                free_records(records, i);
                fclose(config_file);
                return NULL;
            }

            // Regenerate the token
            if (RAND_bytes((unsigned char*)records[i]->token, max_length) != 1) {
                perror("Failed to generate random bytes for token");
                free_records(records, i);
                fclose(config_file);
                return NULL;
            }
        }
    }

    fclose(config_file);
    return records;
}

void free_records(Record** records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        if (records[i]) {
            free(records[i]->token);
            free(records[i]);
        }
    }
