#include <openssl/rand.h>

typedef struct {
    int value;
} record;

void initialize_arrays(long **offsets, int **keys, record **records, size_t max_size, unsigned char *seed, size_t seed_len) {
    // Allocate memory for arrays
    *offsets = (long *)malloc(max_size * sizeof(long));
    *keys = (int *)malloc(max_size * sizeof(int));
    *records = (record *)malloc(max_size * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        // Handle allocation failure
        if (*offsets != NULL) free(*offsets);
        if (*keys != NULL) free(*keys);
        return;
    }

    // Initialize arrays with random values and offsets
    for (size_t i = 0; i < max_size; i++) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand();

        if (!RAND_bytes((unsigned char *)&((*records)[i].value), sizeof(int))) {
            // Handle CSPRNG failure
            free(*offsets);
            free(*keys);
            free(*records);
            return;
        }
    }

    // Seed the CSPRNG with custom seed data if provided, otherwise use current time as seed
    if (seed != NULL && seed_len > 0) {
        RAND_seed(seed, seed_len);
    } else {
        unsigned char seed[16];
        srand(time(NULL));
        for (int i = 0; i < 16; i++) {
            seed[i] = rand();
        }
        RAND_seed(seed, sizeof(seed));
    }

    // Periodically reseed the CSPRNG
    time_t now;
    while ((time(&now) % 3600) != 0); // Wait for a whole hour
    unsigned char new_seed[16];
    srand(time(NULL));
    for (int i = 0; i < 16; i++) {
        new_seed[i] = rand();
    }
    RAND_seed(new_seed, sizeof(new_seed));
}

void free_arrays(long *offsets, int *keys, record *records) {
    // Free allocated memory
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
    if (records != NULL) free(records);
}
