#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <openssl/rand.h> // For cryptographic random number generation

#define ARRAY_SIZE 1000

typedef struct Record {
    long offset;
    int key;
    double value;
} Record;

void logInitialization(FILE* logFile, size_t memorySize, const char* description) {
    time_t current_time = time(NULL);
    fprintf(logFile, "Timestamp: %s, Memory Size: %zu bytes, Description: %s\n", ctime(&current_time), memorySize, description);
}

Record* initializeRecords(FILE* logFile) {
    long* offsets = (long*)malloc(ARRAY_SIZE * sizeof(long));
    int* keys = (int*)malloc(ARRAY_SIZE * sizeof(int));
    double* values = (double*)malloc(ARRAY_SIZE * sizeof(double));

    if (!offsets || !keys || !values) {
        logInitialization(logFile, 0, "Memory allocation failed");
        return NULL;
    }

    Record* records = (Record*)malloc(ARRAY_SIZE * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        free(values);
        logInitialization(logFile, 0, "Memory allocation failed for record array");
        return NULL;
    }

    // Initialize offsets and keys sequentially
    for (size_t i = 0; i < ARRAY_SIZE; ++i) {
        offsets[i] = i * 100L;
        keys[i] = i * 50;
    }

    // Initialize values with cryptographically secure random numbers
    if (!RAND_bytes((unsigned char*)values, ARRAY_SIZE * sizeof(double))) {
        free(offsets);
        free(keys);
        free(values);
        free(records);
        logInitialization(logFile, 0, "Failed to initialize random number generator");
        return NULL;
    }

    // Populate records with initialized data
    for (size_t i = 0; i < ARRAY_SIZE; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].value = values[i];
    }

    logInitialization(logFile, sizeof(Record) * ARRAY_SIZE + sizeof(long) * ARRAY_SIZE + sizeof(int) * ARRAY_SIZE, "Records initialized");

    free(offsets);
    free(keys);

    return records;
}

int main() {
    FILE* logFile = fopen("initialization.log", "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    Record* records = initializeRecords(logFile);
    if (records) {
        // Use the records array for further processing
        free(records);
    }

    fclose(logFile);
    return 0;
}
```

