int initializeDataStructures(int n, long minOffset, long maxOffset, int minValue, int maxValue, record** records) {
    if (n <= 0) return -1; // Error handling for invalid input

    // Allocate arrays in a contiguous block
    size_t totalSize = n * sizeof(long) + n * sizeof(int) + n * sizeof(record);
    void* memoryBlock = malloc(totalSize);
    if (!memoryBlock) return -2; // Memory allocation failure

    long* offsets = (long*)memoryBlock;
    int* keys = (int*)(offsets + n);
    record* recordsArray = (record*)(keys + n);

    // Initialize arrays
    for (int i = 0; i < n; i++) {
        offsets[i] = minOffset + rand() % (maxOffset - minOffset + 1);
        keys[i] = i;
        recordsArray[i].value = minValue + rand() % (maxValue - minValue + 1);
    }

    // Assign the allocated records array to the output parameter
    *records = recordsArray;

    return 0; // Success
}

// Example usage and cleanup
int main() {
    srand(time(NULL)); // Seed the random number generator

    int n = 10;
    record* records;
    int result = initializeDataStructures(n, 100L, 200L, 50, 150, &records);

    if (result == 0) {
        // Use the initialized data structures
        for (int i = 0; i < n; i++) {
            printf("Record %d: Offset=%ld, Key=%d, Value=%d\n", i, records[i].offsets, records[i].keys, records[i].value);
        }

        // Free the allocated memory block
        free(records - n); // Subtract the offset to free the entire block
    } else {
        printf("Failed to initialize data structures with error code: %d\n", result);
    }

    return 0;
}
