unsigned long xorshift(unsigned long* state) {
    unsigned long x = *state;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    *state = x;
    return x;
}

int generate_random(int min, int max, unsigned long* seed_state) {
    return (xorshift(seed_state) % (max - min + 1)) + min;
}

int initialize_arrays(long** timestamps, int** seeds, record*** records, config** configs, int num_records, int seed_range_min, int seed_range_max) {
    *timestamps = malloc(num_records * sizeof(long));
    *seeds = malloc(num_records * sizeof(int));
    **records = malloc(num_records * sizeof(record));
    **configs = malloc(num_records * sizeof(config));

