    char* id;
} Transaction;

// Function to initialize a transaction with a PRNG for the amount
Transaction* init_transaction(long timestamp, const char* id, long seed) {
    // Allocate memory for the transaction
    Transaction* tx = (Transaction*)malloc(sizeof(Transaction));
    if (!tx) {
        perror("Failed to allocate memory for transaction");
        return NULL;
    }

    // Set the timestamp and ID directly
    tx->timestamp = timestamp;
    tx->id = strdup(id);
    if (!tx->id) {
        free(tx);
        perror("Failed to allocate memory for transaction ID");
        return NULL;
    }

    // Initialize a custom PRNG using the seed
    srand(seed);

    // Generate a random amount within a specified range (e.g., $100 to $1000)
    tx->amount = 100 + ((double)rand() / RAND_MAX) * 900;

    return tx;
}

// Function to dynamically resize the transaction array
Transaction** resize_transactions(Transaction** transactions, size_t old_size, size_t new_size) {
    // Reallocate memory for the transaction array
    Transaction** new_transactions = (Transaction**)realloc(transactions, new_size * sizeof(Transaction*));
    if (!new_transactions) {
        perror("Failed to reallocate memory for transactions");
        return NULL;
    }

    return new_transactions;
}

// Function to clean up resources used by transaction objects
void cleanup_transactions(Transaction** transactions, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (transactions[i]) {
            free(transactions[i]->id);
            free(transactions[i]);
        }
    }
    free(transactions);
}

int main() {
    // Example usage
    long seed = time(NULL); // Use current time as the PRNG seed for consistent results across runs

    // Initialize transactions with a custom PRNG
    Transaction* tx1 = init_transaction(time(NULL), "TX001", seed);
    if (tx1) {
        printf("Transaction ID: %s, Amount: %.2f\n", tx1->id, tx1->amount);
        free(tx1->id);
        free(tx1);
    }

    // Dynamically resize transactions array
    size_t initial_size = 10;
    Transaction** transactions = (Transaction**)malloc(initial_size * sizeof(Transaction*));
    if (!transactions) {
        perror("Failed to allocate memory for transaction array");
        return 1;
    }

    // Initialize some transactions
    for (size_t i = 0; i < initial_size; ++i) {
        char id[10];
        snprintf(id, sizeof(id), "TX%03zu", i);
        transactions[i] = init_transaction(time(NULL), id, seed);
        if (!transactions[i]) {
            cleanup_transactions(transactions, i);
            return 1;
        }
    }

    // Resize the transaction array
    size_t new_size = 20;
    transactions = resize_transactions(transactions, initial_size, new_size);
    if (!transactions) {
        return 1;
    }

    // Clean up resources
    cleanup_transactions(transactions, new_size);

    return 0;
}
