    if (n == 0 || timestamps == NULL || indices == NULL || events == NULL) {
        return -1; // Invalid input
    }

    srand(time(NULL)); // Seed the random number generator

    for (unsigned int i = 0; i < n; ++i) {
        indices[i] = i;
        timestamps[i] = time(NULL);
        (*events)[i].index = i;
        (*events)[i].timestamp = timestamps[i];
    }

    for (unsigned int i = 0; i < n; ++i) {
        unsigned long delay = minDelay + rand() % (maxDelay - minDelay + 1);
        (*events)[i].timestamp += delay;
    }

    return 0; // Success
}

// Example usage:
