void manage_memory(long* offset_array, int* key_array, Record** records, int num_records, int min_value, int max_value, unsigned long seed) {
    srand(seed);
    clock_t start = clock();

    // Allocate memory for the arrays
    *offset_array = (long*)malloc(num_records * sizeof(long));
    *key_array = (int*)malloc(num_records * sizeof(int));
    *records = (Record*)calloc(num_records, sizeof(Record));

    if (*offset_array == NULL || *key_array == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize arrays and records
    for (int i = 0; i < num_records; ++i) {
        (*offset_array)[i] = rand() % 1000L; // Example initialization
        (*key_array)[i] = rand() % 1000;     // Example initialization
        do {
            (*records)[i].value = rand() % (max_value - min_value + 1) + min_value;
        } while (find_duplicate(*records, i));

        // Generate unique identifier using PRNG
        (*records)[i].identifier = generate_unique_id(seed);
    }

    clock_t end = clock();
    double time_spent = ((double)(end - start)) / CLOCKS_PER_SEC;

    printf("Memory allocated and initialized in %f seconds\n", time_spent);

    // Clean up if necessary
}

int find_duplicate(Record* records, int index) {
    for (int i = 0; i < index; ++i) {
        if (records[index].value == records[i].value) {
            return 1;
        }
    }
    return 0;
}

unsigned long generate_unique_id(unsigned long seed) {
    // Implement a pseudo-random number generator with unique identifiers
    return rand_r(&seed);
}
