typedef struct {
    int value;
} record;

typedef struct {
    long *timestamps;
    int *seeds;
    record **records;
    size_t num_records;
} config;

config* create_config(size_t num_records) {
    config *cfg = (config*)malloc(sizeof(config));
    if (!cfg) return NULL;

    cfg->num_records = num_records;

    cfg->timestamps = (long*)calloc(num_records, sizeof(long));
    if (!cfg->timestamps) {
        free(cfg);
        return NULL;
    }

    cfg->seeds = (int*)calloc(num_records, sizeof(int));
    if (!cfg->seeds) {
        free(cfg->timestamps);
        free(cfg);
        return NULL;
    }

    cfg->records = (record**)malloc(num_records * sizeof(record*));
    if (!cfg->records) {
        free(cfg->seeds);
        free(cfg->timestamps);
        free(cfg);
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        cfg->records[i] = (record*)malloc(sizeof(record));
        if (!cfg->records[i]) {
            // Clean up previously allocated memory
            for (size_t j = 0; j < i; ++j) free(cfg->records[j]);
            free(cfg->records);
            free(cfg->seeds);
            free(cfg->timestamps);
            free(cfg);
            return NULL;
        }
    }

    return cfg;
}

void initialize_config(config *cfg, time_t start_time, int seed_base) {
    for (size_t i = 0; i < cfg->num_records; ++i) {
        cfg->timestamps[i] = start_time + i * 1000; // Example timestamp generation
        cfg->seeds[i] = seed_base + i; // Example seed generation

        srand(cfg->seeds[i]);
        cfg->records[i]->value = rand() % 1000; // Example PRNG usage
    }
}

void free_config(config *cfg) {
    for (size_t i = 0; i < cfg->num_records; ++i) free(cfg->records[i]);
    free(cfg->records);
    free(cfg->seeds);
    free(cfg->timestamps);
    free(cfg);
}
```

