encryption_record* initialize_encryption_records(int num_records, int min_value, int max_value) {
    if (num_records <= 0 || min_value > max_value) {
        return NULL; // Invalid input
    }

    encryption_record *records = malloc(num_records * sizeof(encryption_record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;

        char *identifier = malloc(21); // Assuming identifiers are up to 20 characters long
        if (!identifier) {
            for (int j = 0; j < i; ++j) {
                free(records[j].identifier);
            }
            free(records);
            return NULL; // Memory allocation failed
        }

        snprintf(identifier, 21, "record_%d", i); // Create a unique identifier
        records[i].identifier = identifier;
    }

    return records;
}

void free_encryption_records(encryption_record *records, int num_records) {
    if (!records) {
        return; // Nothing to free
    }

    for (int i = 0; i < num_records; ++i) {
        free(records[i].identifier);
    }
    free(records);
}
