void* initialize_records(size_t num_records, long offset_range_start, long offset_range_end) {
    if (num_records == 0 || offset_range_start >= offset_range_end) {
        return NULL; // Error handling for invalid input
    }

    // Allocate memory for arrays and structures
    long* offsets = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));
    record* records = malloc(num_records * sizeof(record));

    if (offsets == NULL || keys == NULL || records == NULL) {
        free(offsets);
        free(keys);
        return NULL; // Handle memory allocation failure
    }

    // Initialize CSPRNG seed
    srand(time(NULL)); // Use current time as a seed for simplicity

    // Populate arrays with random values and initialize structures
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % (offset_range_end - offset_range_start) + offset_range_start;
        keys[i] = rand();
        records[i].value = keys[i];
    }

    // Return pointer to the array of record structures
    return records;
}

// Example usage:
