        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize arrays
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % (max_val - min_val + 1) + min_val;
    }

    // Initialize records with random values
    srand(time(NULL)); // Seed PRNG for uniform distribution
    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }

    return records;
}

