        records[i].session_id = (char*)malloc(10 * sizeof(char));
        if (records[i].session_id == NULL) {
            perror("Failed to allocate memory for session ID");
            // Clean up previously allocated records
            for (int j = 0; j < i; j++) {
                free(records[j].session_id);
            }
            free(records);
            return NULL;
        }

        // Generate a simple pseudo-random session ID
        sprintf(records[i].session_id, "ID%05d", rand() % 100000);
    }

    return records;
}

void destroy_session_records(session_record* records, int num_records) {
    if (records == NULL || num_records <= 0) {
        return;
    }

    for (int i = 0; i < num_records; i++) {
        free(records[i].session_id);
    }
    free(records);
