typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    size_t count;
} DataContainer;

DataContainer* create_data_container(size_t offset_size, size_t key_size, size_t record_count) {
    if (offset_size == 0 || key_size == 0 || record_count == 0) {
        fprintf(stderr, "Invalid size parameters\n");
        return NULL;
    }

    DataContainer* container = (DataContainer*)malloc(sizeof(DataContainer));
    if (!container) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    container->offsets = (long*)malloc(offset_size * sizeof(long));
    if (!container->offsets) {
        free(container);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    container->keys = (int*)malloc(key_size * sizeof(int));
    if (!container->keys) {
        free(container->offsets);
        free(container);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    container->records = (Record**)malloc(record_count * sizeof(Record*));
    if (!container->records) {
        free(container->keys);
        free(container->offsets);
        free(container);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = 0; i < record_count; ++i) {
        container->records[i] = (Record*)malloc(sizeof(Record));
        if (!container->records[i]) {
            for (size_t j = 0; j < i; ++j) {
                free(container->records[j]);
            }
            free(container->records);
            free(container->keys);
            free(container->offsets);
            free(container);
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }

        container->records[i]->value = rand();
        size_t str_length = 1 + rand() % 20; // Random string length between 1 and 20
        container->records[i]->str = (char*)malloc(str_length * sizeof(char));
        if (!container->records[i]->str) {
            for (size_t j = 0; j <= i; ++j) {
                free(container->records[j]->str);
                free(container->records[j]);
            }
            free(container->records);
            free(container->keys);
            free(container->offsets);
            free(container);
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }

        for (size_t j = 0; j < str_length - 1; ++j) {
            container->records[i]->str[j] = 'a' + rand() % 26;
        }
        container->records[i]->str[str_length - 1] = '\0';
    }

    container->count = record_count;

    return container;
}

void free_data_container(DataContainer* container) {
    if (container) {
        for (size_t i = 0; i < container->count; ++i) {
            free(container->records[i]->str);
            free(container->records[i]);
        }
        free(container->records);
        free(container->keys);
        free(container->offsets);
        free(container);
    }
}

int get_record_count(DataContainer* container) {
    return (container ? container->count : -1);
}

int main() {
    srand(time(NULL));

    DataContainer* container = create_data_container(1024, 1024, 1000);
    if (!container) {
        fprintf(stderr, "Failed to create data container\n");
        return EXIT_FAILURE;
    }

    printf("Record count: %d\n", get_record_count(container));

    free_data_container(container);

    return EXIT_SUCCESS;
}
