    if (!r) return NULL;

    r->value = rand() % (range + 1);
    r->str = strdup("example");
    if (!r->str) {
        free(r);
        return NULL;
    }

    memset(r->buffer, 0, RECORD_SIZE);

    return r;
}

void destroy_record(record* r) {
    if (r) {
        free(r->str);
        free(r);
    }
}

int serialize_records(record** records, int count, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    for (int i = 0; i < count; ++i) {
        if (fwrite(&records[i]->value, sizeof(int), 1, file) != 1 ||
            fwrite(records[i]->str, strlen(records[i]->str) + 1, 1, file) != 1 ||
            fwrite(records[i]->buffer, RECORD_SIZE, 1, file) != 1) {
            fclose(file);
            return -1;
        }
    }

    fclose(file);
    return 0;
}

record** deserialize_records(int* count, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return NULL;

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);

    *count = size / (sizeof(int) + RECORD_SIZE + 1); // Simplified for example
    record** records = (record**)malloc(*count * sizeof(record*));
    if (!records) {
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < *count; ++i) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            while (i > 0) {
                free(records[--i]);
            }
            free(records);
            fclose(file);
            return NULL;
        }

        if (fread(&records[i]->value, sizeof(int), 1, file) != 1 ||
            fread(records[i]->str = (char*)malloc(256), 256, 1, file) != 1 ||
            fread(records[i]->buffer, RECORD_SIZE, 1, file) != 1) {
            while (i > 0) {
                free(records[--i]);
            }
            free(records);
            fclose(file);
            return NULL;
        }
