void initialize_pool(long **offsets, int **keys, int size) {
    *offsets = (long *)malloc(size * sizeof(long));
    *keys = (int *)malloc(size * sizeof(int));
    if (*offsets == NULL || *keys == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < size; i++) {
        (*offsets)[i] = i;
        (*keys)[i] = i;
    }
}

void allocate_records(record **records, int size) {
    *records = (record *)malloc(size * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void populate_records(record *records, int size, int min_val, int max_val) {
    srand(time(NULL)); // Seed the PRNG
    for (int i = 0; i < size; i++) {
        records[i].key = i;
        records[i].value = min_val + rand() % (max_val - min_val + 1);
    }
}

void serialize_records(record *records, int size, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        exit(EXIT_FAILURE);
    }
    fwrite(records, sizeof(record), size, file);
    fclose(file);
}

int main() {
    int size = 1000;
    record *records;
    long *offsets;
    int *keys;

    initialize_pool(&offsets, &keys, size);
    allocate_records(&records, size);
    populate_records(records, size, 1, 1000);

    serialize_records(records, size, "records.bin");

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
