long* allocate_offset_array(size_t size) {
    long* offsets = (long*)malloc(size * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offset array");
        return NULL;
    }
    return offsets;
}

int* allocate_key_array(size_t size) {
    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for key array");
        return NULL;
    }
    return keys;
}

record* allocate_record_array(size_t size, int min_val, int max_val) {
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for record array");
        return NULL;
    }

    // Initialize records with random values
    srand(time(NULL)); // Seed the PRNG
    for (size_t i = 0; i < size; ++i) {
        int random_value = rand() % (max_val - min_val + 1) + min_val;
        records[i].value = random_value;
    }

    return records;
}

void free_all_memory(long* offsets, int* keys, record* records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

