    long* offsets = allocate_offset_array(NUM_RECORDS);
    int* keys = allocate_key_array(NUM_RECORDS);
    record* records = allocate_record_array(NUM_RECORDS, 100, 999);

    if (offsets && keys && records) {
        // Use the allocated arrays
        printf("Memory allocation successful.\n");

        // Free all allocated memory
        free_all_memory(offsets, keys, records);
