int initialize_pool(long* offsets, int* keys, int size) {
    if (size > MAX_RECORDS) return -1; // Invalid input
    srand(time(0)); // Seed for PRNG
    for (int i = 0; i < size; ++i) {
        offsets[i] = i * sizeof(record);
        keys[i] = i;
    }
    return 0;
}

record* allocate_records(int* sizes, int count) {
    if (count > MAX_RECORDS / sizeof(record)) return NULL; // Not enough memory
    record* records = malloc(count * sizeof(record));
    if (!records) return NULL; // Memory allocation failed

    for (int i = 0; i < count; ++i) {
        records[i].value = rand() % sizes[i]; // Assign random value within the specified range
    }

    return records;
}

int serialize_records(const record* records, int count, FILE* file) {
    if (!records || count <= 0) return -1; // Invalid input

    for (int i = 0; i < count; ++i) {
        if (fwrite(&records[i], sizeof(record), 1, file) != 1) return -1; // Serialization failed
    }

    return 0;
}

void free_records(record* records) {
    if (records) free(records);
