#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
} OffsetStruct;

typedef struct {
    int key;
} KeyStruct;

typedef struct RecordStruct {
    int value;
    int id; // Unique identifier generated by PRNG
} RecordStruct;

// Custom PRNG function (Mersenne Twister)
unsigned int prng(unsigned int *seed) {
    unsigned int mt[312];
    unsigned int mti = 312 + 1, y;
    if (mti >= 312) {
        for (int kk = 0; kk < 312 - 11; kk++) {
            y = (mt[kk] & 0x80000000) | (mt[kk + 1] & 0x7FFFFFFF);
            mt[kk] = mt[(kk + 397) % 312] ^ (y >> 1);
            if ((y & 1) != 0) mt[kk] ^= 0x9908B0DF;
        }
        for (; kk < 311; kk++) {
            y = (mt[kk] & 0x80000000) | (mt[kk + 1] & 0x7FFFFFFF);
            mt[kk] = mt[(kk + 397) % 312] ^ (y >> 1);
            if ((y & 1) != 0) mt[kk] ^= 0x9908B0DF;
        }
        y = (mt[311] & 0x80000000) | (mt[0] & 0x7FFFFFFF);
        mt[311] = mt[0] ^ (y >> 1);
        if ((y & 1) != 0) mt[311] ^= 0x9908B0DF;
        mti = 0;
    }
    y = mt[mti++];
    y ^= (y >> 11);
    y ^= (y << 7) & 0x9D2C5680;
    y ^= (y << 15) & 0xEFC60000;
    y ^= (y >> 18);
    *seed = y;
    return y;
}

void manageStructures(int numRecords, OffsetStruct **offsets, KeyStruct **keys, RecordStruct **records, unsigned int *seed) {
    *offsets = malloc(numRecords * sizeof(OffsetStruct));
    *keys = malloc(numRecords * sizeof(KeyStruct));
    *records = malloc(numRecords * sizeof(RecordStruct));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < numRecords; i++) {
        (*offsets)[i].offset = rand(); // Example initialization
        (*keys)[i].key = i;
        (*records)[i].value = rand() % 100; // Random value between 0 and 99
        (*records)[i].id = prng(seed);
    }
}

int main() {
    int numRecords = 10;
    OffsetStruct *offsets;
    KeyStruct *keys;
    RecordStruct *records;
    unsigned int seed = time(NULL);

    manageStructures(numRecords, &offsets, &keys, &records, &seed);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
