void initializeEventLoggingSystem(Event** events, long* timestamps, int* sequenceNumbers, size_t numEvents) {
    // Allocate memory for arrays
    *events = (Event*)malloc(numEvents * sizeof(Event));
    if (*events == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    timestamps = (long*)malloc(numEvents * sizeof(long));
    if (timestamps == NULL) {
        free(*events);
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    sequenceNumbers = (int*)malloc(numEvents * sizeof(int));
    if (sequenceNumbers == NULL) {
        free(*events);
        free(timestamps);
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize timestamps with current time
    clock_gettime(CLOCK_MONOTONIC, (struct timespec*)&timestamps[0]);
    for (size_t i = 1; i < numEvents; ++i) {
        timestamps[i] = timestamps[i - 1] + 1; // Incremental timestamp for simplicity
    }

    // Initialize sequence numbers with CSPRNG
    if (!RAND_bytes((unsigned char*)&sequenceNumbers[0], numEvents * sizeof(int))) {
        free(*events);
        free(timestamps);
        fprintf(stderr, "CSPRNG initialization failed\n");
        return;
    }

    // Populate events structure
    for (size_t i = 0; i < numEvents; ++i) {
        (*events)[i].timestamp = timestamps[i];
        (*events)[i].sequenceNumber = sequenceNumbers[i];
    }
}

void freeEventLoggingSystem(Event* events, long* timestamps, int* sequenceNumbers) {
    free(events);
    free(timestamps);
    free(sequenceNumbers);
}
