    long *timestamps = malloc(array_size * sizeof(long));
    int *sequence_numbers = malloc(array_size * sizeof(int));
    Record *records = malloc(array_size * sizeof(Record));

    if (timestamps == NULL || sequence_numbers == NULL || records == NULL) {
