    // Handle network latency and data source failures in a separate thread
    pthread_t network_thread;
    if (pthread_create(&network_thread, NULL, handle_network, NULL) != 0) {
        log_message("Failed to create network handling thread.", 1);
        return -1;
    }

    // Join the network handling thread
