}

int main() {
    pthread_t threads[4];

    for (size_t i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, (void*)i) != 0) {
            fprintf(stderr, "Failed to create thread %zu\n", i);
            return 1;
        }
    }

