} record;

record* allocate_and_initialize_records(int count, int* failed_allocations) {
    record* records = malloc(count * sizeof(record));
    if (records == NULL) {
        (*failed_allocations)++;
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i].status = 'A';
        records[i].value = rand() % 1000; // Non-cryptographic PRNG
    }

    return records;
}

void export_records_to_file(const char* filename, record* records, int count) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }

    fprintf(file, "Status,Value\n");
    for (int i = 0; i < count; i++) {
        fprintf(file, "%c,%d\n", records[i].status, records[i].value);
    }

    fclose(file);
}

int main() {
    int failed_allocations = 0;
    record* records = allocate_and_initialize_records(MAX_RECORDS, &failed_allocations);

    if (records != NULL) {
        printf("Records initialized successfully.\n");
        export_records_to_file("output.csv", records, MAX_RECORDS);
        free(records);
    } else {
        printf("Failed to allocate memory for records. Failed allocations: %d\n", failed_allocations);
    }

    return 0;
}
