// Function to initialize packet memory
int init_packet_memory(unsigned long** IDs, double** timestamps, Packet*** packets, size_t max_packets) {
    *IDs = (unsigned long*)malloc(max_packets * sizeof(unsigned long));
    *timestamps = (double*)malloc(max_packets * sizeof(double));
    *packets = (Packet**)malloc(max_packets * sizeof(Packet*));

    if (*IDs == NULL || *timestamps == NULL || *packets == NULL) {
        perror("Memory allocation failed");
        return -1;
    }

    srand(time(NULL)); // Seed the PRNG

    for (size_t i = 0; i < max_packets; ++i) {
        (*IDs)[i] = rand(); // Use a simple PRNG for demonstration purposes
        (*timestamps)[i] = (double)clock() / CLOCKS_PER_SEC; // Current timestamp with double resolution
        (*packets)[i] = malloc(sizeof(Packet));
        if ((*packets)[i] == NULL) {
            perror("Memory allocation failed");
            return -1;
        }
        memset((*packets)[i], 0, sizeof(Packet));
    }

    return 0;
}

// Function to free allocated memory
void free_packet_memory(unsigned long* IDs, double* timestamps, Packet** packets, size_t max_packets) {
    for (size_t i = 0; i < max_packets; ++i) {
        free(packets[i]);
    }
    free(IDs);
    free(timestamps);
    free(packets);
}

int main() {
    unsigned long *packetIDs;
    double *timestamps;
    Packet **packets;
    size_t maxPackets = 1000;

