record* initialize_records(size_t num_records, long *offsets, int **keys, char ***string_fields) {
    srand(time(NULL));
    record *records = malloc(num_records * sizeof(record));
    if (records == NULL) {
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand();
        keys[i] = malloc(sizeof(int));
        if (keys[i] == NULL) {
            free(records);
            return NULL;
        }
        *keys[i] = rand();
        records[i].value = *keys[i];
        records[i].random_char = charset[rand() % strlen(charset)];

        size_t string_length = 5 + rand() % 6; // Between 5 and 10 characters
        string_fields[i] = generate_random_string(string_length);
        if (string_fields[i] == NULL) {
            for (size_t j = 0; j < i; ++j) {
                free(keys[j]);
                free(string_fields[j]);
            }
            free(records);
            return NULL;
        }
    }

    return records;
}

void cleanup(size_t num_records, int **keys, char ***string_fields, record *records) {
    for (size_t i = 0; i < num_records; ++i) {
        free(keys[i]);
        free(string_fields[i]);
