    if (rm->count >= rm->capacity) {
        size_t newCapacity = (rm->capacity > 0) ? rm->capacity * 2 : 16;
        Resource* newResources = realloc(rm->resources, newCapacity * sizeof(Resource));
        if (newResources == NULL) return -1;
        rm->resources = newResources;
        rm->capacity = newCapacity;
