    rm->resources[rm->count].resourceName[255] = '\0';
    rm->resources[rm->count].resourceCapacity = capacity;
    time_t now = time(NULL);
    if (now == -1) return -1;
    rm->resources[rm->count].lastUpdatedTime = now;
