// Define a structure for record
typedef struct {
    int value;
    long long_id;
    double probability;
} Record;

// Function to allocate memory for arrays of different types
void* allocate_memory(int type, size_t size) {
    void* ptr = NULL;
    switch (type) {
        case 1: // 'long' integers
            ptr = malloc(size * sizeof(long));
            break;
        case 2: // 'int' keys
            ptr = malloc(size * sizeof(int));
            break;
        case 3: // 'char' strings
            ptr = malloc(size * sizeof(char*));
            for (size_t i = 0; i < size; ++i) {
                ((char**)(ptr + i * sizeof(char*)))[i] = (char*)malloc(256);
            }
            break;
        case 4: // 'record' structures
            ptr = malloc(size * sizeof(Record));
            for (size_t i = 0; i < size; ++i) {
                ((Record*)(ptr + i * sizeof(Record)))[i].value = rand();
                ((Record*)(ptr + i * sizeof(Record)))[i].long_id = ((long)((rand() % 10) + 1)) * 2147483647; // Prime number
                ((Record*)(ptr + i * sizeof(Record)))[i].probability = (double)rand() / RAND_MAX;
            }
            break;
        default:
            printf("Invalid type\n");
            return NULL;
    }
    if (!ptr) {
        printf("Memory allocation failed\n");
    }
    return ptr;
}

// Function to free memory allocated for arrays of different types
void free_memory(void* ptr, int type, size_t size) {
    switch (type) {
        case 3: // 'char' strings
            for (size_t i = 0; i < size; ++i) {
                free(((char**)(ptr + i * sizeof(char*)))[i]);
            }
        case 1:
        case 2:
        case 4:
            free(ptr);
            break;
    }
}

int main() {
    srand(time(NULL)); // Seed the PRNG

    size_t size = 10; // Example dataset size
    int* longs = (int*)allocate_memory(1, size);
    int* ints = (int*)allocate_memory(2, size);
    char** strings = (char**)allocate_memory(3, size);
    Record* records = (Record*)allocate_memory(4, size);

    // Initialize arrays and check for errors
    if (!longs || !ints || !strings || !records) {
        printf("Memory allocation failed\n");
        return 1;
    }

    // Free allocated memory when done
    free_memory(longs, 1, size);
    free_memory(ints, 2, size);
    free_memory(strings, 3, size);
    free_memory(records, 4, size);

    return 0;
}
