#define MAX_CONFIGS 1024
#define MAX_SESSIONS 512

typedef struct {
    double probability;
    char* name;
    int id;
} config;

typedef struct {
    int sessionId;
    char* token;
    long timestamp;
} session;

typedef struct {
    unsigned flags;
    size_t size;
    int status;
} metadata;

typedef struct {
    long* longArray;
    char** stringArray;
    config* configArray;
    session* sessionArray;
    metadata meta;
} memoryPool;

metadata initMetadata() {
    metadata m = {0};
    m.flags = 0;
    m.size = 0;
    m.status = 0;
    return m;
}

void logAllocation(metadata* meta, const char* action) {
    printf("Action: %s, Size: %zu\n", action, meta->size);
}

int allocateMemory(memoryPool* pool, size_t longSize, size_t stringSize, size_t configSize, size_t sessionSize) {
    if (longSize > MAX_CONFIGS || stringSize > MAX_CONFIGS || configSize > MAX_CONFIGS || sessionSize > MAX_SESSIONS) {
        return -1; // Allocation too large
    }

    pool->meta.size = longSize + stringSize + configSize + sessionSize;
    pool->longArray = (long*)calloc(longSize, sizeof(long));
    pool->stringArray = (char**)calloc(stringSize, sizeof(char*));
    pool->configArray = (config*)calloc(configSize, sizeof(config));
    pool->sessionArray = (session*)calloc(sessionSize, sizeof(session));

    if (!pool->longArray || !pool->stringArray || !pool->configArray || !pool->sessionArray) {
        return -2; // Memory allocation failed
    }

    logAllocation(&pool->meta, "Memory Allocation");
    pool->meta.status = 1; // Initialized
    return 0;
}

void freeMemory(memoryPool* pool) {
    if (pool->longArray) free(pool->longArray);
    if (pool->stringArray) {
        for (size_t i = 0; i < pool->meta.size; ++i) {
            if (pool->stringArray[i]) free(pool->stringArray[i]);
        }
        free(pool->stringArray);
    }
    if (pool->configArray) free(pool->configArray);
    if (pool->sessionArray) free(pool->sessionArray);

    logAllocation(&pool->meta, "Memory Free");
    pool->meta.status = 0; // Freed
}

int main() {
    memoryPool pool;
    memset(&pool, 0, sizeof(memoryPool));
    pool.meta = initMetadata();

    int result = allocateMemory(&pool, 100, 100, 50, 30);
    if (result != 0) {
        printf("Failed to allocate memory: %d\n", result);
        return 1;
    }

    // Use the allocated memory here

    freeMemory(&pool);

    return 0;
}
