                    size_t initialSize) {
    *sessions = malloc(initialSize * sizeof(Session));
    if (*sessions == NULL) return -1; // Memory allocation failed

    *users = malloc(initialSize * sizeof(User));
    if (*users == NULL) {
        free(*sessions);
        return -2; // Memory allocation failed
    }

    *transactions = malloc(initialSize * sizeof(Transaction));
    if (*transactions == NULL) {
        free(*sessions);
        free(*users);
        return -3; // Memory allocation failed
    }

    for (size_t i = 0; i < initialSize; ++i) {
        (*sessions)[i].token = generateSessionToken(); // Assume this function generates a token securely
        if ((*sessions)[i].token == NULL) {
            free(*sessions);
            free(*users);
            free(*transactions);
            return -4; // Token generation failed
        }
        (*users)[i].session = &(*sessions)[i];
    }

    return 0; // Success
}

