#include <stdbool.h>

// Define structures
typedef struct {
    long* data;
} offsets_t;

typedef struct {
    int* data;
} keys_t;

typedef struct {
    int* data;
    size_t size;
} records_t;

// Function to initialize structures
int init_structs(size_t num_offsets, size_t num_keys, size_t num_records, offsets_t* offsets, keys_t* keys, records_t* records) {
    // Allocate memory for offsets and keys
    offsets->data = (long*)malloc(num_offsets * sizeof(long));
    if (!offsets->data) return 1; // Memory allocation failed

    keys->data = (int*)malloc(num_keys * sizeof(int));
    if (!keys->data) {
        free(offsets->data);
        return 2; // Memory allocation failed
    }

    // Allocate memory for records and initialize with pseudo-random numbers
    records->size = num_records;
    records->data = (int*)malloc(num_records * sizeof(int));
    if (!records->data) {
        free(keys->data);
        free(offsets->data);
        return 3; // Memory allocation failed
    }

    // Initialize keys with sequential values
    for (size_t i = 0; i < num_keys; ++i) {
        keys->data[i] = i;
    }

    // Seed the PRNG
    srand(time(NULL));

    // Fill records with unique pseudo-random numbers within a specified range
    bool* used = (bool*)calloc(num_records, sizeof(bool));
    if (!used) {
        free(records->data);
        free(keys->data);
        free(offsets->data);
        return 4; // Memory allocation failed
    }

    for (size_t i = 0; i < num_records; ++i) {
        int value;
        do {
            value = rand() % num_records; // Adjust range as needed
        } while (used[value]);
        records->data[i] = value;
        used[value] = true;
    }

    free(used);
    return 0; // Success
}

// Function to reinitialize records with new pseudo-random numbers
void reinit_records(records_t* records, size_t num_records) {
    srand(time(NULL)); // Reset PRNG seed

    bool* used = (bool*)calloc(num_records, sizeof(bool));
    if (!used) return; // Handle memory allocation failure gracefully

    for (size_t i = 0; i < num_records; ++i) {
        int value;
        do {
            value = rand() % num_records; // Adjust range as needed
        } while (used[value]);
        records->data[i] = value;
        used[value] = true;
    }

    free(used);
}

// Function to free allocated memory
void cleanup(offsets_t* offsets, keys_t* keys, records_t* records) {
    free(records->data);
    free(keys->data);
    free(offsets->data);
}
