#define MAX_PRNG_RANGE 100

typedef struct {
    long* data;
} offsets_t;

typedef struct {
    int* data;
} keys_t;

typedef struct {
    int* data;
} records_t;

int generate_unique_random(int min, int max, int* used_numbers, int count) {
    srand(time(NULL));
    while (1) {
        int random_number = rand() % (max - min + 1) + min;
        int found = 0;
        for (int i = 0; i < count; i++) {
            if (used_numbers[i] == random_number) {
                found = 1;
                break;
            }
        }
        if (!found) {
            return random_number;
        }
    }
}

void initialize_structures(int offsets_size, int keys_size, int records_size) {
    offsets_t* offsets = (offsets_t*)malloc(sizeof(offsets_t));
    if (offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return;
    }

    keys_t* keys = (keys_t*)malloc(sizeof(keys_t));
    if (keys == NULL) {
        free(offsets);
        fprintf(stderr, "Failed to allocate memory for keys\n");
        return;
    }

    records_t* records = (records_t*)malloc(sizeof(records_t));
    if (records == NULL) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Failed to allocate memory for records\n");
        return;
    }

    offsets->data = (long*)calloc(offsets_size, sizeof(long));
    if (offsets->data == NULL) {
        free(offsets);
        free(keys);
        free(records);
        fprintf(stderr, "Failed to allocate memory for offsets data\n");
        return;
    }

    keys->data = (int*)calloc(keys_size, sizeof(int));
    if (keys->data == NULL) {
        free(offsets->data);
        free(offsets);
        free(keys);
        free(records);
        fprintf(stderr, "Failed to allocate memory for keys data\n");
        return;
    }

    records->data = (int*)malloc(sizeof(int) * records_size);
    if (records->data == NULL) {
        free(offsets->data);
        free(offsets);
        free(keys->data);
        free(keys);
        free(records);
        fprintf(stderr, "Failed to allocate memory for records data\n");
        return;
    }

    // Initialize offsets and keys
