            // Clean up previously allocated memory
            for (long long int j = 0; j < i; ++j) {
                free(charArray[j]);
            }
            free(configArray);
            free(longArray);
            return NULL;
        }
        snprintf(charArray[i], 20, "String%d", i);
    }

    for (long long int i = 0; i < sizeConfig; ++i) {
        configArray[i].limit = ((double)rand() / RAND_MAX) * 100.0;
        configArray[i].name = (char*)malloc(20 * sizeof(char));
        if (!configArray[i].name) {
            fprintf(stderr, "Memory allocation failed for config array element %lld.\n", i);
