            for (long long int j = 0; j < i; ++j) {
                free(configArray[j].name);
            }
            for (long long int j = 0; j < sizeChar; ++j) {
                free(charArray[j]);
            }
            free(longArray);
            return NULL;
        }
        snprintf(configArray[i].name, 20, "Config%d", i);
    }

    return longArray;
}
