import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class EnvironmentService {
    private Config[] configArray;
    private Lock lock = new ReentrantLock();

    public EnvironmentService(long size) {
        this.configArray = new Config[size];
        // Initialize configurations dynamically based on system metrics and environmental factors
        for (int i = 0; i < size; ++i) {
            configArray[i] = new Config((Math.random() * 100), "Config" + i);
        }
    }

    public void updateService(String serviceName, double newLimit) {
        lock.lock();
        try {
            for (Config config : configArray) {
                if (config.name.equals(serviceName)) {
                    config.limit = newLimit;
                    break;
                }
            }
        } finally {
            lock.unlock();
        }
    }

    public void deprecateService(String serviceName) {
        lock.lock();
        try {
            for (int i = 0; i < configArray.length; ++i) {
                if (configArray[i].name.equals(serviceName)) {
                    // Apply fallback configuration
                    configArray[i] = new Config(50.0, "FallbackConfig" + i);
                    break;
                }
            }
        } finally {
            lock.unlock();
        }
    }

    public class Config {
        double limit;
        String name;

        public Config(double limit, String name) {
            this.limit = limit;
            this.name = name;
        }
    }
}
