unsigned int generate_key(unsigned long seed) {
    return (seed * 2654435769U + 1664525U) % UINT_MAX;
}

record* create_record(unsigned int data) {
    record* r = malloc(sizeof(record));
    if (r != NULL) {
        r->data = data;
    }
    return r;
}

unsigned long* allocate_long_array(size_t *size) {
    unsigned long* array = malloc(*size * sizeof(unsigned long));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed for long array\n");
        exit(EXIT_FAILURE);
    }
    return array;
}

unsigned int* allocate_uint_array(size_t *size) {
    unsigned int* array = malloc(*size * sizeof(unsigned int));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed for uint array\n");
        exit(EXIT_FAILURE);
    }
    return array;
}

record** allocate_record_array(size_t *size) {
    record** array = malloc(*size * sizeof(record*));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed for record array\n");
        exit(EXIT_FAILURE);
    }
    return array;
}

void free_long_array(unsigned long* array, size_t size) {
    free(array);
}

void free_uint_array(unsigned int* array, size_t size) {
    free(array);
}

void free_record_array(record** array, size_t size) {
    for (size_t i = 0; i < size; i++) {
        free(array[i]);
    }
    free(array);
}

void init_arrays(size_t *offset_size, size_t *key_size, size_t *record_size) {
    *offset_size = INITIAL_CAPACITY;
    *key_size = INITIAL_CAPACITY;
    *record_size = INITIAL_CAPACITY;

    unsigned long* offsets = allocate_long_array(offset_size);
    unsigned int* keys = allocate_uint_array(key_size);
    record** records = allocate_record_array(record_size);

    srand(time(NULL));

    for (size_t i = 0; i < *offset_size; i++) {
        offsets[i] = rand();
    }

    for (size_t i = 0; i < *key_size; i++) {
        keys[i] = generate_key(rand());
    }

    for (size_t i = 0; i < *record_size; i++) {
        records[i] = create_record(rand());
    }

    // Use the arrays...

    free_long_array(offsets, *offset_size);
    free_uint_array(keys, *key_size);
    free_record_array(records, *record_size);
}

int main() {
    size_t offset_size, key_size, record_size;
    init_arrays(&offset_size, &key_size, &record_size);
    return 0;
}
