typedef struct {
    int amount;
    char* description;
} Transaction;

void initializeTransactionLog(int numTransactions, long* offsets, int* keys, Transaction** transactions) {
    srand(time(NULL)); // Seed the PRNG for consistent randomness
    const char* descriptions[] = {"Deposit", "Withdrawal", "Transfer"};
    int descCount = sizeof(descriptions) / sizeof(descriptions[0]);

    *transactions = (Transaction*)malloc(numTransactions * sizeof(Transaction));
    if (*transactions == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    offsets = (long*)malloc(numTransactions * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(*transactions);
        return;
    }

    keys = (int*)malloc(numTransactions * sizeof(int));
    if (keys == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(*transactions);
        free(offsets);
        return;
    }

    for (int i = 0; i < numTransactions; ++i) {
        offsets[i] = rand(); // Example offset logic
        keys[i] = rand() % descCount; // Randomly select a description

        (*transactions)[i].amount = rand() % 1000 + 1; // Random transaction amount between 1 and 1000
        int descLength = strlen(descriptions[keys[i]]) + 1;
        (*transactions)[i].description = (char*)malloc(descLength * sizeof(char));
        if ((*transactions)[i].description == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            // Clean up previously allocated memory
            for (int j = 0; j < i; ++j) {
                free((*transactions)[j].description);
            }
            free(*transactions);
            free(offsets);
            free(keys);
            return;
        }
        strcpy((*transactions)[i].description, descriptions[keys[i]]);
    }
}

void cleanupTransactionLog(int numTransactions, long* offsets, int* keys, Transaction** transactions) {
    for (int i = 0; i < numTransactions; ++i) {
        free((*transactions)[i].description);
    }
    free(*transactions);
    free(offsets);
    free(keys);
}
```

