        offsets[i] = rand() % 1000L; // Example offset initialization
        keys[i] = rand() % 1000;     // Example key initialization
        records[i] = malloc(sizeof(record));

        if (records[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            exit(1); // Exit on failure
        }

        double random_value = min_value + (double)(rand() / (RAND_MAX / (max_value - min_value)));
        records[i]->value = random_value;
    }
}

void convert_to_hex(record *record, char **hex_string) {
    *hex_string = malloc(17); // Double precision float is 16 bytes in size
    if (*hex_string == NULL) {
        fprintf(stderr, "Memory allocation failed for hex string\n");
        exit(1); // Exit on failure
    }

