    *keys = (int*)malloc(ARRAY_SIZE * sizeof(int));
    *records = (record*)malloc(ARRAY_SIZE * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

