    for (int i = 0; i < ARRAY_SIZE; i++) {
        (*offsets)[i] = rand() % range;
        (*keys)[i] = rand() % range;
        (*records)[i].field = rand() % range;
    }
}

void free_arrays(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int compare(const void* a, const void* b) {
    return (*(record*)a).field - (*(record*)b).field;
}

void sort_records(record* records) {
    qsort(records, ARRAY_SIZE, sizeof(record), compare);
}

int main() {
    long* offsets;
    int* keys;
    record* records;

    initialize_arrays(&offsets, &keys, &records, 100);

    printf("Original records:\n");
    for (int i = 0; i < ARRAY_SIZE; i++) {
        printf("%d: %d\n", records[i].field, offsets[i]);
    }

    sort_records(records);

    printf("\nSorted records:\n");
    for (int i = 0; i < ARRAY_SIZE; i++) {
        printf("%d: %ld\n", records[i].field, offsets[i]);
    }

