void free_memory(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}

record* allocate_records(int size, unsigned seed) {
    if (size <= 0 || seed == 0) {
        return NULL;
    }

    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < size; ++i) {
        records[i].value = rand() % 100; // Random value between 0 and 99
    }

    return records;
}

void initialize_arrays(int offset_size, int key_size, unsigned seed) {
    if (offset_size <= 0 || key_size <= 0 || seed == 0) {
        fprintf(stderr, "Invalid parameters for array initialization.\n");
        return;
    }

    long* offsets = (long*)malloc(offset_size * sizeof(long));
    int* keys = (int*)malloc(key_size * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed.\n");
        free_memory(NULL, NULL, NULL); // Clean up allocated memory
        return;
    }

    // Initialize arrays with user-provided data sizes
    for (int i = 0; i < offset_size; ++i) {
        offsets[i] = rand() % 1000L; // Example initialization
    }
    for (int i = 0; i < key_size; ++i) {
        keys[i] = rand() % 100; // Example initialization
    }

    record* records = allocate_records(key_size, seed);
    if (!records) {
        free_memory(offsets, keys, NULL); // Clean up allocated memory
        return;
    }

    // Use the arrays as needed

    free_memory(offsets, keys, records); // Free all allocated memory upon completion
}

int main() {
    int offset_size = 100; // Example data size
    int key_size = 50;     // Example data size
