typedef struct {
    int id;
    char name[10];
} record;

long* allocate_offsets(int n, FILE* log_fd) {
    long* offsets = (long*)malloc(n * sizeof(long));
    if (!offsets) {
        fprintf(log_fd, "Memory allocation failed for offsets\n");
        return NULL;
    }
    return offsets;
}

int* allocate_keys(int n, FILE* log_fd) {
    int* keys = (int*)malloc(n * sizeof(int));
    if (!keys) {
        fprintf(log_fd, "Memory allocation failed for keys\n");
        return NULL;
    }
    return keys;
}

record* allocate_records(int n, FILE* log_fd) {
    record* records = (record*)malloc(n * sizeof(record));
    if (!records) {
        fprintf(log_fd, "Memory allocation failed for records\n");
        return NULL;
    }
    return records;
}

void init_arrays(long* offsets, int* keys, record* records, int n, FILE* log_fd) {
    srand(time(NULL)); // Seed the PRNG
    for (int i = 0; i < n; ++i) {
        offsets[i] = rand() % 1000L; // Example range: [0, 999]
        keys[i] = rand() % 100; // Example range: [0, 99]

        records[i].id = i;
        for (int j = 0; j < 10; ++j) {
            records[i].name[j] = 'A' + rand() % ('Z' - 'A' + 1); // Random uppercase letter
        }
        records[i].name[10] = '\0';
    }
}

int compare_records(const void* a, const void* b) {
    record* rec_a = (record*)a;
    record* rec_b = (record*)b;

    if (rec_a->key != rec_b->key) {
        return rec_a->key - rec_b->key; // Ascending order for keys
    } else {
        return -(rec_a->offset - rec_b->offset); // Descending order for offsets when keys are equal
    }
}

record* sort_records(record* records, int n, FILE* log_fd) {
    if (qsort(records, n, sizeof(record), compare_records)) {
        fprintf(log_fd, "Sorting failed\n");
        return NULL;
    }
    return records;
}

record** initialize_and_sort_arrays(int n, FILE* log_fd) {
    long* offsets = allocate_offsets(n, log_fd);
    int* keys = allocate_keys(n, log_fd);
    record* records = allocate_records(n, log_fd);

    if (!offsets || !keys || !records) {
        return NULL;
    }

    init_arrays(offsets, keys, records, n, log_fd);

    qsort(records, n, sizeof(record), compare_records);

    // Optionally free the intermediate arrays if needed
    free(offsets);
    free(keys);

    return records;
}
