    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} TransactionPool;

TransactionPool* create_transaction_pool(size_t initial_capacity) {
    TransactionPool *pool = (TransactionPool*)malloc(sizeof(TransactionPool));
    pool->logs = (TransactionLog*)calloc(initial_capacity, sizeof(TransactionLog));
    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void destroy_transaction_pool(TransactionPool *pool) {
    free(pool->logs);
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

void add_transaction_log(TransactionPool *pool, int transaction_id) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->size == pool->capacity) {
        // Implement dynamic resizing strategy
        TransactionLog *new_logs = realloc(pool->logs, pool->capacity * 2 * sizeof(TransactionLog));
        if (new_logs) {
            pool->logs = new_logs;
            pool->capacity *= 2;
        } else {
            // Handle memory allocation failure
        }
    }
    pool->logs[pool->size].timestamp = time(NULL);
    pool->logs[pool->size].transaction_id = transaction_id;
