#include <time.h>

#define MAX_RECORD_SIZE 16

typedef struct {
    int key;
    long offset;
    char value[MAX_RECORD_SIZE];
} Record;

void initializeRecords(Record **records, size_t numRecords, int keyRangeStart, int keyRangeEnd, long offsetRangeStart, long offsetRangeEnd) {
    srand(time(NULL));

    for (size_t i = 0; i < numRecords; ++i) {
        records[i] = (Record *)malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record %zu\n", i);
            exit(EXIT_FAILURE);
        }

        // Initialize key and offset with a non-cryptographic PRNG
        records[i]->key = rand() % (keyRangeEnd - keyRangeStart + 1) + keyRangeStart;
        records[i]->offset = rand() % (offsetRangeEnd - offsetRangeStart + 1) + offsetRangeStart;

        // Initialize value array with a null terminator
        memset(records[i]->value, 0, MAX_RECORD_SIZE);
    }
}

void writeRecordsToFile(Record **records, size_t numRecords) {
    FILE *file = fopen("output.txt", "w");
    if (!file) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < numRecords; ++i) {
        fprintf(file, "Key: %d, Offset: %ld, Value: %s\n", records[i]->key, records[i]->offset, records[i]->value);
