function executeTestsWithMemoryManagement(moduleName, label, f) {
    const memoryPool = new CMemoryPoolManager(1024 * 1024); // Initialize with 1MB

    function safeLoadModule(name) {
        try {
            return require(name);
        } catch (e) {
            blueslip.error("Failed to load module: " + name, e);
            return null;
        }
    }

    async function runTestWithMonitoring(func) {
        const startTime = performance.now();
        await func();
        const endTime = performance.now();
        console.log(`Test ${label} took ${endTime - startTime} ms`);
    }

    function resetMockingLibrary() {
        blueslip.reset();
    }

    function handleErrors(error) {
        blueslip.error("Unexpected error occurred", error);
    }

    function allocateMemory(size) {
        return memoryPool.allocate(size);
    }

    function deallocateMemory(ptr) {
        memoryPool.deallocate(ptr);
    }

    async function executeTests() {
        const module = safeLoadModule(moduleName);
        if (!module) {
            blueslip.error("Failed to load module for tests");
            return;
        }

        resetMockingLibrary();

        try {
            await runTestWithMonitoring(f);
        } catch (error) {
            handleErrors(error);
        }
    }

    executeTests();
}
