    int volume;
    double avg_price;
} TradeInfo;

typedef struct {
    char symbol[10];
    int trade_count;
} Record;

// PRNG state
static unsigned long seed = 42; // Default seed for reproducibility

// Function prototypes
void initialize_prng(unsigned long new_seed);
double next_random_double();
int* allocate_int_array(size_t size);
double* allocate_double_array(size_t size);
char** allocate_char_array(size_t size, size_t symbol_len);
TradeInfo* allocate_trade_info_structs(size_t size);
Record* allocate_record_structs(size_t size, int trade_count_range[2]);

// Main function
int main() {
    // Example usage
    initialize_prng(time(NULL)); // Initialize with current time for unique sequences

    size_t size = 1000; // Number of elements in each array
    double* prices = allocate_double_array(size);
    char** symbols = allocate_char_array(size, 10); // Assuming 10-character symbols
    TradeInfo* trades = allocate_trade_info_structs(size);
    Record* records = allocate_record_structs(size, (int[]){10, 1000}); // Range for trade counts

    if (!prices || !symbols || !trades || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    // Use the allocated arrays
    // ...

    // Free memory
    free(prices);
    for (size_t i = 0; i < size; ++i) {
        free(symbols[i]);
    }
    free(symbols);
    free(trades);
    free(records);

    return EXIT_SUCCESS;
}

// PRNG functions
void initialize_prng(unsigned long new_seed) {
    seed = new_seed;
}

double next_random_double() {
    // Simple linear congruential generator
    seed = (seed * 1664525 + 1013904223) % 4294967296;
    return (double)seed / 4294967296.0;
}

// Memory allocation functions
int* allocate_int_array(size_t size) {
    int* array = (int*)malloc(size * sizeof(int));
    if (!array) {
        perror("Failed to allocate int array");
        return NULL;
    }
    return array;
}

double* allocate_double_array(size_t size) {
    double* array = (double*)malloc(size * sizeof(double));
    if (!array) {
        perror("Failed to allocate double array");
        return NULL;
    }
    return array;
}

char** allocate_char_array(size_t size, size_t symbol_len) {
    char** array = (char**)malloc(size * sizeof(char*));
    if (!array) {
        perror("Failed to allocate char array pointers");
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        array[i] = (char*)malloc(symbol_len + 1);
        if (!array[i]) {
            perror("Failed to allocate char array elements");
            // Free previously allocated elements
            for (size_t j = 0; j < i; ++j) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }
    }

    return array;
}

TradeInfo* allocate_trade_info_structs(size_t size) {
    TradeInfo* array = (TradeInfo*)malloc(size * sizeof(TradeInfo));
    if (!array) {
        perror("Failed to allocate trade info structs");
        return NULL;
    }
    return array;
}

Record* allocate_record_structs(size_t size, int trade_count_range[2]) {
    Record* array = (Record*)malloc(size * sizeof(Record));
    if (!array) {
        perror("Failed to allocate record structs");
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        array[i].trade_count = trade_count_range[0] + rand() % (trade_count_range[1] - trade_count_range[0] + 1);
        snprintf(array[i].symbol, sizeof(array[i].symbol), "SYMBOL%d", i); // Example symbol format
    }

    return array;
}
