    *offsets = (long *)malloc(size * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        exit(EXIT_FAILURE);
    }

    *keys = (int *)malloc(size * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    *records = (Record *)malloc(size * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(*offsets);
        free(*keys);
        exit(EXIT_FAILURE);
    }

    // Initialize offsets and keys
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand();
    }

    // Initialize records with random values in a specified range
    const int min_value = -1000;
    const int max_value = 1000;
    for (size_t i = 0; i < size; ++i) {
        (*records)[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Check total allocated memory
    size_t total_memory = size * (sizeof(long) + sizeof(int) + sizeof(Record));
    if (total_memory > 2 * 1024 * 1024) {
        fprintf(stderr, "Total memory allocation exceeds 2 MB\n");
        free(*offsets);
        free(*keys);
        free(*records);
        exit(EXIT_FAILURE);
    }
}

int main() {
    size_t array_size = 1000; // Example array size
    long *offsets;
    int *keys;
    Record *records;

    initializeArrays(array_size, &offsets, &keys, &records);

