void initializeRecords(Record* records, size_t count, int keyRangeStart, int keyRangeEnd, long offsetRangeStart, long offsetRangeEnd) {
    srand(time(NULL)); // Seed PRNG

    for (size_t i = 0; i < count; ++i) {
        records[i].key = rand() % (keyRangeEnd - keyRangeStart + 1) + keyRangeStart;
        records[i].offset = rand() % (offsetRangeEnd - offsetRangeStart + 1) + offsetRangeStart;
        snprintf(records[i].value, sizeof(records[i].value), "Record%d", i);
    }
}

void writeRecordsToFile(Record* records, size_t count) {
    FILE* file = fopen("output.txt", "w");
    if (!file) {
        perror("Failed to open output.txt");
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        fprintf(file, "Key: %d, Offset: %ld, Value: %s\n", records[i].key, records[i].offset, records[i].value);
    }

    fclose(file);
}

void freeRecords(Record* records) {
    if (records) {
        free(records);
    }
}

int main() {
    size_t count = 100;
    int keyRangeStart = 1;
    int keyRangeEnd = 1000;
    long offsetRangeStart = 0;
    long offsetRangeEnd = 1000000;

    Record* records = (Record*)malloc(count * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return EXIT_FAILURE;
    }

    initializeRecords(records, count, keyRangeStart, keyRangeEnd, offsetRangeStart, offsetRangeEnd);
    writeRecordsToFile(records, count);

    freeRecords(records);

    return EXIT_SUCCESS;
}
