#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int* data;
    size_t capacity;
    size_t count;
} DynamicDataset;

DynamicDataset* init_dataset(size_t initial_capacity) {
    DynamicDataset* dataset = (DynamicDataset*)malloc(sizeof(DynamicDataset));
    if (!dataset) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }
    dataset->data = (int*)calloc(initial_capacity, sizeof(int));
    if (!dataset->data) {
        free(dataset);
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }
    dataset->capacity = initial_capacity;
    dataset->count = 0;
    srand(time(0)); // Seed for PRNG
    return dataset;
}

void expand_dataset(DynamicDataset* dataset, size_t additional_elements) {
    if (additional_elements == 0) return;

    size_t new_capacity = dataset->capacity + additional_elements;
    int* new_data = (int*)realloc(dataset->data, new_capacity * sizeof(int));
    if (!new_data) {
        fprintf(stderr, "Memory reallocation failed.\n");
        return;
    }
    dataset->data = new_data;
    dataset->capacity = new_capacity;

    // Initialize new elements with random values
    for (size_t i = dataset->count; i < dataset->capacity; ++i) {
        dataset->data[i] = rand();
    }

    dataset->count += additional_elements;
}

int get_random_value(DynamicDataset* dataset, size_t index) {
    if (index >= dataset->count) {
        fprintf(stderr, "Index out of bounds.\n");
        return -1; // Error value
    }
    return dataset->data[index];
}

void free_dataset(DynamicDataset* dataset) {
    free(dataset->data);
    free(dataset);
}

int main() {
    DynamicDataset* ds = init_dataset(100);
    if (!ds) return 1;

    expand_dataset(ds, 50);

    for (size_t i = 0; i < ds->count; ++i) {
        printf("Element at index %zu: %d\n", i, get_random_value(ds, i));
    }

    free_dataset(ds);
    return 0;
}
```

This code provides a basic structure for managing a dynamic dataset of integers. It includes initialization, expansion, data retrieval, and cleanup functions. The use of `calloc` ensures that the initial memory is zero-initialized, which can be beneficial depending on the PRNG algorithm used. Error handling is included to manage memory allocation failures gracefully.']

