    pthread_mutex_lock(&memory_pool_lock);
    if (next_record_index >= pool_size) {
        Record** new_pool = realloc(record_pool, (pool_size + 1000) * sizeof(Record*));
        if (!new_pool) {
            fprintf(stderr, "Memory allocation failed for records\n");
            pthread_mutex_unlock(&memory_pool_lock);
            return NULL;
        }
        record_pool = new_pool;
        pool_size += 1000;
    }
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed for record\n");
        pthread_mutex_unlock(&memory_pool_lock);
        return NULL;
    }
    new_record->value = rand() % 1001;
    record_pool[next_record_index++] = new_record;
    pthread_mutex_unlock(&memory_pool_lock);
    return new_record;
}

