#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define LOG_FILE "memory_log.txt"

typedef struct User {
    int user_id;
    char username[50];
    char hashed_password[64];
} User;

typedef struct Session {
    int session_id;
    time_t timestamp;
    User* user_profile;
} Session;

typedef struct Transaction {
    int transaction_id;
    time_t timestamp;
    User* user_profile;
    Session* session_object;
} Transaction;

typedef struct MemoryPool {
    void* pool;
    size_t size;
    size_t used;
} MemoryPool;

MemoryPool create_memory_pool(size_t initial_size) {
    MemoryPool pool = {malloc(initial_size), initial_size, 0};
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->pool);
    pool->size = 0;
    pool->used = 0;
    pool->pool = NULL;
}

void log_memory_allocation(const char* message, size_t size) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file != NULL) {
        fprintf(file, "%s - Size: %zu bytes\n", message, size);
        fclose(file);
    }
    printf("%s - Size: %zu bytes\n", message, size);
}

void* allocate_from_pool(MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->size) {
        size_t new_size = pool->size * 2;
        while (new_size < pool->used + size)
            new_size *= 2;
        void* new_pool = realloc(pool->pool, new_size);
        if (new_pool == NULL) {
            log_memory_allocation("Memory allocation failed", size);
            return NULL;
        }
        pool->pool = new_pool;
        pool->size = new_size;
    }
    void* ptr = (char*)pool->pool + pool->used;
    pool->used += size;
    log_memory_allocation("Allocated from pool", size);
    return ptr;
}

int generate_session_id() {
    static int seed = 0;
    if (!seed) {
        seed = time(NULL);
        srand(seed);
    }
    return rand();
}

Session* create_session(User* user_profile) {
    Session* session = (Session*)allocate_from_pool(&memory_pool, sizeof(Session));
    if (session == NULL)
        return NULL;
    session->session_id = generate_session_id();
    session->timestamp = time(NULL);
    session->user_profile = user_profile;
    return session;
}

User* create_user(int user_id, const char* username, const char* hashed_password) {
    User* user = (User*)allocate_from_pool(&memory_pool, sizeof(User));
    if (user == NULL)
        return NULL;
    user->user_id = user_id;
    strncpy(user->username, username, 50);
    strncpy(user->hashed_password, hashed_password, 64);
    return user;
}

Transaction* create_transaction(int transaction_id, User* user_profile, Session* session_object) {
    Transaction* transaction = (Transaction*)allocate_from_pool(&memory_pool, sizeof(Transaction));
    if (transaction == NULL)
        return NULL;
    transaction->transaction_id = transaction_id;
    transaction->timestamp = time(NULL);
    transaction->user_profile = user_profile;
    transaction->session_object = session_object;
    return transaction;
}

int main() {
    MemoryPool memory_pool = create_memory_pool(1024);

    User* user = create_user(1, "john_doe", "hashed_password_123");
    Session* session = create_session(user);
    Transaction* transaction = create_transaction(1, user, session);

    if (user && session && transaction) {
        printf("Session ID: %d\n", session->session_id);
        printf("Transaction ID: %d\n", transaction->transaction_id);
    }

    destroy_memory_pool(&memory_pool);
    return 0;
}
