    unsigned int capacity;
    void** array;
} DynamicArray;

// Function prototypes
DynamicArray* create_dynamic_array(size_t initial_capacity);
void free_dynamic_array(DynamicArray* array);
unsigned long generate_session_id();
User* create_user(const char* name, const char* email);
Transaction* create_transaction(time_t timestamp, double amount, const char* description, User* user_profile);
void log_memory_allocation(void* memory, size_t size);

// Implementation of functions
DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->array = (void**)calloc(initial_capacity, sizeof(void*));
    if (!array->array) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    log_memory_allocation(array->array, initial_capacity * sizeof(void*));
    return array;
}

void free_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->array[i]);
    }
    free(array->array);
    free(array);
}

unsigned long generate_session_id() {
    unsigned long id;
    FILE* random_device = fopen("/dev/urandom", "rb");
    if (random_device) {
        fread(&id, sizeof(id), 1, random_device);
        fclose(random_device);
    } else {
        srand(time(NULL));
        id = rand();
    }
    return id;
}

User* create_user(const char* name, const char* email) {
    User* user = (User*)malloc(sizeof(User));
    if (!user) return NULL;

    user->name = strdup(name);
    user->email = strdup(email);
    user->session_id = generate_session_id();
    log_memory_allocation(user, sizeof(User));
    return user;
}

Transaction* create_transaction(time_t timestamp, double amount, const char* description, User* user_profile) {
    Transaction* transaction = (Transaction*)malloc(sizeof(Transaction));
    if (!transaction) return NULL;

    transaction->timestamp = timestamp;
    transaction->amount = amount;
    transaction->description = strdup(description);
    transaction->user_profile = user_profile;
    log_memory_allocation(transaction, sizeof(Transaction));
    return transaction;
}

void log_memory_allocation(void* memory, size_t size) {
    static FILE* log_file = fopen("memory_log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: Allocated %zu bytes at %p\n", ctime(&now), size, memory);
        fflush(log_file);
    } else {
        printf("Failed to open log file for writing.\n");
    }
}

// Example usage
int main() {
    DynamicArray* users = create_dynamic_array(10);
    if (!users) {
        fprintf(stderr, "Failed to create user array.\n");
        return 1;
    }

    User* user1 = create_user("John Doe", "john@example.com");
    if (!user1) {
        fprintf(stderr, "Failed to create user.\n");
        free_dynamic_array(users);
        return 1;
    }

    users->array[users->size++] = user1;

    Transaction* transaction1 = create_transaction(time(NULL), 100.0, "Initial deposit", user1);
    if (!transaction1) {
        fprintf(stderr, "Failed to create transaction.\n");
        free(user1->name);
        free(user1->email);
        free(user1);
        free_dynamic_array(users);
        return 1;
    }

    printf("Transaction created successfully with ID: %lu\n", user1->session_id);

    // Clean up
    free(transaction1->description);
    free(transaction1->user_profile);
    free(transaction1);
    for (size_t i = 0; i < users->size; ++i) {
        free(((User*)users->array[i])->name);
        free(((User*)users->array[i])->email);
        free(users->array[i]);
    }
    free_dynamic_array(users);

    return 0;
}
```

