class ConfigManager {
private:
    std::unordered_map<std::string, int> configSettings;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool updatePending_;

public:
    ConfigManager() : updatePending_(false) {}

    void readConfigFromDatabase(const std::string& url) {
        // Simulate reading from REST API
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
        configSettings["networkTimeout"] = 10;
        configSettings["retryInterval"] = 3;
        configSettings["logLevel"] = 2;
    }

    void updateConfig(const std::unordered_map<std::string, int>& newSettings) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& setting : newSettings) {
            configSettings[setting.first] = setting.second;
        }
        updatePending_ = true;
        cv_.notify_one();
    }

    void applyConfigChanges() {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this]{ return updatePending_; });
        // Apply changes to the system based on configSettings
        std::cout << "Applying configuration changes:" << std::endl;
        for (const auto& setting : configSettings) {
            std::cout << setting.first << ": " << setting.second << std::endl;
        }
        updatePending_ = false;
    }

    int getConfigValue(const std::string& key) const {
        std::lock_guard<std::mutex> lock(mutex_);
        return configSettings.at(key);
    }

private:
    std::random_device rd_;
    std::mt19937 prng_(rd());
};

int main() {
    ConfigManager manager;
    manager.readConfigFromDatabase("http://example.com/api/config");
    std::this_thread::sleep_for(std::chrono::seconds(2));
    manager.updateConfig({{"networkTimeout", 15}, {"retryInterval", 4}});
    manager.applyConfigChanges();
    return 0;
}
