    int unique_id;
} config;

typedef struct {
    time_t timestamp;
    char* event_description;
    config* config_ref;
} event_record;

config* create_configs(int initial_size, int* current_size) {
    config* configs = (config*)malloc(initial_size * sizeof(config));
    if (!configs) return NULL;

    for (int i = 0; i < initial_size; ++i) {
        configs[i].probability = ((double)rand() / RAND_MAX);
        configs[i].config_name = strdup("default_config");
        configs[i].timeout_duration = rand() % 100;
        configs[i].unique_id = rand();
    }

    *current_size = initial_size;
    return configs;
}

event_record* create_events(int initial_size, int* current_size) {
    event_record* events = (event_record*)malloc(initial_size * sizeof(event_record));
    if (!events) return NULL;

    for (int i = 0; i < initial_size; ++i) {
        events[i].timestamp = time(NULL);
        events[i].event_description = strdup("default_event");
        events[i].config_ref = &create_configs(1, &current_size)->[rand() % current_size];
    }

    *current_size = initial_size;
    return events;
}

void resize_configs(config** configs, int* current_size) {
    int new_size = *current_size * 2;
    config* new_configs = (config*)realloc(*configs, new_size * sizeof(config));
    if (!new_configs) {
        free(*configs);
        exit(EXIT_FAILURE);
    }

    for (int i = *current_size; i < new_size; ++i) {
        new_configs[i].probability = ((double)rand() / RAND_MAX);
        new_configs[i].config_name = strdup("default_config");
        new_configs[i].timeout_duration = rand() % 100;
        new_configs[i].unique_id = rand();
    }

    *configs = new_configs;
    *current_size = new_size;
}

void resize_events(event_record** events, int* current_size) {
    int new_size = *current_size * 2;
    event_record* new_events = (event_record*)realloc(*events, new_size * sizeof(event_record));
    if (!new_events) {
        free(*events);
        exit(EXIT_FAILURE);
    }

    for (int i = *current_size; i < new_size; ++i) {
        new_events[i].timestamp = time(NULL);
        new_events[i].event_description = strdup("default_event");
        new_events[i].config_ref = &create_configs(1, &new_size)->[rand() % new_size];
    }

    *events = new_events;
    *current_size = new_size;
}

void free_resources(config** configs, event_record** events) {
    for (int i = 0; i < (*configs)->length; ++i) {
        free((*configs)[i].config_name);
    }
    free(*configs);

    for (int i = 0; i < (*events)->length; ++i) {
        free((*events)[i].event_description);
    }
    free(*events);
}
