#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_SESSIONS 1000
#define SESSION_ID_LENGTH 32

typedef struct {
    char id[SESSION_ID_LENGTH];
    char token[64];
    time_t last_activity;
} UserSession;

UserSession* sessions[MAX_SESSIONS];
int session_count = 0;
int session_capacity = MAX_SESSIONS;

void init_session_manager(int initial_capacity) {
    if (initial_capacity > MAX_SESSIONS) {
        printf("Initial capacity exceeds maximum allowed.\n");
        return;
    }
    session_capacity = initial_capacity;
}

char* generate_unique_session_id() {
    static char id[SESSION_ID_LENGTH];
    // Use a secure PRNG to generate unique IDs
    srand(time(0));
    for (int i = 0; i < SESSION_ID_LENGTH; ++i) {
        id[i] = 'a' + rand() % ('z' - 'a');
    }
    return id;
}

int add_user_session(const char* token) {
    if (session_count >= session_capacity) {
        printf("Session list is full.\n");
        return -1;
    }
    UserSession* new_session = malloc(sizeof(UserSession));
    if (!new_session) {
        printf("Memory allocation failed for new session.\n");
        return -2;
    }
    strcpy(new_session->id, generate_unique_session_id());
    strcpy(new_session->token, token);
    time(&new_session->last_activity);
    sessions[session_count++] = new_session;
    printf("Session created: ID=%s, Token=%s\n", new_session->id, new_session->token);
    return 0;
}

void update_user_session(const char* id) {
    for (int i = 0; i < session_count; ++i) {
        if (strcmp(sessions[i]->id, id) == 0) {
            time(&sessions[i]->last_activity);
            printf("Session updated: ID=%s\n", sessions[i]->id);
            return;
        }
    }
    printf("Session with ID %s not found.\n", id);
}

void expire_user_session(const char* id) {
    for (int i = 0; i < session_count; ++i) {
        if (strcmp(sessions[i]->id, id) == 0) {
            free(sessions[i]);
            sessions[i] = NULL;
            printf("Session expired: ID=%s\n", id);
            return;
        }
    }
    printf("Session with ID %s not found.\n", id);
}

void cleanup_session_manager() {
    for (int i = 0; i < session_count; ++i) {
        if (sessions[i]) {
            free(sessions[i]);
        }
    }
    session_count = 0;
}
