void initialize_arrays(long** timestamps, int** seeds, record** records, config** configs, long** offsets, long** identifiers, size_t size) {
    *timestamps = allocate_memory(size);
    *seeds = allocate_memory(size);
    *records = (record*)malloc(size * sizeof(record));
    *configs = (config*)malloc(size * sizeof(config));
    *offsets = allocate_memory(size);
    *identifiers = allocate_memory(size);

    if (*records == NULL || *timestamps == NULL || *seeds == NULL || *configs == NULL || *offsets == NULL || *identifiers == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
