fn measure_rust_compile_time_and_memory() -> Result<i32, Box<dyn std::error::Error>> {
    let start = Instant::now();
    let compile_start = SystemTime::now();

    let mut child = Command::new("rustc")
        .arg("--crate-type=bin")
        .arg("main.rs") // Replace with your Rust program
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()?;

    if let Some(status) = child.wait()? {
        let duration = start.elapsed();
        let compile_duration = compile_start.elapsed();

        println!("Compilation time: {:?}", compile_duration);
        println!("Total execution time: {:?}", duration);

        Ok(status.code().unwrap_or(1))
    } else {
        Err("Failed to execute rustc".into())
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let exit_code = measure_rust_compile_time_and_memory()?;
