void generate_secure_values(long *offsets, int *keys, record **records, size_t size, int range_start, int range_end) {
    if (RAND_bytes((unsigned char*)offsets, sizeof(long) * size) != 1 ||
        RAND_bytes((unsigned char*)keys, sizeof(int) * size) != 1) {
        fprintf(stderr, "Error generating secure random values.\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand() % (range_end - range_start + 1) + range_start;
        keys[i] = rand() % (range_end - range_start + 1) + range_start;

        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record %zu.\n", i);
            exit(EXIT_FAILURE);
        }
        records[i]->value = rand() % (range_end - range_start + 1) + range_start;
    }
}

record** filter_records_by_timestamp(record **records, size_t size, time_t start_time, time_t end_time) {
    record **filtered_records = malloc(sizeof(record*) * size);
    if (!filtered_records) {
        fprintf(stderr, "Memory allocation failed for filtered records.\n");
        exit(EXIT_FAILURE);
    }

    size_t count = 0;
    for (size_t i = 0; i < size; ++i) {
        if (records[i]->timestamp >= start_time && records[i]->timestamp <= end_time) {
            filtered_records[count++] = records[i];
        }
    }

    // Resize the array to remove unused space
    filtered_records = realloc(filtered_records, sizeof(record*) * count);
    return filtered_records;
}

int main() {
    const size_t num_entries = 1000;
    long *offsets = malloc(sizeof(long) * num_entries);
    int *keys = malloc(sizeof(int) * num_entries);
    record **records = malloc(sizeof(record*) * num_entries);

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed for main arrays.\n");
        exit(EXIT_FAILURE);
    }

    generate_secure_values(offsets, keys, records, num_entries, 0, 10000);

    // Example usage of filtering
    time_t start_time = time(NULL);
    time_t end_time = start_time + 3600; // One hour from now
    record **filtered_records = filter_records_by_timestamp(records, num_entries, start_time, end_time);

    // Clean up allocated memory
    for (size_t i = 0; i < num_entries; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
    free(filtered_records);

    return 0;
}
