['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1024
#define MIN_VALUE 0
#define MAX_VALUE 100

typedef struct {
    int value;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* memory_pool_create(size_t initial_capacity) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (pool == NULL) {
        fprintf(stderr, "Failed to allocate memory for MemoryPool\n");
        return NULL;
    }
    pool->records = malloc(initial_capacity * sizeof(Record));
    if (pool->records == NULL) {
        free(pool);
        fprintf(stderr, "Failed to allocate memory for records\n");
        return NULL;
    }
    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void memory_pool_destroy(MemoryPool* pool) {
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

void memory_pool_resize(MemoryPool* pool, size_t new_capacity) {
    if (new_capacity > MAX_RECORDS) {
        fprintf(stderr, "Attempted to resize beyond maximum capacity\n");
        return;
    }
    Record* new_records = realloc(pool->records, new_capacity * sizeof(Record));
    if (new_records == NULL) {
        fprintf(stderr, "Failed to reallocate memory for records\n");
        return;
    }
    pool->records = new_records;
    pool->capacity = new_capacity;
}

int memory_pool_add(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity) {
        size_t new_capacity = pool->capacity == 0 ? 1 : pool->capacity * 2;
        memory_pool_resize(pool, new_capacity);
    }
    int random_value = MIN_VALUE + rand() % (MAX_VALUE - MIN_VALUE + 1);
    pool->records[pool->size].value = random_value;
    pthread_mutex_unlock(&pool->lock);
    return pool->size++;
}

void* thread_func(void* arg) {
    MemoryPool* pool = (MemoryPool*)arg;
    for (int i = 0; i < 100; ++i) {
        memory_pool_add(pool);
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    MemoryPool* pool = memory_pool_create(256);
    if (pool == NULL) {
        fprintf(stderr, "Failed to create memory pool\n");
        return 1;
    }

    pthread_t threads[8];
    for (int i = 0; i < 8; ++i) {
        pthread_create(&threads[i], NULL, thread_func, pool);
    }

    for (int i = 0; i < 8; ++i) {
        pthread_join(threads[i], NULL);
    }

    memory_pool_destroy(pool);
    return 0;
}
```']

