#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int value;
    long* offset;
    int key_index;
} record;

record* create_records(int* error_code) {
    const int MAX_KEYS = 5000;
    const int MAX_RECORDS = 10000;

    // Allocate memory for offsets
    long* offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return NULL;
    }

    // Allocate memory for keys
    int* keys = (int*)malloc(MAX_KEYS * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        return NULL;
    }

    // Initialize key array with unique values
    for (int i = 0; i < MAX_KEYS; ++i) {
        keys[i] = i;
    }

    // Shuffle the keys array using a non-cryptographic PRNG
    srand(time(NULL));
    for (int i = MAX_KEYS - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        int temp = keys[i];
        keys[i] = keys[j];
        keys[j] = temp;
    }

    // Allocate memory for records
    record* recs = (record*)malloc(MAX_RECORDS * sizeof(record));
    if (!recs) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize records with unique values and pointers
    int key_index = 0;
    for (int i = 0; i < MAX_RECORDS; ++i) {
        recs[i].value = keys[key_index++];
        recs[i].offset = &offsets[i];
        if (key_index >= MAX_KEYS) {
            key_index = 0;
        }
    }

    *error_code = 0; // Success
    return recs;
}

int main() {
    int error_code;
    record* records = create_records(&error_code);
    if (!records) {
        printf("Failed to create records. Error code: %d\n", error_code);
    } else {
        free(records[0].offset); // Free individual offsets
        free(records);           // Free records array
    }
    return 0;
}
