#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define a simple record structure
typedef struct {
    int value;
} Record;

// Define error codes
#define ERR_SUCCESS 0
#define ERR_ALLOC_FAILED -1
#define ERR_INVALID_SIZE -2

// Function to allocate memory for arrays and records
int allocateMemory(size_t size, long **offsets, int **keys, Record **records) {
    if (size <= 0) {
        return ERR_INVALID_SIZE;
    }

    // Allocate memory for offsets
    *offsets = (long *)malloc(size * sizeof(long));
    if (*offsets == NULL) {
        return ERR_ALLOC_FAILED;
    }

    // Allocate memory for keys
    *keys = (int *)malloc(size * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return ERR_ALLOC_FAILED;
    }

    // Allocate memory for records
    *records = (Record *)malloc(size * sizeof(Record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return ERR_ALLOC_FAILED;
