} record;

typedef struct {
    record** records;
    size_t count;
    pthread_mutex_t lock;
} data_set;

void* generate_data(void* arg) {
    data_set* ds = (data_set*)arg;
    pthread_mutex_lock(&ds->lock);

    for (size_t i = 0; i < ds->count; ++i) {
        ds->records[i] = malloc(sizeof(record));
        if (!ds->records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }

        ds->records[i]->offsets = malloc(100 * sizeof(long)); // Example size
        ds->records[i]->keys = malloc(100 * sizeof(int));     // Example size

        if (!ds->records[i]->offsets || !ds->records[i]->keys) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }

        // Initialize records with random values using a selected PRNG
        for (size_t j = 0; j < 100; ++j) { // Example size
            ds->records[i]->offsets[j] = arc4random(); // Example PRNG
            ds->records[i]->keys[j] = rand() % 100;   // Random key
        }
    }

    pthread_mutex_unlock(&ds->lock);
    return NULL;
}

int main() {
    data_set ds;
    ds.count = 5; // Example number of records

    ds.records = malloc(ds.count * sizeof(record*));
    if (!ds.records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    pthread_mutex_init(&ds.lock, NULL);

    pthread_t threads[ds.count];
    for (size_t i = 0; i < ds.count; ++i) {
        pthread_create(&threads[i], NULL, generate_data, &ds);
    }

    for (size_t i = 0; i < ds.count; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Process the data_set as needed

    for (size_t i = 0; i < ds.count; ++i) {
        free(ds.records[i]->offsets);
        free(ds.records[i]->keys);
        free(ds.records[i]);
    }
    free(ds.records);

    pthread_mutex_destroy(&ds.lock);

    return 0;
}
