['```csharp
using System;
using System.IO;
using System.Numerics;

public record struct RandomIntRecord(int Value);

public class RandomValueGenerator : IDisposable
{
    private readonly long _minValue;
    private readonly long _maxValue;
    private readonly BigInteger _currentState;
    private static readonly RandomNumberGenerator _rng = RandomNumberGenerator.Create();

    public RandomValueGenerator(long minValue, long maxValue)
    {
        if (minValue > maxValue) throw new ArgumentException("Min value cannot be greater than max value.");
        _minValue = minValue;
        _maxValue = maxValue;
        _currentState = GenerateInitialState();
    }

    private BigInteger GenerateInitialState()
    {
        var buffer = new byte[16]; // 128-bit state
        _rng.GetBytes(buffer);
        return new BigInteger(buffer);
    }

    public long NextLong()
    {
        return (long)(_currentState % (_maxValue - _minValue + 1)) + _minValue;
    }

    public int NextInt()
    {
        return (int)NextLong();
    }

    public RandomIntRecord NextRandomIntRecord()
    {
        return new RandomIntRecord(NextInt());
    }

    public void Dispose()
    {
        _rng.Dispose();
    }

    public override string ToString()
    {
        return $"Range: {_minValue} to {_maxValue}, State: {_currentState}";
    }
}
