#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    char status;
} data_record;

void generate_random_data(data_record **data, size_t size, int min_value, int max_value) {
    // Use the Mersenne Twister algorithm for high-quality randomness
    static unsigned long mt[624] = {0};
    static int index = 625;
    if (index == 625) {
        srand(time(NULL));
        for (int i = 0; i < 624; ++i) {
            mt[i] = rand();
        }
        index = 0;
    }

    // Fill the data records with random values
    for (size_t i = 0; i < size; ++i) {
        (*data)[i].value = min_value + (mt[index++] % (max_value - min_value + 1));
        (*data)[i].status = 'A'; // Example status flag
    }
}

void initialize_timestamps(long **timestamps, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        (*timestamps)[i] = (long)(time(NULL) * 1000L) - i;
        if ((*timestamps)[i] < 0) {
            (*timestamps)[i] = 0;
        }
    }
}

void* populate_data(void* arg) {
    size_t thread_id = *(size_t*)arg;
    data_record **data = ((long*)arg + 1);
    long *timestamps = (long*)(((long*)arg + 1) + size);

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    generate_random_data(data, thread_id, 0, 100); // Example range
    initialize_timestamps(timestamps, thread_id);

    pthread_mutex_unlock(&mutex);
    return NULL;
}

int main() {
    size_t num_threads = 4;
    data_record **data_records = (data_record**)malloc(num_threads * sizeof(data_record*));
    long *timestamps = (long*)malloc(num_threads * sizeof(long));

    pthread_t threads[num_threads];
    for (size_t i = 0; i < num_threads; ++i) {
        size_t thread_id = i;
        data_records[i] = (data_record*)malloc(i * sizeof(data_record));
        if (!data_records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            return EXIT_FAILURE;
        }
        pthread_create(&threads[i], NULL, populate_data, &thread_id);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
        free(data_records[i]);
    }

    free(timestamps);
    free(data_records);

    return EXIT_SUCCESS;
}
