#include <stdlib.h>
#include <stdint.h>
#include <openssl/rand.h>

typedef struct {
    int value;
} record;

record* initialize_records(size_t N, int lower_bound, int upper_bound) {
    if (N == 0 || lower_bound > upper_bound) {
        return NULL; // Invalid input
    }

    // Allocate memory for offset and key arrays
    long* offsets = malloc(N * sizeof(long));
    int* keys = malloc(N * sizeof(int));

    if (offsets == NULL || keys == NULL) {
        free(offsets);
        free(keys);
        return NULL; // Memory allocation failed
    }

    // Initialize arrays with some values (e.g., zero)
    for (size_t i = 0; i < N; ++i) {
        offsets[i] = 0;
        keys[i] = i;
    }

    // Allocate memory for record array
    record* records = malloc(N * sizeof(record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        return NULL; // Memory allocation failed
    }

    // Initialize CSPRNG state
    unsigned char seed[32];
    if (!RAND_bytes(seed, sizeof(seed))) {
        free(offsets);
        free(keys);
        free(records);
        return NULL; // CSPRNG initialization failed
    }
    RAND_seed(seed, sizeof(seed));

    // Populate record array with random integers
    for (size_t i = 0; i < N; ++i) {
        int random_value;
        if (!RAND_int_between(RAND_get_rng(), lower_bound, upper_bound, &random_value)) {
            free(offsets);
            free(keys);
            free(records);
            return NULL; // Failed to generate a valid random number
        }
        records[i].value = random_value;
    }

    // Reset CSPRNG state (optional)
    RAND_add(seed, sizeof(seed), 0);

    // Return initialized record array
    return records;
}

void free_records(record* records) {
    if (records != NULL) {
        free(records);
    }
}
```

