User* create_user_array(size_t initial_size, size_t *current_size) {
    if (initial_size > MAX_USERS) {
        fprintf(stderr, "Error: Initial size exceeds maximum allowed users.\n");
        return NULL;
    }

    User *users = malloc(initial_size * sizeof(User));
    if (!users) {
        fprintf(stderr, "Error: Failed to allocate memory for user array.\n");
        return NULL;
    }

    *current_size = initial_size;

    srand(time(NULL));
    for (size_t i = 0; i < initial_size; ++i) {
        users[i].id = rand();
        snprintf(users[i].name, sizeof(users[i].name), "User%d", i);
        snprintf(users[i].email, sizeof(users[i].email), "user%d@example.com", i);
        users[i].transaction_count = 0;
    }

    return users;
}

void add_transaction(User *user, time_t timestamp, double amount, const char *description) {
    if (user->transaction_count >= MAX_TRANSACTIONS) {
        fprintf(stderr, "Error: User has reached maximum number of transactions.\n");
        return;
    }

    user->transactions[user->transaction_count].timestamp = timestamp;
    user->transactions[user->transaction_count].amount = amount;
    snprintf(user->transactions[user->transaction_count].description, sizeof(user->transactions[user->transaction_count].description), "%s", description);
    ++user->transaction_count;
}

void free_user_array(User *users, size_t size) {
    free(users);
}
