    if (!keys) {
        fprintf(stderr, "Memory allocation failed for key array\n");
        exit(EXIT_FAILURE);
    }
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        keys[i] = rand() % 100000; // Example range
    }
    return keys;
}

Record* create_record_array(size_t size) {
    Record* records = malloc(size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for record array\n");
        exit(EXIT_FAILURE);
    }
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % 100000; // Example range
    }
    return records;
}

unsigned long* create_metadata_array(Record* records, size_t size) {
    unsigned long* metadata = malloc(size * sizeof(unsigned long));
    if (!metadata) {
        fprintf(stderr, "Memory allocation failed for metadata array\n");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < size; ++i) {
        metadata[i] = hash_function(records[i].value);
    }
    return metadata;
}

void serialize_data(long* offsets, int* keys, Record* records, unsigned long* metadata, size_t size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Error opening file for writing");
        return;
    }

    fwrite(offsets, sizeof(long), size, file);
    fwrite(keys, sizeof(int), size, file);
    fwrite(records, sizeof(Record), size, file);
    fwrite(metadata, sizeof(unsigned long), size, file);

    fclose(file);
}

void deserialize_data(long** offsets, int** keys, Record** records, unsigned long** metadata, size_t* size, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file for reading");
        return;
    }

    fread(offsets, sizeof(long), *size, file);
    fread(keys, sizeof(int), *size, file);
    fread(records, sizeof(Record), *size, file);
    fread(metadata, sizeof(unsigned long), *size, file);

    fclose(file);
}

void verify_data_integrity(int* keys, Record* records, unsigned long* metadata, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (metadata[i] != hash_function(records[i].value)) {
            fprintf(stderr, "Data integrity check failed at index %zu\n", i);
            return;
        }
    }
    printf("Data integrity verified successfully.\n");
}
