void* initialize_memory(size_t n, size_t* total_size) {
    size_t offset_size = n * sizeof(long);
    size_t key_size = n * sizeof(int);
    size_t record_size = n * sizeof(record);

    *total_size = offset_size + key_size + record_size;
    void* memory_block = malloc(*total_size);

    if (memory_block == NULL) {
        return NULL; // Memory allocation failed
    }

    long* offsets = (long*)memory_block;
    int* keys = (int*)(offsets + n);
    record* records = (record*)(keys + n);

    for (size_t i = 0; i < n; ++i) {
        offsets[i] = i * 1024L; // Example offset calculation
        keys[i] = rand() % 1000; // Fast random number generator for keys
        records[i].value = rand() % 100; // Random values for record data
    }

    return memory_block;
}

void free_memory(void* memory_block, size_t total_size) {
    free(memory_block);
}
