#define ARRAY_SIZE 1000

typedef struct {
    int value;
    char identifier[50];
} Record;

void generate_random_data(long *timestamps, int *identifiers, Record *records) {
    srand(time(NULL));

    for (int i = 0; i < ARRAY_SIZE; i++) {
        // Allocate memory for the timestamp
        timestamps[i] = rand() % 1000000;

        // Generate unique identifier using a hash of the timestamp
        snprintf(records[i].identifier, sizeof(records[i].identifier), "ID%d_%ld", identifiers[i], timestamps[i]);

        // Fill record with random data
        records[i].value = rand() % 100;
    }
}

int main() {
    long *timestamps = (long *)malloc(ARRAY_SIZE * sizeof(long));
    int *identifiers = (int *)malloc(ARRAY_SIZE * sizeof(int));
    Record *records = (Record *)malloc(ARRAY_SIZE * sizeof(Record));

    if (!timestamps || !identifiers || !records) {
        printf("Memory allocation failed\n");
        return 1;
    }

    generate_random_data(timestamps, identifiers, records);

    // Process the generated data
    for (int i = 0; i < ARRAY_SIZE; i++) {
        printf("Timestamp: %ld, Identifier: %s, Record Value: %d\n", timestamps[i], records[i].identifier, records[i].value);
    }

    // Free allocated memory
    free(timestamps);
    free(identifiers);
    free(records);

    return 0;
}
