#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
} Record;

typedef struct metadata {
    int hash_value;
} Metadata;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    Metadata* metadatas;
    int* statuses;
    int active_count;
    size_t capacity;
} DataStructure;

DataStructure* create_data_structure(size_t initial_capacity) {
    DataStructure* ds = malloc(sizeof(DataStructure));
    if (ds == NULL) return NULL;

    ds->offsets = malloc(initial_capacity * sizeof(long));
    ds->keys = malloc(initial_capacity * sizeof(int));
    ds->records = malloc(initial_capacity * sizeof(Record*));
    ds->metadatas = malloc(initial_capacity * sizeof(Metadata));
    ds->statuses = malloc(initial_capacity * sizeof(int));

    if (ds->offsets == NULL || ds->keys == NULL || ds->records == NULL ||
        ds->metadatas == NULL || ds->statuses == NULL) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds->metadatas);
        free(ds->statuses);
        free(ds);
        return NULL;
    }

    for (size_t i = 0; i < initial_capacity; i++) {
        ds->records[i] = malloc(sizeof(Record));
        if (ds->records[i] == NULL) {
            // Clean up previously allocated memory
            for (size_t j = 0; j < i; j++) {
                free(ds->records[j]);
            }
            free(ds->offsets);
            free(ds->keys);
            free(ds->records);
            free(ds->metadatas);
            free(ds->statuses);
            free(ds);
            return NULL;
        }
    }

    srand(time(NULL));
    for (size_t i = 0; i < initial_capacity; i++) {
        ds->offsets[i] = rand();
        ds->keys[i] = rand() % 1000; // Random key within a specified range
        ds->records[i]->value = rand() % 1000;
        ds->metadatas[i].hash_value = abs(ds->records[i]->value);
        ds->statuses[i] = 1; // Initially all records are active
    }

    ds->active_count = initial_capacity;
    ds->capacity = initial_capacity;

    return ds;
}

void destroy_data_structure(DataStructure* ds) {
    for (size_t i = 0; i < ds->capacity; i++) {
        free(ds->records[i]);
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds->metadatas);
    free(ds->statuses);
    free(ds);
}

void serialize_data_structure(DataStructure* ds, FILE* file) {
    // Write the capacity and active count
    fwrite(&ds->capacity, sizeof(size_t), 1, file);
    fwrite(&ds->active_count, sizeof(int), 1, file);

    // Write offsets, keys, records, metadatas, and statuses
    fwrite(ds->offsets, sizeof(long), ds->capacity, file);
    fwrite(ds->keys, sizeof(int), ds->capacity, file);
    for (size_t i = 0; i < ds->capacity; i++) {
        fwrite(ds->records[i], sizeof(Record), 1, file);
    }
    fwrite(ds->metadatas, sizeof(Metadata), ds->capacity, file);
    fwrite(ds->statuses, sizeof(int), ds->capacity, file);
}

int deserialize_data_structure(DataStructure** ds, FILE* file) {
    size_t capacity;
    int active_count;

    // Read the capacity and active count
    if (fread(&capacity, sizeof(size_t), 1, file) != 1 ||
        fread(&active_count, sizeof(int), 1, file) != 1) {
        return -1; // Error in reading
    }

    *ds = malloc(sizeof(DataStructure));
    if (*ds == NULL) return -1;

    (*ds)->offsets = malloc(capacity * sizeof(long));
    (*ds)->keys = malloc(capacity * sizeof(int));
    (*ds)->records = malloc(capacity * sizeof(Record*));
    (*ds)->metadatas = malloc(capacity * sizeof(Metadata));
    (*ds)->statuses = malloc(capacity * sizeof(int));

    if ((*ds)->offsets == NULL || (*ds)->keys == NULL ||
        (*ds)->records == NULL || (*ds)->metadatas == NULL ||
        (*ds)->statuses == NULL) {
        free((*ds)->offsets);
        free((*ds)->keys);
        free((*ds)->records);
        free((*ds)->metadatas);
        free((*ds)->statuses);
        free(*ds);
        return -1;
    }

    // Read offsets, keys, records, metadatas, and statuses
    if (fread((*ds)->offsets, sizeof(long), capacity, file) != capacity ||
        fread((*ds)->keys, sizeof(int), capacity, file) != capacity ||
        fread((*ds)->records, sizeof(Record), capacity, file) != capacity ||
        fread((*ds)->metadatas, sizeof(Metadata), capacity, file) != capacity ||
        fread((*ds)->statuses, sizeof(int), capacity, file) != capacity) {
        free((*ds)->offsets);
        free((*ds)->keys);
        free((*ds)->records);
        free((*ds)->metadatas);
        free((*ds)->statuses);
        free(*ds);
        return -1;
    }

    (*ds)->active_count = active_count;
    (*ds)->capacity = capacity;

    return 0; // Success
}
