    if (num_records > MAX_RECORDS) {
        return NULL; // Handle error: Too many records requested
    }

    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        return NULL; // Handle error: Failed to allocate memory for offsets
    }

    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        free(offsets); // Clean up allocated memory
