    }

    record* records = (record*)malloc(num_records * RECORD_SIZE);
    if (!records) {
        free(offsets);
        free(keys); // Clean up allocated memory
        return NULL; // Handle error: Failed to allocate memory for records
    }

    srand(time(NULL)); // Seed the PRNG

    for (int i = 0; i < num_records; i++) {
        offsets[i] = i * sizeof(long); // Initialize offsets
        keys[i] = rand() % range + 1; // Initialize keys with random values within range
        records[i].value = rand() % range + 1; // Initialize record values with random values
    }

    return records;
}

void cleanup_records(record* records, int num_records) {
    if (records) {
        free(records); // Free the memory allocated for records
    }
