typedef struct {
    int value;
    uint64_t id;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    size_t capacity;
    size_t count;
    double memory_threshold;
    time_t cleanup_interval;
    FILE *log_file;
} RecordManager;

RecordManager* create_record_manager(size_t initial_capacity, double memory_threshold, time_t cleanup_interval, const char *log_path) {
    RecordManager *rm = (RecordManager*)malloc(sizeof(RecordManager));
    if (!rm) {
        perror("Failed to allocate memory for RecordManager");
        return NULL;
    }

    rm->offsets = (long*)calloc(initial_capacity, sizeof(long));
    if (!rm->offsets) {
        perror("Failed to allocate memory for offsets array");
        free(rm);
        return NULL;
    }

    rm->keys = (int*)malloc(initial_capacity * sizeof(int));
    if (!rm->keys) {
        perror("Failed to allocate memory for keys array");
        free(rm->offsets);
        free(rm);
        return NULL;
    }

    rm->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    if (!rm->records) {
        perror("Failed to allocate memory for records array");
        free(rm->keys);
        free(rm->offsets);
        free(rm);
        return NULL;
    }

    rm->capacity = initial_capacity;
    rm->count = 0;
    rm->memory_threshold = memory_threshold;
    rm->cleanup_interval = cleanup_interval;

    if (log_path) {
        rm->log_file = fopen(log_path, "a");
        if (!rm->log_file) {
            perror("Failed to open log file");
            free(rm->records);
            free(rm->keys);
            free(rm->offsets);
            free(rm);
            return NULL;
        }
    } else {
        rm->log_file = NULL;
    }

    srand(time(NULL));
    return rm;
}

void destroy_record_manager(RecordManager *rm) {
    for (size_t i = 0; i < rm->count; ++i) {
        free(rm->records[i]);
    }
    free(rm->offsets);
    free(rm->keys);
    free(rm->records);

    if (rm->log_file) {
        fclose(rm->log_file);
    }

    free(rm);
}

void add_record(RecordManager *rm, int value_range_start, int value_range_end) {
    // Check for capacity and resize if necessary
    if (rm->count == rm->capacity) {
        size_t new_capacity = rm->capacity ? 2 * rm->capacity : 1;
        long *new_offsets = realloc(rm->offsets, new_capacity * sizeof(long));
        int *new_keys = realloc(rm->keys, new_capacity * sizeof(int));
        Record **new_records = realloc(rm->records, new_capacity * sizeof(Record*));

        if (!new_offsets || !new_keys || !new_records) {
            perror("Failed to reallocate memory for record manager");
            return;
        }

        rm->offsets = new_offsets;
        rm->keys = new_keys;
        rm->records = new_records;
        rm->capacity = new_capacity;
    }

    // Generate unique ID, value, and add to arrays
    uint64_t id = generate_unique_id(rm);
    int value = generate_random_value(value_range_start, value_range_end);
    Record *rec = (Record*)malloc(sizeof(Record));
    if (!rec) {
        perror("Failed to allocate memory for record");
        return;
    }

    rec->value = value;
    rec->id = id;

    rm->offsets[rm->count] = (long)((char*)rec - (char*)rm->records);
    rm->keys[rm->count] = id; // Assuming ID is unique and can be used as a key
    rm->records[rm->count++] = rec;

    log_event(rm, "Added record with value %d and ID %" PRIu64 "", value, id);
}

uint64_t generate_unique_id(RecordManager *rm) {
    // Implement unique ID generation logic
    return (uint64_t)time(NULL) ^ ((uintptr_t)rm->records[0] >> 32) ^ rm->count;
}

int generate_random_value(int start, int end) {
    // Implement random value generation within the specified range
    return rand() % (end - start + 1) + start;
}

void log_event(RecordManager *rm, const char *format, ...) {
    if (!rm->log_file) {
        return;
    }

    va_list args;
    va_start(args, format);
    vfprintf(rm->log_file, format, args);
    fprintf(rm->log_file, "\n");
    fflush(rm->log_file);
    va_end(args);
}

void clean_up_records(RecordManager *rm) {
    // Implement logic to clean up unused records
    for (size_t i = 0; i < rm->count; ++i) {
        if (!is_record_used(rm, i)) {
            free(rm->records[i]);
            memmove(&rm->offsets[i], &rm->offsets[i + 1], (rm->count - i - 1) * sizeof(long));
            memmove(&rm->keys[i], &rm->keys[i + 1], (rm->count - i - 1) * sizeof(int));
            memmove(&rm->records[i], &rm->records[i + 1], (rm->count - i - 1) * sizeof(Record*));
            --rm->count;
            --i;
        }
    }

    log_event(rm, "Cleaned up %zu unused records", rm->capacity - rm->count);
}

