sensor_entry* manage_sensor_data(size_t initial_size, size_t max_size, long min_timestamp, long max_timestamp,
                                  int min_key, int max_key, float range_start, float range_end) {
    if (initial_size == 0 || initial_size > max_size) {
        fprintf(stderr, "Invalid size parameters.\n");
        return NULL;
    }

    sensor_entry* entries = malloc(initial_size * sizeof(sensor_entry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed for PRNG

    for (size_t i = 0; i < initial_size; ++i) {
        entries[i].timestamp = rand_range(min_timestamp, max_timestamp);
        entries[i].key = rand_range(min_key, max_key);
        entries[i].measurement = range_start + ((float)rand() / RAND_MAX) * (range_end - range_start);
    }

    return entries;
}

long rand_range(long min_val, long max_val) {
    if (max_val < min_val) {
        fprintf(stderr, "Invalid range for random value generation.\n");
        return 0;
    }
    return min_val + rand() % (max_val - min_val + 1);
}

record* manage_records(size_t size, int min_value, int max_value) {
    if (size == 0) {
        fprintf(stderr, "Invalid size for records.\n");
        return NULL;
    }

    record* recs = malloc(size * sizeof(record));
    if (!recs) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
