    srand(time(NULL));
    buffer[0] = rand() % 256; // Random ASCII character
    for (size_t i = 1; i < length; ++i) {
        int new_char;
        do {
            new_char = rand() % 256;
        } while (new_char == buffer[i - 1]);
        buffer[i] = new_char;
