Record* create_records(size_t num_records, size_t *offsets, int **keys, Record ***records) {
    if (num_records == 0) return NULL;

    // Allocate memory for offsets
    offsets = malloc(num_records * sizeof(*offsets));
    if (!offsets) return NULL;

    // Allocate memory for keys
    *keys = malloc(num_records * sizeof(**keys));
    if (!*keys) {
        free(offsets);
        return NULL;
    }

    // Allocate memory for records
    **records = malloc(num_records * sizeof(***records));
    if (!**records) {
        free(offsets);
        free(*keys);
        return NULL;
    }

    // Initialize records with random data
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = rand() % 10000; // Example offset initialization
        (*keys)[i] = rand(); // Random key

        size_t string_length = rand() % (MAX_STRING_LENGTH - 1) + 1;
        fill_string((**records)[i].buffer, string_length);
        (**records)[i].value = rand();
    }

    return **records;
}

int main() {
    size_t num_records = 5;
    size_t *offsets;
    int *keys;
