        free(offsets);
        free(keys);
        for (size_t i = 0; i < num_records; ++i) {
            records[0][i].buffer[0] = '\0'; // Clear buffer to avoid dangling pointers
        }
        free(records[0]);
    } else {
        printf("Failed to allocate memory for records.\n");
    }

    return 0;
