#define DEFAULT_SESSION_DATA "DefaultData"
#define MAX_SESSION_DATA_SIZE 100

typedef struct {
    long timestamp;
    int session_id;
    char session_data[MAX_SESSION_DATA_SIZE];
} Session;

typedef struct {
    int key;
} Record;

Session* create_session_array(int *array_size, int new_size) {
    if (new_size < *array_size) return NULL; // No resizing needed

    Session *new_sessions = realloc(*sessions, new_size * sizeof(Session));
    if (!new_sessions) return NULL; // Allocation failed

    for (int i = *array_size; i < new_size; i++) {
        new_sessions[i].timestamp = time(NULL);
        new_sessions[i].session_id = rand();
        strncpy(new_sessions[i].session_data, DEFAULT_SESSION_DATA, MAX_SESSION_DATA_SIZE);
    }

    *array_size = new_size;
    return new_sessions;
}

int* create_offset_array(int *array_size, int new_size) {
    if (new_size < *array_size) return NULL; // No resizing needed

    int *new_offsets = realloc(*offsets, new_size * sizeof(int));
    if (!new_offsets) return NULL; // Allocation failed

    for (int i = *array_size; i < new_size; i++) {
        new_offsets[i] = rand(); // Initialize with random values
    }

    *array_size = new_size;
    return new_offsets;
}

Record* create_record_array(int size) {
    Record *records = malloc(size * sizeof(Record));
    if (!records) return NULL; // Allocation failed

    for (int i = 0; i < size; i++) {
        records[i].key = rand(); // Initialize with random values
    }

    return records;
}

void free_all_arrays(Session **sessions, int *session_size,
                      int **offsets, int *offset_size,
                      Record **records) {
    if (*sessions) free(*sessions);
    if (offsets) free(*offsets);
    if (*records) free(*records);

    *sessions = NULL;
    *offsets = NULL;
    *records = NULL;

    *session_size = 0;
    *offset_size = 0;
}
