typedef struct {
    size_t size;
    time_t creation_timestamp;
    uuid_t unique_id;
} metadata;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    metadata **metadata_array;
    size_t array_size;
} data_structure_manager;

data_structure_manager* create_data_structures(size_t size, int min_random, int max_random) {
    if (size == 0 || min_random > max_random) {
        return NULL; // Invalid input
    }

    data_structure_manager *manager = malloc(sizeof(data_structure_manager));
    if (!manager) {
        perror("Memory allocation failed for manager");
        return NULL;
    }

    manager->array_size = size;

    manager->offsets = malloc(size * sizeof(long));
    if (!manager->offsets) {
        perror("Memory allocation failed for offsets");
        free(manager);
        return NULL;
    }

    manager->keys = malloc(size * sizeof(int));
    if (!manager->keys) {
        perror("Memory allocation failed for keys");
        free(manager->offsets);
        free(manager);
        return NULL;
    }

    manager->records = malloc(size * sizeof(record));
    if (!manager->records) {
        perror("Memory allocation failed for records");
        free(manager->offsets);
        free(manager->keys);
        free(manager);
        return NULL;
    }

    manager->metadata_array = malloc(size * sizeof(metadata *));
    if (!manager->metadata_array) {
        perror("Memory allocation failed for metadata array");
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        free(manager);
        return NULL;
    }

    srand(time(NULL));
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    for (size_t i = 0; i < size; ++i) {
        manager->offsets[i] = i * 8; // Example offset calculation
        manager->keys[i] = rand() % (max_random - min_random + 1) + min_random;

        manager->records[i].value = random(); // Use cryptographically secure PRNG for value

        metadata *meta = malloc(sizeof(metadata));
        if (!meta) {
            perror("Memory allocation failed for metadata");
            free(manager->offsets);
            free(manager->keys);
            free(manager->records);
            for (size_t j = 0; j < i; ++j) {
                free(manager->metadata_array[j]);
            }
            free(manager->metadata_array);
            return NULL;
        }

        meta->size = sizeof(record);
        meta->creation_timestamp = ts.tv_sec + ts.tv_nsec / 1e9;
        uuid_generate(meta->unique_id);

        manager->metadata_array[i] = meta;
    }

    return manager;
}

void free_data_structures(data_structure_manager *manager) {
    for (size_t i = 0; i < manager->array_size; ++i) {
        free(manager->metadata_array[i]);
    }
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager->metadata_array);
    free(manager);
}

int main() {
    data_structure_manager *manager = create_data_structures(100, 1, 1000);
    if (manager) {
        // Use the manager
        free_data_structures(manager);
    }
    return 0;
}
