typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    double* timestamps;
    int* keys;
    double* statistics;
    record** records;
    size_t num_records;
} data_structure;

data_structure* create_data_structure(size_t num_records, int seed) {
    data_structure* ds = (data_structure*)malloc(sizeof(data_structure));
    if (!ds) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    ds->num_records = num_records;
    ds->offsets = (long*)malloc(num_records * sizeof(long));
    ds->timestamps = (double*)malloc(num_records * sizeof(double));
    ds->keys = (int*)malloc(num_records * sizeof(int));
    ds->statistics = (double*)malloc(num_records * sizeof(double));
    ds->records = (record**)malloc(num_records * sizeof(record*));

    if (!ds->offsets || !ds->timestamps || !ds->keys || !ds->statistics || !ds->records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(ds);
        return NULL;
    }

    srand(seed); // Initialize PRNG with seed for reproducibility

    for (size_t i = 0; i < num_records; ++i) {
        ds->offsets[i] = rand();
        ds->timestamps[i] = ((double)rand() / RAND_MAX) * 1e9;
        ds->keys[i] = rand() % 1000;
        ds->statistics[i] = (double)rand() / RAND_MAX;

        ds->records[i] = (record*)malloc(sizeof(record));
        if (!ds->records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            free(ds);
            for (size_t j = 0; j < i; ++j) {
                free(ds->records[j]);
            }
            return NULL;
        }

        ds->records[i]->value = rand() % (100 - (-100)) + (-100); // Random value in [-100, 100]
    }

    return ds;
}

void destroy_data_structure(data_structure* ds) {
    for (size_t i = 0; i < ds->num_records; ++i) {
        free(ds->records[i]);
    }
    free(ds->offsets);
    free(ds->timestamps);
    free(ds->keys);
    free(ds->statistics);
    free(ds->records);
    free(ds);
}
