typedef struct {
    long timestamp;
    char* description;
    double engagement_score;
} LogEntry;

LogEntry** create_log_entries(int size, long start_timestamp, long end_timestamp) {
    if (size <= 0 || start_timestamp >= end_timestamp) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    LogEntry** log_entries = (LogEntry**)malloc(size * sizeof(LogEntry*));
    if (!log_entries) {
        fprintf(stderr, "Memory allocation failed for log entries.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed PRNG for random descriptions

    for (int i = 0; i < size; ++i) {
        log_entries[i] = (LogEntry*)malloc(sizeof(LogEntry));
        if (!log_entries[i]) {
            fprintf(stderr, "Memory allocation failed for log entry %d.\n", i);
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(log_entries[j]->description);
                free(log_entries[j]);
            }
            free(log_entries);
            return NULL;
        }

        // Generate random timestamp within the specified range
        log_entries[i]->timestamp = start_timestamp + rand() % (end_timestamp - start_timestamp);

        // Allocate memory for description and generate a random value
        int desc_length = 10 + rand() % 20; // Random length between 10 and 30 characters
        log_entries[i]->description = (char*)malloc(desc_length * sizeof(char));
        if (!log_entries[i]->description) {
            fprintf(stderr, "Memory allocation failed for description of log entry %d.\n", i);
            // Free previously allocated memory
            for (int j = 0; j <= i; ++j) {
                free(log_entries[j]->description);
                free(log_entries[j]);
            }
            free(log_entries);
            return NULL;
        }

        // Fill description with random characters
        for (int j = 0; j < desc_length - 1; ++j) {
            log_entries[i]->description[j] = 'A' + rand() % 26;
        }
        log_entries[i]->description[desc_length - 1] = '\0';

        // Generate random engagement score within the range [0.0, 1.0]
        double eng_score = (double)rand() / RAND_MAX;
        log_entries[i]->engagement_score = eng_score;
    }

    return log_entries;
}

void free_log_entries(LogEntry** log_entries, int size) {
    if (!log_entries || size <= 0) {
        return;
    }

    for (int i = 0; i < size; ++i) {
        free(log_entries[i]->description);
        free(log_entries[i]);
    }
    free(log_entries);
}

void print_log_entries(LogEntry** log_entries, int size) {
    if (!log_entries || size <= 0) {
        return;
    }

    for (int i = 0; i < size; ++i) {
        printf("Timestamp: %ld, Description: %s, Engagement Score: %.2f\n",
               log_entries[i]->timestamp, log_entries[i]->description, log_entries[i]->engagement_score);
    }
}

int main() {
    int num_entries = 10;
    long start_time = 1633072800; // Example timestamp
    long end_time = 1633159200;

    LogEntry** log_entries = create_log_entries(num_entries, start_time, end_time);
    if (log_entries) {
        print_log_entries(log_entries, num_entries);
        free_log_entries(log_entries, num_entries);
    }

    return 0;
}
