// Function to initialize and allocate memory for the data processing module
void* init_data_processing_module(unsigned long num_records, size_t min_string_len, size_t max_string_len) {
    // Allocate memory for each array
    unsigned long *id_array = (unsigned long *)malloc(num_records * sizeof(unsigned long));
    double *value_array = (double *)malloc(num_records * sizeof(double));
    char **buffer_array = (char **)malloc(num_records * sizeof(char *));
    float *timestamp_array = (float *)malloc(num_records * sizeof(float));
    data_record *record_array = (data_record *)malloc(num_records * sizeof(data_record));

    // Initialize PRNG
    srand(time(NULL));

    if (!id_array || !value_array || !buffer_array || !timestamp_array || !record_array) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (unsigned long i = 0; i < num_records; i++) {
        // Initialize ID array
        id_array[i] = i;

        // Initialize value array
        value_array[i] = (double)i * 1.1;

        // Allocate memory for buffer and initialize with random ASCII characters
        buffer_array[i] = (char *)malloc(max_string_len + 1);
        if (!buffer_array[i]) {
            printf("Memory allocation failed for buffer %lu.\n", i);
            return NULL;
        }
        size_t string_len = min_string_len + rand() % (max_string_len - min_string_len + 1);
        char last_char = '\0';
        for (size_t j = 0; j < string_len; j++) {
            char new_char;
            do {
                new_char = '!' + rand() % 95;
            } while (new_char == last_char);
            buffer_array[i][j] = new_char;
            last_char = new_char;
        }
        buffer_array[i][string_len] = '\0';

        // Initialize timestamp array
        timestamp_array[i] = (float)i * 1.001;

        // Initialize record array
        record_array[i].identifier = i;
        strncpy(record_array[i].buffer, buffer_array[i], sizeof(record_array[i].buffer) - 1);
        record_array[i].value = value_array[i];
    }

    // Return pointers to all allocated arrays and the record structure array
    void **result = (void **)malloc(5 * sizeof(void *));
    result[0] = id_array;
    result[1] = value_array;
    result[2] = buffer_array;
    result[3] = timestamp_array;
    result[4] = record_array;

    return result;
}

int main() {
    unsigned long num_records = 5;
    size_t min_string_len = 5;
    size_t max_string_len = 10;

    void **module_arrays = init_data_processing_module(num_records, min_string_len, max_string_len);

    if (module_arrays != NULL) {
        // Use the allocated arrays here
        for (unsigned long i = 0; i < num_records; i++) {
            printf("ID: %lu, Value: %f, Buffer: %s\n", ((unsigned long *)module_arrays[0])[i], 
                   ((double *)module_arrays[1])[i], ((char **)module_arrays[2])[i]);
        }

        // Free allocated memory
        free(module_arrays[0]);
        free(module_arrays[1]);
        for (unsigned long i = 0; i < num_records; i++) {
            free(((char **)module_arrays[2])[i]);
        }
        free(module_arrays[2]);
        free(module_arrays[3]);
        free(module_arrays[4]);
        free(module_arrays);
    }

    return 0;
}
