#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    char username[100];
    char email[150];
    unsigned int unique_id;
} UserProfile;

// Function to generate a non-cryptographic pseudo-random number
unsigned int generate_unique_id() {
    static unsigned int seed = 0;
    if (seed == 0) {
        seed = time(NULL); // Seed the PRNG with the current time on the first call
    }
    return rand_r(&seed);
}

// Function to asynchronously initialize user profiles
void async_init_user_profile(UserProfile *profile, const char *username, const char *email) {
    strncpy(profile->username, username, sizeof(profile->username));
    strncpy(profile->email, email, sizeof(profile->email));
    profile->unique_id = generate_unique_id();
}

// Function to synchronously initialize user profiles
void sync_init_user_profile(UserProfile *profile, const char *username, const char *email) {
    async_init_user_profile(profile, username, email);
}

// Example usage of the function
int main() {
    UserProfile profiles[10];

    // Simulate asynchronous initialization for 5 profiles
    for (int i = 0; i < 5; i++) {
        async_init_user_profile(&profiles[i], "user", "email");
    }

    // Simulate synchronous initialization for the remaining 5 profiles
    for (int i = 5; i < 10; i++) {
        sync_init_user_profile(&profiles[i], "user", "email");
    }

    // Print out the user profiles to verify initialization
    for (int i = 0; i < 10; i++) {
        printf("Profile %d: Username=%s, Email=%s, Unique ID=%u\n",
               i, profiles[i].username, profiles[i].email, profiles[i].unique_id);
    }

    return 0;
}
