char** allocate_char_array(size_t size, size_t string_length) {
    char** array = (char**)malloc(size * sizeof(char*));
    for (size_t i = 0; i < size; ++i) {
        array[i] = (char*)malloc((string_length + 1) * sizeof(char));
    }
    return array;
}

config* allocate_config_array(size_t size, int min_id, int max_id) {
    config* array = (config*)malloc(size * sizeof(config));
    for (size_t i = 0; i < size; ++i) {
        if (!RAND_bytes((unsigned char*)&array[i].id, sizeof(int))) {
            // Handle error
        }
        array[i].id = array[i].id % (max_id - min_id + 1) + min_id;
        array[i].probability = (double)rand() / RAND_MAX; // Not cryptographically secure
        array[i].name = (char*)malloc(20 * sizeof(char)); // Assuming a max length of 19 characters plus null terminator
    }
    return array;
}

void free_all_memory(long* long_array, char** char_array, config* config_array, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(char_array[i]);
    }
    free(char_array);
    for (size_t i = 0; i < size; ++i) {
        free(config_array[i].name);
    }
    free(config_array);
    free(long_array);
}

// Example usage
