#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <openssl/rand.h>

typedef struct {
    int id;
} Session;

typedef struct {
    char name[100];
    char email[100];
    Session *session;
} User;

typedef struct {
    time_t timestamp;
    double amount;
    char description[256];
    User *user;
} Transaction;

Session* create_session() {
    Session *session = (Session*)malloc(sizeof(Session));
    if (!session) {
        perror("Failed to allocate memory for session");
        exit(EXIT_FAILURE);
    }
    if (!RAND_bytes((unsigned char*)&session->id, sizeof(session->id))) {
        fprintf(stderr, "Error generating random number\n");
        free(session);
        exit(EXIT_FAILURE);
    }
    return session;
}

User* create_user(const char *name, const char *email) {
    User *user = (User*)malloc(sizeof(User));
    if (!user) {
        perror("Failed to allocate memory for user");
        exit(EXIT_FAILURE);
    }
    snprintf(user->name, sizeof(user->name), "%s", name);
    snprintf(user->email, sizeof(user->email), "%s", email);
    user->session = create_session();
    return user;
}

Transaction* create_transaction(time_t timestamp, double amount, const char *description, User *user) {
    Transaction *transaction = (Transaction*)malloc(sizeof(Transaction));
    if (!transaction) {
        perror("Failed to allocate memory for transaction");
        exit(EXIT_FAILURE);
    }
    transaction->timestamp = timestamp;
    transaction->amount = amount;
    snprintf(transaction->description, sizeof(transaction->description), "%s", description);
    transaction->user = user;
    return transaction;
}

void free_session(Session *session) {
    if (session) {
        free(session);
    }
}

void free_user(User *user) {
    if (user) {
        free_session(user->session);
        free(user);
    }
}

void free_transaction(Transaction *transaction) {
    if (transaction) {
        free_user(transaction->user);
        free(transaction);
    }
}
