typedef struct DeviceConfig {
    int device_id;
} DeviceConfig;

typedef struct Event {
    time_t timestamp;
    char type[50];
    char description[256];
} Event;

typedef struct UserProfile {
    char name[100];
    char email[100];
    int device_id;
    Event* events;
    size_t event_count;
    size_t event_capacity;
} UserProfile;

DeviceConfig** create_device_configs(size_t count, size_t initial_capacity) {
    DeviceConfig** configs = memory_pool_alloc(sizeof(DeviceConfig*) * count);
    if (!configs) return NULL;

    for (size_t i = 0; i < count; ++i) {
        configs[i] = memory_pool_alloc(sizeof(DeviceConfig));
        if (!configs[i]) {
            // Handle allocation failure
            while (i > 0) {
                memory_pool_free(configs[--i]);
            }
            memory_pool_free(configs);
            return NULL;
        }

        if (RAND_bytes((unsigned char*)&configs[i]->device_id, sizeof(int)) != 1) {
            // Handle PRNG failure
            memory_pool_free(configs[i]);
            while (i > 0) {
                memory_pool_free(configs[--i]);
            }
            memory_pool_free(configs);
            return NULL;
        }
    }

    return configs;
}

UserProfile** create_user_profiles(size_t count, size_t initial_capacity) {
    UserProfile** profiles = memory_pool_alloc(sizeof(UserProfile*) * count);
    if (!profiles) return NULL;

    for (size_t i = 0; i < count; ++i) {
        profiles[i] = memory_pool_alloc(sizeof(UserProfile));
        if (!profiles[i]) {
            // Handle allocation failure
            while (i > 0) {
                memory_pool_free(profiles[--i]);
            }
            memory_pool_free(profiles);
            return NULL;
        }

        profiles[i]->event_count = 0;
        profiles[i]->event_capacity = initial_capacity;
        profiles[i]->events = memory_pool_alloc(sizeof(Event) * initial_capacity);
        if (!profiles[i]->events) {
            // Handle allocation failure
            memory_pool_free(profiles[i]);
            while (i > 0) {
                memory_pool_free(profiles[--i]);
            }
            memory_pool_free(profiles);
            return NULL;
        }
    }

    return profiles;
}

void free_device_configs(DeviceConfig** configs, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        memory_pool_free(configs[i]);
    }
    memory_pool_free(configs);
}

void free_user_profiles(UserProfile** profiles, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        memory_pool_free(profiles[i]->events);
        memory_pool_free(profiles[i]);
    }
    memory_pool_free(profiles);
}
