#define NUM_RECORDS 1000

typedef struct {
    int key;
} record;

record* initialize_records(int num_records, time_t seed) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    unsigned long long state = seed;

    for (int i = 0; i < num_records; i++) {
        pthread_mutex_lock(&mutex);
        // Custom PRNG: Linear Congruential Generator (LCG)
        state = (state * 1664525 + 1013904223) % UINT_MAX;
        records[i].key = (int)(state % 100); // Adjust range as needed
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);
    return records;
}

void free_records(record* records) {
    free(records);
}

// Example usage
int main() {
    time_t seed = time(NULL);
    record* my_records = initialize_records(NUM_RECORDS, seed);

    // Use my_records...

    free_records(my_records);
    return 0;
}
