    long *offsets;
    int *keys;
    Record **records;
    EventTimestamp *timestamps;
    size_t capacity;
    size_t count;
    Record *record_list_head;
} DataStructureManager;

DataStructureManager* create_data_structure_manager() {
    DataStructureManager *manager = (DataStructureManager*)malloc(sizeof(DataStructureManager));
    if (!manager) return NULL;

    manager->offsets = (long*)calloc(INITIAL_CAPACITY, sizeof(long));
    manager->keys = (int*)calloc(INITIAL_CAPACITY, sizeof(int));
    manager->records = (Record**)calloc(INITIAL_CAPACITY, sizeof(Record*));
    manager->timestamps = (EventTimestamp*)malloc(INITIAL_CAPACITY * sizeof(EventTimestamp));
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->record_list_head = NULL;

    if (!manager->offsets || !manager->keys || !manager->records || !manager->timestamps) {
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        free(manager->timestamps);
        free(manager);
        return NULL;
    }

    srand(time(0));
    for (size_t i = 0; i < INITIAL_CAPACITY; ++i) {
        manager->records[i] = (Record*)malloc(sizeof(Record));
        if (!manager->records[i]) {
            // Handle memory allocation failure
            clean_up_data_structure_manager(manager);
            return NULL;
        }
        manager->records[i]->value = rand() % 100; // Random value between 0 and 99
        manager->records[i]->next = manager->record_list_head;
        manager->record_list_head = manager->records[i];
    }

    return manager;
}

void clean_up_data_structure_manager(DataStructureManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        Record *current = manager->records[i];
        while (current) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }
    free(manager->offsets);
    free(manager->keys);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i]);
    }
    free(manager->timestamps);
    free(manager);
}
