#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} Record;

void* fetch_data(void* arg) {
    // Simulate data fetching from an external source
    static int count = 0;
    if (count >= MAX_RECORDS) return NULL;
    Record* record = malloc(sizeof(Record));
    if (!record) return NULL;
    record->value = rand() % 100; // Non-cryptographically secure PRNG for demonstration
    count++;
    return record;
}

void process_data(Record** records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        if (!records[i]) break; // Early exit on NULL pointer
        printf("Processing record with value: %d\n", records[i]->value);
        free(records[i]);
    }
}

void* worker_thread(void* arg) {
    Record** local_records = malloc(MAX_RECORDS * sizeof(Record*));
    if (!local_records) return NULL;

    int num_records = 0;
    while ((local_records[num_records] = fetch_data(NULL)) != NULL && num_records < MAX_RECORDS) {
        num_records++;
    }

    process_data(local_records, num_records);
    free(local_records);
    return NULL;
}

void run_thread_pool(int thread_count) {
    pthread_t* threads = malloc(thread_count * sizeof(pthread_t));
    if (!threads) return;

    for (int i = 0; i < thread_count; i++) {
        if (pthread_create(&threads[i], NULL, worker_thread, NULL) != 0) {
            perror("Failed to create thread");
        }
    }

    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
}

int main() {
    srand(time(NULL)); // Seed PRNG
    run_thread_pool(4); // Example with 4 threads

    return 0;
}
```

