#define MAX_KEY_LENGTH 256
#define VALUE_SIZE 4096

typedef struct {
    uint64_t unique_id;
    char key[MAX_KEY_LENGTH];
    char value[VALUE_SIZE];
    time_t last_modified;
} ConfigSetting;

typedef struct {
    size_t allocated_count;
    size_t max_count;
    ConfigSetting *settings;
} ConfigDatabase;

ConfigDatabase* config_db_init(size_t initial_size) {
    ConfigDatabase *db = malloc(sizeof(ConfigDatabase));
    if (!db) return NULL;

    db->allocated_count = 0;
    db->max_count = initial_size;
    db->settings = calloc(initial_size, sizeof(ConfigSetting));
    if (!db->settings) {
        free(db);
        return NULL;
    }

    srand(time(NULL)); // Initialize PRNG seed
    return db;
}

void config_db_add(ConfigDatabase *db, const char *key, const char *value) {
    if (db->allocated_count == db->max_count) {
        db->max_count *= 2;
        ConfigSetting *new_settings = realloc(db->settings, db->max_count * sizeof(ConfigSetting));
        if (!new_settings) return; // Handle reallocation failure
        db->settings = new_settings;
    }

    ConfigSetting *new_setting = &db->settings[db->allocated_count];
    new_setting->unique_id = (uint64_t)(rand() << 32 | rand()); // Generate unique ID using PRNG
    strncpy(new_setting->key, key, MAX_KEY_LENGTH - 1);
    strncpy(new_setting->value, value, VALUE_SIZE - 1);
    new_setting->last_modified = time(NULL);

    db->allocated_count++;
}

void config_db_log(ConfigDatabase *db) {
    printf("Config Database Log:\n");
    printf("Allocated Count: %zu\n", db->allocated_count);
    for (size_t i = 0; i < db->allocated_count; i++) {
        ConfigSetting *setting = &db->settings[i];
        printf("ID: %llu, Key: %s, Value: %.*s, Last Modified: %ld\n",
               setting->unique_id, setting->key, VALUE_SIZE - 1, setting->value, setting->last_modified);
    }
}

void config_db_free(ConfigDatabase *db) {
    free(db->settings);
    free(db);
}
