#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SESSIONS 1024

typedef struct {
    int session_id;
    time_t timestamp;
    int active;
} Session;

Session *session_pool = NULL;
int pool_size = 0;
int current_count = 0;

void init_session_pool(int initial_size) {
    if (initial_size > MAX_SESSIONS) {
        fprintf(stderr, "Initial size exceeds maximum allowed.\n");
        exit(EXIT_FAILURE);
    }
    session_pool = (Session *)malloc(initial_size * sizeof(Session));
    if (!session_pool) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    pool_size = initial_size;
    current_count = 0;
}

int create_session() {
    if (current_count == pool_size) {
        // Resize the pool
        Session *new_pool = (Session *)realloc(session_pool, pool_size * 2 * sizeof(Session));
        if (!new_pool) {
            perror("Memory reallocation failed");
            return -1;
        }
        session_pool = new_pool;
        pool_size *= 2;
    }

    int session_id = rand();
    // Ensure uniqueness
    while (is_session_id_taken(session_id)) {
        session_id = rand();
    }

    time_t timestamp = time(NULL);
    int active = 1;

    session_pool[current_count].session_id = session_id;
    session_pool[current_count].timestamp = timestamp;
    session_pool[current_count].active = active;

    current_count++;
    return session_id;
}

int is_session_id_taken(int id) {
    for (int i = 0; i < current_count; i++) {
        if (session_pool[i].session_id == id) {
            return 1;
        }
    }
    return 0;
}

void delete_session(int session_id) {
    for (int i = 0; i < current_count; i++) {
        if (session_pool[i].session_id == session_id) {
            // Shift the remaining sessions to fill the gap
            for (int j = i; j < current_count - 1; j++) {
                session_pool[j] = session_pool[j + 1];
            }
            current_count--;
            return;
        }
    }
}

void log_session_event(int session_id, const char *event) {
    printf("Session %d: %s\n", session_id, event);
}
```

