#include <time.h>

#define MAX_TRANSACTIONS 10000
#define PRNG_SEED 42

typedef struct {
    int id;
    time_t timestamp;
    double amount;
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    int count;
    int reset_threshold;
    int *reset_counts;
    int total_resets;
} TransactionPool;

void init_transaction_pool(TransactionPool *pool, int num_ids) {
    pool->count = 0;
    pool->reset_threshold = 100; // Example threshold
    pool->reset_counts = (int *)calloc(num_ids, sizeof(int));
    pool->total_resets = 0;
}

void generate_random_amount(double *amount, double min, double max) {
    *amount = ((double)rand() / RAND_MAX) * (max - min) + min;
}

void add_transaction(TransactionPool *pool, int id, time_t timestamp, double amount) {
    if (pool->count >= MAX_TRANSACTIONS) {
        printf("Transaction pool full!\n");
        return;
    }
    Transaction new_tx = {id, timestamp, amount};
    pool->transactions[pool->count++] = new_tx;
}

void reset_transaction_count(TransactionPool *pool, int id) {
    if (id < 0 || id >= pool->reset_counts) {
        printf("Invalid transaction ID!\n");
        return;
    }
    if (++pool->reset_counts[id] >= pool->reset_threshold) {
        pool->total_resets++;
        pool->reset_counts[id] = 0; // Reset the counter
    }
}

void cleanup_transaction_pool(TransactionPool *pool) {
    free(pool->reset_counts);
}

int main() {
    srand(PRNG_SEED);
    time_t timestamp;
    TransactionPool pool;

    init_transaction_pool(&pool, 10);

    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        generate_random_amount(&timestamp, 100.0, 500.0); // Example range
        add_transaction(&pool, i % 10, timestamp, amount);
        reset_transaction_count(&pool, i % 10);
    }

    cleanup_transaction_pool(&pool);

    return 0;
}
