#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000000
#define MAX_KEYS 100

typedef struct {
    char status;
    int value;
} record;

void init_prng() {
    srand(time(NULL));
}

int prng(int min, int max) {
    return min + rand() % (max - min + 1);
}

record* create_record_pool(long offset[], int keys[], int num_records, int max_keys_per_key) {
    record* pool = (record*)malloc(num_records * sizeof(record));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for record pool\n");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_records; i++) {
        pthread_mutex_lock(&lock);
        int key = keys[i % max_keys_per_key];
        if (++key > max_keys_per_key) {
            key = 1;
        }
        keys[i % max_keys_per_key] = key;
        pool[i].status = 'A'; // Active
        pool[i].value = prng(0, 100); // Random value between 0 and 100
        pthread_mutex_unlock(&lock);
    }

    return pool;
}

void export_records(record* pool, int num_records, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    fprintf(file, "[\n");
    for (int i = 0; i < num_records; i++) {
        fprintf(file, "{\"status\":\"%c\",\"value\":%d}", pool[i].status, pool[i].value);
        if (i != num_records - 1) {
            fprintf(file, ",\n");
        }
    }
    fprintf(file, "\n]\n");

    fclose(file);
}

int main() {
    long offsets[MAX_RECORDS];
    int keys[MAX_KEYS] = {1, 2, 3, 4, 5}; // Example keys

    init_prng();
    record* pool = create_record_pool(offsets, keys, MAX_RECORDS, MAX_KEYS);

    if (pool) {
        export_records(pool, MAX_RECORDS, "records.json");
        free(pool);
    }

    return 0;
}
