typedef struct {
    int value;
} record;

record* initialize_records(int size, int min_val, int max_val, FILE* log_file) {
    if (size <= 0 || min_val > max_val) {
        fprintf(log_file, "Error: Invalid input values.\n");
        return NULL;
    }

    record* records = (record*)malloc(size * sizeof(record));
    if (records == NULL) {
        fprintf(log_file, "Error: Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }

    fprintf(log_file, "Records initialized successfully.\n");
    return records;
}

void free_records(record* records, int size, FILE* log_file) {
    if (records != NULL && size > 0) {
        free(records);
        fprintf(log_file, "Records freed successfully.\n");
    } else {
        fprintf(log_file, "Error: Invalid record pointer or size.\n");
    }
}

int main() {
    int array_size = 10;
    int min_value = 1;
    int max_value = 100;
    FILE* log_file = fopen("log.txt", "w");

    if (log_file == NULL) {
        printf("Error: Unable to open log file.\n");
        return EXIT_FAILURE;
    }

    record* my_records = initialize_records(array_size, min_value, max_value, log_file);
    if (my_records != NULL) {
        for (int i = 0; i < array_size; ++i) {
            printf("Record %d: %d\n", i, my_records[i].value);
        }
        free_records(my_records, array_size, log_file);
    }

    fclose(log_file);
    return EXIT_SUCCESS;
}
