        (*records)[i] = (record*)malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            free(*offsets);
            free(*keys);
            for (int j = 0; j < i; j++) {
                free((*records)[j]);
            }
            free(*records);
            return "Memory allocation for record failed";
