        RAND_bytes((unsigned char*)&((*records)[i]->value), sizeof(int));
    }

    return NULL;
}

void resize_and_initialize(long** offsets, int** keys, record*** records, long* offset_size, int* key_size, int* record_count, long new_offset_size, int new_key_size, int new_record_count) {
    if (new_offset_size > *offset_size) {
        *offsets = (long*)realloc(*offsets, new_offset_size * sizeof(long));
        if (*offsets == NULL) {
            return;
        }
        *offset_size = new_offset_size;
    }

