        *keys = (int*)realloc(*keys, new_key_size * sizeof(int));
        if (*keys == NULL) {
            free(*offsets);
            return;
        }
        *key_size = new_key_size;
    }

    int old_record_count = *record_count;
    *records = (record**)realloc(*records, new_record_count * sizeof(record*));
    if (*records == NULL) {
        for (int i = 0; i < old_record_count; i++) {
            free((*records)[i]);
        }
        free(*offsets);
        free(*keys);
        return;
    }

    for (int i = old_record_count; i < new_record_count; i++) {
        (*records)[i] = (record*)malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            for (int j = 0; j <= i; j++) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            *records = realloc(*records, old_record_count * sizeof(record*));
            return;
        }
        RAND_bytes((unsigned char*)&((*records)[i]->value), sizeof(int));
    }

    *record_count = new_record_count;
}
