#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    int value;
} record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

record* create_records(int initial_capacity) {
    record* records = (record*)safe_malloc(initial_capacity * sizeof(record));
    for (int i = 0; i < initial_capacity; i++) {
        records[i].value = rand() % 1000; // Random value between 0 and 999
    }
    return records;
}

void resize_records(record** records, int* capacity) {
    *capacity *= GROWTH_FACTOR;
    record* new_records = (record*)safe_malloc(*capacity * sizeof(record));
    for (int i = 0; i < *capacity / 2; i++) {
        new_records[i].value = (*records)[i].value;
    }
    free(*records);
    *records = new_records;
}

void manage_memory() {
    srand(time(NULL));
    int capacity = INITIAL_CAPACITY;
    record* records = create_records(capacity);

    // Example usage
    for (int i = 0; i < capacity; i++) {
        printf("Record %d: %d\n", i, records[i].value);
    }

    resize_records(&records, &capacity);
    printf("Records resized to capacity %d\n", capacity);

    free(records);
}

int main() {
    manage_memory();
    return 0;
}
```

