#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define GROWTH_FACTOR 2
#define INITIAL_CAPACITY 10
#define MIN_SIZE 0

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    unsigned long seed;
} DynamicArray;

void init_dynamic_array(DynamicArray* array, unsigned long seed) {
    array->records = malloc(INITIAL_CAPACITY * sizeof(Record));
    if (array->records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    array->seed = seed;
}

void resize_dynamic_array(DynamicArray* array) {
    size_t new_capacity = array->capacity * GROWTH_FACTOR;
    Record* new_records = realloc(array->records, new_capacity * sizeof(Record));
    if (new_records == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->records = new_records;
    array->capacity = new_capacity;
}

void add_record(DynamicArray* array, long offset, int key) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        resize_dynamic_array(array);
    }
    array->records[array->size].offset = offset;
    array->records[array->size].key = key;
    array->size++;
    pthread_mutex_unlock(&array->lock);
}

void* data_ingestion_thread(void* arg) {
    DynamicArray* array = (DynamicArray*)arg;
    unsigned long seed = time(NULL);
    srand(seed);

    while (1) {
        add_record(array, rand() % 1000000, rand() % 1000);
        usleep(100); // Simulate data ingestion rate
    }

    return NULL;
}

int main() {
    DynamicArray array;
    init_dynamic_array(&array, time(NULL));

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, data_ingestion_thread, &array) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_join(thread_id, NULL);

    free(array.records);
    pthread_mutex_destroy(&array.lock);

    return 0;
}
