#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define CSPRNG(seed) ((seed * 214013 + 2531011) >> 16)

typedef struct {
    int size;
    int capacity;
} DynamicArray;

typedef struct {
    char* token;
} SessionID;

typedef struct {
    char name[128];
    char email[128];
    SessionID session;
} UserProfile;

typedef struct {
    time_t timestamp;
    double amount;
    char description[256];
    UserProfile* user;
} TransactionRecord;

DynamicArray* init_dynamic_array(int initial_capacity) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed for DynamicArray.\n");
        exit(1);
    }
    array->size = 0;
    array->capacity = initial_capacity > 0 ? initial_capacity : 16;
    array->data = malloc(array->capacity * sizeof(void*));
    if (array->data == NULL) {
        fprintf(stderr, "Memory allocation failed for DynamicArray data.\n");
        free(array);
        exit(1);
    }
    return array;
}

void dynamic_array_add(DynamicArray* array, void* item) {
    if (array->size >= array->capacity) {
        array->capacity *= 2;
        array->data = realloc(array->data, array->capacity * sizeof(void*));
        if (array->data == NULL) {
            fprintf(stderr, "Memory reallocation failed for DynamicArray data.\n");
            exit(1);
        }
    }
    array->data[array->size++] = item;
}

void free_dynamic_array(DynamicArray* array) {
    free(array->data);
    free(array);
}

SessionID generate_session_id() {
    SessionID id;
    unsigned seed = time(NULL);
    for (int i = 0; i < sizeof(id.token); i++) {
        id.token[i] = CSPRNG(seed++);
    }
    return id;
}

UserProfile* create_user_profile(const char* name, const char* email) {
    UserProfile* user = malloc(sizeof(UserProfile));
    if (user == NULL) {
        fprintf(stderr, "Memory allocation failed for UserProfile.\n");
        exit(1);
    }
    strncpy(user->name, name, sizeof(user->name));
    strncpy(user->email, email, sizeof(user->email));
    user->session = generate_session_id();
    return user;
}

TransactionRecord* create_transaction(time_t timestamp, double amount, const char* description, UserProfile* user) {
    TransactionRecord* transaction = malloc(sizeof(TransactionRecord));
    if (transaction == NULL) {
        fprintf(stderr, "Memory allocation failed for TransactionRecord.\n");
        exit(1);
    }
    transaction->timestamp = timestamp;
    transaction->amount = amount;
    strncpy(transaction->description, description, sizeof(transaction->description));
    transaction->user = user;
    return transaction;
}

void free_user_profile(UserProfile* user) {
    free(user);
}

void free_transaction_record(TransactionRecord* transaction) {
    free(transaction);
}
