#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

typedef struct Node {
    int identifier;
    int timestamp;
    Record *record;
    struct Node *left, *right;
} Node;

typedef struct HashTable {
    int size;
    int count;
    struct Node **buckets;
} HashTable;

Node* create_node(int identifier, int timestamp) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->identifier = identifier;
    new_node->timestamp = timestamp;
    new_node->record = (Record*)malloc(sizeof(Record));
    if (!new_node->record) {
        free(new_node);
        return NULL;
    }
    new_node->record->value = rand();
    new_node->left = new_node->right = NULL;
    return new_node;
}

Node* insert_bst(Node *root, int identifier, int timestamp) {
    if (!root) return create_node(identifier, timestamp);
    if (identifier < root->identifier)
        root->left = insert_bst(root->left, identifier, timestamp);
    else
        root->right = insert_bst(root->right, identifier, timestamp);
    return root;
}

HashTable* create_hash_table(int size) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;
    table->size = size;
    table->count = 0;
    table->buckets = (Node**)calloc(size, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    return table;
}

unsigned int hash_function(int identifier, int size) {
    return abs(identifier) % size;
}

void insert_hash_table(HashTable *table, int identifier, int timestamp) {
    unsigned int index = hash_function(identifier, table->size);
    Node *new_node = create_node(identifier, timestamp);
    if (!new_node) return;

    if (table->buckets[index]) {
        new_node->next = table->buckets[index];
    }
    table->buckets[index] = new_node;
    table->count++;
}

Node* search_hash_table(HashTable *table, int identifier) {
    unsigned int index = hash_function(identifier, table->size);
    Node *current = table->buckets[index];
    while (current) {
        if (current->identifier == identifier)
            return current;
        current = current->next;
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    long *offsets = (long*)malloc(1000 * sizeof(long));
    int *identifiers = (int*)malloc(1000 * sizeof(int));
    int *timestamps = (int*)malloc(1000 * sizeof(int));
    Node *root = NULL;
    HashTable *table = create_hash_table(1000);

    if (!offsets || !identifiers || !timestamps || !root || !table) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    for (int i = 0; i < 1000; i++) {
        offsets[i] = rand() % 1000000L;
        identifiers[i] = rand();
        timestamps[i] = rand();
        root = insert_bst(root, identifiers[i], timestamps[i]);
        insert_hash_table(table, identifiers[i], timestamps[i]);
    }

    // Free allocated memory
    free(offsets);
    free(identifiers);
    free(timestamps);
    Node *node;
    while (table->count > 0) {
        node = table->buckets[0];
        table->buckets[0] = node->next;
        free(node->record);
        free(node);
        table->count--;
    }
    free(table->buckets);
    free(table);

    return 0;
}
