    int* keys = safe_malloc(size * sizeof(int));
    Record** records = safe_malloc(size * sizeof(Record*));

    for (size_t i = 0; i < size; ++i) {
        records[i] = (Record*)safe_malloc(sizeof(Record));
    }

    initialize_records(records, size);

