#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 100000

typedef struct {
    int value;
} Record;

unsigned long xorshift64star() {
    static unsigned long x = time(NULL);
    x ^= x >> 12;
    x ^= x << 25;
    x ^= x >> 27;
    return x * 2685890624ULL;
}

int is_unique(Record* records, int size, int value) {
    for (int i = 0; i < size; ++i) {
        if (records[i].value == value) {
            return 0;
        }
    }
    return 1;
}

void fill_records_with_random_values(Record* records, int count, int range_min, int range_max) {
    if (range_min >= range_max || count > MAX_RECORDS) {
        fprintf(stderr, "Invalid range or record count.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < count; ++i) {
        unsigned long value;
        do {
            value = xorshift64star() % (range_max - range_min + 1) + range_min;
        } while (!is_unique(records, i, value));
        records[i].value = value;
    }
}

int main() {
    int offset_count = 100;
    int key_count = 50;

    long* offsets = (long*)calloc(offset_count, sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        exit(EXIT_FAILURE);
