        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys.\n");
        exit(EXIT_FAILURE);
    }

    Record* records = (Record*)calloc(count, sizeof(Record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed for records.\n");
        exit(EXIT_FAILURE);
    }

    fill_records_with_random_values(records, key_count, 1, 1000);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
