size_t record_count = 0;

void free_arrays() {
    if (offsets) {
        free(offsets);
        offsets = NULL;
    }
    if (keys) {
        free(keys);
        keys = NULL;
    }
    if (records) {
        for (size_t i = 0; i < record_count; i++) {
            free(records[i]);
        }
        free(records);
        records = NULL;
    }
}

void load_arrays_from_file(const char* filename, long** offsets, int** keys, record*** records, size_t* offset_count, size_t* key_count, size_t* record_count) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        *offsets = (long*)malloc(1 * sizeof(long));
        *keys = (int*)malloc(1 * sizeof(int));
        *records = (record**)malloc(1 * sizeof(record*));
        (*offsets)[0] = 0;
        (*keys)[0] = 0;
        (*records)[0] = (record*)malloc(sizeof(record));
        (*records)[0]->value = 42; // Default value
        *offset_count = 1;
        *key_count = 1;
        *record_count = 1;
        return;
    }

    size_t capacity = 16;
    *offsets = (long*)malloc(capacity * sizeof(long));
    *keys = (int*)malloc(capacity * sizeof(int));
    *records = (record**)malloc(capacity * sizeof(record*));

    long offset;
    int key;
    while (fscanf(file, "%ld %d", &offset, &key) == 2) {
        if (*record_count >= capacity) {
            capacity *= 2;
            *offsets = (long*)realloc(*offsets, capacity * sizeof(long));
            *keys = (int*)realloc(*keys, capacity * sizeof(int));
            *records = (record**)realloc(*records, capacity * sizeof(record*));
        }
        (*offsets)[*offset_count] = offset;
        (*keys)[*key_count] = key;
        (*records)[*record_count] = (record*)malloc(sizeof(record));
        (*records)[*record_count]->value = rand() % 100; // Random value for demonstration
        *offset_count += 1;
        *key_count += 1;
    }

    fclose(file);
}

void load_dependent_files(const char* dependencies_filename) {
    FILE* file = fopen(dependencies_filename, "r");
    if (!file) return;

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        buffer[strcspn(buffer, "\n")] = 0; // Remove newline character
        load_arrays_from_file(buffer, &offsets, &keys, &records, &offset_count, &key_count, &record_count);
    }

    fclose(file);
}

record* initialize_records(size_t size) {
    record* records = (record*)malloc(size * sizeof(record));
    for (size_t i = 0; i < size; i++) {
        records[i].value = rand() % 100; // Random value for demonstration
    }
    return records;
}

int main() {
    load_arrays_from_file("input.txt", &offsets, &keys, &records, &offset_count, &key_count, &record_count);
    load_dependent_files("dependencies.txt");

    record* final_records = initialize_records(record_count);

    // Free allocated memory
    free_arrays();
    free(final_records);

    return 0;
}
