    large_integers = (long*)malloc(size * sizeof(long));
    unique_ids = (int*)malloc(size * sizeof(int));
    records = (Record*)malloc(size * sizeof(Record));

    if (!large_integers || !unique_ids || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void init_prng() {
    srand(time(NULL)); // Seed the PRNG with the current time
}

long generate_large_integer(long min, long max) {
    return (rand() % (max - min + 1)) + min;
}

int generate_unique_id(int last_id) {
    int id = rand() % MAX_INT; // Simplified for demonstration
    while (id == last_id || find_id_in_array(unique_ids, last_id, id)) {
        id = rand() % MAX_INT;
    }
    return id;
}

void initialize_record(Record* record) {
    record->timestamp = time(NULL);
    record->large_integer = generate_large_integer(1000, 10000);
}

