    for (size_t i = 0; i < size; ++i) {
        records[i].timestamp = time(NULL);
        records[i].large_integer = generate_large_integer(1, MAX_INT);
        unique_ids[i] = generate_unique_id(last_id);
        last_id = unique_ids[i];
    }

    export_data_to_file("data.bin", size);

    free(large_integers);
    free(unique_ids);
    free(records);

    return 0;
}
