#define MAX_MEMORY 1024 * 1024 // 1 MB

typedef struct {
    int value;
} record;

unsigned long xorshift32(unsigned long *state) {
    unsigned long x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return *state = x;
}

void generate_records(int offset_size, int key_size, int value_range_start, int value_range_end) {
    if (offset_size + key_size > MAX_MEMORY / sizeof(int)) {
        fprintf(stderr, "Error: Requested size exceeds the memory limit.\n");
        return;
    }

    unsigned long state = time(NULL); // Seed for PRNG
    record *records = (record *)malloc(sizeof(record) * offset_size);
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    for (int i = 0; i < offset_size; i++) {
        records[i].value = xorshift32(&state) % (value_range_end - value_range_start + 1) + value_range_start;
        if (records[i].value < value_range_start || records[i].value > value_range_end) {
            fprintf(stderr, "Error: Generated value out of range. Please adjust input parameters.\n");
            free(records);
            return;
        }
    }

    // Further processing with records...

    free(records); // Cleanup
}

int main() {
    int offset_size, key_size, value_range_start, value_range_end;

    printf("Enter the size for offset array: ");
    scanf("%d", &offset_size);

    printf("Enter the size for key array: ");
    scanf("%d", &key_size);

    printf("Enter the start of value range: ");
    scanf("%d", &value_range_start);

    printf("Enter the end of value range: ");
    scanf("%d", &value_range_end);

    generate_records(offset_size, key_size, value_range_start, value_range_end);

    return 0;
}
