        configs[i].probability = (double)rand() / RAND_MAX * 0.5;
        configs[i].config_name = "Config1";
    }

    // Log memory allocation details
    time_t end_time = time(NULL);
    printf("Memory allocation successful\n");
    printf("Start Time: %s", ctime(&start_time));
    printf("End Time: %s", ctime(&end_time));
    printf("Total Memory Used: %zu bytes\n", 
           (initial_size * sizeof(order) + initial_size * sizeof(client) +
            initial_size * sizeof(market) + initial_size * sizeof(config) +
            max_size * sizeof(long) + max_size * sizeof(int) +
            initial_size * sizeof(record)));

    // Cleanup
    free(orders);
    free(clients);
    free(markets);
    free(configs);
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    manage_memory(100, 200);
    return 0;
