    long timestamp;
    Record* record;
    struct BSTNode* left, * right;
} BSTNode;

long* allocateLongArray(size_t size) {
    return (long*)malloc(size * sizeof(long));
}

int* allocateIntArray(size_t size) {
    return (int*)malloc(size * sizeof(int));
}

Record** allocateRecordArray(size_t size) {
    Record** records = (Record**)malloc(size * sizeof(Record*));
    for (size_t i = 0; i < size; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
    }
    return records;
}

HashNode* createHashNode(const char* key, long timestamp) {
    HashNode* node = (HashNode*)malloc(sizeof(HashNode));
    strcpy(node->key, key);
    node->timestamp = timestamp;
    node->next = NULL;
    return node;
}

BSTNode* createBSTNode(char* identifier, Record* record) {
    BSTNode* node = (BSTNode*)malloc(sizeof(BSTNode));
    strcpy(node->identifier, identifier);
    node->record = record;
    node->left = node->right = NULL;
    return node;
}

void populateRandomRecords(int* intArray, Record** recordArray, size_t size) {
    srand(time(0)); // Seed the random number generator
    for (size_t i = 0; i < size; ++i) {
        intArray[i] = rand() % 1000; // Random int between 0 and 999
        recordArray[i]->value = intArray[i];
        strcpy(recordArray[i]->id, generateRandomString(16));
    }
}

char* generateRandomString(size_t length) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char* str = (char*)malloc(length + 1);
    for (size_t i = 0; i < length; ++i) {
        str[i] = charset[rand() % sizeof(charset)];
    }
    str[length] = '\0';
    return str;
}

HashNode** initializeHashTable(size_t size) {
    HashNode** hashTable = (HashNode**)calloc(size, sizeof(HashNode*));
    return hashTable;
}

BSTNode* insertIntoBST(BSTNode* root, char* identifier, Record* record) {
    if (root == NULL) return createBSTNode(identifier, record);
    if (strcmp(identifier, root->identifier) < 0)
        root->left = insertIntoBST(root->left, identifier, record);
    else
        root->right = insertIntoBST(root->right, identifier, record);
    return root;
}

void freeRecordArray(Record** array, size_t size) {
    for (size_t i = 0; i < size; ++i)
        free(array[i]);
    free(array);
}

// Additional functions to handle hash table and BST operations

int main() {
    // Example usage
    const size_t size = 1000;
    long* offsets = allocateLongArray(size);
    int* keys = allocateIntArray(size);
    Record** records = allocateRecordArray(size);

    populateRandomRecords(keys, records, size);

    HashNode** hashTable = initializeHashTable(128);

    BSTNode* bstRoot = NULL;

    for (size_t i = 0; i < size; ++i) {
        hashTable[keys[i] % 128] = insertIntoBST(hashTable[keys[i] % 128], records[i]->id, records[i]);
        bstRoot = insertIntoBST(bstRoot, records[i]->id, records[i]);
    }

    // Free allocated memory
    freeRecordArray(records, size);
    for (size_t i = 0; i < 128; ++i) {
        HashNode* current = hashTable[i];
        while (current != NULL) {
            HashNode* next = current->next;
            free(current);
            current = next;
        }
    }
    free(hashTable);

    return 0;
}
```

