#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define RECORD_COUNT 1000

typedef struct {
    long offset;
} Offset;

typedef struct {
    int key;
} Key;

typedef struct {
    int value;
} Record;

typedef struct {
    time_t timestamp;
    int key;
    int random_value;
} Log;

int generate_random_number(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void initialize_data_structures(Offset** offsets, Key** keys, Record** records, Log** logs) {
    *offsets = (Offset*)malloc(RECORD_COUNT * sizeof(Offset));
    *keys = (Key*)malloc(RECORD_COUNT * sizeof(Key));
    *records = (Record*)malloc(RECORD_COUNT * sizeof(Record));
    *logs = (Log*)malloc(RECORD_COUNT * sizeof(Log));

    if (*offsets == NULL || *keys == NULL || *records == NULL || *logs == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (int i = 0; i < RECORD_COUNT; ++i) {
        (*records)[i].value = generate_random_number(1, 1000);

        while (!check_uniqueness(*records, i)) {
            (*records)[i].value = generate_random_number(1, 1000);
        }

        (*keys)[i].key = i; // Simple key initialization
        (*offsets)[i].offset = i * sizeof(Record); // Simple offset calculation

        time_t current_time;
        time(&current_time);

        (*logs)[i].timestamp = current_time;
        (*logs)[i].key = i;
        (*logs)[i].random_value = (*records)[i].value;

        printf("Initialized record %d with value %d\n", i, (*records)[i].value);
    }
}

int check_uniqueness(Record* records, int index) {
    for (int i = 0; i < index; ++i) {
        if (records[i].value == records[index].value) {
            return 0;
        }
    }
    return 1;
}

void free_memory(Offset** offsets, Key** keys, Record** records, Log** logs) {
    free(*offsets);
    *offsets = NULL;

    free(*keys);
    *keys = NULL;

    free(*records);
    *records = NULL;

    free(*logs);
    *logs = NULL;
}

int main() {
    Offset* offsets = NULL;
    Key* keys = NULL;
    Record* records = NULL;
    Log* logs = NULL;

    initialize_data_structures(&offsets, &keys, &records, &logs);

    // Use the initialized data structures...

    free_memory(&offsets, &keys, &records, &logs);

    return 0;
}
