#define CSPRNG(seed) ((seed) = (seed) * 1103515245 + 12345)

typedef struct {
    time_t timestamp;
    int value;
    char* event_description;
} record;

typedef struct {
    double probability;
    char* config_name;
    int timeout_duration;
    short unique_id;
} config;

record* init_records(long initial_size) {
    record* records = malloc(initial_size * sizeof(record));
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        return NULL;
    }
    time_t seed = time(NULL);
    for (long i = 0; i < initial_size; i++) {
        records[i].timestamp = time(NULL);
        records[i].value = rand_r(&seed) % 1000; // Pseudo-random value between 0 and 999
        records[i].event_description = "Event";
    }
    return records;
}

config* init_configs(long initial_size, short* unique_ids) {
    config* configs = malloc(initial_size * sizeof(config));
    if (configs == NULL) {
        perror("Failed to allocate memory for configs");
        return NULL;
    }
    for (long i = 0; i < initial_size; i++) {
        configs[i].probability = ((double)(rand_r(&unique_ids[i])) / RAND_MAX);
        configs[i].config_name = "Config";
        configs[i].timeout_duration = rand_r(&unique_ids[i]) % 3600; // Timeout between 0 and 3600 seconds
        configs[i].unique_id = unique_ids[i];
    }
    return configs;
}

int main() {
    srand(time(NULL));
    long initial_size = 1024;
    short* unique_ids = malloc(initial_size * sizeof(short));
    if (unique_ids == NULL) {
        perror("Failed to allocate memory for unique IDs");
        return 1;
    }
    CSPRNG(time(NULL));
    for (long i = 0; i < initial_size; i++) {
        unique_ids[i] = CSPRNG(rand());
    }

    record* records = init_records(initial_size);
    config* configs = init_configs(initial_size, unique_ids);

    if (records != NULL && configs != NULL) {
        printf("Initialization successful.\n");
        // Use the arrays as needed
        free(records);
        free(configs);
    } else {
        printf("Initialization failed.\n");
    }

    free(unique_ids);
    return 0;
}
