typedef struct {
    unsigned long id;
    time_t expiration;
    int config_flag;
} SessionData;

SessionData* allocate_sessions(int num_sessions) {
    if (num_sessions <= 0) {
        return NULL; // Invalid input
    }

    SessionData *sessions = malloc(num_sessions * sizeof(SessionData));
    if (!sessions) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_sessions; ++i) {
        sessions[i].id = generate_unique_session_id();
        sessions[i].expiration = calculate_expiration_time();
        sessions[i].config_flag = set_config_flag(i); // Example function to set config flag

        if (!validate_session_data(&sessions[i])) {
            free(sessions);
            return NULL; // Invalid session data
        }
    }

    return sessions;
}

unsigned long generate_unique_session_id() {
    static unsigned long last_id = 0;
    unsigned long new_id;
    do {
        new_id = (unsigned long)rand() * RAND_MAX + rand();
    } while (new_id == last_id);
    last_id = new_id;
    return new_id;
}

time_t calculate_expiration_time() {
    time_t now = time(NULL);
    return now + 3600; // Example: expiration in 1 hour
}

int set_config_flag(int session_index) {
    // Example: alternate between two flags
    return session_index % 2 == 0 ? 1 : 0;
}

int validate_session_data(SessionData *session) {
    if (session->expiration <= time(NULL)) {
        return 0; // Invalid expiration time
    }
    if (session->id == 0 || session->config_flag < 0) {
        return 0; // Invalid session data
    }
    return 1;
}

void free_sessions(SessionData *sessions, int num_sessions) {
    if (sessions) {
        free(sessions);
    }
}
