        if (!entries[i].name) goto cleanup;

        snprintf(entries[i].name, name_len + 1, "ConfigName%d", i);
    }

    return entries;

cleanup:
    for (int i = 0; i < num_entries; ++i) {
        free(entries[i].long_array);
        for (int j = 0; entries[i].string_array && entries[i].string_array[j]; ++j) {
            free(entries[i].string_array[j]);
        }
        free(entries[i].string_array);
        free(entries[i].name);
    }
    free(entries);
    return NULL;
}
