typedef struct {
    long offset;
    int key;
    char* buffer;
} Record;

Record* allocate_and_initialize_records(size_t num_records, int min_key, int max_key, size_t max_buffer_len) {
    if (num_records == 0 || min_key > max_key || max_buffer_len == 0) {
        return NULL;
    }

    Record* records = malloc(num_records * sizeof(Record));
    if (!records) {
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = rand(); // Simplified for example
        RAND_int(&records[i].key, min_key, max_key + 1);
        records[i].buffer = malloc((max_buffer_len + 1) * sizeof(char));
        if (!records[i].buffer) {
            // Handle buffer allocation failure gracefully
            free(records);
            return NULL;
        }
        for (size_t j = 0; j < max_buffer_len; ++j) {
            RAND_bytes(&records[i].buffer[j], 1);
            records[i].buffer[j] = isalnum(records[i].buffer[j]) ? records[i].buffer[j] : 'A';
        }
        records[i].buffer[max_buffer_len] = '\0';
    }

    return records;
}

void free_records(Record* records, size_t num_records) {
    if (!records) {
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].buffer);
    }
    free(records);
}
