#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/rand.h>

typedef struct Record {
    long offset;
    int key;
    char* buffer;
} Record;

Record* allocate_and_initialize_records(size_t count, int min_key, int max_key, size_t max_buffer_length) {
    if (count == 0 || min_key >= max_key || max_buffer_length == 0) {
        return NULL; // Invalid parameters
    }

    Record* records = malloc(count * sizeof(Record));
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    const char* characters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    size_t char_length = strlen(characters);

    for (size_t i = 0; i < count; ++i) {
        records[i].offset = i * sizeof(Record);

        if (!RAND_int(&records[i].key, min_key, max_key)) {
            fprintf(stderr, "Failed to generate random key for record %zu\n", i);
            free(records);
            return NULL;
        }

        records[i].buffer = malloc(max_buffer_length + 1);
        if (records[i].buffer == NULL) {
            perror("Failed to allocate memory for buffer");
            for (size_t j = 0; j < i; ++j) {
                free(records[j].buffer);
            }
            free(records);
            return NULL;
        }

        size_t length = RAND_int(&length, 1, max_buffer_length);
        for (size_t j = 0; j < length; ++j) {
            records[i].buffer[j] = characters[RAND_int(NULL, 0, char_length)];
        }
        records[i].buffer[length] = '\0';
    }

    return records;
}

void free_records(Record* records, size_t count) {
    if (records == NULL || count == 0) {
        return;
    }

    for (size_t i = 0; i < count; ++i) {
        free(records[i].buffer);
    }
    free(records);
}
