long** allocate_long_array(size_t size) {
    long** array = malloc(size * sizeof(long*));
    if (array == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    for (size_t i = 0; i < size; ++i) {
        array[i] = malloc(sizeof(long));
        if (array[i] == NULL) {
            // Free previously allocated memory on failure
            for (size_t j = 0; j < i; ++j) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }
    }
    return array;
}

char*** allocate_char_array(size_t size, size_t max_length) {
    char*** array = malloc(size * sizeof(char**));
    if (array == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    for (size_t i = 0; i < size; ++i) {
        array[i] = malloc(max_length * sizeof(char*));
        if (array[i] == NULL) {
            // Free previously allocated memory on failure
            for (size_t j = 0; j < i; ++j) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }
    }
    return array;
}

Config** allocate_config_array(size_t size, Config* template_config) {
    Config** array = malloc(size * sizeof(Config*));
    if (array == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    for (size_t i = 0; i < size; ++i) {
        array[i] = malloc(sizeof(Config));
        if (array[i] == NULL) {
            // Free previously allocated memory on failure
            for (size_t j = 0; j < i; ++j) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }
        *array[i] = template_config[i];
    }
    return array;
}

void generate_unique_ids(Config** config_array, size_t size) {
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        // Generate a unique identifier using a PRNG
        config_array[i]->probability = rand() / (double)RAND_MAX;
        // Allocate memory for the name and copy the template's string
        config_array[i]->name = strdup(template_config[i].name);
    }
}

void free_memory(void** pointers, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (pointers[i] != NULL) {
            free(pointers[i]);
            pointers[i] = NULL;
        }
    }
}

int main() {
    // Example usage
    size_t size = 5;
    Config template_config = {0.75, "default"};
    Config** config_array = allocate_config_array(size, &template_config);

    if (config_array != NULL) {
        generate_unique_ids(config_array, size);

        // Use the allocated arrays...

        free_memory((void**)config_array, size);
    }

    return 0;
}
