        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    for (int i = 0; i < array_size; i++) {
        offsets[i] = rand();
        keys[i] = rand();

        records[i].value = rand() % INT_MAX;
        snprintf(records[i].string, 256, "Record_%d", i);
        time_t now = time(NULL);
        struct tm* tm = localtime(&now);
        records[i].ts.year = tm->tm_year + 1900;
        records[i].ts.month = tm->tm_mon + 1;
        records[i].ts.day = tm->tm_mday;
        records[i].ts.hour = tm->tm_hour;
        records[i].ts.minute = tm->tm_min;
        records[i].ts.second = tm->tm_sec;

        char insert_query[512];
        snprintf(insert_query, sizeof(insert_query),
                 "INSERT INTO records (offset, key, value, string, year, month, day, hour, minute, second) VALUES (%ld, %d, %d, '%s', %d, %d, %d, %d, %d, %d)",
                 offsets[i], keys[i], records[i].value, records[i].string,
                 records[i].ts.year, records[i].ts.month, records[i].ts.day,
                 records[i].ts.hour, records[i].ts.minute, records[i].ts.second);

        sqlite3_stmt* stmt;
        rc = sqlite3_prepare_v2(db, insert_query, -1, &stmt, 0);
        if (rc != SQLITE_OK) {
            fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(db));
            sqlite3_close(db);
            free(records[i].string);
            for (int j = i - 1; j >= 0; j--) {
                free(records[j].string);
            }
            free(records);
            free(keys);
            free(offsets);
            return NULL;
        }

        rc = sqlite3_step(stmt);
        if (rc != SQLITE_DONE) {
            fprintf(stderr, "Failed to insert record: %s\n", sqlite3_errmsg(db));
            sqlite3_finalize(stmt);
            sqlite3_close(db);
            for (int j = i - 1; j >= 0; j--) {
                free(records[j].string);
            }
            free(records);
            free(keys);
            free(offsets);
            return NULL;
        }

        sqlite3_finalize(stmt);
    }

    sqlite3_close(db);

    return records;
}
