    if (file == NULL) {
        printf("Failed to open file. Defaulting offsets to zero.\n");
        return;
    }

    long offset;
    while (fread(&offset, sizeof(long), 1, file) == 1) {
        // Process the offset
        printf("Read offset: %ld\n", offset);
    }

    fclose(file);
}

void log_execution(const char* message) {
