#include <time.h>

typedef struct {
    int id;
    char name[100];
    char *email;
    int session_id;
} User;

typedef struct {
    time_t timestamp;
    double amount;
    char description[256];
    User *user;
} Transaction;

typedef struct {
    int *session_ids;
    User *users;
    Transaction *transactions;
    size_t capacity;
    size_t size;
    FILE *log_file;
} MemoryManager;

MemoryManager* create_memory_manager(size_t initial_size, const char *log_path) {
    MemoryManager *mm = malloc(sizeof(MemoryManager));
    if (mm == NULL) {
        perror("Failed to allocate memory for MemoryManager");
        return NULL;
    }

    mm->session_ids = malloc(initial_size * sizeof(int));
    mm->users = malloc(initial_size * sizeof(User));
    mm->transactions = malloc(initial_size * sizeof(Transaction));
    if (mm->session_ids == NULL || mm->users == NULL || mm->transactions == NULL) {
        perror("Failed to allocate memory for data structures");
        free(mm);
        return NULL;
    }

    mm->capacity = initial_size;
    mm->size = 0;

    if (log_path != NULL) {
        mm->log_file = fopen(log_path, "w");
        if (mm->log_file == NULL) {
            perror("Failed to open log file");
            free(mm->session_ids);
            free(mm->users);
            free(mm->transactions);
            free(mm);
            return NULL;
        }
    } else {
        mm->log_file = NULL;
    }

    // Initialize session IDs, users, and transactions

    return mm;
}

void destroy_memory_manager(MemoryManager *mm) {
    if (mm == NULL) {
        return;
    }

    for (size_t i = 0; i < mm->size; ++i) {
        free(mm->users[i].email);
    }

    free(mm->session_ids);
    free(mm->users);
    free(mm->transactions);

    if (mm->log_file != NULL) {
        fclose(mm->log_file);
    }

    free(mm);
}

void log_memory_allocation(MemoryManager *mm, size_t allocated_size, const char *description) {
    if (mm->log_file != NULL) {
        time_t now = time(NULL);
        fprintf(mm->log_file, "Allocated %zu bytes for %s at %s", allocated_size, description, ctime(&now));
    }
}
