#define MAX_SESSIONS 1024
#define MAX_USERS 512
#define MAX_TRANSACTIONS 2048

typedef struct {
    char token[32];
} session;

typedef struct {
    char name[128];
    char email[128];
    session *sess;
} user_profile;

typedef struct {
    time_t timestamp;
    double amount;
    char description[512];
    user_profile *user;
} transaction_record;

void generate_session_token(session *sess) {
    if (!RAND_bytes((unsigned char *)sess->token, sizeof(sess->token))) {
        fprintf(stderr, "Failed to generate session token\n");
        exit(EXIT_FAILURE);
    }
}

void initialize_data_structures(int num_sessions, int num_users, int num_transactions) {
    session *sessions = malloc(num_sessions * sizeof(session));
    user_profile *users = malloc(num_users * sizeof(user_profile));
    transaction_record *transactions = malloc(num_transactions * sizeof(transaction_record));

    if (!sessions || !users || !transactions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_sessions; ++i) {
        generate_session_token(&sessions[i]);
    }

    for (int i = 0; i < num_users; ++i) {
        users[i].sess = &sessions[i % num_sessions];
        snprintf(users[i].name, sizeof(users[i].name), "User%d", i);
        snprintf(users[i].email, sizeof(users[i].email), "user%d@example.com", i);
    }

    for (int i = 0; i < num_transactions; ++i) {
        transactions[i].timestamp = time(NULL);
        transactions[i].amount = (double)(rand() % 1000) / 100;
        snprintf(transactions[i].description, sizeof(transactions[i].description), "Transaction%d", i);
        transactions[i].user = &users[i % num_users];
    }

    // Free allocated memory
    free(sessions);
    free(users);
    free(transactions);
}

int main() {
    srand(time(NULL));
    initialize_data_structures(MAX_SESSIONS, MAX_USERS, MAX_TRANSACTIONS);
    return 0;
}
