typedef struct {
    pthread_mutex_t lock;
    int record_count;
    Record* records;
} RecordArray;

void initialize_record_array(RecordArray* array, int count) {
    pthread_mutex_init(&array->lock, NULL);
    array->record_count = count;
    array->records = malloc(count * sizeof(Record));
}

void destroy_record_array(RecordArray* array) {
    pthread_mutex_destroy(&array->lock);
    free(array->records);
}

int allocate_and_initialize_records(RecordArray* array, int start_index, int end_index, const char* config_file) {
    // Parse configuration file and extract parameters
    int buffer_length = DEFAULT_BUFFER_LENGTH;
    int key_range = MAX_KEY_RANGE;
    int logging_level = 0;

    // Validate configuration settings

    pthread_mutex_lock(&array->lock);
    for (int i = start_index; i <= end_index; i++) {
        Record* record = &array->records[i];
        record->offset = i;

        // Generate cryptographically secure pseudo-random number
        if (!RAND_bytes((unsigned char*)&record->key, sizeof(record->key))) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        record->key %= key_range;

        // Initialize buffer with random ASCII string
        for (int j = 0; j < buffer_length; j++) {
            record->buffer[j] = 'a' + rand() % ('z' - 'a');
        }
    }
    pthread_mutex_unlock(&array->lock);

    return 0;
}

void* thread_function(void* arg) {
    RecordArray* array = (RecordArray*)arg;
    int start_index = 0;
    int end_index = array->record_count - 1;

    return (void*)(long)allocate_and_initialize_records(array, start_index, end_index, "config.ini");
