#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    char** strings;
    Record* records;
    size_t capacity;
    size_t count;
} MemoryPool;

void seed_prng() {
    srand(time(NULL));
}

unsigned long generate_unique_id(unsigned long range) {
    return (unsigned long)(rand()) % range;
}

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    pool->offsets = malloc(initial_capacity * sizeof(long));
    pool->strings = malloc(initial_capacity * sizeof(char*));
    pool->records = malloc(initial_capacity * sizeof(Record));
    pool->capacity = initial_capacity;
    pool->count = 0;
    return pool;
}

void resize_memory_pool(MemoryPool* pool, size_t new_capacity) {
    pool->offsets = realloc(pool->offsets, new_capacity * sizeof(long));
    pool->strings = realloc(pool->strings, new_capacity * sizeof(char*));
    pool->records = realloc(pool->records, new_capacity * sizeof(Record));
    pool->capacity = new_capacity;
}

void add_record(MemoryPool* pool, long offset, const char* str) {
    if (pool->count >= pool->capacity) {
        resize_memory_pool(pool, pool->capacity * 2);
    }
    pool->offsets[pool->count] = offset;
    pool->strings[pool->count] = strdup(str);
    pool->records[pool->count].value = generate_unique_id(MAX_RECORDS);
    pool->count++;
}

void cleanup_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->count; i++) {
        free(pool->strings[i]);
    }
    free(pool->offsets);
    free(pool->strings);
    free(pool->records);
    free(pool);
}

// Logging functions (simple implementation)
void log_message(const char* message, int verbosity) {
    static const int LOG_DEBUG = 1;
    static const int LOG_INFO = 2;

    if (verbosity >= LOG_INFO) {
        printf("INFO: %s\n", message);
    }
    if (verbosity >= LOG_DEBUG) {
        fprintf(stderr, "DEBUG: %s\n", message);
    }
}

int main() {
    seed_prng();
    MemoryPool* pool = create_memory_pool(10);

    add_record(pool, 12345, "Hello");
    add_record(pool, 67890, "World");

    log_message("Memory pool created and records added.", LOG_INFO);
    cleanup_memory_pool(pool);
    return 0;
}
```

