dataEntry* allocateAndInitialize(int numSessions, int minOffset, int maxOffset) {
    if (numSessions <= 0 || minOffset > maxOffset) return NULL;

    dataEntry *entries = malloc(numSessions * sizeof(dataEntry));
    if (!entries) return NULL;

    srand(time(NULL)); // Seed PRNG

    for (int i = 0; i < numSessions; ++i) {
        entries[i].offset = rand() % (maxOffset - minOffset + 1) + minOffset;
        entries[i].key = rand();
        entries[i].sess = malloc(sizeof(session));
        if (!entries[i].sess) {
            for (int j = 0; j < i; ++j) free(entries[j].sess);
            free(entries);
            return NULL;
        }
        entries[i].sess->recordField = rand() % (MAX_RECORD_FIELD - MIN_RECORD_FIELD + 1) + MIN_RECORD_FIELD;
        time(&entries[i].eventTimestamp);
    }

    return entries;
}

void freeAllocatedMemory(dataEntry *entries, int numSessions) {
    if (!entries || numSessions <= 0) return;

    for (int i = 0; i < numSessions; ++i) free(entries[i].sess);
    free(entries);
}
