#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1000
#define MIN_ID 100
#define MAX_ID 9999
#define MIN_METADATA_LENGTH 10
#define MAX_METADATA_LENGTH 256

typedef struct {
    time_t timestamp;
    int connection_id;
    char metadata[MAX_METADATA_LENGTH];
} NetworkConnection;

NetworkConnection* connections = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int connection_count = 0;
int logging_level = 1; // 1 for INFO, 2 for DEBUG

void log_message(int level, const char* message) {
    if (level <= logging_level) {
        printf("%s\n", message);
    }
}

int init_network_connections() {
    connections = (NetworkConnection*)malloc(MAX_CONNECTIONS * sizeof(NetworkConnection));
    if (!connections) {
        log_message(1, "Failed to allocate memory for network connections");
        return -1;
    }

    srand(time(NULL));

    pthread_mutex_lock(&mutex);
    connection_count = 0;
    for (; connection_count < MAX_CONNECTIONS; ++connection_count) {
        time_t timestamp = time(NULL);
        connections[connection_count].timestamp = timestamp;

        int connection_id = rand() % (MAX_ID - MIN_ID + 1) + MIN_ID;
        connections[connection_count].connection_id = connection_id;

        int metadata_length = rand() % (MAX_METADATA_LENGTH - MIN_METADATA_LENGTH + 1) + MIN_METADATA_LENGTH;
        for (int i = 0; i < metadata_length; ++i) {
            connections[connection_count].metadata[i] = 'A' + rand() % ('Z' - 'A' + 1);
        }
        connections[connection_count].metadata[metadata_length] = '\0';
    }
    pthread_mutex_unlock(&mutex);

    log_message(2, "Initialized network connections");
    return 0;
}

void free_network_connections() {
    if (connections) {
        free(connections);
        connections = NULL;
        connection_count = 0;
        log_message(2, "Freed network connections memory");
    }
}

void* manage_network_connections(void* arg) {
    int thread_id = *(int*)arg;

    pthread_mutex_lock(&mutex);
    for (int i = thread_id; i < connection_count; i += pthread_num_threads()) {
        // Perform operations on each connection
        log_message(2, "Processing connection ID: %d", connections[i].connection_id);
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

int main() {
    int num_threads = 4;

    init_network_connections();

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, manage_network_connections, &i);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_network_connections();

    return 0;
}
