#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    char data[128]; // Fixed size based on system architecture
} Record;

Record* allocate_and_initialize_records(int num_records, size_t max_memory, unsigned int seed, int *failure_mode) {
    if (num_records <= 0 || max_memory <= 0 || seed < 0 || failure_mode == NULL) {
        return NULL;
    }

    Record *records = malloc(num_records * sizeof(Record));
    if (records == NULL) {
        *failure_mode = 1; // Out of memory
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = rand();
        records[i].key = rand();

        if (sizeof(records[i].data) != sizeof(char[128])) {
            *failure_mode = 2; // Fixed size mismatch
            free(records);
            return NULL;
        }

        for (int j = 0; j < sizeof(records[i].data); ++j) {
            records[i].data[j] = 'a' + (rand() % 26); // Random unique characters
        }
    }

    *failure_mode = 0; // No failure
    return records;
}

void free_records(Record *records, int num_records) {
    if (records != NULL) {
        free(records);
    }
}
