} metric_t;

// Function to allocate memory for data structures
int allocate_memory(size_t num_configs, size_t num_metrics, long** long_array, char*** string_array,
                    config_t*** config_array, metric_t*** metric_array) {
    // Allocate memory for arrays
    *long_array = (long*)malloc(num_configs * sizeof(long));
    if (*long_array == NULL) return -1;

    *string_array = (char**)malloc(num_configs * sizeof(char*));
    if (*string_array == NULL) {
        free(*long_array);
        return -1;
    }

    *config_array = (config_t**)malloc(num_configs * sizeof(config_t*));
    if (*config_array == NULL) {
        free(*string_array);
        free(*long_array);
        return -1;
    }

    *metric_array = (metric_t**)malloc(num_metrics * sizeof(metric_t*));
    if (*metric_array == NULL) {
        free(*config_array);
        free(*string_array);
        free(*long_array);
        return -1;
    }

    // Allocate memory for each structure
    for (size_t i = 0; i < num_configs; ++i) {
        (*config_array)[i] = (config_t*)malloc(sizeof(config_t));
        if ((*config_array)[i] == NULL) {
            for (size_t j = 0; j < i; ++j) free((*config_array)[j]);
            free(*metric_array);
            free(*config_array);
            free(*string_array);
            free(*long_array);
            return -1;
        }
    }

    for (size_t i = 0; i < num_metrics; ++i) {
        (*metric_array)[i] = (metric_t*)malloc(sizeof(metric_t));
        if ((*metric_array)[i] == NULL) {
            for (size_t j = 0; j < i; ++j) free((*metric_array)[j]);
            for (size_t j = 0; j < num_configs; ++j) free((*config_array)[j]);
            free(*metric_array);
            free(*config_array);
            free(*string_array);
            free(*long_array);
            return -1;
        }
    }

    return 0;
}

// Function to initialize config and metric structures
void init_structures(config_t** config_array, metric_t** metric_array,
                     size_t num_configs, size_t num_metrics) {
    // Initialize config structures with non-cryptographically secure random identifiers
    for (size_t i = 0; i < num_configs; ++i) {
        (*config_array)[i]->probability = (double)rand() / RAND_MAX;
        (*config_array)[i]->name = strdup("Config");
        (*config_array)[i]->mode = MODE_HIGH_PERF;
    }

    // Initialize metric structures
    for (size_t i = 0; i < num_metrics; ++i) {
        (*metric_array)[i]->performance_metric = (float)rand() / RAND_MAX;
        (*metric_array)[i]->timestamp = time(NULL);
        (*metric_array)[i]->label = strdup("Metric");
    }
}

// Function to free allocated memory
void free_memory(long* long_array, char** string_array,
                 config_t** config_array, metric_t** metric_array,
                 size_t num_configs, size_t num_metrics) {
    // Free memory for each structure
    for (size_t i = 0; i < num_configs; ++i) {
        free((*config_array)[i]->name);
        free((*config_array)[i]);
    }
    for (size_t i = 0; i < num_metrics; ++i) {
        free((*metric_array)[i]->label);
        free((*metric_array)[i]);
    }

    // Free memory for arrays
    free(long_array);
    free(string_array);
    free(config_array);
    free(metric_array);
}
