#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct Record {
    int key;
    long offset;
    struct Record* next;
} Record;

// Initialize and populate a linked list with records
Record* initializeRecords(int size, int range) {
    Record* head = NULL;
    Record* current = NULL;

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < size; i++) {
        Record* newRecord = (Record*)malloc(sizeof(Record));
        if (newRecord == NULL) {
            perror("Memory allocation failed");
            return head;
        }

        newRecord->key = rand() % range + 1; // Generate a random key
        newRecord->offset = i * sizeof(Record); // Set the offset value
        newRecord->next = NULL;

        if (head == NULL) {
            head = newRecord;
            current = newRecord;
        } else {
            current->next = newRecord;
            current = newRecord;
        }
    }

    return head;
}

// Iterate over the linked list and print each record's key
void iterateRecords(Record* head) {
    Record* current = head;
    while (current != NULL) {
        printf("Key: %d, Offset: %ld\n", current->key, current->offset);
        current = current->next;
    }
}

// Free the memory allocated for the linked list
void freeRecords(Record* head) {
    Record* current = head;
    while (current != NULL) {
        Record* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    int size = 10;
    int range = 100;

    // Initialize the linked list
    Record* records = initializeRecords(size, range);

    // Iterate over and print the records
    iterateRecords(records);

    // Free the allocated memory
    freeRecords(records);

    return 0;
}
```

This code provides a basic implementation of managing a dynamic collection of 'record' structures using a linked list in C. It includes functions for initializing the records, iterating over them, and freeing the allocated memory. The random number generation is done using `rand()`, which is suitable for non-cryptographic purposes. For more advanced requirements, additional optimizations and features can be added as needed.']

