#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    struct Record *next;
} Record;

typedef struct ResourceManager {
    Record *head;
    pthread_mutex_t mutex;
} ResourceManager;

void resourceManager(ResourceManager *rm) {
    pthread_mutex_init(&rm->mutex, NULL);
    // Initialize and populate the linked list
    rm->head = NULL;
    for (int i = 0; i < 1000; i++) {
        Record *new_record = malloc(sizeof(Record));
        new_record->key = rand() % 1000000;
        new_record->offset = rand();
        new_record->next = rm->head;
        rm->head = new_record;
    }

    // Example of iterating over the linked list
    Record *current = rm->head;
    while (current != NULL) {
        printf("Key: %d, Offset: %ld\n", current->key, current->offset);
        current = current->next;
    }

    pthread_mutex_destroy(&rm->mutex);
}

void updateResource(ResourceManager *rm, int key, long newOffset) {
    pthread_mutex_lock(&rm->mutex);
    Record *current = rm->head;
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    if (current != NULL) {
        current->offset = newOffset;
    }
    pthread_mutex_unlock(&rm->mutex);
}

void deleteResource(ResourceManager *rm, int key) {
    pthread_mutex_lock(&rm->mutex);
    Record *current = rm->head;
    Record *prev = NULL;
    while (current != NULL && current->key != key) {
        prev = current;
        current = current->next;
    }
    if (current != NULL) {
        if (prev == NULL) {
            rm->head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&rm->mutex);
}

int main() {
    ResourceManager rm;
    resourceManager(&rm);

    updateResource(&rm, 123456, 987654321);
    deleteResource(&rm, 123456);

    return 0;
}
