#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    struct record *next;
} Record;

Record* create_record(int value) {
    Record *new_record = (Record*)malloc(sizeof(Record));
    if (new_record == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    new_record->value = value;
    new_record->next = NULL;
    return new_record;
}

void add_record_to_list(Record **head, int value) {
    Record *new_record = create_record(value);
    if (new_record == NULL) {
        // Handle memory allocation failure
        return;
    }
    new_record->next = *head;
    *head = new_record;
}

int generate_random_value(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void populate_list_with_random_values(Record **head, int count, int min_value, int max_value) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        int random_value = generate_random_value(min_value, max_value);
        add_record_to_list(head, random_value);
    }
}

void free_record(Record *record) {
    if (record != NULL) {
        Record *next = record->next;
        free(record);
        free_record(next);
    }
}

// Example usage
int main() {
    Record *head = NULL;
    populate_list_with_random_values(&head, 1000, 1, 1000);

    // Process the list...

    free_record(head);
    return 0;
}
